INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rickoslyder/HypeDelta/prediction-tracking', 'community', 'rickoslyder', 'HypeDelta', 'rickoslyder/HypeDelta', 'prediction-tracking', 0, 0, 48, '2026-03-08T01:57:15.303Z', '2026-03-08T02:01:48.540Z', '1d8fddba5c670b4e11f4b1337d3e2f9fe1a5add369bc2313ad0cd274ac6a1956', '{"id":"rickoslyder/HypeDelta/prediction-tracking","name":"prediction-tracking","description":{"en":"The prediction-tracking skill enables AI researchers and critics to track and evaluate the accuracy of predictions over time, capturing key details such as text, author, and timeframe","zh":"预测跟踪技能是AI研究智能聚合器，记录和评估AI研究人员和评论者的预测","ja":"予測追跡スキルは、AIエージェントの研究インテリジェンスアグリゲーターであり、AI研究者と批評家の予測を記録して評価する","ko":"예측 추적 기능은 AI 툴 연구 인텔리전스 집계기로서 AI 연구자와 평론가의 예측을 기록하고 평가합니다","es":"El seguimiento de predicciones es una habilidad de inteligencia artificial que permite registrar y evaluar la precisión de las predicciones realizadas por investigadores y críticos de IA. Se capturan campos como texto, autor, fecha y tema","fr":"Le suivi de prédictions est une fonctionnalité d''intelligence artificielle qui permet d''enregistrer et d''évaluer la précision des prédictions réalisées par les chercheurs et critiques en IA. Des champs tels que le texte, l''auteur, la date et le sujet sont capturés","de":"Die Vorhersage-Verfolgung ist eine KI-Fähigkeit, die das Aufzeichnen und Bewertung der Genauigkeit von Vorhersagen ermöglicht, die von KI-Forschern und -Kritikern gemacht wurden. Felder wie Text, Autor, Datum und Thema werden erfasst","pt":"A habilidade de previsão de rastreamento é um agregador de inteligência de pesquisa de IA que captura e avalia previsões de pesquisadores e críticos.","ru":"ИИ Агенты: отслеживание прогнозов исследователей и критиков, оценка их точности с течением времени.","ar":"مراقبة التنبؤات هو تجميع لمعلومات ذكاء اصطناعي لتعقب وتقييم تنبؤات الباحثين والنقاد."},"seo":{"title":{"en":"prediction-tracking: AI Research Intelligence Aggregator ...","zh":"预测跟踪设置指南 - AI研究智能聚合器","ja":"予測追跡ベストプラクティス - AIエージェントの研究インテリジェンスアグリゲーター","ko":"예측 추적 가이드 - AI 툴 연구 인텔리전스 집계기","es":"Guía de configuración de seguimiento de predicciones para...","fr":"Guide de mise en place de la fonctionnalité de suivi de p...","de":"Einrichtungsleitfaden für Vorhersage-Verfolgung in KI-Age...","pt":"Guia de Configuração de Previsão de Rastreamento de Intel...","ru":"Настройка ИИ Агентов: Руководство по отслеживанию прогнозов","ar":"دليل إعداد مراقبة التنبؤات ل_tool AI الإحترافي"},"description":{"en":"Unlock the power of AI research tracking - discover how to record, evaluate, and analyze predictions made by AI researchers and critics with our prediction-t...","zh":"了解预测跟踪技能，记录和评估AI研究人员和评论者的预测，提高预测准确性","ja":"予測追跡スキルを使用して、AI研究者と批評家の予測を記録して評価し、予測の精度を高める","ko":"예측 추적 기능을 사용하여 AI 연구자와 평론가의 예측을 기록하고 평가하여 예측 정확도를 높입니다","es":"Aprende a rastrear predicciones de investigadores y críticos de IA con nuestro agente de seguimiento de predicciones. Mejora la precisión con nuestro sistema...","fr":"Découvrez comment suivre les prédictions des chercheurs et critiques en IA avec notre outil de suivi de prédictions. Améliorez la précision avec notre systèm...","de":"Erfahren Sie, wie Sie Vorhersagen von KI-Forschern und -Kritikern mit unserem Vorhersage-Verfolgungs-Tool nachverfolgen können. Verbessern Sie die Genauigkei...","pt":"Aprenda a configurar e utilizar a habilidade de previsão de rastreamento para IA, capturando previsões e avaliando sua precisão ao longo do tempo.","ru":"Отслеживайте прогнозы ИИ исследователей и критиков, оценивайте их точность с течением времени с помощью ИИ Агентов.","ar":"تعرف على إعداد مراقبة التنبؤات للحصول على أدوات ذكاء اصطناعي متقدمة لتعقب التنبؤات وتقييم دقتها بمرور الوقت."},"definition":{"en":"prediction-tracking is an AI research intelligence aggregator that records and evaluates predictions made by AI researchers and critics","zh":"预测跟踪是指记录和评估AI研究人员和评论者的预测的过程","ja":"予測追跡は、AI研究者と批評家の予測を記録して評価するプロセスを指す","ko":"예측 추적은 AI 연구자와 평론가의 예측을 기록하고 평가하는 것을 의미합니다","es":"Seguimiento de predicciones: una habilidad de IA que registra y evalúa la precisión de las predicciones de investigadores y críticos de IA","fr":"Suivi de prédictions : une fonctionnalité d''IA qui enregistre et évalue la précision des prédictions des chercheurs et critiques en IA","de":"Vorhersage-Verfolgung: eine KI-Fähigkeit, die die Genauigkeit von Vorhersagen von KI-Forschern und -Kritikern aufzeichnet und bewertet","pt":"O que é previsão de rastreamento? É um agregador de inteligência de pesquisa de IA que captura previsões e avalia sua precisão.","ru":"Что такое отслеживание прогнозов? Это ИИ Агенты, которые отслеживают прогнозы исследователей и критиков.","ar":"ما هو مراقبة التنبؤات؟ هو أداة ذكاء اصطناعي لتعقب وتقييم التنبؤات."},"features":{"en":["Captures required fields including text, author, madeAt, timeframe, topic, and confidence","Supports optional fields such as sourceUrl and targetD","Enables evaluation of prediction accuracy over time","Tracks predictions across various areas of AI","Allows for recording of new predictions with specific details"],"zh":["记录预测时捕获必要字段：文本、作者、时间、时间范围、主题、置信度","支持可选字段：来源URL、目标","评估预测准确性","跟踪预测的时间范围","记录预测的作者和来源"],"ja":["予測を記録する際に必要なフィールドをキャプチャ：テキスト、著者、時間、時間枠、テーマ、信頼度","オプションフィールドをサポート：ソースURL、ターゲット","予測の精度を評価する","予測の時間枠を追跡する","予測の著者とソースを記録する"],"ko":["예측을 기록할 때 필수 필드를 캡처: 텍스트, 저자, 시간, 시간 범위, 주제, 확신도","옵션 필드를 지원: 소스 URL, 대상","예측의 정확도를 평가","예측의 시간 범위를 추적","예측의 저자와 소스를 기록"],"es":["Registro de predicciones con campos como texto, autor y fecha","Evaluación de la precisión de las predicciones sobre el tiempo","Captura de metadatos como tema y confianza","Compatibilidad con fuentes de datos externas a través de URL","Análisis de tendencias y patrones en las predicciones","Integración con herramientas de inteligencia artificial para mejorar la precisión"],"fr":["Enregistrement de prédictions avec des champs tels que le texte, l''auteur et la date","Évaluation de la précision des prédictions sur le temps","Capture de métadonnées telles que le sujet et la confiance","Compatibilité avec des sources de données externes via URL","Analyse de tendances et de modèles dans les prédictions","Intégration avec des outils d''intelligence artificielle pour améliorer la précision"],"de":["Aufzeichnung von Vorhersagen mit Feldern wie Text, Autor und Datum","Bewertung der Genauigkeit von Vorhersagen über die Zeit","Erfassung von Metadaten wie Thema und Vertrauen","Kompatibilität mit externen Datenquellen über URL","Analyse von Trends und Mustern in den Vorhersagen","Integration mit KI-Tools zur Verbesserung der Genauigkeit"],"pt":["Captura de previsões com campos obrigatórios: texto, autor, data e hora, prazo e tópico","Avaliação da precisão das previsões ao longo do tempo","Suporte a campos opcionais: URL de origem e destino","Integração com tecnologias de IA para análise de dados","Interface de usuário intuitiva para fácil configuração","Suporte a múltiplos formatos de dados para importação e exportação"],"ru":["Захват прогнозов с обязательными полями: текст, автор, дата и время, срок и тема","Оценка точности прогнозов с течением времени","Поддержка необязательных полей: URL источника и целевого","Интеграция с технологиями ИИ для анализа данных","Интуитивно понятный интерфейс пользователя для легкой настройки","Поддержка нескольких форматов данных для импорта и экспорта"],"ar":["التعقب التنبؤات مع حقول إجبارية: النص، الكاتب، التاريخ والوقت، الفترة والمنطقة","تقييم دقة التنبؤات بمرور الوقت","دعم حقول اختيارية: رابط المصدر والوجهة","التكامل مع تكنولوجيا الذكاء الاصطناعي لتحليل البيانات","واجهة المستخدم بديهية للتركيب السهل","دعم عدة صيغ بيانات للاستيراد والتصدير"]},"keywords":{"en":["how to use prediction-tracking","what is prediction-tracking","prediction-tracking alternative","prediction-tracking vs AI trend analysis","prediction-tracking install","prediction-tracking setup guide","AI research intelligence aggregator","tracking AI predictions","evaluating AI prediction accuracy"],"zh":["预测跟踪","AI研究智能聚合器","预测记录","预测评估","AI研究人员","AI评论者","预测准确性","时间范围","主题","信頼度"],"ja":["予測追跡","AIエージェントの研究インテリジェンスアグリゲーター","予測記録","予測評価","AI研究者","AI批評家","予測精度","時間枠","テーマ","信頼度"],"ko":["예측 추적","AI 툴 연구 인텔리전스 집계기","예측 기록","예측 평가","AI 연구자","AI 평론가","예측 정확도","시간 범위","주제","확신도"],"es":["seguimiento de predicciones","inteligencia artificial","agentes de IA","evaluación de predicciones","registro de predicciones","análisis de tendencias","herramientas de IA","desarrollo de IA","investigación de IA"],"fr":["suivi de prédictions","intelligence artificielle","outils d''IA","évaluation de prédictions","enregistrement de prédictions","analyse de tendances","développement d''IA","recherche d''IA","prédictions d''IA"],"de":["Vorhersage-Verfolgung","künstliche Intelligenz","KI-Tools","Bewertung von Vorhersagen","Aufzeichnung von Vorhersagen","Trend-Analyse","KI-Entwicklung","KI-Forschung","Vorhersagen von KI"],"pt":["previsão de rastreamento","IA","inteligência de pesquisa","captura de previsões","avaliação de precisão","tecnologias de IA","análise de dados","importação e exportação de dados","configuração de previsão de rastreamento"],"ru":["отслеживание прогнозов","ИИ Агенты","ИИ","захват прогнозов","оценка точности","технологии ИИ","анализ данных","импорт и экспорт данных","настройка отслеживания прогнозов"],"ar":["مراقبة التنبؤات","أدوات الذكاء الاصطناعي","ذكاء اصطناعي","تعقب التنبؤات","تقييم الدقة","تكنولوجيا الذكاء الاصطناعي","تحليل البيانات","استيراد وتصدير البيانات","إعداد مراقبة التنبؤات"]}},"owner":"rickoslyder","repo":"HypeDelta","repoPath":"rickoslyder/HypeDelta","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.303Z","topics":[],"category":"community","skillMd":{"name":"prediction-tracking","description":"Track and evaluate AI predictions over time to assess accuracy. Use when reviewing past predictions to determine if they came true, failed, or remain uncertain.","bodyPreview":"# Prediction Tracking Skill\n\nTrack predictions made by AI researchers and critics, evaluate their accuracy over time.\n\n## Prediction Recording\n\nWhen recording a new prediction, capture:\n\n### Required Fields\n- **text**: The prediction as stated\n- **author**: Who made it\n- **madeAt**: When it was made\n- **timeframe**: When they expect it to happen\n- **topic**: What area of AI\n- **confidence**: How confident they seemed\n\n### Optional Fields\n- **sourceUrl**: Where the prediction was made\n- **targetD","body":"# Prediction Tracking Skill\n\nTrack predictions made by AI researchers and critics, evaluate their accuracy over time.\n\n## Prediction Recording\n\nWhen recording a new prediction, capture:\n\n### Required Fields\n- **text**: The prediction as stated\n- **author**: Who made it\n- **madeAt**: When it was made\n- **timeframe**: When they expect it to happen\n- **topic**: What area of AI\n- **confidence**: How confident they seemed\n\n### Optional Fields\n- **sourceUrl**: Where the prediction was made\n- **targetDate**: Specific date if mentioned\n- **conditions**: Any caveats or conditions\n- **metrics**: How to measure success\n\n## Evaluation Status\n\nWhen evaluating predictions, assign one of:\n\n### `verified`\nClearly came true as stated.\n- The predicted capability/event occurred\n- Within the stated timeframe\n- Substantially as described\n\n### `falsified`\nClearly did not come true.\n- Timeframe passed without occurrence\n- Contradictory evidence emerged\n- Author retracted or modified claim\n\n### `partially-verified`\nPartially accurate.\n- Some aspects came true, others didn''t\n- Capability exists but weaker than claimed\n- Timeframe was off but direction correct\n\n### `too-early`\nNot enough time has passed.\n- Still within stated timeframe\n- No definitive evidence either way\n\n### `unfalsifiable`\nCannot be objectively assessed.\n- Too vague to measure\n- No clear success criteria\n- Moved goalposts\n\n### `ambiguous`\nPrediction was too vague to evaluate.\n- Multiple interpretations possible\n- Success criteria unclear\n\n## Evaluation Process\n\nFor each prediction being evaluated:\n\n### 1. Restate the prediction\nWhat exactly was claimed?\n\n### 2. Identify timeframe\nHas enough time passed to evaluate?\n\n### 3. Gather evidence\nWhat has happened since?\n- Relevant releases or announcements\n- Benchmark results\n- Real-world deployments\n- Counter-evidence\n\n### 4. Assess status\nWhich evaluation status applies?\n\n### 5. Score accuracy\nIf verifiable, rate 0.0-1.0:\n- 1.0: Exactly as predicted\n- 0.7-0.9: Substantially correct\n- 0.4-0.6: Partially correct\n- 0.1-0.3: Mostly wrong\n- 0.0: Completely wrong\n\n### 6. Note lessons\nWhat does this tell us about:\n- The author''s forecasting ability\n- The topic''s predictability\n- Common prediction pitfalls\n\n## Output Format\n\nFor evaluation:\n```json\n{\n  \"evaluations\": [\n    {\n      \"predictionId\": \"id\",\n      \"status\": \"verified\",\n      \"accuracyScore\": 0.85,\n      \"evidence\": \"Description of evidence\",\n      \"notes\": \"Additional context\",\n      \"evaluatedAt\": \"timestamp\"\n    }\n  ]\n}\n```\n\nFor accuracy statistics:\n```json\n{\n  \"author\": \"Author name\",\n  \"totalPredictions\": 15,\n  \"verified\": 5,\n  \"falsified\": 3,\n  \"partiallyVerified\": 2,\n  \"pending\": 4,\n  \"unfalsifiable\": 1,\n  \"averageAccuracy\": 0.62,\n  \"topicBreakdown\": {\n    \"reasoning\": { \"predictions\": 5, \"accuracy\": 0.7 },\n    \"agents\": { \"predictions\": 3, \"accuracy\": 0.4 }\n  },\n  \"calibration\": \"Assessment of how well-calibrated they are\"\n}\n```\n\n## Calibration Assessment\n\nEvaluate whether predictors are well-calibrated:\n\n### Well-Calibrated\n- High-confidence predictions usually come true\n- Low-confidence predictions have mixed results\n- Acknowledges uncertainty appropriately\n\n### Overconfident\n- High-confidence predictions often fail\n- Rarely expresses uncertainty\n- Doesn''t update on evidence\n\n### Underconfident\n- Low-confidence predictions often come true\n- Hedges even on likely outcomes\n- Too conservative\n\n### Inconsistent\n- Confidence doesn''t correlate with accuracy\n- Random relationship between stated and actual accuracy\n\n## Tracking Notable Predictors\n\nKeep running assessments of key voices:\n\n| Predictor | Total | Accuracy | Calibration | Notes |\n|-----------|-------|----------|-------------|-------|\n| Sam Altman | 20 | 55% | Overconfident | Timeline optimism |\n| Gary Marcus | 15 | 70% | Well-calibrated | Conservative |\n| Dario Amodei | 12 | 65% | Slightly over | Safety-focused |\n\n## Red Flags\n\nWatch for prediction patterns that suggest bias:\n- Always bullish regardless of topic\n- Never acknowledges failed predictions\n- Moves goalposts when wrong\n- Predictions align suspiciously with financial interests\n- Vague enough to claim credit for anything\n"},"lastSynced":"2026-03-08T02:01:48.540Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Research Agents requiring advanced prediction analysis and tracking capabilities.","zh":"非常适合需要高级预测分析和跟踪能力的AI研究代理。","ja":"高度な予測分析および追跡機能を必要とするAIリサーチエージェントに最適です。","ko":"고급 예측 분석 및 추적 기능을 필요로 하는 AI 연구 에이전트에 적합합니다.","es":"Perfecto para Agentes de Investigación de IA que requieren análisis de predicción avanzado y capacidades de seguimiento.","fr":"Parfait pour les agents de recherche en IA nécessitant une analyse de prédiction avancée et des capacités de suivi.","de":"Perfekt für KI-Forschungsagenten, die erweiterte Vorhersageanalysen und Nachverfolgungsfunktionen benötigen.","pt":"Perfeito para Agentes de Pesquisa de IA que exigem análise de previsão avançada e capacidades de rastreamento.","ru":"Идеально подходит для агентов-исследователей ИИ, требующих расширенного анализа прогнозирования и возможностей отслеживания.","ar":"مثالي للوكلاء الباحثين في مجال الذكاء الاصطناعي الذين يحتاجون إلى تحليل تنبؤ متقدم وقدرات تتبع."},"recommendation":{"en":"Empowers agents to track and evaluate prediction accuracy over time, capturing key details such as text, author, and timeframe, utilizing fields like confidence levels and topic categorization, and optionally, source URLs.","zh":"赋予代理跟踪和评估预测准确性随时间的变化的能力，捕获诸如文本、作者和时间范围等关键细节，利用诸如置信水平和主题分类等字段，并可选地，源URL。","ja":"エージェントに、テキスト、著者、時間枠などの重要な詳細をキャプチャし、信頼レベルやトピック分類などのフィールドを使用して、時間の経過とともに予測の精度を追跡および評価する機能を提供します。さらに、ソースURLなどのオプションフィールドも利用できます。","ko":"에이전트가 텍스트, 저자, 시간 범위 등의 주요 세부 정보를 캡처하여 시간 경과에 따른 예측 정확도를 추적 및 평가할 수 있는 기능을 제공하며,信頼 수준 및 주제 분류와 같은 필드를 사용하고, 소스 URL과 같은 옵션 필드를 사용할 수 있습니다.","es":"Habilita a los agentes a seguir y evaluar la precisión de la predicción con el tiempo, capturando detalles clave como texto, autor y marco temporal, utilizando campos como niveles de confianza y categorización de temas, y opcionalmente, URLs de origen.","fr":"Permet aux agents de suivre et d''évaluer la précision de la prédiction au fil du temps, en capturant des détails clés tels que le texte, l''auteur et le cadre temporel, en utilisant des champs tels que les niveaux de confiance et la catégorisation des sujets, et éventuellement, les URL de source.","de":"Ermöglicht es Agenten, die Vorhersagegenauigkeit über einen bestimmten Zeitraum hinweg zu verfolgen und zu bewerten, wobei wichtige Details wie Text, Autor und Zeitrahmen erfasst werden, unter Verwendung von Feldern wie Vertrauensniveaus und Themenkategorisierung, und optional, Quell-URLs.","pt":"Habilita os agentes a rastrear e avaliar a precisão da previsão ao longo do tempo, capturando detalhes importantes como texto, autor e período de tempo, utilizando campos como níveis de confiança e categorização de tópicos, e opcionalmente, URLs de origem.","ru":"Позволяет агентам отслеживать и оценивать точность прогнозирования во времени, захватывая ключевые детали, такие как текст, автор и временной интервал, используя поля, такие как уровни уверенности и категоризация тем, и опционально, URL-адреса источников.","ar":"تمكّن الوكلاء من تتبع وتقييم دقة التنبؤ مع مرور الوقت، وتصوير التفاصيل الرئيسية مثل النص والكاتب والفترة الزمنية، و باستخدام حقول مثل مستويات الثقة وتصنيف المواضيع، و خياريًا، عناوين URL للمصادر."},"useCases":{"en":["Automating prediction tracking for AI researcher statements","Generating reports on prediction accuracy over specific timeframes","Debugging inconsistencies in prediction confidence levels"],"zh":["自动化AI研究人员陈述的预测跟踪","生成特定时间范围内预测准确性的报告","调试预测置信水平的不一致性"],"ja":["AIリサーチャーの声明の予測追跡を自動化する","特定の時間枠内での予測精度のレポートを生成する","予測信頼レベルの不一致をデバッグする"],"ko":["AI 연구자 진술의 예측 추적 자동화","특정 시간 범위 내 예측 정확도 보고서 생성","예측 신뢰도 수준의 불일치 디버깅"],"es":["Automatizar el seguimiento de predicciones para declaraciones de investigadores de IA","Generar informes sobre la precisión de la predicción en marcos temporales específicos","Depurar inconsistencias en los niveles de confianza de la predicción"],"fr":["Automatiser le suivi des prédictions pour les déclarations des chercheurs en IA","Générer des rapports sur la précision de la prédiction sur des cadres temporels spécifiques","Déboguer les incohérences dans les niveaux de confiance de la prédiction"],"de":["Automatisieren der Nachverfolgung von Vorhersagen für Aussagen von KI-Forschern","Erstellen von Berichten über die Vorhersagegenauigkeit in bestimmten Zeiträumen","Fehlerbehebung bei Inkonsistenzen in den Vertrauensniveaus der Vorhersage"],"pt":["Automatizar o rastreamento de previsões para declarações de pesquisadores de IA","Gerar relatórios sobre a precisão da previsão em períodos de tempo específicos","Depurar inconsistências nos níveis de confiança da previsão"],"ru":["Автоматизировать отслеживание прогнозов для заявлений исследователей ИИ","Генерировать отчеты о точности прогнозирования за определенные периоды времени","Отладить несоответствия в уровнях уверенности прогнозирования"],"ar":["تلفيق تتبع التنبؤات للبيانات الصادرة عن باحثي الذكاء الاصطناعي","توليد تقارير حول دقة التنبؤ في فترات زمنية محددة","تصحيح عدم الاتساق في مستويات الثقة بالتنبؤ"]},"limitations":{"en":["Requires manual input of prediction details","Limited to tracking predictions with specified fields (text, author, madeAt, timeframe, topic, confidence)","Optional fields (sourceUrl, target) may not always be available"],"zh":["需要手动输入预测详细信息","仅限跟踪具有指定字段（文本、作者、madeAt、时间范围、主题、置信度）的预测","可选字段（sourceUrl、target）可能并不总是可用"],"ja":["予測の詳細を手動で入力する必要がある","指定されたフィールド（テキスト、著者、madeAt、時間枠、トピック、信頼レベル）を持つ予測のみを追跡可能","オプションフィールド（sourceUrl、target）が常に利用できるわけではない"],"ko":["예측 세부 정보를 수동으로 입력해야 함","지정된 필드(텍스트, 저자, madeAt, 시간 범위, 주제, 신뢰도)가 있는 예측만 추적 가능","옵션 필드(소스 URL, 대상)가 항상 사용 가능하지는 않음"],"es":["Requiere entrada manual de detalles de predicción","Limitado a la seguimiento de predicciones con campos especificados (texto, autor, madeAt, timeframe, tema, confianza)","Campos opcionales (sourceUrl, target) pueden no estar siempre disponibles"],"fr":["Nécessite une entrée manuelle des détails de prédiction","Limité au suivi des prédictions avec des champs spécifiés (texte, auteur, madeAt, cadre temporel, sujet, confiance)","Des champs optionnels (sourceUrl, target) peuvent ne pas être toujours disponibles"],"de":["Benötigt manuelle Eingabe von Vorhersagedetails","Begrenzt auf die Nachverfolgung von Vorhersagen mit angegebenen Feldern (Text, Autor, madeAt, Zeitrahmen, Thema, Vertrauen)","Optionale Felder (sourceUrl, target) sind möglicherweise nicht immer verfügbar"],"pt":["Exige entrada manual de detalhes da previsão","Limitado ao rastreamento de previsões com campos especificados (texto, autor, feitoEm, período de tempo, tópico, confiança)","Campos opcionais (urlDaFonte, destino) podem não estar sempre disponíveis"],"ru":["Требует ручного ввода деталей прогнозирования","Ограничен отслеживанием прогнозов с указанными полями (текст, автор, сделано, временной интервал, тема, уверенность)","Опциональные поля (url-адрес источника, цель) могут не всегда быть доступны"],"ar":["يتطلب إدخال يدوي للتفاصيل المتعلقة بالتنبؤ","محدود بتتبع التنبؤات ذات الحقول المحددة (نص، كاتب، تم في، الفترة الزمنية، الموضوع، الثقة)","الحقول الاختيارية (عنوان URL للمصدر، الهدف) قد لا تكون متاحة دائمًا"]},"version":4},"contentHash":"1d8fddba5c670b4e11f4b1337d3e2f9fe1a5add369bc2313ad0cd274ac6a1956","qualityScore":48}');
