INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('changoo89/claude-pilot/docs-verify', 'docs-verify', 'changoo89', 'claude-pilot', 'community', 'docs-verify changoo89 claude-pilot community docs-verify is a Claude Code workflow engine that automates documentation validation, ensuring compliance with line limits, cross-references, and file counts. It benefits developers by simplifying the documentation process. docs-verify 是一个验证 3-Tier 文档系统的技能，用于检查行限制、交叉引用和文件数量 docs-verify は 3-Tier ドキュメント システムの検証スキルで、行制限、交差参照、ファイル数をチェック docs-verify는 3-Tier 문서 시스템을 검증하는 스킬로, 행 제한, 교차 참조, 파일 수를 확인 docs-verify es una herramienta para validar la documentación de 3 capas, que verifica los límites de línea, referencias cruzadas y recuentos de archivos. Aprende a configurarla para mejorar tu flujo de trabajo docs-verify est un outil pour valider la documentation à 3 niveaux, qui vérifie les limites de ligne, les références croisées et les décomptes de fichiers. Découvrez comment la configurer pour améliorer votre flux de travail docs-verify ist ein Tool zur Überprüfung der Dokumentation von 3 Ebenen, das die Zeilenlimits, Querreferenzen und Dateizählungen überprüft. Erfahren Sie, wie Sie es konfigurieren, um Ihren Arbeitsablauf zu verbessern O docs-verify é uma ferramenta de verificação de documentação automatizada que valida a conformidade com os padrões de documentação de 3 camadas docs-verify - это инструмент автоматизированной верификации документации, который проверяет соответствие документации стандартам документации из 3 уровней для ИИ Агентов docs-verify هو أداة للتحقق التلقائي من المستندات التي تتحقق من مطابقتها لمعايير المستندات من ثلاثة مستويات لأدوات الذكاء الاصطناعي how to use docs-verify docs-verify setup guide what is docs-verify docs-verify alternative docs-verify vs Claude Code automated documentation validation SPEC-first planning TDD automation GPT delegation context engineering docs-verify 文档验证 SPEC-first TDD GPT AIエージェント 文档系统 验证技能 Validates line limits, cross-references, and file counts in documentation Utilizes SPEC-first planning for disciplined documentation Supports TDD automation for efficient testing and validation Employs GPT delegation for intelligent documentation processing Performs context engineering for accurate documentation analysis Executes pure bash link checks with no external dependencies docs-verify is a technical skill that validates 3-Tier documentation system compliance, ensuring adherence to specific guidelines and protocols.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ZhiruiFeng/LocalAgentCrew/stock-picker', 'community', 'ZhiruiFeng', 'LocalAgentCrew', 'ZhiruiFeng/LocalAgentCrew', 'stock-picker', 0, 0, 48, '2026-03-08T01:57:15.312Z', '2026-03-08T02:02:37.748Z', '949bd99817959cc79d7fec00f5c9e245ca03908fdcdfd817f799bfa0dad7a13e', '{"id":"ZhiruiFeng/LocalAgentCrew/stock-picker","name":"stock-picker","description":{"en":"The stock-picker skill is designed for AI agents to screen and select stocks based on quantitative criteria, benefiting developers and traders alike. It enables multi-factor stock screening, value stock identification, and growth stock discovery.","zh":"Stock Picker AIエージェント是一种用于股票筛选和分析的工具，具有多因素筛选、价值股识别和增长股发现等功能","ja":"Stock Picker AIエージェントは、株式分析ツールです。多因素による株式の検索や価値株の特定、成長株の発見などを行うことができます","ko":"Stock Picker는 주식 분석ツール로 주식 선정과 분석을 위한 다양한 기능을 제공합니다. 주식 분석과 투자 전략에 대한 전문 지식 제공","es":"El Stock Picker es un agente especializado en la selección de acciones basadas en criterios cuantitativos. Permite la selección de acciones de valor, crecimiento y dividendos.","fr":"L''agent Stock Picker est spécialisé dans la sélection d''actions basées sur des critères quantitatifs. Il permet la sélection d''actions de valeur, de croissance et de dividendes.","de":"Der Stock Picker ist ein Agent, der auf die Selektion von Aktien basierend auf quantitativen Kriterien spezialisiert ist. Er ermöglicht die Selektion von Aktien mit Wert, Wachstum und Dividenden.","pt":"O Stock Picker é um agente especializado em seleção de ações com base em critérios quantitativos, incluindo valor, crescimento e dividendos. Ele oferece recursos como filtragem de empresas de qualidade e detecção de sinais de momento","ru":"ИИ Агент Stock Picker специализируется на выборе акций по количественным критериям, включая стоимость, рост и дивиденды. Он предлагает функции, такие как фильтрация компаний высокого качества и обнаружение сигналов импульса","ar":"وكيل اختيار الأسهم هو وكيل متخصص في اختيار الأسهم حسب المعايير الكمية، بما في ذلك القيمة والعائد والأسهم الكافعة. يوفر ميزات مثل تصفية الشركات ذات الجودة العالية واكتشاف إشارات الزخم"},"seo":{"title":{"en":"stock-picker: Multi-Factor Stock Screening for AI Agents ...","zh":"股票筛选工具Setup Guide - 使用AIエージェント进行股票分析","ja":"Stock Picker AIエージェントのベストプラクティス - 株式分析ツール","ko":"주식 분석ツール Setup Guide - AI Stock Picker를 사용한 주식 선정","es":"Guía de configuración del Stock Picker para desarrolladores","fr":"Mise en route de l''agent Stock Picker pour les développeurs","de":"Einrichtungsanleitung für den Stock Picker für Entwickler","pt":"Guia de Configuração do Stock Picker: Seleção de Ações Pe...","ru":"Настройка ИИ Агента Stock Picker: Выбор Акций по Критериям","ar":"دليل إعداد وكيل اختيار الأسهم: اختيار أسهم حسب المعايير ا..."},"description":{"en":"Unlock the power of data-driven stock selection with stock-picker. Discover how to activate this AI agent skill for value stock identification, growth stock ...","zh":"了解如何使用Stock Picker AIエージェント进行股票筛选和分析，包括多因素筛选、价值股识别和增长股发现等功能","ja":"Stock Picker AIエージェントの機能と使い方を紹介します。株式分析ツールを使用して、最適な投資戦略を立てよう","ko":"주식 분석ツール인 Stock Picker를 사용하여 주식 선정을 개선하고投資 수익을 높이세요. 주식 분석과 투자 전략에 대한 전문 지식 제공","es":"Descubre cómo utilizar el Stock Picker para seleccionar acciones basadas en criterios cuantitativos. Aprende a configurar y utilizar esta habilidad para tus ...","fr":"Découvrez comment utiliser l''agent Stock Picker pour sélectionner des actions basées sur des critères quantitatifs. Apprenez à configurer et à utiliser cette...","de":"Erfahren Sie, wie Sie den Stock Picker verwenden können, um Aktien basierend auf quantitativen Kriterien auszuwählen. Lernen Sie, wie Sie diese Fähigkeit für...","pt":"Aprenda a configurar o Stock Picker para seleção de ações personalizada com base em critérios quantitativos, incluindo valor, crescimento e dividendos","ru":"Узнайте, как настроить ИИ Агента Stock Picker для выбора акций по критериям, включая стоимость, рост и дивиденды","ar":"تعرف على كيفية إعداد وكيل اختيار الأسهم لاختيار الأسهم حسب المعايير الكمية، بما في ذلك القيمة والعائد والأسهم الكافعة"},"definition":{"en":"stock-picker is a specialized AI agent skill for screening and selecting stocks based on quantitative criteria, including value, growth, quality, momentum, and dividend factors.","zh":"Stock Picker AIエージェント是一种用于股票筛选和分析的AI工具","ja":"Stock Picker AIエージェントは、株式分析のためのAIエージェントです","ko":"Stock Picker는 주식 분석을 위한 AI 주식 선정 도구입니다","es":"El Stock Picker es un agente de inteligencia artificial que selecciona acciones basadas en criterios cuantitativos como valor, crecimiento y dividendos.","fr":"L''agent Stock Picker est un agent d''intelligence artificielle qui sélectionne des actions basées sur des critères quantitatifs tels que la valeur, la croissance et les dividendes.","de":"Der Stock Picker ist ein KI-Agent, der Aktien basierend auf quantitativen Kriterien wie Wert, Wachstum und Dividenden auswählt.","pt":"O Stock Picker é um agente de inteligência artificial que seleciona ações com base em critérios quantitativos","ru":"ИИ Агент Stock Picker - это агент искусственного интеллекта, который выбирает акции по количественным критериям","ar":"وكيل اختيار الأسهم هو وكيل ذكاء اصطناعي يختار الأسهم حسب المعايير الكمية"},"features":{"en":["Multi-factor stock screening for data-driven selection","Value stock identification using quantitative criteria","Growth stock discovery through advanced filtering","Quality company filtering for informed investment decisions","Momentum signal detection for timely stock picks","Custom criteria screening for tailored investment strategies"],"zh":["多因素股票筛选","价值股识别","增长股发现","质量公司过滤","动量信号检测","股息股票选择"],"ja":["多因素による株式の検索","価値株の特定","成長株の発見","質の高い会社のフィルタリング","モメンタム信号の検出","配当株の選択"],"ko":["다중 요소 주식 선정","가치 주식 식별","성장 주식 발견","품질 회사 필터링","모멘텀 신호 감지","배당 주식 선택"],"es":["Selección de acciones de valor","Detección de señales de crecimiento","Filtrado de empresas de calidad","Detección de señales de momentum","Selección de acciones de dividendos","Puntuación y clasificación compuesta"],"fr":["Sélection d''actions de valeur","Détection de signaux de croissance","Filtrage d''entreprises de qualité","Détection de signaux de momentum","Sélection d''actions de dividendes","Notation et classement composite"],"de":["Auswahl von Aktien mit Wert","Erkennung von Wachstumssignalen","Filterung von Unternehmen mit Qualität","Erkennung von Momentum-Signalen","Auswahl von Aktien mit Dividenden","Kompositorische Bewertung und Rangliste"],"pt":["Filtragem de ações por valor","Identificação de ações de crescimento","Filtragem de empresas de qualidade","Detecção de sinais de momento","Seleção de ações com dividendos","Filtragem personalizada por critérios"],"ru":["Фильтрация акций по стоимости","Определение акций роста","Фильтрация компаний высокого качества","Обнаружение сигналов импульса","Выбор акций с дивидендами","Пользовательская фильтрация по критериям"],"ar":["تصفية الأسهم حسب القيمة","تحديد الأسهم ذات العائد","تصفية الشركات ذات الجودة العالية","اكتشاف إشارات الزخم","اختيار الأسهم الكافعة","تصفية مخصصة حسب المعايير"]},"keywords":{"en":["how to use stock-picker","what is stock-picker","stock-picker alternative","stock-picker vs robo-advisors","stock-picker install guide","stock-picker setup for AI agents","multi-factor stock screening tutorial","value stock identification strategies","growth stock discovery with AI"],"zh":["股票筛选","AIエージェント","股票分析","价值股","增长股","多因素筛选","股票投资","股票分析工具"],"ja":["株式分析","AIエージェント","株式検索","価値株","成長株","多因素による検索","株式投資","株式分析ツール"],"ko":["주식 분석","AI 주식 선정","주식 검색","가치 주식","성장 주식","다중 요소 주식 선정","주식 투자","주식 분석ツール"],"es":["Stock Picker","selección de acciones","criterios cuantitativos","acciones de valor","crecimiento","dividendos","desarrollo de aplicaciones","herramientas de inteligencia artificial","agentes de inteligencia artificial"],"fr":["Agent Stock Picker","sélection d''actions","critères quantitatifs","actions de valeur","croissance","dividendes","développement d''applications","outils d''intelligence artificielle","agents d''intelligence artificielle"],"de":["Stock Picker","Auswahl von Aktien","quantitative Kriterien","Aktien mit Wert","Wachstum","Dividenden","Anwendungsentwicklung","KI-Tools","KI-Agenten"],"pt":["stock picker","seleção de ações","critérios quantitativos","valor","crescimento","dividendos","filtragem de empresas","detecção de sinais de momento","Python","CLI"],"ru":["ИИ Агент Stock Picker","выбор акций","количественные критерии","стоимость","рост","дивиденды","фильтрация компаний","обнаружение сигналов импульса","Python","CLI","ИИ Агенты"],"ar":["وكيل اختيار الأسهم","اختيار الأسهم","المعايير الكمية","القيمة","العائد","الأسهم الكافعة","تصفية الشركات","اكتشاف إشارات الزخم","Python","CLI","أدوات الذكاء الاصطناعي"]}},"owner":"ZhiruiFeng","repo":"LocalAgentCrew","repoPath":"ZhiruiFeng/LocalAgentCrew","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.312Z","topics":[],"category":"community","skillMd":{"name":"stock-picker","description":"Screens and selects stocks based on customizable quantitative criteria including value, growth, quality, and momentum factors","bodyPreview":"# Stock Picker Skill\n\nYou are the **Stock Picker Agent** specialized in screening and selecting stocks based on quantitative criteria.\n\n## Capabilities\n- Multi-factor stock screening\n- Value stock identification\n- Growth stock discovery\n- Quality company filtering\n- Momentum signal detection\n- Dividend stock selection\n- Custom criteria screening\n- Composite scoring and ranking\n\n## When to Activate\nActivate this skill when the user requests:\n- \"Find me value stocks\"\n- \"Screen for high-growth comp","body":"# Stock Picker Skill\n\nYou are the **Stock Picker Agent** specialized in screening and selecting stocks based on quantitative criteria.\n\n## Capabilities\n- Multi-factor stock screening\n- Value stock identification\n- Growth stock discovery\n- Quality company filtering\n- Momentum signal detection\n- Dividend stock selection\n- Custom criteria screening\n- Composite scoring and ranking\n\n## When to Activate\nActivate this skill when the user requests:\n- \"Find me value stocks\"\n- \"Screen for high-growth companies\"\n- \"What are the best dividend stocks?\"\n- \"Pick stocks with strong momentum\"\n- \"Screen for quality companies\"\n- \"Find undervalued stocks\"\n- \"Stock screener for [criteria]\"\n\n## Process\n\n1. **Define Criteria**: Establish screening parameters based on user request\n2. **Select Universe**: Determine stock universe (S&P 500, all stocks, sector)\n3. **Apply Filters**: Run quantitative screens\n4. **Score Results**: Calculate composite scores\n5. **Rank Candidates**: Order by overall attractiveness\n6. **Present Findings**: Display results with key metrics\n\n## Preset Screens\n\n### 1. Value Screen\n**Objective**: Find undervalued quality companies\n\n**Criteria**:\n| Metric | Requirement |\n|--------|-------------|\n| P/E Ratio | < 15 |\n| P/B Ratio | < 2.0 |\n| Dividend Yield | > 2% |\n| ROE | > 12% |\n| Debt/Equity | < 1.0 |\n| 5Y Earnings Growth | > 0% |\n\n**Best For**: Patient investors seeking undervalued, dividend-paying stocks\n\n### 2. Growth Screen\n**Objective**: Find high-growth opportunities\n\n**Criteria**:\n| Metric | Requirement |\n|--------|-------------|\n| Revenue Growth (YoY) | > 20% |\n| EPS Growth (YoY) | > 25% |\n| PEG Ratio | < 2.0 |\n| ROE | > 15% |\n| Gross Margin | > 40% |\n| Price > 200-day SMA | Yes |\n\n**Best For**: Growth-oriented investors accepting higher valuations\n\n### 3. Quality Screen\n**Objective**: Find financially strong companies\n\n**Criteria**:\n| Metric | Requirement |\n|--------|-------------|\n| ROE | > 20% |\n| Operating Margin | > 15% |\n| Debt/Equity | < 0.5 |\n| Current Ratio | > 1.5 |\n| Interest Coverage | > 10x |\n| 5+ Years Positive Earnings | Yes |\n\n**Best For**: Conservative investors prioritizing financial stability\n\n### 4. Dividend Screen\n**Objective**: Find reliable dividend payers\n\n**Criteria**:\n| Metric | Requirement |\n|--------|-------------|\n| Dividend Yield | 3% - 8% |\n| Payout Ratio | < 70% |\n| Dividend Growth (5Y) | > 5% |\n| Consecutive Dividend Years | > 10 |\n| Debt/Equity | < 1.0 |\n| FCF > Dividends | Yes |\n\n**Best For**: Income-focused investors seeking sustainable dividends\n\n### 5. Momentum Screen\n**Objective**: Find stocks with strong price momentum\n\n**Criteria**:\n| Metric | Requirement |\n|--------|-------------|\n| Price > 200-day SMA | Yes |\n| Price > 50-day SMA | Yes |\n| RSI (14) | 50 - 70 |\n| 3-Month Return | > 10% |\n| 12-Month Return | > 20% |\n| Volume > 20-day Avg | Yes |\n\n**Best For**: Trend-following traders seeking momentum\n\n### 6. GARP Screen (Growth at Reasonable Price)\n**Objective**: Find growth at reasonable valuations\n\n**Criteria**:\n| Metric | Requirement |\n|--------|-------------|\n| PEG Ratio | < 1.5 |\n| EPS Growth (5Y Est) | > 15% |\n| P/E Ratio | < 25 |\n| ROE | > 15% |\n| Debt/Equity | < 1.0 |\n\n**Best For**: Balanced investors seeking growth with valuation discipline\n\n### 7. Small Cap Value Screen\n**Objective**: Find undervalued small caps\n\n**Criteria**:\n| Metric | Requirement |\n|--------|-------------|\n| Market Cap | $500M - $2B |\n| P/E Ratio | < 15 |\n| P/B Ratio | < 1.5 |\n| ROE | > 10% |\n| Insider Ownership | > 10% |\n| Debt/Equity | < 0.75 |\n\n**Best For**: Investors seeking undiscovered small cap opportunities\n\n### 8. Oversold Quality Screen (超卖的好公司)\n**Objective**: Find quality companies temporarily beaten down\n\n**Technical Criteria (Oversold)**:\n| Metric | Requirement |\n|--------|-------------|\n| RSI (14) | < 30 |\n| Price vs 52-Week High | < -20% |\n| Price vs 200-day SMA | < -10% |\n| Volume | > 1.5x 20-day avg |\n\n**Quality Criteria (Good Company)**:\n| Metric | Requirement |\n|--------|-------------|\n| ROE | > 15% |\n| Operating Margin | > 10% |\n| Debt/Equity | < 1.0 |\n| Current Ratio | > 1.2 |\n| 3+ Years Positive Earnings | Yes |\n| Free Cash Flow | > 0 |\n\n**Best For**: Contrarian investors seeking mean-reversion opportunities in quality names\n\n### 9. Deep Oversold Quality Screen\n**Objective**: Find extremely oversold quality companies\n\n**Criteria**:\n| Metric | Requirement |\n|--------|-------------|\n| RSI (14) | < 25 |\n| RSI (5) | < 20 |\n| Price vs 52-Week High | < -30% |\n| ROE | > 20% |\n| Operating Margin | > 15% |\n| Debt/Equity | < 0.5 |\n| Current Ratio | > 1.5 |\n\n**Best For**: High-conviction contrarian plays on quality names at extreme levels\n\n## Scoring System\n\n### Factor Weights\n| Factor | Weight | Components |\n|--------|--------|------------|\n| Valuation | 25% | P/E, P/B, P/S, EV/EBITDA, FCF Yield |\n| Quality | 25% | ROE, margins, debt ratios, earnings stability |\n| Growth | 20% | Revenue growth, EPS growth, FCF growth |\n| Technical | 15% | Trend, momentum, volume |\n| Risk | 15% | Beta, volatility, drawdown |\n\n### Scoring Scale\n| Score | Interpretation |\n|-------|----------------|\n| 9-10 | Exceptional - Strongly passes all criteria |\n| 7-8 | Strong - Passes most criteria well |\n| 5-6 | Average - Mixed results |\n| 3-4 | Weak - Fails multiple criteria |\n| 1-2 | Poor - Fails most criteria |\n\n## Output Format\n\n### Screening Results Report\n```markdown\n# 📊 Stock Screening Results\n\n**Screen Type**: {Value/Growth/Quality/Dividend/Momentum/Custom}\n**Date**: {Date}\n**Universe**: {S&P 500 / Russell 3000 / Sector / Custom}\n\n## Screening Criteria Applied\n\n| Criteria | Threshold | Filter Type |\n|----------|-----------|-------------|\n| {Metric 1} | {Value} | {Include/Exclude} |\n| {Metric 2} | {Value} | {Include/Exclude} |\n| {Metric 3} | {Value} | {Include/Exclude} |\n...\n\n## Filter Funnel\n\n```\n{Universe Size} stocks in universe\n     ↓ {Filter 1}\n{Count} passed ({%})\n     ↓ {Filter 2}\n{Count} passed ({%})\n     ↓ {Filter 3}\n{Count} passed ({%})\n     ...\n     ↓ Final filters\n{Final Count} stocks in results\n```\n\n## Top 20 Results (Ranked by Composite Score)\n\n| Rank | Symbol | Company | Score | Valuation | Quality | Growth | Technical |\n|------|--------|---------|-------|-----------|---------|--------|-----------|\n| 1 | {TICK} | {Name} | 8.5 | 8.2 | 9.0 | 8.5 | 8.3 |\n| 2 | {TICK} | {Name} | 8.3 | 7.8 | 8.5 | 8.8 | 8.1 |\n| 3 | {TICK} | {Name} | 8.1 | 8.5 | 8.2 | 7.9 | 7.8 |\n...\n\n## Detailed View - Top 5\n\n### #1: {TICKER} - {Company Name}\n**Score**: 8.5/10 | **Sector**: {Sector} | **Market Cap**: ${X}B\n\n| Key Metrics | Value | vs Industry |\n|-------------|-------|-------------|\n| P/E | XX.X | {Better/Worse} |\n| ROE | XX.X% | {Better/Worse} |\n| Growth | XX.X% | {Better/Worse} |\n| Dividend | X.X% | {Better/Worse} |\n\n**Why It Passed**: {1-2 sentence explanation}\n**Key Risk**: {Main risk factor}\n\n---\n\n### #2: {TICKER} - {Company Name}\n[Similar format]\n\n...\n\n## Sector Distribution\n\n| Sector | Count | % of Results |\n|--------|-------|--------------|\n| Technology | X | XX% |\n| Healthcare | X | XX% |\n| Financials | X | XX% |\n| Consumer | X | XX% |\n| Industrial | X | XX% |\n| Other | X | XX% |\n\n## Market Cap Distribution\n\n| Size | Count | % of Results |\n|------|-------|--------------|\n| Large Cap (>$10B) | X | XX% |\n| Mid Cap ($2-10B) | X | XX% |\n| Small Cap (<$2B) | X | XX% |\n\n## Key Observations\n\n1. **Sector Concentration**: {Observation about sector distribution}\n2. **Valuation Range**: {Observation about valuation spreads}\n3. **Quality Metrics**: {Observation about quality characteristics}\n4. **Technical Setup**: {Observation about technical patterns}\n\n## Watch List Recommendations\n\nBased on this screen, consider adding to watch list:\n- **{TICKER}**: {Brief reason - e.g., \"Strong value with improving momentum\"}\n- **{TICKER}**: {Brief reason}\n- **{TICKER}**: {Brief reason}\n\n## Screening Notes\n\n⚠️ **Important Considerations**:\n- Screens are point-in-time and should be re-run regularly\n- Quantitative screens don''t capture qualitative factors\n- Results require further due diligence before investing\n- Past performance doesn''t guarantee future results\n\n---\n*Screen run on {Date} at {Time}*\n*Data as of {Data Date}*\n```\n\n## Custom Screening\n\nUsers can request custom criteria:\n\n**Example**: \"Screen for stocks with P/E under 20, ROE over 15%, and positive momentum\"\n\n**Response**: Apply custom filters and present results using standard format.\n\n### Common Custom Criteria\n- Market cap ranges\n- Sector/industry filters\n- Geographic filters\n- Index membership\n- Specific ratio thresholds\n- Technical conditions\n- Dividend requirements\n\n## Constraints\n- Use current market data (note staleness)\n- Results are for research, not recommendations\n- Quantitative screens have limitations\n- Note missing data for any stock\n- Screens should be re-run periodically\n- Do your own due diligence on results\n"},"lastSynced":"2026-03-08T02:02:37.748Z","agentAnalysis":{"suitability":{"en":"Perfect for Finance Agents needing advanced quantitative stock screening capabilities.","zh":"非常适合需要高级量化股票筛选功能的金融代理。","ja":"高度な量化的ストックスクリーニング機能を必要とするファイナンスエージェントに最適です。","ko":"고급 양적 주식 스크리닝 기능이 필요한 금융 에이전트에게 최적입니다.","es":"Perfecto para agentes de finanzas que necesitan capacidades avanzadas de selección de acciones cuantitativas.","fr":"Parfait pour les agents de finance ayant besoin de capacités de sélection d''actions quantitatives avancées.","de":"Perfekt für Finanzagenten, die erweiterte quantitative Aktienauswahl-Funktionen benötigen.","pt":"Perfeito para Agentes de Finanças que precisam de capacidades avançadas de triagem quantitativa de ações.","ru":"Идеально подходит для финансовых агентов, которым требуются продвинутые возможности количественной отборки акций.","ar":"مثالي لوكلاء التمويل الذين يحتاجون إلى قدرات متقدمة لفرز الأسهم الكمية."},"recommendation":{"en":"Empowers agents to screen and select stocks based on multi-factor criteria, including value stock identification, growth stock discovery, and custom criteria screening, utilizing composite scoring and ranking methodologies.","zh":"赋予代理人根据多因素标准筛选和选择股票的能力，包括价值股票识别、增长股票发现和自定义标准筛选，利用复合评分和排名方法。","ja":"エージェントに、価値株識別、成長株発見、カスタム基準スクリーニングなど、多要因基準に基づいて株式をスクリーンして選択する能力を付与します。コンポジットスコアリングおよびランキング手法を使用します。","ko":"에이전트가 가치 주식 식별, 성장 주식 발견, 사용자 정의 기준 스크리닝 등을 포함한 다중 요인 기준에 따라 주식을 스크리닝하고 선택할 수 있는 능력을 부여합니다. 복합 평가 및 순위 방법을 사용합니다.","es":"Habilita a los agentes a seleccionar y elegir acciones en función de criterios multifactoriales, incluida la identificación de acciones de valor, el descubrimiento de acciones de crecimiento y la selección de criterios personalizados, utilizando metodologías de puntuación y clasificación compuestas.","fr":"Permet aux agents de sélectionner et de choisir des actions en fonction de critères multifactoriels, notamment l''identification d''actions de valeur, la découverte d''actions de croissance et la sélection de critères personnalisés, en utilisant des méthodologies de notation et de classement composites.","de":"Ermächtigt Agenten, Aktien auf Basis multifaktorieller Kriterien auszuwählen und zu selektieren, einschließlich der Identifizierung von Wertpapieren, der Entdeckung von Wachstumspapieren und der Auswahl benutzerdefinierter Kriterien, unter Verwendung von Composite-Scoring- und Ranking-Methoden.","pt":"Habilita os agentes a selecionar e filtrar ações com base em critérios multifatoriais, incluindo identificação de ações de valor, descoberta de ações de crescimento e filtragem personalizada, utilizando metodologias de pontuação e classificação compostas.","ru":"Наделяет агентов возможностью отбирать и выбирать акции на основе многокритериальных показателей, включая выявление акций стоимости, открытие акций роста и индивидуальную отборку, используя методологии составного баллов и рейтинга.","ar":"تمكّن الوكلاء من فرز واختيار الأسهم بناءً على معايير متعددة، بما في ذلك تحديد الأسهم القيمة واكتشاف الأسهم النامية والفرز المخصص، باستخدام منهجيات التقييم التركيبي والتصنيف."},"useCases":{"en":["Automating value stock identification","Generating growth stock discovery reports","Filtering quality companies based on momentum signals"],"zh":["自动进行价值股票识别","生成增长股票发现报告","根据动量信号筛选高质量公司"],"ja":["価値株識別の自動化","成長株発見レポートの生成","モメンタム信号に基づく高品質会社のフィルタリング"],"ko":["가치 주식 식별 자동화","성장 주식 발견 보고서 생성","모멘텀 신호 기반 고품질 회사 필터링"],"es":["Automatización de la identificación de acciones de valor","Generación de informes de descubrimiento de acciones de crecimiento","Filtrado de empresas de calidad en función de señales de impulso"],"fr":["Automatisation de l''identification d''actions de valeur","Génération de rapports de découverte d''actions de croissance","Filtrage d''entreprises de qualité en fonction de signaux de mouvement"],"de":["Automatisierung der Identifizierung von Wertpapieren","Erstellung von Berichten zur Entdeckung von Wachstumspapieren","Filtern von Qualitätsgesellschaften basierend auf Impulssignalen"],"pt":["Automatizar a identificação de ações de valor","Gerar relatórios de descoberta de ações de crescimento","Filtrar empresas de qualidade com base em sinais de momento"],"ru":["Автоматизировать выявление акций стоимости","Генерировать отчеты об открытии акций роста","Фильтровать качественные компании на основе сигналов импульса"],"ar":["التحكم الآلي في تحديد الأسهم القيمة","إنتاج تقارير عن اكتشاف الأسهم النامية","ترشيح الشركات الجودة بالاعتماد على إشارات الزخم"]},"limitations":{"en":["Requires historical stock data access","Dependent on quantitative criteria accuracy"],"zh":["需要历史股票数据访问","依赖于量化标准的准确性"],"ja":["歴史的な株式データへのアクセスが必要","量化基準の精度に依存"],"ko":["역사적인 주식 데이터 액세스가 필요","量화 기준의 정확도에 의존"],"es":["Requiere acceso a datos históricos de acciones","Dependiente de la precisión de los criterios cuantitativos"],"fr":["Nécessite un accès aux données historiques des actions","Dépend de l''exactitude des critères quantitatifs"],"de":["Benötigt Zugriff auf historische Aktien-Daten","Abhängig von der Genauigkeit der quantitativen Kriterien"],"pt":["Requer acesso a dados históricos de ações","Dependente da precisão dos critérios quantitativos"],"ru":["Требует доступа к историческим данным акций","Зависит от точности количественных критериев"],"ar":["يتطلب الوصول إلى بيانات الأسهم التاريخية","يعتمد على دقة المعايير الكمية"]},"version":4},"contentHash":"949bd99817959cc79d7fec00f5c9e245ca03908fdcdfd817f799bfa0dad7a13e","qualityScore":48}');
