INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ZhiruiFeng/LocalAgentCrew/stock-picker', 'stock-picker', 'ZhiruiFeng', 'LocalAgentCrew', 'community', 'stock-picker ZhiruiFeng LocalAgentCrew community The stock-picker skill is designed for AI agents to screen and select stocks based on quantitative criteria, benefiting developers and traders alike. It enables multi-factor stock screening, value stock identification, and growth stock discovery. Stock Picker AIエージェント是一种用于股票筛选和分析的工具，具有多因素筛选、价值股识别和增长股发现等功能 Stock Picker AIエージェントは、株式分析ツールです。多因素による株式の検索や価値株の特定、成長株の発見などを行うことができます Stock Picker는 주식 분석ツール로 주식 선정과 분석을 위한 다양한 기능을 제공합니다. 주식 분석과 투자 전략에 대한 전문 지식 제공 El Stock Picker es un agente especializado en la selección de acciones basadas en criterios cuantitativos. Permite la selección de acciones de valor, crecimiento y dividendos. L''agent Stock Picker est spécialisé dans la sélection d''actions basées sur des critères quantitatifs. Il permet la sélection d''actions de valeur, de croissance et de dividendes. Der Stock Picker ist ein Agent, der auf die Selektion von Aktien basierend auf quantitativen Kriterien spezialisiert ist. Er ermöglicht die Selektion von Aktien mit Wert, Wachstum und Dividenden. O Stock Picker é um agente especializado em seleção de ações com base em critérios quantitativos, incluindo valor, crescimento e dividendos. Ele oferece recursos como filtragem de empresas de qualidade e detecção de sinais de momento ИИ Агент Stock Picker специализируется на выборе акций по количественным критериям, включая стоимость, рост и дивиденды. Он предлагает функции, такие как фильтрация компаний высокого качества и обнаружение сигналов импульса وكيل اختيار الأسهم هو وكيل متخصص في اختيار الأسهم حسب المعايير الكمية، بما في ذلك القيمة والعائد والأسهم الكافعة. يوفر ميزات مثل تصفية الشركات ذات الجودة العالية واكتشاف إشارات الزخم how to use stock-picker what is stock-picker stock-picker alternative stock-picker vs robo-advisors stock-picker install guide stock-picker setup for AI agents multi-factor stock screening tutorial value stock identification strategies growth stock discovery with AI 股票筛选 AIエージェント 股票分析 价值股 增长股 多因素筛选 股票投资 股票分析工具 Multi-factor stock screening for data-driven selection Value stock identification using quantitative criteria Growth stock discovery through advanced filtering Quality company filtering for informed investment decisions Momentum signal detection for timely stock picks Custom criteria screening for tailored investment strategies stock-picker is a specialized AI agent skill for screening and selecting stocks based on quantitative criteria, including value, growth, quality, momentum, and dividend factors.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ludiscan/ludiscan-webapp/pre-push-quality-checks', 'community', 'ludiscan', 'ludiscan-webapp', 'ludiscan/ludiscan-webapp', 'pre-push-quality-checks', 0, 0, 48, '2026-03-08T01:57:15.315Z', '2026-03-08T02:02:46.105Z', 'e9008edd2bbe3d4f3fbf4e918f2876ef499cb9450867ae45cdddb9185c15691c', '{"id":"ludiscan/ludiscan-webapp/pre-push-quality-checks","name":"pre-push-quality-checks","description":{"en":"The pre-push-quality-checks skill automates code review for developers, ensuring high-quality code before pushing changes. It integrates with Git and supports commands like `gh pr create` and `git push`.","zh":"pre-push-quality-checks 是一个代码质量检查工具，用于确保代码质量和一致性。它提供了代码分析和服务器管理功能","ja":"pre-push-quality-checks はコード品質チェックツールであり、コード品質と一貫性を確保するために使用されます。コード分析とサーバー管理機能を提供します","ko":"pre-push-quality-checks는 코드 품질을 확인하고 일관성을 유지하기 위한 코드 품질 검사 도구입니다. 코드 분석 및 서버 관리 기능을 제공합니다","es":"El skill pre-push-quality-checks analiza y verifica la calidad del código antes de realizar un push a Git, utilizando tecnologías como CLI y Git","fr":"Le skill pre-push-quality-checks analyse et vérifie la qualité du code avant de pousser vers Git, en utilisant des technologies comme CLI et Git","de":"Das Skill pre-push-quality-checks analysiert und überprüft die Qualität des Codes vor dem Pushen zu Git, unter Verwendung von Technologien wie CLI und Git","pt":"O pre-push-quality-checks é uma ferramenta que ajuda a garantir a qualidade do código antes de fazer push para o repositório Git","ru":"Pre-push-quality-checks - это инструмент, который помогает обеспечить качество кода перед отправкой в репозиторий Git","ar":"الفحص النوعي قبل الدفع هو أداة تساعد على ضمان جودة الكود قبل دفعها إلى مستودع جيت"},"seo":{"title":{"en":"pre-push-quality-checks: Automated Code Review Setup Guid...","zh":"pre-push-quality-checks 设置指南：代码质量检查最佳实践","ja":"pre-push-quality-checks セットアップガイド：コード品質チェックのベストプラクティス","ko":"pre-push-quality-checks 설정 가이드: 코드 품질 검사 최적화","es":"Guía de configuración de pre-push-quality-checks para des...","fr":"Guide d''installation des vérifications de qualité préalab...","de":"Einrichtungsleitfaden für pre-push-quality-checks für Ent...","pt":"Guia de Configuração de Pre-Push-Quality-Checks para Dese...","ru":"Настройка Pre-Push-Quality-Checks: ИИ Агенты для Разработ...","ar":"دليل إعداد الفحص النوعي قبل الدفع للبرمجة"},"description":{"en":"Ensure code quality before pushing changes with pre-push-quality-checks. Learn how to install and use this AI agent skill to streamline your development work...","zh":"了解 pre-push-quality-checks 的技术细节和使用场景，优化代码质量和开发效率","ja":"pre-push-quality-checks の技術的詳細と使用シーンを理解し、コード品質と開発効率を最適化する","ko":"pre-push-quality-checks의 기술적 세부 정보와 사용 시나리오를 이해하고 코드 품질 및 개발 효율성을 최적화하십시오","es":"Aprende a configurar pre-push-quality-checks para mejorar la calidad de tu código antes de realizar un push a Git","fr":"Découvrez comment configurer les vérifications de qualité préalables pour améliorer la qualité de votre code avant de pousser vers Git","de":"Erfahren Sie, wie Sie pre-push-quality-checks einrichten, um die Qualität Ihres Codes vor dem Pushen zu Git zu verbessern","pt":"Aprenda a configurar pre-push-quality-checks para melhorar a qualidade do seu código antes de fazer push para o repositório Git","ru":"Узнайте, как настроить pre-push-quality-checks для повышения качества кода перед отправкой в репозиторий Git","ar":"تعرف على كيفية إعداد الفحص النوعي قبل الدفع لتحسين جودة كودك قبل دفعها إلى مستودع جيت"},"definition":{"en":"pre-push-quality-checks is a skill that automates quality checks for code changes, analyzing functionality and server management before pushing updates to Git.","zh":"pre-push-quality-checks 是一个自动化代码质量检查工具，用于在代码提交前检查代码质量和一致性","ja":"pre-push-quality-checks は自動化コード品質チェックツールであり、コードの品質と一貫性をコミット前にチェックするために使用されます","ko":"pre-push-quality-checks는 자동화된 코드 품질 검사 도구로 코드를 제출하기 전에 코드의 품질과 일관성을 확인하는 데 사용됩니다","es":"Pre-push-quality-checks es un skill que realiza verificaciones de calidad en el código antes de realizar un push a Git","fr":"Les vérifications de qualité préalables sont un skill qui effectue des vérifications de qualité dans le code avant de pousser vers Git","de":"Pre-push-quality-checks ist ein Skill, der Qualitätssicherungen im Code durchführt, bevor er zu Git gepusht wird","pt":"Pre-push-quality-checks é uma ferramenta de análise de código que executa verificações de qualidade antes de fazer push para o repositório Git","ru":"Pre-push-quality-checks - это инструмент анализа кода, который выполняет проверки качества перед отправкой в репозиторий Git","ar":"الفحص النوعي قبل الدفع هو أداة تحليل كود تقوم بتشغيل فحوصات جودة قبل دفعها إلى مستودع جيت"},"features":{"en":["Runs quality checks before creating a PR with `gh pr create`","Installs dependencies with `bun install` to ensure a smooth review process","Supports skipping checks for documentation-only changes, such as README.md updates","Analyzes code changes in the `src/` directory to identify potential issues","Allows users to explicitly request quality checks for specific changes"],"zh":["自动安装依存关系","代码分析和检查","服务器管理功能","支持 Git push 和 PR 创建","代码质量检查和报告"],"ja":["依存関係の自動インストール","コード分析とチェック","サーバー管理機能","Git push と PR 作成のサポート","コード品質チェックと報告"],"ko":["의존성 자동 설치","코드 분석 및 확인","서버 관리 기능","Git 푸시 및 PR 생성 지원","코드 품질 확인 및 보고"],"es":["Instalación de dependencias con bun install","Verificación de calidad del código antes de realizar un push a Git","Compatibilidad con tecnologías como CLI y Git","Análisis de código en src/ y otros directorios","Soporte para PR y cambios de código"],"fr":["Installation des dépendances avec bun install","Vérification de la qualité du code avant de pousser vers Git","Compatibilité avec des technologies comme CLI et Git","Analyse de code dans src/ et d''autres répertoires","Prise en charge des PR et des modifications de code"],"de":["Installation von Abhängigkeiten mit bun install","Qualitätsüberprüfung des Codes vor dem Pushen zu Git","Kompatibilität mit Technologien wie CLI und Git","Code-Analyse in src/ und anderen Verzeichnissen","Unterstützung für PR und Code-Änderungen"],"pt":["Verificação de dependências com ''bun install''","Análise de código antes de fazer push para o repositório Git","Suporte a verificações de qualidade personalizadas","Integração com o fluxo de trabalho do Git","Verificação de alterações no código antes de fazer push"],"ru":["Проверка зависимостей с помощью ''bun install''","Анализ кода перед отправкой в репозиторий Git","Поддержка пользовательских проверок качества","Интеграция с рабочим процессом Git","Проверка изменений в коде перед отправкой"],"ar":["فحص الإعتماديات باستخدام ''bun install''","تحليل الكود قبل دفعها إلى مستودع جيت","دعم الفحوصات النوعية المخصصة","التكامل مع تدفق العمل جيت","فحص التغييرات في الكود قبل دفعها"]},"keywords":{"en":["how to use pre-push-quality-checks","pre-push-quality-checks setup guide","automated code review tools","pre-push-quality-checks vs git hooks","pre-push-quality-checks install","what is pre-push-quality-checks","pre-push-quality-checks alternative","pre-push-quality-checks and Git integration"],"zh":["pre-push-quality-checks","代码质量检查","自动化代码检查","代码分析","服务器管理","Git push","PR 创建","代码一致性","AIエージェント"],"ja":["pre-push-quality-checks","コード品質チェック","自動化コードチェック","コード分析","サーバー管理","Git push","PR 作成","コード一貫性","AIエージェント"],"ko":["pre-push-quality-checks","코드 품질 확인","자동화 코드 확인","코드 분석","서버 관리","Git 푸시","PR 생성","코드 일관성","AI 에이전트"],"es":["pre-push-quality-checks","verificaciones de calidad","CLI","Git","desarrollo de software","calidad de código","pruebas de calidad","herramientas de desarrollo"],"fr":["vérifications de qualité préalables","analyse de code","CLI","Git","développement de logiciels","qualité de code","tests de qualité","outils de développement"],"de":["pre-push-quality-checks","Qualitätssicherungen","CLI","Git","Software-Entwicklung","Code-Qualität","Qualitäts-Tests","Entwickler-Tools"],"pt":["pre-push-quality-checks","ferramenta de análise de código","verificação de qualidade","git","desenvolvimento de software","análise de código antes de fazer push","verificação de dependências","integração com o fluxo de trabalho do Git"],"ru":["pre-push-quality-checks","инструмент анализа кода","проверка качества","git","разработка программного обеспечения","анализ кода перед отправкой","проверка зависимостей","интеграция с рабочим процессом Git"],"ar":["الفحص النوعي قبل الدفع","أداة تحليل الكود","فحص الجودة","جيت","تطوير البرمجيات","تحليل الكود قبل دفعها","فحص الإعتماديات","التكامل مع تدفق العمل جيت"]}},"owner":"ludiscan","repo":"ludiscan-webapp","repoPath":"ludiscan/ludiscan-webapp","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.315Z","topics":[],"category":"community","skillMd":{"name":"pre-push-quality-checks","description":"PR作成・git push前に必ず使用。bun install → fix → format → type → lint を順番に実行。","bodyPreview":"## When to Use This Skill\n\nこのスキルは以下の場合に**必ず**実行してください:\n\n1. **PR作成前** - `gh pr create` を実行する前\n2. **Git push前** - `git push` を実行する前\n3. **コード変更後** - src/ 配下のファイルを変更した後\n4. **ユーザーが明示的に品質チェックを要求した場合**\n\n## When NOT to Use This Skill\n\n以下の場合はこのスキルをスキップできます:\n\n1. ドキュメントのみの変更 (README.md, CLAUDE.md等)\n2. 設定ファイルのみの変更 (.gitignore, .envファイル等)\n3. src/ 配下のコードが変更されていない場合\n\n## Quality Check Process\n\n### Step 0: Install Dependencies (MANDATORY)\n\n**まず最初に、必ず依存関係をインストールしてください:**\n\n```bash\nbun install\n```\n\n**重要**: このステップをス","body":"## When to Use This Skill\n\nこのスキルは以下の場合に**必ず**実行してください:\n\n1. **PR作成前** - `gh pr create` を実行する前\n2. **Git push前** - `git push` を実行する前\n3. **コード変更後** - src/ 配下のファイルを変更した後\n4. **ユーザーが明示的に品質チェックを要求した場合**\n\n## When NOT to Use This Skill\n\n以下の場合はこのスキルをスキップできます:\n\n1. ドキュメントのみの変更 (README.md, CLAUDE.md等)\n2. 設定ファイルのみの変更 (.gitignore, .envファイル等)\n3. src/ 配下のコードが変更されていない場合\n\n## Quality Check Process\n\n### Step 0: Install Dependencies (MANDATORY)\n\n**まず最初に、必ず依存関係をインストールしてください:**\n\n```bash\nbun install\n```\n\n**重要**: このステップをスキップすると、lintやtype checkが失敗する可能性があります。**必ず実行してください。**\n\n### Step 1: Run Auto-Fix Commands\n\nまず、自動修正可能な問題を修正します:\n\n```bash\n# 1. ESLintとStylelintの自動修正\nbun run fix\n\n# 2. Prettierでコード整形\nbun run format\n```\n\n**重要**: これらのコマンドでファイルが変更された場合、変更をgit addする必要があります。\n\n### Step 2: Run Type Check\n\nTypeScript型チェックを実行します:\n\n```bash\nbun run type\n```\n\n**型エラーが1つでもある場合、PRやpushは禁止です。**\n\n### Step 3: Final Lint Check\n\n最終的なlintチェックを実行します:\n\n```bash\nbun run lint\n```\n\n**lintエラーが1つでもある場合、PRやpushは禁止です。**\n\n## Complete Workflow\n\n### For PR Creation\n\nPR作成時は以下の順序で実行してください:\n\n```markdown\n0. `bun install` を実行 (MANDATORY - 最初に必ず実行)\n1. コード変更を完了\n2. `bun run fix` を実行 → ファイルが変更された場合は git add\n3. `bun run format` を実行 → ファイルが変更された場合は git add\n4. `bun run type` を実行 → エラーがある場合は修正して再度実行\n5. `bun run lint` を実行 → エラーがある場合は修正して再度実行\n6. すべてのチェックが通ったら git commit\n7. git push\n8. gh pr create\n```\n\n**エラーが発生した場合**:\n\n- 型エラーの場合: エラーメッセージを読み、該当ファイルを修正\n- lintエラーの場合: エラーメッセージを読み、該当ファイルを修正\n- 自動修正で解決しない場合: 手動で修正\n\n### For Git Push\n\ngit push前は以下の順序で実行してください:\n\n```markdown\n0. `bun install` を実行 (MANDATORY - 最初に必ず実行)\n1. コード変更を完了\n2. `bun run fix` を実行 → ファイルが変更された場合は git add\n3. `bun run format` を実行 → ファイルが変更された場合は git add\n4. `bun run type` を実行 → エラーがある場合は修正して再度実行\n5. `bun run lint` を実行 → エラーがある場合は修正して再度実行\n6. すべてのチェックが通ったら git commit\n7. git push\n```\n\n## CRITICAL: All Errors Must Be Fixed\n\n**🚨 絶対に守るべきルール 🚨**\n\n検出された**すべてのエラー**を修正する必要があります。以下の言い訳は**一切認められません**:\n\n❌ **禁止される言い訳**:\n- ❌ 「このエラーは既存のもので、私の変更によるものではありません」\n- ❌ 「このエラーは以前から存在していました」\n- ❌ 「この型エラーは自分のコードとは関係ありません」\n- ❌ 「このlintエラーは別の人が作ったコードです」\n\n✅ **正しい対応**:\n- ✅ 検出されたエラーが既存のものであっても、**全て修正する**\n- ✅ エラーの原因が自分の変更かどうかに関わらず、**全て修正する**\n- ✅ エラーが見つかった時点で、**その場で全て修正する**\n\n**理由**:\n- コード品質を維持するためには、既存のエラーも含めて全て修正する必要があります\n- 「既存のエラー」という概念は品質チェックにおいては存在しません\n- エラーが検出された時点で、それは修正すべき問題です\n\n**重要**: このルールに違反した場合、PRやpushは**絶対に許可されません**。\n\n## Error Handling\n\n### Type Errors\n\n型エラーが発生した場合:\n\n```bash\n# エラーメッセージ例:\nsrc/component/atoms/Button.tsx(15,7): error TS2322: Type ''string'' is not assignable to type ''number''.\n```\n\n**対処法**:\n1. エラーメッセージから該当ファイルと行番号を特定\n2. ファイルを開いて問題を確認\n3. 型を修正\n4. 再度 `bun run type` を実行して確認\n\n**絶対にやってはいけないこと**:\n- ❌ `any` 型を使用してエラーを隠す\n- ❌ `@ts-ignore` コメントでエラーを無視する\n- ❌ 型チェックをスキップする\n\n### Lint Errors\n\nlintエラーが発生した場合:\n\n```bash\n# エラーメッセージ例:\nsrc/component/atoms/Button.tsx\n  15:7  error  ''handleClick'' is assigned a value but never used  @typescript-eslint/no-unused-vars\n```\n\n**対処法**:\n1. `bun run fix` で自動修正を試みる\n2. 自動修正できない場合、エラーメッセージを読んで手動で修正\n3. 再度 `bun run lint` を実行して確認\n\n**よくあるlintエラーと対処法**:\n- `no-unused-vars`: 未使用の変数を削除するか、使用する\n- `@typescript-eslint/no-explicit-any`: `any` 型を適切な型に置き換える\n- `react-hooks/exhaustive-deps`: useEffectの依存配列を修正\n\n## Integration with Other Skills\n\nこのスキルは他のスキルと組み合わせて使用してください:\n\n### With Implementation Planning Skill\n\n実装計画の最終ステップとしてこのスキルを実行:\n\n```markdown\n## Implementation Steps\n\n### 5. Final Quality Checks (最終ステップ)\n**Status**: PENDING\n\n**What to do**:\n- Run `bun install` to ensure dependencies are installed (MANDATORY)\n- Run `bun run fix` to auto-fix linting issues\n- Run `bun run format` to format code\n- Run `bun run type` to check TypeScript errors\n- Run `bun run lint` to verify no linting errors\n- Fix ALL errors found (既存のエラーも含めて全て修正)\n- Commit any changes from auto-fix\n- Ready for PR creation\n\n**Completion criteria**:\n- Dependencies installed successfully\n- Type check passes (no errors - including existing errors)\n- Lint check passes (no errors - including existing errors)\n- All code properly formatted\n- No excuses about \"existing errors\" - all errors must be fixed\n```\n\n## Example Execution\n\n### Successful Case\n\n```bash\n# Step 0: Install dependencies (MANDATORY)\n$ bun install\n✓ Dependencies installed successfully\n\n# Step 1: Auto-fix\n$ bun run fix\n✓ ESLint: Fixed 5 issues automatically\n✓ Stylelint: Fixed 2 issues automatically\n\n# ファイルが変更された場合\n$ git add .\n\n# Step 2: Format\n$ bun run format\n✓ Prettier: Formatted 10 files\n\n# ファイルが変更された場合\n$ git add .\n\n# Step 3: Type check\n$ bun run type\n✓ No type errors found\n\n# Step 4: Lint check\n$ bun run lint\n✓ ESLint: No errors found\n✓ Stylelint: No errors found\n\n# すべて成功 - PRやpush可能\n✅ All quality checks passed! Ready to push/create PR.\n```\n\n### Error Case\n\n```bash\n# Step 0: Install dependencies (MANDATORY)\n$ bun install\n✓ Dependencies installed successfully\n\n# Step 1: Auto-fix\n$ bun run fix\n✓ ESLint: Fixed 5 issues automatically\n\n# Step 2: Format\n$ bun run format\n✓ Prettier: Formatted 10 files\n\n# Step 3: Type check\n$ bun run type\n❌ Error: Type errors found\n\nsrc/component/atoms/Button.tsx(15,7): error TS2322: Type ''string'' is not assignable to type ''number''.\n\n# ⚠️ 重要: このエラーが既存のものでも、必ず修正してください\n# 「既存のエラー」という言い訳は認められません\n\n# エラーを修正する\n# ... ファイルを修正 ...\n\n# 再度type checkを実行\n$ bun run type\n✓ No type errors found\n\n# Step 4: Lint check\n$ bun run lint\n✓ ESLint: No errors found\n✓ Stylelint: No errors found\n\n# すべて成功\n✅ All quality checks passed! Ready to push/create PR.\n```\n\n## Reporting to User\n\n品質チェック完了後、ユーザーに結果を報告してください:\n\n### Success Report\n\n```markdown\n✅ コード品質チェックが完了しました\n\n**実行したチェック:**\n- [x] bun install (dependencies)\n- [x] ESLint & Stylelint auto-fix\n- [x] Prettier format\n- [x] TypeScript type check\n- [x] Final lint check\n\n**結果:**\n- 型エラー: 0件\n- Lintエラー: 0件\n- フォーマット: 完了\n\nPRの作成またはpushを実行できます。\n```\n\n### Error Report\n\n```markdown\n⚠️ コード品質チェックでエラーが見つかりました\n\n**実行したチェック:**\n- [x] bun install (dependencies)\n- [x] ESLint & Stylelint auto-fix\n- [x] Prettier format\n- [ ] TypeScript type check (エラーあり)\n\n**エラー詳細:**\n```\nsrc/component/atoms/Button.tsx(15,7): error TS2322: Type ''string'' is not assignable to type ''number''.\n```\n\n⚠️ **重要**: このエラーが既存のものでも、必ず修正してください。\n「既存のエラー」や「私の変更によるものではない」という言い訳は認められません。\n\nエラーを修正してから、再度チェックを実行してください。\n```\n\n## Important Notes\n\n1. **必ず`bun install`から開始** - 最初に依存関係をインストールしてください\n2. **品質チェックは必須です** - スキップしないでください\n3. **すべてのエラーを修正** - 既存のエラーも含めて、検出された全てのエラーを修正してください\n4. **エラーがある場合、PRやpushは禁止** - すべてのエラーを修正してください\n5. **自動修正を優先** - `bun run fix` と `bun run format` を先に実行\n6. **型安全性を維持** - `any` 型や `@ts-ignore` でエラーを隠さない\n7. **言い訳は禁止** - 「既存のエラー」や「私の変更ではない」という言い訳は認められません\n8. **ユーザーに報告** - チェック結果を明確に伝える\n\n## Automation Reminder\n\nこのスキルは以下のタイミングで**自動的に**実行されるべきです:\n\n- ✅ ユーザーがPR作成を依頼したとき\n- ✅ ユーザーがgit pushを依頼したとき\n- ✅ 実装計画の最終ステップとして\n- ✅ コード変更が完了したとき\n\n**ユーザーが明示的に依頼しなくても、Claude Codeは自動的にこのスキルを実行してください。**\n\n## Summary\n\nこのスキルにより以下が保証されます:\n\n1. **依存関係の整合性** - `bun install`により常に最新の依存関係が利用可能\n2. **コード品質の一貫性** - すべてのコードがlintとformatルールに従う\n3. **型安全性** - TypeScriptエラーがない状態を維持\n4. **スムーズなCI/CD** - ローカルでチェックするため、CIでのエラーを防ぐ\n5. **効率的な開発** - 自動修正により手動修正の手間を削減\n6. **完全なエラー修正** - 既存のエラーも含めて全て修正され、コードベース全体の品質が向上\n\n**Remember**:\n- **必ず`bun install`から開始してください**\n- 品質チェックは面倒に見えますが、長期的にはバグを減らし、コードの保守性を高めます\n- **「既存のエラー」という言い訳は絶対に認められません** - 検出されたエラーは全て修正してください\n- 絶対にスキップしないでください\n"},"lastSynced":"2026-03-08T02:02:46.105Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents requiring automated Git integration and quality checks","zh":"适用于需要自动化Git集成和质量检查的代码审查代理","ja":"コードレビュー代理が自動化されたGit統合と品質チェックを必要とする場合に最適","ko":"코드 리뷰 에이전트가 자동화된 Git 통합 및 품질 확인을 필요로 할 때 적합","es":"Ideal para Agentes de Revisión de Código que requieren integración automática de Git y comprobaciones de calidad","fr":"Idéal pour les Agents de Révision de Code nécessitant une intégration automatique de Git et des contrôles de qualité","de":"Ideal für Code-Review-Agenten, die eine automatisierte Git-Integration und Qualitätsprüfungen erfordern","pt":"Ideal para Agentes de Revisão de Código que exigem integração automática do Git e verificações de qualidade","ru":"Идеально для агентов кодового обзора, требующих автоматической интеграции Git и проверок качества","ar":"مثالي للوكلاء المراجعة للرمز الذين يتطلبون دمج Git التلقائي وفحوصات الجودة"},"recommendation":{"en":"Empowers agents to enforce high-quality code standards by automating reviews with Git and supporting commands like `gh pr create` and `git push`, ensuring consistency and reliability in code changes, particularly in src/ directory files","zh":"通过自动化代码审查和支持诸如`gh pr create`和`git push`之类的命令，赋予代理执行高质量代码标准的能力，确保代码更改的一致性和可靠性，特别是在src/目录文件中","ja":"コードの自動レビューと`gh pr create`および`git push`などのコマンドをサポートすることで、高品質なコード標準を実施するエージェントを可能にし、特にsrc/ディレクトリのファイルにおいてコード変更の一貫性と信頼性を確保する","ko":"코드 자동 리뷰 및 `gh pr create` 및 `git push`와 같은 명령어 지원을 통해 에이전트가 높은 품질의 코드 표준을 강제할 수 있도록 하며, 특히 src/ 디렉토리의 파일에서 코드 변경의 일관성 및 신뢰성을 보장","es":"Habilita a los agentes a aplicar estándares de código de alta calidad mediante la automatización de revisiones con Git y el soporte de comandos como `gh pr create` y `git push`, garantizando la consistencia y la confiabilidad en los cambios de código, particularmente en los archivos del directorio src/","fr":"Permet aux agents d''appliquer des normes de code de haute qualité en automatisant les révisions avec Git et en prenant en charge des commandes comme `gh pr create` et `git push`, garantissant la cohérence et la fiabilité des modifications de code, en particulier dans les fichiers du répertoire src/","de":"Ermächtigt die Agenten, Qualitätsstandards für den Code durchzusetzen, indem sie die Überprüfung mit Git automatisieren und Befehle wie `gh pr create` und `git push` unterstützen, um Konsistenz und Zuverlässigkeit bei Codeänderungen zu gewährleisten, insbesondere bei Dateien im src/-Verzeichnis","pt":"Habilite os agentes a impor padrões de código de alta qualidade, automatizando as revisões com o Git e suportando comandos como `gh pr create` e `git push`, garantindo a consistência e a confiabilidade nas alterações de código, particularmente nos arquivos do diretório src/","ru":"Наделяет агентов возможностью обеспечивать высокие стандарты кода, автоматизируя обзоры с помощью Git и поддерживая команды типа `gh pr create` и `git push`, обеспечивая последовательность и надежность изменений кода, особенно в файлах директории src/","ar":"تمكين الوكلاء من فرض معايير جودة عالية من خلال تلقين المراجعات مع Git ودعم أوامر مثل `gh pr create` و `git push`، وضمان الاتساق والموثوقية في تغييرات الرمز، خاصة في ملفات دليل src/"},"useCases":{"en":["Automating code reviews before PR creation","Validating code quality before Git push","Debugging code changes in src/ directory files"],"zh":["在PR创建之前自动化代码审查","在Git推送之前验证代码质量","在src/目录文件中调试代码更改"],"ja":["PR作成前にコードレビューを自動化する","Gitプッシュ前にコード品質を検証する","src/ディレクトリのファイルでコード変更をデバッグする"],"ko":["PR 생성 전에 코드 리뷰를 자동화","Git 푸시 전에 코드 품질을 검증","src/ 디렉토리 파일에서 코드 변경을 디버깅"],"es":["Automatización de revisiones de código antes de la creación de PR","Validación de la calidad del código antes de la ejecución de Git push","Depuración de cambios de código en archivos del directorio src/"],"fr":["Automatisation des révisions de code avant la création de PR","Validation de la qualité du code avant l''exécution de Git push","Débogage des modifications de code dans les fichiers du répertoire src/"],"de":["Automatisierung von Code-Reviews vor der Erstellung von PR","Validierung der Codequalität vor dem Ausführen von Git push","Fehlerbehebung bei Codeänderungen in Dateien im src/-Verzeichnis"],"pt":["Automatizar revisões de código antes da criação de PR","Validar a qualidade do código antes de enviar para o Git","Depurar alterações de código em arquivos do diretório src/"],"ru":["Автоматизировать обзоры кода до создания PR","Проверять качество кода до отправки в Git","Отлаживать изменения кода в файлах директории src/"],"ar":["تلقين مراجعات الرمز قبل إنشاء PR","تحقق من جودة الرمز قبل دفعها إلى Git","تصحيح أخطاء التغييرات في الرمز في ملفات دليل src/"]},"limitations":{"en":["Requires Git installation and configuration","Limited to code changes in src/ directory","Excludes documentation and setting file changes"],"zh":["需要Git安装和配置","仅限于src/目录中的代码更改","排除文档和设置文件更改"],"ja":["Gitのインストールと設定が必要","src/ディレクトリ内のコード変更のみに限定","ドキュメントと設定ファイルの変更は除外"],"ko":["Git 설치 및 구성이 필요","src/ 디렉토리 내의 코드 변경만 제한","문서 및 설정 파일 변경은 제외"],"es":["Requiere instalación y configuración de Git","Limitado a cambios de código en el directorio src/","Excluye cambios en la documentación y los archivos de configuración"],"fr":["Nécessite l''installation et la configuration de Git","Limité aux modifications de code dans le répertoire src/","Exclut les modifications de la documentation et des fichiers de configuration"],"de":["Erfordert die Installation und Konfiguration von Git","Begrenzt auf Codeänderungen im src/-Verzeichnis","Schließt Änderungen an der Dokumentation und den Konfigurationsdateien aus"],"pt":["Exige a instalação e configuração do Git","Limitado a alterações de código no diretório src/","Exclui alterações nos arquivos de documentação e configuração"],"ru":["Требует установки и конфигурации Git","Ограничен изменениями кода в директории src/","Исключает изменения в файлах документации и настройки"],"ar":["يتطلب تثبيت وضبط Git","محدود بالتغييرات في الرمز في دليل src/","استبعاد التغييرات في ملفات التوثيق وإعدادات الإعداد"]},"version":4},"contentHash":"e9008edd2bbe3d4f3fbf4e918f2876ef499cb9450867ae45cdddb9185c15691c","qualityScore":48}');
