INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ludiscan/ludiscan-webapp/pre-push-quality-checks', 'pre-push-quality-checks', 'ludiscan', 'ludiscan-webapp', 'community', 'pre-push-quality-checks ludiscan ludiscan-webapp community The pre-push-quality-checks skill automates code review for developers, ensuring high-quality code before pushing changes. It integrates with Git and supports commands like `gh pr create` and `git push`. pre-push-quality-checks 是一个代码质量检查工具，用于确保代码质量和一致性。它提供了代码分析和服务器管理功能 pre-push-quality-checks はコード品質チェックツールであり、コード品質と一貫性を確保するために使用されます。コード分析とサーバー管理機能を提供します pre-push-quality-checks는 코드 품질을 확인하고 일관성을 유지하기 위한 코드 품질 검사 도구입니다. 코드 분석 및 서버 관리 기능을 제공합니다 El skill pre-push-quality-checks analiza y verifica la calidad del código antes de realizar un push a Git, utilizando tecnologías como CLI y Git Le skill pre-push-quality-checks analyse et vérifie la qualité du code avant de pousser vers Git, en utilisant des technologies comme CLI et Git Das Skill pre-push-quality-checks analysiert und überprüft die Qualität des Codes vor dem Pushen zu Git, unter Verwendung von Technologien wie CLI und Git O pre-push-quality-checks é uma ferramenta que ajuda a garantir a qualidade do código antes de fazer push para o repositório Git Pre-push-quality-checks - это инструмент, который помогает обеспечить качество кода перед отправкой в репозиторий Git الفحص النوعي قبل الدفع هو أداة تساعد على ضمان جودة الكود قبل دفعها إلى مستودع جيت how to use pre-push-quality-checks pre-push-quality-checks setup guide automated code review tools pre-push-quality-checks vs git hooks pre-push-quality-checks install what is pre-push-quality-checks pre-push-quality-checks alternative pre-push-quality-checks and Git integration pre-push-quality-checks 代码质量检查 自动化代码检查 代码分析 服务器管理 Git push PR 创建 代码一致性 AIエージェント Runs quality checks before creating a PR with `gh pr create` Installs dependencies with `bun install` to ensure a smooth review process Supports skipping checks for documentation-only changes, such as README.md updates Analyzes code changes in the `src/` directory to identify potential issues Allows users to explicitly request quality checks for specific changes pre-push-quality-checks is a skill that automates quality checks for code changes, analyzing functionality and server management before pushing updates to Git.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AppleLamps/web-term/lint-typecheck', 'community', 'AppleLamps', 'web-term', 'AppleLamps/web-term', 'lint-typecheck', 0, 0, 48, '2026-03-08T01:57:15.315Z', '2026-03-08T02:02:46.957Z', 'd911c3977915411230e9e9f9969156e9f74b1ff958a32f8b5ab0a85b2c02eb94', '{"id":"AppleLamps/web-term/lint-typecheck","name":"lint-typecheck","description":{"en":"The lint-typecheck skill provides a streamlined process for linting and type checking in frontend directories, benefiting developers working with TypeScript and npm. It automates error detection and offers fixes for ESLint issues.","zh":"lint-typecheck 是一个用于检测和修复 TypeScript 和 ESLint 错误的 AI 工具，帮助开发者提高代码质量","ja":"lint-typecheck はTypeScriptとESLintのエラーを検出して修正するためのAIツールです。開発者のコード品質を向上させます","ko":"lint-typecheck는 TypeScript 및 ESLint 오류를检测하고 수정하는 AI 도구로 개발자가 코드 품질을 향상시킵니다","es":"Lint-typecheck es una herramienta que ayuda a los desarrolladores a identificar errores y warnings en su código frontend","fr":"Lint-typecheck est un outil qui aide les développeurs à identifier les erreurs et les avertissements dans leur code frontend","de":"Lint-typecheck ist ein Tool, das Entwicklern hilft, Fehler und Warnungen in ihrem Frontend-Code zu identifizieren","pt":"O lint-typecheck é uma ferramenta que ajuda a garantir a qualidade do código frontend, realizando checagens de lint e tipo com TypeScript e ESLint.","ru":"Lint-typecheck - это инструмент, который помогает обеспечить качество кода frontend, выполняя проверки lint и типов с помощью TypeScript и ESLint.","ar":"أداة lint-typecheck هي أداة تساعد على ضمان جودة код الويب الأمامي من خلال إجراء عمليات فحص لينت و فحص نوع مع TypeScript و ESLint"},"seo":{"title":{"en":"lint-typecheck: TypeScript Linting and Type Checking Setu...","zh":"lint-typecheck 设置指南：TypeScript 和 ESLint 最佳实践","ja":"lint-typecheck セットアップガイド：TypeScript と ESLint のベストプラクティス","