INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AppleLamps/web-term/lint-typecheck', 'lint-typecheck', 'AppleLamps', 'web-term', 'community', 'lint-typecheck AppleLamps web-term community The lint-typecheck skill provides a streamlined process for linting and type checking in frontend directories, benefiting developers working with TypeScript and npm. It automates error detection and offers fixes for ESLint issues. lint-typecheck 是一个用于检测和修复 TypeScript 和 ESLint 错误的 AI 工具，帮助开发者提高代码质量 lint-typecheck はTypeScriptとESLintのエラーを検出して修正するためのAIツールです。開発者のコード品質を向上させます lint-typecheck는 TypeScript 및 ESLint 오류를检测하고 수정하는 AI 도구로 개발자가 코드 품질을 향상시킵니다 Lint-typecheck es una herramienta que ayuda a los desarrolladores a identificar errores y warnings en su código frontend Lint-typecheck est un outil qui aide les développeurs à identifier les erreurs et les avertissements dans leur code frontend Lint-typecheck ist ein Tool, das Entwicklern hilft, Fehler und Warnungen in ihrem Frontend-Code zu identifizieren O lint-typecheck é uma ferramenta que ajuda a garantir a qualidade do código frontend, realizando checagens de lint e tipo com TypeScript e ESLint. Lint-typecheck - это инструмент, который помогает обеспечить качество кода frontend, выполняя проверки lint и типов с помощью TypeScript и ESLint. أداة lint-typecheck هي أداة تساعد على ضمان جودة код الويب الأمامي من خلال إجراء عمليات فحص لينت و فحص نوع مع TypeScript و ESLint how to use lint-typecheck lint-typecheck setup guide TypeScript linting and type checking npm run lint tutorial ESLint issue fixing lint-typecheck vs eslint install lint-typecheck lint-typecheck alternative frontend code optimization AI agent development tools lint-typecheck TypeScript ESLint 代码检查 AI工具 代码质量 npm run lint npx tsc Runs lint checks using npm run lint in the frontend directory Performs TypeScript compilation checks with npx tsc -b --noEmit Lists all errors with file locations for easier debugging Offers to fix auto-fixable ESLint issues with npm run lint -- --fix Identifies type mismatches for TypeScript errors lint-typecheck is a skill that automates linting and type checking for frontend code, utilizing npm and TypeScript to identify and fix errors.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chrisagrams/mscompress/github-copilot-pr-comments', 'community', 'chrisagrams', 'mscompress', 'chrisagrams/mscompress', 'github-copilot-pr-comments', 0, 0, 48, '2026-03-08T01:57:15.316Z', '2026-03-08T02:02:48.572Z', 'd41c7bfbfa94f74cf74b989a7ca71ec646fa1e6d0380f372610882a1e2db608b', '{"id":"chrisagrams/mscompress/github-copilot-pr-comments","name":"github-copilot-pr-comments","description":{"en":"The github-copilot-pr-comments skill extracts GitHub Copilot review comments from a PR and produces a markdown report using the gh CLI. It benefits developers by simplifying the comment extraction process.","zh":"GitHub Copilot PR 评论工具是一种使用 gh CLI 和 jq 从 PR 中提取评论并生成 markdown 报告的工具。","ja":"GitHub Copilot PR コメントスキルは、gh CLI と jq を使用して PR からコメントを抽出して markdown レポートを生成するツールです。","ko":"GitHub Copilot PR 댓글 도구는 gh CLI와 jq를 사용하여 PR에서 댓글을 추출하고 markdown 보고서를 생성하는 도구입니다.","es":"github-copilot-pr-comments es una herramienta para extraer comentarios de revisión de GitHub Copilot y generar un informe en markdown","fr":"github-copilot-pr-comments est un outil pour extraire les commentaires de révision de GitHub Copilot et générer un rapport en markdown","de":"github-copilot-pr-comments ist ein Tool zur Extraktion von Überprüfungskommentaren von GitHub Copilot und zur Generierung eines Berichts im Markdown-Format","pt":"O GitHub Copilot PR Comments é uma ferramenta que extrai comentários de revisão do GitHub Copilot de um PR e produz um relatório em markdown","ru":"GitHub Copilot PR Комментариев - это инструмент, который извлекает комментарии к обзору GitHub Copilot из PR и создает отчет в формате markdown","ar":"GitHub Copilot PR Comments هو أداة لاستخراج تعليقات مراجعة GitHub Copilot من طلب سحب وإنشاء تقرير بالتنسيق markdown"},"seo":{"title":{"en":"github-copilot-pr-comments: GitHub Copilot PR Comments Se...","zh":"GitHub Copilo