INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chrisagrams/mscompress/github-copilot-pr-comments', 'github-copilot-pr-comments', 'chrisagrams', 'mscompress', 'community', 'github-copilot-pr-comments chrisagrams mscompress community The github-copilot-pr-comments skill extracts GitHub Copilot review comments from a PR and produces a markdown report using the gh CLI. It benefits developers by simplifying the comment extraction process. GitHub Copilot PR 评论工具是一种使用 gh CLI 和 jq 从 PR 中提取评论并生成 markdown 报告的工具。 GitHub Copilot PR コメントスキルは、gh CLI と jq を使用して PR からコメントを抽出して markdown レポートを生成するツールです。 GitHub Copilot PR 댓글 도구는 gh CLI와 jq를 사용하여 PR에서 댓글을 추출하고 markdown 보고서를 생성하는 도구입니다. github-copilot-pr-comments es una herramienta para extraer comentarios de revisión de GitHub Copilot y generar un informe en markdown github-copilot-pr-comments est un outil pour extraire les commentaires de révision de GitHub Copilot et générer un rapport en markdown github-copilot-pr-comments ist ein Tool zur Extraktion von Überprüfungskommentaren von GitHub Copilot und zur Generierung eines Berichts im Markdown-Format O GitHub Copilot PR Comments é uma ferramenta que extrai comentários de revisão do GitHub Copilot de um PR e produz um relatório em markdown GitHub Copilot PR Комментариев - это инструмент, который извлекает комментарии к обзору GitHub Copilot из PR и создает отчет в формате markdown GitHub Copilot PR Comments هو أداة لاستخراج تعليقات مراجعة GitHub Copilot من طلب سحب وإنشاء تقرير بالتنسيق markdown github-copilot-pr-comments setup guide how to use github-copilot-pr-comments github-copilot-pr-comments alternative github-copilot-pr-comments vs github cli github-copilot-pr-comments install what is github-copilot-pr-comments GitHub Copilot PR 评论工具 AIエージェント gh CLI jq markdown 报告 PR 评论提取 GitHub Copilot 设置 AI工具 Extracts GitHub Copilot review comments from a PR using the gh CLI Produces markdown reports with extracted comments Utilizes jq for efficient JSON processing Supports custom output file specification Requires gh CLI installed and authenticated via gh auth login github-copilot-pr-comments is a skill that leverages the gh CLI and jq for JSON processing to extract GitHub Copilot review comments and generate markdown reports.');
