INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Takazudo/takazudomodular-manuals/l-capture-all-pages', 'l-capture-all-pages', 'Takazudo', 'takazudomodular-manuals', 'community', 'l-capture-all-pages Takazudo takazudomodular-manuals community The l-capture-all-pages skill captures screenshots of all pages in the manual viewer for translation verification, benefiting developers and translators. It ensures correct layouts and no content mismatches. l-capture-all-pages AI工具捕获所有页面，用于验证翻译和布局，确保内容无误 l-capture-all-pages AIエージェントはすべてのページをキャプチャし、翻訳とレイアウトを検証します l-capture-all-pages AI 에이전트는 모든 페이지를 캡처하여 번역 및 레이아웃을 확인합니다 l-capture-all-pages es una habilidad que captura pantallas de alta resolución para verificar traducciones y layouts l-capture-all-pages est une compétence qui capture des écrans haute résolution pour vérifier les traductions et les dispositions l-capture-all-pages ist eine Fähigkeit, die hochauflösende Screenshots erfasst, um Übersetzungen und Layouts zu überprüfen O l-capture-all-pages é uma habilidade que captura todas as páginas do visualizador de manual em alta resolução para verificação de traduções ИИ Агент l-capture-all-pages - это навык, который захватывает все страницы руководства в высоком разрешении для проверки переводов l-capture-all-pages هي مهارة تقوم بتقاط جميع صفحات معرض الدليل بدرجة عالية الدقة للتحقق من الترجمات how to use l-capture-all-pages l-capture-all-pages setup guide l-capture-all-pages alternative l-capture-all-pages vs manual verification l-capture-all-pages install with Playwright l-capture-all-pages high-resolution page capture AI工具 l-capture-all-pages 页面捕获 翻译验证 布局验证 Playwright pnpm dev 高分辨率截图 Captures screenshots of all pages at 2000x1600 resolution Verifies translations match page images using Playwright Checks layout correctness and detects content mismatches Requires pnpm dev server running on port 3100 Supports global or project-level Playwright installation l-capture-all-pages is a skill that captures high-resolution screenshots of all pages in a manual viewer for visual verification of translations and layout correctness');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('phpmac/trader/binance-futures-trading', 'community', 'phpmac', 'trader', 'phpmac/trader', 'binance-futures-trading', 0, 0, 48, '2026-03-08T01:57:15.316Z', '2026-03-08T02:02:50.711Z', '54b467638c4448d27b0971f12087b8a77cef37ea95e2529273822b4355959517', '{"id":"phpmac/trader/binance-futures-trading","name":"binance-futures-trading","description":{"en":"The binance-futures-trading skill provides a comprehensive trading solution for Binance USDT-M perpetual contracts, enabling developers to automate account balance queries, position information, and order management. This skill benefits developers and traders looking to streamline their trading o...","zh":"币安 USDT 合约交易技能提供了完整的交易功能，包括账户余额查询、持仓信息查询、杠杆/保证金模式设置等，通过 MCP 工具实现","ja":"Binance Futures Trading AIエージェントは、口座残高の照会、ポジション情報の照会、レバレッジ/マージン モードの設定など、包括的な取引機能を提供します","ko":"바이낸스 선물 거래 AI 에이전트는 계좌 잔고 조회, 포지션 정보 조회, 레버리지/마진 모드 설정 등 완전한 거래 기능을 제공합니다","es":"El skill de trading de futuros en Binance ofrece funcionalidades de trading completas para USDT-M, incluyendo consulta de cuenta y gestión de órdenes","fr":"Le skill de trading de futures sur Binance propose des fonctionnalités de trading complètes pour USDT-M, notamment la consultation de compte et la gestion d''ordres","de":"Der Binance-Futures-Trading-Skill bietet umfassende Trading-Funktionen für USDT-M, einschließlich Kontostandsabfragen und Ordermanagement","pt":"A habilidade de negociação de futuros da Binance fornece funcionalidades de trading completo para contratos USDT-M, incluindo consultas de saldo e posição, configuração de alavancagem e garantia, e gerenciamento de ordens.","ru":"Навык торговли фьючерсами Binance предоставляет полный функционал для торговли контрактами USDT-M, включая запросы баланса и позиции, настройку кредитного плеча и гарантий, а также управление ордерами.","ar":"توفّر مهارة تداول العقود الآجلة لبياننس وظائف تداول كاملة ل العقود USDT-M ، بما في ذلك استفسارات الرصيد والمركز ، وإعداد الرافعة المالية والضمان ، وإدارة الطلبات."},"seo":{"title":{"en":"Binance-Futures-Trading: Automated USDT-M Contract Tradin...","zh":"币安 USDT 合约交易技能 Setup Guide - MCP 工具实现","ja":"Binance Futures Trading AIエージェント - MCP ツールによる取引機能","ko":"바이낸스 선물 거래 AI 에이전트 - MCP 툴을 통한 거래 기능","es":"Guía de configuración para trading de futuros en Binance","fr":"Guide de mise en place du trading de futures sur Binance","de":"Einrichtungsanleitung für Binance-Futures-Trading","pt":"Guia de Configuração para Negociação de Futuros da Binance","ru":"Настройка торговли фьючерсами Binance: Руководство","ar":"دليل إعداد تداول العقود الآجلة لبياننس"},"description":{"en":"Unlock efficient USDT-M contract trading with our binance-futures-trading skill. Learn how to set up and use this AI agent to automate your trades and stay a...","zh":"了解币安 USDT 合约交易技能的技术细节，包括账户余额查询、持仓信息查询、杠杆/保证金模式设置等，通过 MCP 工具实现自动化交易","ja":"Binance Futures Trading AIエージェントの技術的詳細を学びます。MCP ツールを使用して、口座残高の照会、ポジション情報の照会、レバレッジ/マージン モードの設定などを実行します","ko":"바이낸스 선물 거래 AI 에이전트의 기술적 세부사항을 알아보세요. MCP 툴을 사용하여 계좌 잔고 조회, 포지션 정보 조회, 레버리지/마진 모드 설정 등 자동화 거래를 구현합니다","es":"Aprende a configurar y utilizar el skill de trading de futuros en Binance con nuestra guía detallada y mejores prácticas","fr":"Découvrez comment configurer et utiliser le skill de trading de futures sur Binance avec notre guide détaillé et les meilleures pratiques","de":"Erfahren Sie, wie Sie den Binance-Futures-Trading-Skill konfigurieren und verwenden können, mit unserer detaillierten Anleitung und besten Praktiken","pt":"Aprenda a configurar e usar a habilidade de negociação de futuros da Binance para automatizar suas operações de trading com API e MCP","ru":"Узнайте, как настроить и использовать навык торговли фьючерсами Binance для автоматизации ваших торговых операций с помощью API и MCP","ar":"تعلم كيفية إعداد واستخدام مهارة تداول العقود الآجلة لبياننس لتتمكن من تداول آلي باستخدام واجهة برمجة التطبيقات و MCP"},"definition":{"en":"binance-futures-trading is a skill that offers automated trading functionality for Binance USDT-M perpetual contracts, supporting features like account balance queries and order management via the MCP tool.","zh":"币安 USDT 合约交易技能是一种通过 MCP 工具实现的自动化交易功能","ja":"Binance Futures Trading AIエージェントは、MCP ツールを使用して取引を自動化する機能です","ko":"바이낸스 선물 거래 AI 에이전트는 MCP 툴을 사용하여 거래를 자동화하는 기능입니다","es":"Un skill de trading de futuros en Binance es una herramienta que permite a los desarrolladores interactuar con la API de Binance para realizar operaciones de trading","fr":"Un skill de trading de futures sur Binance est un outil qui permet aux développeurs d''interagir avec l''API de Binance pour effectuer des opérations de trading","de":"Ein Binance-Futures-Trading-Skill ist ein Tool, das es Entwicklern ermöglicht, mit der Binance-API zu interagieren, um Trading-Operationen durchzuführen","pt":"O que é a habilidade de negociação de futuros da Binance? É uma ferramenta que fornece funcionalidades de trading completo para contratos USDT-M.","ru":"Что такое навык торговли фьючерсами Binance? Это инструмент, который предоставляет полный функционал для торговли контрактами USDT-M.","ar":"ما هي مهارة تداول العقود الآجلة لبياننس؟ إنها أداة توفر وظائف تداول كاملة ل العقود USDT-M."},"features":{"en":["Account balance queries using BINANCE_API_KEY and BINANCE_API_SECRET","Position information queries and leverage/margin mode setting","Automated opening and closing of positions with stop-loss and take-profit settings","Order management capabilities, including query and cancellation of orders","Support for simulated trading mode (TRADING_SIMULATION) and testnet (BINANCE_USE_TESTNET)","Environment configuration using bash variables for API keys and simulation mode"],"zh":["账户余额查询","持仓信息查询","杠杆/保证金模式设置","开仓/平仓操作","止损止盈设置","订单管理（查询/撤销）"],"ja":["口座残高の照会","ポジション情報の照会","レバレッジ/マージン モードの設定","新規注文/決済注文の操作","ストップロス/利益確定の設定","注文管理（照会/取消）"],"ko":["계좌 잔고 조회","포지션 정보 조회","레버리지/마진 모드 설정","신규 주문/정산 주문 운영","스톱 로스/이익 실현 설정","주문 관리（조회/취소）"],"es":["Consulta de cuenta y gestión de órdenes","Configuración de apalancamiento y margen","Apertura y cierre de posiciones","Gestión de stop loss y take profit","Uso de la herramienta MCP para realizar operaciones de trading"],"fr":["Consultation de compte et gestion d''ordres","Configuration de l''effet de levier et de la marge","Ouverture et fermeture de positions","Gestion des stop loss et take profit","Utilisation de l''outil MCP pour effectuer des opérations de trading"],"de":["Kontostandsabfragen und Ordermanagement","Konfiguration von Hebel und Margin","Öffnen und Schließen von Positionen","Verwaltung von Stop-Loss und Take-Profit","Verwendung des MCP-Tools für Trading-Operationen"],"pt":["Consulta de saldo e posição","Configuração de alavancagem e garantia","Gerenciamento de ordens (criação, cancelamento e consulta)","Suporte a modo de simulação para testar estratégias","Integração com API da Binance para operações de trading","Suporte a testnet para testar e validar estratégias"],"ru":["Запросы баланса и позиции","Настройка кредитного плеча и гарантий","Управление ордерами (создание, отмена и запрос)","Поддержка режима симуляции для тестирования стратегий","Интеграция с API Binance для торговых операций","Поддержка тестовой сети для тестирования и проверки стратегий"],"ar":["استفسارات الرصيد والمركز","إعداد الرافعة المالية والضمان","إدارة الطلبات (إنشاء ، إلغاء ، استفسار)","دعم وضع المحاكاة لاختبار الاستراتيجيات","التكامل مع واجهة برمجة التطبيقات لبياننس لعمليات التداول","دعم شبكة الاختبار لاختبار وتحقق الاستراتيجيات"]},"keywords":{"en":["how to use binance-futures-trading","binance-futures-trading setup guide","automated USDT-M contract trading","binance-futures-trading vs manual trading","install binance-futures-trading skill","binance-futures-trading API documentation","what is binance-futures-trading","binance-futures-trading alternative solutions","binance-futures-trading tutorial for developers"],"zh":["币安 USDT 合约交易","MCP 工具","自动化交易","账户余额查询","持仓信息查询","杠杆/保证金模式设置","AI 交易技能"],"ja":["Binance Futures Trading","MCP ツール","自動化取引","口座残高の照会","ポジション情報の照会","レバレッジ/マージン モードの設定","AI エージェント"],"ko":["바이낸스 선물 거래","MCP 툴","자동화 거래","계좌 잔고 조회","포지션 정보 조회","레버리지/마진 모드 설정","AI 에이전트"],"es":["trading de futuros en Binance","skill de trading de futuros","API de Binance","herramienta de trading","gestión de órdenes","configuración de apalancamiento","stop loss y take profit"],"fr":["trading de futures sur Binance","skill de trading de futures","API de Binance","outils de trading","gestion d''ordres","configuration de l''effet de levier","stop loss et take profit"],"de":["Binance-Futures-Trading","Binance-Futures-Trading-Skill","Binance-API","Trading-Tool","Ordermanagement","Hebel- und Margin-Konfiguration","Stop-Loss und Take-Profit"],"pt":["negociação de futuros da Binance","trading de criptomoedas","API da Binance","MCP","simulação de trading","testnet","estratégias de trading","automatização de trading","ferramentas de trading"],"ru":["торговля фьючерсами Binance","торговля криптовалютами","API Binance","MCP","симуляция торговли","тестовая сеть","стратегии торговли","автоматизация торговли","инструменты торговли"],"ar":["تداول العقود الآجلة لبياننس","تداول العملات الرقمية","واجهة برمجة التطبيقات لبياننس","MCP","محاكاة التداول","شبكة الاختبار","استراتيجيات التداول","تأتميم التداول","أدوات التداول"]}},"owner":"phpmac","repo":"trader","repoPath":"phpmac/trader","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.316Z","topics":[],"category":"community","skillMd":{"name":"binance-futures-trading","description":"使用币安 USDT-M 永续合约 MCP 工具进行交易操作, 包括账户查询、杠杆设置、开仓平仓、止损止盈等.当需要执行币安合约交易相关操作时触发此技能.","bodyPreview":"# 币安 USDT 合约交易技能\n\n## 概述\n\n本技能提供币安 USDT-M 永续合约的完整交易功能, 通过 MCP 工具实现:\n\n- 账户余额查询\n- 持仓信息查询\n- 杠杆/保证金模式设置\n- 开仓/平仓操作\n- 止损止盈设置\n- 订单管理 (查询/撤销)\n\n---\n\n## 环境配置\n\n### 必需的环境变量\n\n```bash\n# API 密钥 (必需)\nBINANCE_API_KEY=your_api_key\nBINANCE_API_SECRET=your_api_secret\n\n# 模拟交易模式 (默认 true, 不执行真实订单)\nTRADING_SIMULATION=true\n\n# 使用测试网 (可选, 默认 false)\nBINANCE_USE_TESTNET=false\n```\n\n### 安全提醒\n\n- **禁止**在代码中硬编码 API 密钥\n- 建议先使用测试网验证策略\n- 默认启用模拟模式, 防止误操作\n\n---\n\n## 可用工具\n\n### 查询类 (只读)\n\n| 工具名称 | 功能 | 参数 |\n|----------|------|------|\n| `bi","body":"# 币安 USDT 合约交易技能\n\n## 概述\n\n本技能提供币安 USDT-M 永续合约的完整交易功能, 通过 MCP 工具实现:\n\n- 账户余额查询\n- 持仓信息查询\n- 杠杆/保证金模式设置\n- 开仓/平仓操作\n- 止损止盈设置\n- 订单管理 (查询/撤销)\n\n---\n\n## 环境配置\n\n### 必需的环境变量\n\n```bash\n# API 密钥 (必需)\nBINANCE_API_KEY=your_api_key\nBINANCE_API_SECRET=your_api_secret\n\n# 模拟交易模式 (默认 true, 不执行真实订单)\nTRADING_SIMULATION=true\n\n# 使用测试网 (可选, 默认 false)\nBINANCE_USE_TESTNET=false\n```\n\n### 安全提醒\n\n- **禁止**在代码中硬编码 API 密钥\n- 建议先使用测试网验证策略\n- 默认启用模拟模式, 防止误操作\n\n---\n\n## 可用工具\n\n### 查询类 (只读)\n\n| 工具名称 | 功能 | 参数 |\n|----------|------|------|\n| `binance_get_balance` | 查询账户余额 | `asset` (可选) |\n| `binance_get_positions` | 查询持仓信息 | `symbol` (可选) |\n| `binance_get_open_orders` | 查询普通挂单 (限价单等) | `symbol` (可选) |\n| `binance_get_open_algo_orders` | 查询条件单 (止盈止损) | `symbol` (可选) |\n\n> **注意**: 止盈止损订单使用 Algo Order API, 需要用 `binance_get_open_algo_orders` 查询, 不会出现在 `binance_get_open_orders` 中.\n\n### 设置类\n\n| 工具名称 | 功能 | 参数 |\n|----------|------|------|\n| `binance_change_leverage` | 设置杠杆倍数 | `symbol`, `leverage` (1-125) |\n| `binance_change_margin_type` | 设置保证金模式 | `symbol`, `margin_type` (ISOLATED/CROSSED) |\n\n### 交易类\n\n| 工具名称 | 功能 | 关键参数 |\n|----------|------|----------|\n| `binance_place_order` | 下单 | `symbol`, `side`, `type`, `quantity` |\n| `binance_close_position` | 平仓 | `symbol`, `quantity` (可选) |\n| `binance_set_stop_loss_take_profit` | 设置止损止盈 | `symbol`, `stopLossPrice`, `takeProfitPrice` |\n| `binance_cancel_order` | 撤销普通订单 | `symbol`, `orderId` |\n| `binance_cancel_all_orders` | 撤销所有普通订单 | `symbol` |\n| `binance_cancel_algo_order` | 撤销单个条件单 | `symbol`, `algoId` |\n| `binance_cancel_all_algo_orders` | 撤销所有条件单 | `symbol` |\n\n---\n\n## 使用示例\n\n### 1. 查询账户状态\n\n```python\n# 查询 USDT 余额\nbinance_get_balance(asset=\"USDT\")\n\n# 查询所有持仓\nbinance_get_positions()\n\n# 查询指定交易对持仓\nbinance_get_positions(symbol=\"BTCUSDT\")\n```\n\n### 2. 设置杠杆和保证金模式\n\n```python\n# 设置 BTCUSDT 杠杆为 10 倍\nbinance_change_leverage(symbol=\"BTCUSDT\", leverage=10)\n\n# 切换为逐仓模式 (有持仓时无法切换)\nbinance_change_margin_type(symbol=\"BTCUSDT\", margin_type=\"ISOLATED\")\n```\n\n### 3. 开仓\n\n```python\n# 市价做多 0.01 BTC\nbinance_place_order(\n    symbol=\"BTCUSDT\",\n    side=\"BUY\",\n    type=\"MARKET\",\n    quantity=0.01,\n    confirm_real_order=True  # 实盘必须\n)\n\n# 限价做空\nbinance_place_order(\n    symbol=\"BTCUSDT\",\n    side=\"SELL\",\n    type=\"LIMIT\",\n    quantity=0.01,\n    price=100000,\n    timeInForce=\"GTC\",\n    confirm_real_order=True\n)\n```\n\n### 4. 平仓\n\n```python\n# 全部平仓\nbinance_close_position(\n    symbol=\"BTCUSDT\",\n    confirm_real_order=True\n)\n\n# 部分平仓\nbinance_close_position(\n    symbol=\"BTCUSDT\",\n    quantity=0.005,\n    confirm_real_order=True\n)\n```\n\n### 5. 设置止损止盈\n\n```python\n# 同时设置止损和止盈\nbinance_set_stop_loss_take_profit(\n    symbol=\"BTCUSDT\",\n    stopLossPrice=95000,\n    takeProfitPrice=110000,\n    confirm_real_order=True\n)\n\n# 只设置止损\nbinance_set_stop_loss_take_profit(\n    symbol=\"BTCUSDT\",\n    stopLossPrice=95000,\n    confirm_real_order=True\n)\n```\n\n### 6. 订单管理\n\n```python\n# 查询普通挂单 (限价单等)\nbinance_get_open_orders(symbol=\"BTCUSDT\")\n\n# 查询条件单 (止盈止损订单)\nbinance_get_open_algo_orders(symbol=\"BTCUSDT\")\n\n# 撤销指定订单\nbinance_cancel_order(symbol=\"BTCUSDT\", orderId=123456789)\n\n# 撤销所有普通挂单\nbinance_cancel_all_orders(symbol=\"BTCUSDT\")\n\n# 撤销单个条件单 (止盈止损)\nbinance_cancel_algo_order(symbol=\"BTCUSDT\", algoId=123456789)\n\n# 撤销所有条件单 (止盈止损)\nbinance_cancel_all_algo_orders(symbol=\"BTCUSDT\")\n```\n\n> **重要**:\n> - 止盈止损订单使用 Algo Order API (2025-12-09 迁移后)\n> - 查询条件单: `binance_get_open_algo_orders`\n> - 撤销条件单: `binance_cancel_algo_order` 或 `binance_cancel_all_algo_orders`\n> - 普通的 `binance_cancel_all_orders` **无法撤销条件单**\n\n---\n\n## 订单类型说明\n\n| 类型 | 说明 | 必需参数 |\n|------|------|----------|\n| `MARKET` | 市价单, 立即成交 | `quantity` |\n| `LIMIT` | 限价单 | `quantity`, `price`, `timeInForce` |\n| `STOP_MARKET` | 止损市价单 | `stopPrice` |\n| `TAKE_PROFIT_MARKET` | 止盈市价单 | `stopPrice` |\n| `STOP` | 止损限价单 | `price`, `stopPrice` |\n| `TAKE_PROFIT` | 止盈限价单 | `price`, `stopPrice` |\n\n---\n\n## 交易方向\n\n**账户使用对冲模式 (Hedge Mode)**, 所有交易操作必须指定 `positionSide` 参数:\n\n- **开多**: `side=BUY` + `positionSide=LONG`\n- **平多**: `side=SELL` + `positionSide=LONG`\n- **开空**: `side=SELL` + `positionSide=SHORT`\n- **平空**: `side=BUY` + `positionSide=SHORT`\n\n> 注意: 不要使用 `positionSide=BOTH`, 会报错 `-4061`\n\n---\n\n## 模拟交易模式\n\n默认情况下, 所有交易类工具运行在**模拟模式**:\n\n1. 不会执行真实订单\n2. 返回模拟订单信息\n3. 用于验证参数和策略逻辑\n\n### 启用实盘交易\n\n1. 设置环境变量: `TRADING_SIMULATION=false`\n2. 调用时传入: `confirm_real_order=True`\n\n```python\n# 两个条件都满足才会执行真实订单\nbinance_place_order(\n    symbol=\"BTCUSDT\",\n    side=\"BUY\",\n    type=\"MARKET\",\n    quantity=0.01,\n    confirm_real_order=True  # 必须显式确认\n)\n```\n\n---\n\n## 风险提示\n\n1. **资金安全**: 合约交易有爆仓风险, 请谨慎操作\n2. **杠杆风险**: 高杠杆放大盈亏, 建议使用低杠杆\n3. **止损保护**: 开仓后应立即设置止损\n4. **测试优先**: 新策略先在测试网验证\n5. **单笔风险**: 建议单笔亏损不超过账户 1-2%\n\n---\n\n## 常见错误码\n\n| 错误码 | 说明 | 解决方案 |\n|--------|------|----------|\n| -1000 | 未知错误 | 检查网络, 重试 |\n| -1021 | 时间戳超出范围 | 检查系统时间同步 |\n| -1022 | 签名无效 | 检查 API Secret |\n| -2010 | 余额不足 | 检查可用余额 |\n| -2019 | 保证金不足 | 降低仓位或增加保证金 |\n| -4003 | 数量小于最小值 | 检查交易对最小交易量 |\n| -4014 | 价格不符合精度 | 调整价格精度 |\n\n---\n\n## 技术实现\n\n本 MCP 工具使用 [binance-futures-connector-python](https://github.com/binance/binance-futures-connector-python) 官方 SDK, 无需手动处理签名等底层细节.\n\n### API 端点说明\n\n**普通订单 API**:\n- `GET /fapi/v1/openOrders` - 查询普通挂单\n- `DELETE /fapi/v1/order` - 撤销单个普通订单\n- `DELETE /fapi/v1/allOpenOrders` - 撤销所有普通订单\n\n**条件单 Algo Order API** (2025-12-09 迁移后):\n- `POST /fapi/v1/algoOrder` - 创建条件单 (止盈止损)\n- `GET /fapi/v1/openAlgoOrders` - 查询条件单\n- `DELETE /fapi/v1/algoOrder` - 撤销单个条件单\n- **注意**: 币安没有提供批量撤销条件单的 API, `binance_cancel_all_algo_orders` 工具通过先查询再逐个撤销实现\n\n### 开发注意事项\n\n修改本 MCP 服务前, 应使用 Context7 查询最新 API 文档:\n\n```\n# 查询币安合约 API 文档\nresolve-library-id: \"binance futures connector python\"\nget-library-docs: context7CompatibleLibraryID=\"/binance/binance-futures-connector-python\", topic=\"具体功能\"\n```\n\n---\n\n## 参考资料\n\n- [币安 USDT-M 合约 API 文档](https://developers.binance.com/docs/zh-CN/derivatives/usds-margined-futures/general-info)\n- [binance-futures-connector-python](https://github.com/binance/binance-futures-connector-python)\n- Context7 Library ID: `/binance/binance-futures-connector-python`\n\n"},"lastSynced":"2026-03-08T02:02:50.711Z","agentAnalysis":{"suitability":{"en":"Perfect for Trading Agents needing automated Binance USDT-M perpetual contract management.","zh":"非常适合需要自动化 Binance USDT-M 永续合约管理的交易代理","ja":"Binance USDT-M 永続契約の自動化管理が必要なトレーディングエージェントに最適","ko":"바이낸스 USDT-M 永續 계약 관리 자동화를 필요로 하는 거래 에이전트에게 적합","es":"Perfecto para Agentes de Trading que necesitan una gestión automática de contratos perpetuos USDT-M de Binance.","fr":"Parfait pour les agents de trading ayant besoin d''une gestion automatisée des contrats perpetuels USDT-M de Binance.","de":"Perfekt für Trading-Agenten, die eine automatisierte Verwaltung von Binance USDT-M Perpetual-Kontrakten benötigen.","pt":"Perfeito para Agents de Negociação que necessitam de gestão automatizada de contratos perpétuos USDT-M da Binance.","ru":"Идеально подходит для торговых агентов, которым требуется автоматизированное управление вечными контрактами USDT-M Binance.","ar":"مثالي للوكلاء التجاريين الذين يحتاجون إلى إدارة تلقائية لعقود USDT-M الدائمة من بينانس."},"recommendation":{"en":"Empowers agents to automate account balance queries, position information, and order management using the Binance API, with features like leverage and margin mode setting, and stop-loss and take-profit orders, all while utilizing the MCP tool for streamlined trading.","zh":"赋予代理自动化查询账户余额、持仓信息和订单管理的能力，使用 Binance API，具有设置杠杆和保证金模式、止损和止盈订单等功能，同时利用 MCP 工具进行流线化交易","ja":"Binance API を使用して、エージェントに口座残高の照会、ポジション情報、注文管理を自動化する機能を付与し、レバレッジとマージン モードの設定、ストップ ロスとテイク プロフィット注文などの機能を提供し、MCP ツールを使用してトレーディングを効率化","ko":"Binance API를 사용하여 에이전트가 계좌 잔고, 포지션 정보 및 주문 관리를 자동화할 수 있는 능력을 부여하며, 레버리지 및 마진 모드 설정, 스탑 로스 및 테이크 프로핏 주문 등의 기능을 제공하며, MCP 툴을 사용하여 거래를 최적화","es":"Habilita a los agentes a automatizar consultas de saldo de cuenta, información de posición y gestión de pedidos mediante la API de Binance, con características como configuración de apalancamiento y modo de margen, y pedidos de stop-loss y take-profit, todo mientras utiliza la herramienta MCP para un trading optimizado.","fr":"Permet aux agents d''automatiser les requêtes de solde de compte, les informations de position et la gestion des commandes à l''aide de l''API Binance, avec des fonctionnalités telles que la configuration du levier et du mode de marge, et les commandes de stop-loss et take-profit, le tout en utilisant l''outil MCP pour un trading optimisé.","de":"Ermächtigt Agenten, Abfrage des Kontosaldo, Positionsinformationen und Auftragsverwaltung mithilfe der Binance-API zu automatisieren, mit Funktionen wie Hebel- und Margenmodus-Einstellung sowie Stop-Loss- und Take-Profit-Aufträgen, und zwar unter Verwendung des MCP-Tools für optimiertes Trading.","pt":"Habilita os agentes a automatizar consultas de saldo de conta, informações de posição e gerenciamento de pedidos usando a API da Binance, com recursos como definição de alavancagem e modo de margem, e ordens de stop-loss e take-profit, tudo enquanto utiliza a ferramenta MCP para negociação otimizada.","ru":"Наделяет агентов возможностью автоматизировать запросы баланса счета, информацию о позиции и управление заказами с помощью API Binance, с функциями такими как настройка кредитного плеча и режима маржи, а также ордера стоп-лосс и тейк-профит, все это при использовании инструмента MCP для оптимизированной торговли.","ar":"تمكّن الوكلاء من توفير استفسارات رصيد الحساب ومعلومات المركز وإدارة الطلبات باستخدام واجهة برمجة التطبيقات Binance، مع ميزات مثل ضبط الرافعة المالية ووضع الهامش وأوامر وقف الخسارة وأوامر إيقاف الربح، كل ذلك مع استخدام أداة MCP للتعامل المركز."},"useCases":{"en":["Automating Binance USDT-M perpetual contract trading strategies","Managing account balances and position information in real-time","Executing orders with precision using stop-loss and take-profit settings"],"zh":["自动化 Binance USDT-M 永续合约交易策略","实时管理账户余额和持仓信息","使用止损和止盈设置精确执行订单"],"ja":["Binance USDT-M 永続契約のトレーディング戦略を自動化","口座残高とポジション情報をリアルタイムで管理","ストップ ロスとテイク プロフィットの設定を使用して注文を精密に実行"],"ko":["바이낸스 USDT-M 永續 계약 거래 전략 자동화","계좌 잔고 및 포지션 정보를 실시간으로 관리","스탑 로스 및 테이크 프로핏 설정을 사용하여 주문 정확히 실행"],"es":["Automatización de estrategias de trading de contratos perpetuos USDT-M de Binance","Gestión de saldos de cuenta y información de posición en tiempo real","Ejecución de pedidos con precisión utilizando configuraciones de stop-loss y take-profit"],"fr":["Automatisation des stratégies de trading de contrats perpetuels USDT-M de Binance","Gestion des soldes de compte et des informations de position en temps réel","Exécution des commandes avec précision en utilisant les paramètres de stop-loss et take-profit"],"de":["Automatisierung von Handelsstrategien für Binance USDT-M Perpetual-Kontrakte","Verwaltung von Kontosaldo und Positionsinformationen in Echtzeit","Ausführung von Aufträgen mit Präzision unter Verwendung von Stop-Loss- und Take-Profit-Einstellungen"],"pt":["Automatizar estratégias de negociação de contratos perpétuos USDT-M da Binance","Gerenciar saldos de conta e informações de posição em tempo real","Executar pedidos com precisão usando configurações de stop-loss e take-profit"],"ru":["Автоматизировать стратегии торговли вечными контрактами USDT-M Binance","Управлять балансом счета и информацией о позиции в режиме реального времени","Выполнять заказы с точностью с помощью настроек стоп-лосс и тейк-профит"],"ar":["توفير استراتيجيات تداول عقود USDT-M الدائمة من بينانس","إدارة رصيد الحساب ومعلومات المركز في الوقت الفعلي","تنفيذ الطلبات بدقة باستخدام إعدادات وقف الخسارة وإيقاف الربح"]},"limitations":{"en":["Requires Binance API key and secret","Default simulation mode must be disabled for live trading","Compatibility with Binance testnet is optional"],"zh":["需要 Binance API 密钥和密钥秘密","默认模拟模式必须禁用以进行实盘交易","与 Binance 测试网的兼容性是可选的"],"ja":["Binance API キーとシークレット キーが必要","デフォルトのシミュレーション モードを無効にする必要があり、実際のトレーディングを行う","Binance テストネットとの互換性はオプション"],"ko":["바이낸스 API 키 및 시크릿 키가 필요","기본 시뮬레이션 모드를 비활성화하여 실시간 거래를进行","바이낸스 테스트넷과의 호환성은 선택"],"es":["Requiere clave y secreto de API de Binance","El modo de simulación predeterminado debe estar deshabilitado para trading en vivo","La compatibilidad con Binance testnet es opcional"],"fr":["Nécessite une clé et un secret d''API Binance","Le mode de simulation par défaut doit être désactivé pour le trading en direct","La compatibilité avec Binance testnet est facultative"],"de":["Benötigt Binance-API-Schlüssel und -Geheimnis","Der Standard-Simulationsmodus muss für Live-Trading deaktiviert werden","Die Kompatibilität mit Binance Testnet ist optional"],"pt":["Exige chave e segredo da API da Binance","O modo de simulação padrão deve ser desativado para negociação ao vivo","Compatibilidade com a testnet da Binance é opcional"],"ru":["Требует ключа и секрета API Binance","Режим симуляции по умолчанию должен быть отключен для живой торговли","Совместимость с тестовой сетью Binance является опциональной"],"ar":["يتطلب مفتاح وسر واجهة برمجة التطبيقات Binance","يجب تعطيل وضع المحاكاة الإفتراضي للتعامل الحي","التوافق مع شبكة الاختبار بينانس هو اختياري"]},"version":4},"contentHash":"54b467638c4448d27b0971f12087b8a77cef37ea95e2529273822b4355959517","qualityScore":48}');
