INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('scarf005/blog/i18n', 'i18n', 'scarf005', 'blog', 'community', 'i18n scarf005 blog community The i18n skill automates translations for developers working with Korean text, blog posts, and documentation, maintaining multilingual content with specific style patterns i18n 技术可以自动翻译内容，支持韩英、韩日等语言对，保留原文的语气和风格 AIエージェントの i18n 機能を使用して、韓国語のテキストを英語や日本語に自動翻訳します i18n 기능을 사용하면 파일 편집 시 한국어 텍스트를 영어 또는 일본어로 자동 번역할 수 있습니다 i18n es una habilidad que traduce contenido automáticamente, conservando el tono y estilo originales, y es ideal para editar archivos que contienen texto coreano i18n est une compétence qui traduit du contenu de manière automatisée tout en préservant le ton et le style d''origine, idéale pour éditer des fichiers contenant du texte coréen i18n ist eine Fähigkeit, die Inhalte automatisch übersetzt, während sie den Originalton und -stil bewahrt, und ist ideal für die Bearbeitung von Dateien, die koreanischen Text enthalten O i18n é uma habilidade que traduz automaticamente conteúdo coreano para inglês e japonês, seguindo padrões de estilo específicos И18н - это навык, который автоматически переводит корейский контент на английский и японский языки, следуя определенным стилям i18n هي مهارة تترجم تلقائيًا المحتوى الكوري إلى الإنجليزية واليابانية باتباع الأنماط الأسلوبية المحددة i18n setup guide how to use i18n for translation i18n vs Google Translate automated translation tools multilingual content management Korean to English translation i18n 技术 自动翻译 多语言化 韩英翻译 韩日翻译 文件编辑 博客翻译 文档翻译 Automatically translates Korean text to English using the pattern `냉혹한 {A}의 세계` → `The {A} *Experience*` Translates Korean text to Japanese using the pattern `냉혹한 {A}의 세계` → `闇が深い{A}の世界` Preserves the tone and style of the original content during translation Supports editing files containing Korean text for multilingual content maintenance i18n is an AI agent skill that automates content translations from Korean to English and Japanese, following predefined style patterns');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('itsimonfredlingjack/codex-dev-plugin/sync-policies', 'community', 'itsimonfredlingjack', 'codex-dev-plugin', 'itsimonfredlingjack/codex-dev-plugin', 'sync-policies', 0, 0, 48, '2026-03-08T01:57:15.330Z', '2026-03-08T02:03:10.734Z', 'b8e37917ba6d047b962df144c1c2900970fd61d4e3bb13e847670c3c3a72968f', '{"id":"itsimonfredlingjack/codex-dev-plugin/sync-policies","name":"sync-policies","description":{"en":"The sync-policies skill generates XML output for AI agents, providing a structured format for analysis, solution implementation, and consideration of trade-offs. This skill benefits developers working with XML and AI agents.","zh":"Sync-Policies 是一种实现 XML 输出格式的技术，包括分析、解决方案和考虑因素","ja":"Sync-Policies は、AIエージェントによる XML 出力を実装する技術で、分析、解決策、考慮事項を含む","ko":"Sync-Policies는 XML 출력 형식을 구현하는 기술로 분석, 해결책, 고려 사항을 포함","es":"Sync-policies permite la implementación de análisis y soluciones personalizadas para agentes de IA. Ofrece un formato de resultado en XML.","fr":"Les sync-policies permettent la mise en œuvre d''analyses et de solutions personnalisées pour les outils d''IA, avec un format de résultat XML.","de":"Sync-policies ermöglicht die Implementierung von Analysen und Lösungen für KI-Agents, mit einem XML-Ergebnisformat.","pt":"O sync-policies é uma habilidade que permite a análise e implementação de soluções de sincronização de políticas.","ru":"ИИ Агенты с sync-policies позволяет проанализировать и реализовать решения для синхронизации политик.","ar":"سياسات المزامنة ل(sync-policies) تسمح بتحليل وتنفيذ حلول لمزامنة السياسات."},"seo":{"title":{"en":"sync-policies: XML Output Generation for AI Agents | AI A...","zh":"Sync-Policies 设置指南：XML 输出格式","ja":"Sync-Policies のベストプラクティス：AIエージェントによるXML出力","ko":"Sync-Policies 구현 가이드: XML 출력 형식","es":"Guía de configuración de sync-policies para agentes de IA","fr":"Meilleures pratiques pour la mise en œuvre de sync-polici...","de":"Einrichtungsleitfaden für sync-policies in KI-Agents","pt":"Guia de Configuração de sync-policies para Desenvolvedores","ru":"Настройка ИИ Агентов: sync-policies Лучшие Практики","ar":"دليل تنفيذ سياسات المزامنة ل(sync-policies) المطورين"},"description":{"en":"Discover how to leverage sync-policies for structured output. Learn to analyze, implement, and consider trade-offs with our expert guide. Get started now!","zh":"了解 Sync-Policies 的技术细节，包括 XML 输出格式和实现考虑","ja":"Sync-Policies の技術的な詳細を学び、AIエージェントによる XML 出力を実装する","ko":"Sync-Policies 구현을 위한 기술 정보 및 XML 출력 형식에 대한 가이드","es":"Aprende a configurar sync-policies para mejorar la eficiencia de tus agentes de IA. Descubre las mejores prácticas y características clave.","fr":"Découvrez comment mettre en œuvre des sync-policies efficaces avec les outils d''IA pour améliorer la productivité. Conseils et fonctionnalités clés.","de":"Erfahren Sie, wie Sie sync-policies in KI-Agents einrichten, um die Effizienz zu steigern. Enthält beste Praktiken und wichtige Funktionen.","pt":"Aprenda a configurar sync-policies para melhorar a eficiência do seu projeto com nossa guia passo a passo","ru":"Узнайте, как настроить sync-policies для ИИ Агентов, чтобы повысить производительность вашего проекта","ar":"تعرف على كيفية تنفيذ سياسات المزامنة ل(sync-policies) لتحسين كفاءة مشروعك"},"definition":{"en":"sync-policies is a skill that generates XML output in a specific format, including analysis, solution, and considerations elements, for use in AI agent applications.","zh":"Sync-Policies 是一种技术，用于实现 XML 输出格式，包括分析、解决方案和考虑因素","ja":"Sync-Policies は、AIエージェントによる XML 出力を実装する技術のこと","ko":"Sync-Policies는 XML 출력 형식을 구현하는 기술을 말함","es":"Sync-policies es una función que permite la configuración de análisis y soluciones personalizadas para agentes de IA.","fr":"Les sync-policies sont une fonctionnalité qui permet la configuration d''analyses et de solutions personnalisées pour les outils d''IA.","de":"Sync-policies ist eine Funktion, die die Konfiguration von Analysen und Lösungen für KI-Agents ermöglicht.","pt":"O que é sync-policies? É uma habilidade de análise e solução de sincronização de políticas.","ru":"Что такое sync-policies? Это способность анализа и реализации решений для синхронизации политик.","ar":"ما هي سياسات المزامنة ل(sync-policies)? إنه khảية لتحليل وتنفيذ حلول لمزامنة السياسات."},"features":{"en":["Generates XML output in a structured format","Includes analysis, solution, and considerations elements","Supports XML format for data exchange and parsing","Provides a standardized output format for AI agents","Enables easy parsing and analysis of output data"],"zh":["XML 输出格式","分析和解决方案的实现","考虑因素和trade-offs的讨论","CLI 和 React 的集成支持","Python 语言的支持"],"ja":["XML 出力形式","分析と解決策の実装","考慮事項とトレードオフの議論","CLI と React の統合サポート","Python 言語のサポート"],"ko":["XML 출력 형식","분석 및 해결책 구현","고려 사항 및 트레이드 오프 논의","CLI 및 React 통합 지원","Python 언어 지원"],"es":["Análisis personalizado en formato XML","Implementación de soluciones para agentes de IA","Formato de resultado flexible","Compatibilidad con diversas tecnologías","Opciones de configuración avanzadas"],"fr":["Analyse personnalisée au format XML","Mise en œuvre de solutions pour les outils d''IA","Format de résultat flexible","Compatibilité avec diverses technologies","Options de configuration avancées"],"de":["Benutzerdefinierte Analyse im XML-Format","Implementierung von Lösungen für KI-Agents","Flexibles Ergebnisformat","Kompatibilität mit verschiedenen Technologien","Erweiterte Konfigurationsmöglichkeiten"],"pt":["Análise de políticas de sincronização","Implementação de soluções de sincronização","Considerações de trade-offs e notas","Formatação de saída em XML","Análise breve e solução personalizada"],"ru":["Анализ политик синхронизации","Реализация решений для синхронизации","Учет компромиссов и заметок","Формат вывода в XML","Краткий анализ и индивидуальное решение"],"ar":["تحليل سياسات المزامنة","تنفيذ حلول لمزامنة","ملاحظات حول التبادل والملاحظات","تنسيق الإخراج في XML","تحليل موجز وحل مخصص"]},"keywords":{"en":["how to use sync-policies","sync-policies XML output","AI agent skills","sync-policies alternative","sync-policies setup guide","XML data exchange for AI agents"],"zh":["Sync-Policies","XML 输出格式","AI工具","CLI","React","Python","技术实现","输出格式","分析和解决方案"],"ja":["Sync-Policies","XML 出力形式","AIエージェント","CLI","React","Python","技術実装","出力形式","分析と解決策"],"ko":["Sync-Policies","XML 출력 형식","AI 에이전트","CLI","React","Python","기술 구현","출력 형식","분석 및 해결책"],"es":["sync-policies","agentes de IA","configuración de sync-policies","análisis personalizado","implementación de soluciones","formato de resultado XML","tecnologías de IA","desarrollo de agentes de IA","integración de sync-policies"],"fr":["sync-policies","outils d''IA","configuration de sync-policies","analyse personnalisée","mise en œuvre de solutions","format de résultat XML","technologies d''IA","développement d''outils d''IA","intégration de sync-policies"],"de":["sync-policies","KI-Agents","Konfiguration von sync-policies","benutzerdefinierte Analyse","Implementierung von Lösungen","XML-Ergebnisformat","KI-Technologien","Entwicklung von KI-Agents","Integration von sync-policies"],"pt":["sync-policies","análise de políticas","sincronização de políticas","implementação de soluções","XML","desenvolvedores","guias de configuração"],"ru":["sync-policies","анализ политик","синхронизация политик","реализация решений","XML","ИИ Агенты","лучшие практики"],"ar":["سياسات المزامنة","تحليل سياسات","مزامنة سياسات","تنفيذ حلول","XML","أدوات الذكاء الاصطناعي","دليل التهيئة"]}},"owner":"itsimonfredlingjack","repo":"codex-dev-plugin","repoPath":"itsimonfredlingjack/codex-dev-plugin","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.330Z","topics":[],"category":"community","skillMd":{"name":"sync-policies","description":"Skill for sync-policies tasks.","bodyPreview":"## Output Format\n\n```xml\n<result>\n  <analysis>Brief analysis</analysis>\n  <solution>Implementation</solution>\n  <considerations>Trade-offs and notes</considerations>\n</result>\n```","body":"## Output Format\n\n```xml\n<result>\n  <analysis>Brief analysis</analysis>\n  <solution>Implementation</solution>\n  <considerations>Trade-offs and notes</considerations>\n</result>\n```\n"},"lastSynced":"2026-03-08T02:03:10.734Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor and AutoGPT requiring structured XML output for policy synchronization and analysis.","zh":"非常适合需要结构化XML输出以进行策略同步和分析的AI Agent，如Cursor和AutoGPT。","ja":"ポリシーの同期と分析のために構造化されたXML出力を必要とするCursorやAutoGPTなどのAIエージェントに理想的です。","ko":"정책 동기화 및 분석을 위해 구조화된 XML 출력이 필요한 Cursor 및 AutoGPT와 같은 AI 에이전트에 이상적입니다.","es":"Ideal para agentes de IA como Cursor y AutoGPT que requieren una salida XML estructurada para la sincronización y análisis de políticas.","fr":"Idéal pour les agents IA comme Cursor et AutoGPT nécessitant une sortie XML structurée pour la synchronisation et l''analyse des politiques.","de":"Ideal für KI-Agents wie Cursor und AutoGPT, die eine strukturierte XML-Ausgabe für die Synchronisierung und Analyse von Richtlinien erfordern.","pt":"Ideal para agentes de IA como Cursor e AutoGPT que exigem saída XML estruturada para sincronização e análise de políticas.","ru":"Идеально подходит для агентов ИИ, таких как Cursor и AutoGPT, требующих структурированного выхода XML для синхронизации и анализа политики.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Cursor و AutoGPT الذين يتطلبون مخرجات XML منظمة للتزامن والتحليل السياسي."},"recommendation":{"en":"Empowers agents to generate comprehensive XML reports for policy analysis, solution implementation, and trade-off consideration, utilizing XML formatting for seamless integration with existing systems and protocols.","zh":"使Agent能够生成全面的XML报告，用于策略分析、解决方案实施和权衡考量，利用XML格式化实现与现有系统和协议的无缝集成。","ja":"既存のシステムやプロトコルとのシームレスな統合を実現するためにXMLフォーマットを活用し、ポリシー分析、ソリューション実装、トレードオフ検討のための包括的なXMLレポートを生成するようにエージェントを強化します。","ko":"기존 시스템 및 프로토콜과의 원활한 통합을 위해 XML 형식을 활용하여 정책 분석, 솔루션 구현 및 트레이드오프 고려를 위한 포괄적인 XML 보고서를 생성하도록 에이전트를 강화합니다.","es":"Habilita a los agentes a generar informes XML completos para el análisis de políticas, la implementación de soluciones y la consideración de compensaciones, utilizando el formato XML para una integración sin problemas con los sistemas y protocolos existentes.","fr":"Permet aux agents de générer des rapports XML complets pour l''analyse des politiques, la mise en œuvre des solutions et la prise en compte des compromis, en utilisant le formatage XML pour une intégration transparente avec les systèmes et les protocoles existants.","de":"Ermöglicht es Agents, umfassende XML-Berichte für die Analyse von Richtlinien, die Implementierung von Lösungen und die Berücksichtigung von Kompromissen zu generieren, indem XML-Formatierung für eine nahtlose Integration mit bestehenden Systemen und Protokollen verwendet wird.","pt":"Habilita os agentes a gerar relatórios XML abrangentes para análise de políticas, implementação de soluções e consideração de compensações, utilizando formatação XML para integração perfeita com sistemas e protocolos existentes.","ru":"Предоставляет агентам возможность генерировать всесторонние отчеты XML для анализа политики, реализации решений и учета компромиссов, используя форматирование XML для бесшовной интеграции с существующими системами и протоколами.","ar":"يمنح الوكلاء إمكانية إنشاء تقارير XML شاملة لتحليل السياسات وتنفيذ الحلول ومراعاة التعويضات، باستخدام تنسيق XML من أجل التكامل السلس مع الأنظمة والبروتوكولات الحالية."},"useCases":{"en":["Generating XML output for policy synchronization","Analyzing trade-offs in policy implementation","Implementing solutions based on XML policy reports"],"zh":["生成用于策略同步的XML输出","分析策略实施中的权衡","基于XML策略报告实施解决方案"],"ja":["ポリシー同期のためのXML出力の生成","ポリシー実装におけるトレードオフの分析","XMLポリシーレポートに基づくソリューションの実装"],"ko":["정책 동기화를 위한 XML 출력 생성","정책 구현에서의 트레이드오프 분석","XML 정책 보고서를 기반으로 한 솔루션 구현"],"es":["Generar salida XML para la sincronización de políticas","Analizar compensaciones en la implementación de políticas","Implementar soluciones basadas en informes de políticas XML"],"fr":["Générer une sortie XML pour la synchronisation des politiques","Analyser les compromis dans la mise en œuvre des politiques","Mettre en œuvre des solutions basées sur les rapports de politiques XML"],"de":["XML-Ausgabe für die Synchronisierung von Richtlinien generieren","Kompromisse bei der Implementierung von Richtlinien analysieren","Lösungen auf der Grundlage von XML-Richtlinienberichten implementieren"],"pt":["Geração de saída XML para sincronização de políticas","Análise de compensações na implementação de políticas","Implementação de soluções com base em relatórios de políticas XML"],"ru":["Генерация выхода XML для синхронизации политики","Анализ компромиссов при реализации политики","Реализация решений на основе отчетов о политике XML"],"ar":["إنشاء مخرجات XML لتنسيق السياسات","تحليل التعويضات في تنفيذ السياسات","تنفيذ الحلول على أساس تقارير السياسات XML"]},"limitations":{"en":["Requires XML compatibility","Structured output may not be suitable for all agent applications"],"zh":["需要XML兼容性","结构化输出可能不适用于所有Agent应用程序"],"ja":["XML互換性が必要","構造化された出力はすべてのエージェントアプリケーションに適しているとは限りません"],"ko":["XML 호환성이 필요함","구조화된 출력이 모든 에이전트 애플리케이션에 적합하지 않을 수 있음"],"es":["Requiere compatibilidad con XML","La salida estructurada puede no ser adecuada para todas las aplicaciones de agentes"],"fr":["Nécessite la compatibilité XML","La sortie structurée peut ne pas être adaptée à toutes les applications d''agents"],"de":["Benötigt XML-Kompatibilität","Die strukturierte Ausgabe kann nicht für alle Agenten-Anwendungen geeignet sein"],"pt":["Exige compatibilidade XML","Saída estruturada pode não ser adequada para todas as aplicações de agentes"],"ru":["Требует совместимости XML","Структурированный выход может быть не подходящим для всех приложений агентов"],"ar":["يتطلب توافقًا مع XML","المخرجات المنظمة قد لا تكون مناسبة لجميع تطبيقات الوكلاء"]},"version":4},"contentHash":"b8e37917ba6d047b962df144c1c2900970fd61d4e3bb13e847670c3c3a72968f","qualityScore":48}');
