INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('itsimonfredlingjack/codex-dev-plugin/sync-policies', 'sync-policies', 'itsimonfredlingjack', 'codex-dev-plugin', 'community', 'sync-policies itsimonfredlingjack codex-dev-plugin community The sync-policies skill generates XML output for AI agents, providing a structured format for analysis, solution implementation, and consideration of trade-offs. This skill benefits developers working with XML and AI agents. Sync-Policies 是一种实现 XML 输出格式的技术，包括分析、解决方案和考虑因素 Sync-Policies は、AIエージェントによる XML 出力を実装する技術で、分析、解決策、考慮事項を含む Sync-Policies는 XML 출력 형식을 구현하는 기술로 분석, 해결책, 고려 사항을 포함 Sync-policies permite la implementación de análisis y soluciones personalizadas para agentes de IA. Ofrece un formato de resultado en XML. Les sync-policies permettent la mise en œuvre d''analyses et de solutions personnalisées pour les outils d''IA, avec un format de résultat XML. Sync-policies ermöglicht die Implementierung von Analysen und Lösungen für KI-Agents, mit einem XML-Ergebnisformat. O sync-policies é uma habilidade que permite a análise e implementação de soluções de sincronização de políticas. ИИ Агенты с sync-policies позволяет проанализировать и реализовать решения для синхронизации политик. سياسات المزامنة ل(sync-policies) تسمح بتحليل وتنفيذ حلول لمزامنة السياسات. how to use sync-policies sync-policies XML output AI agent skills sync-policies alternative sync-policies setup guide XML data exchange for AI agents Sync-Policies XML 输出格式 AI工具 CLI React Python 技术实现 输出格式 分析和解决方案 Generates XML output in a structured format Includes analysis, solution, and considerations elements Supports XML format for data exchange and parsing Provides a standardized output format for AI agents Enables easy parsing and analysis of output data sync-policies is a skill that generates XML output in a specific format, including analysis, solution, and considerations elements, for use in AI agent applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ROBOTIS-GIT/zenoh_ros2_sdk/create-example', 'community', 'ROBOTIS-GIT', 'zenoh_ros2_sdk', 'ROBOTIS-GIT/zenoh_ros2_sdk', 'create-example', 0, 0, 48, '2026-03-08T01:57:15.348Z', '2026-03-08T02:03:40.921Z', '86ee95f45eb3c0c3f5b272e3116ec47660514ef689939c5054d8cff255be9e30', '{"id":"ROBOTIS-GIT/zenoh_ros2_sdk/create-example","name":"create-example","description":{"en":"The create-example skill enables developers to create new publish/subscribe examples for the zenoh-ros2-sdk, facilitating ROS 2 communication without a ROS2 environment. It benefits developers working with ROS 2 messages.","zh":"本技能指导您创建新的发布/订阅示例，用于Zenoh的ROS 2通信Python SDK。创建publisher/subscriber用于新的ROS2消息类型","ja":"このスキルでは、ZenohのROS 2通信Python SDK用の新しいパブリッシュ/サブスクライブ例を作成します。新しいROS2メッセージタイプのpublisher/subscriberを作成します","ko":"이 스킬은 Zenoh의 ROS 2 통신 Python SDK용 새로운 발행/구독 예제를 생성합니다. 새로운 ROS2 메시지 유형의 발행자/구독자를 생성합니다","es":"El skill create-example permite crear ejemplos de publicación y suscripción para Zenoh-ROS2-SDK. Utiliza Python para la comunicación ROS 2 vía Zenoh.","fr":"Le skill create-example permet de créer des exemples de publication et d''abonnement pour Zenoh-ROS2-SDK. Il utilise Python pour la communication ROS 2 via Zenoh.","de":"Das Skill create-example ermöglicht die Erstellung von Beispielen für die Veröffentlichung und das Abonnieren für Zenoh-ROS2-SDK. Es verwendet Python für die ROS 2-Kommunikation via Zenoh.","pt":"O Create-Example é uma habilidade que guia você na criação de novos exemplos de publicação/assinatura para o zenoh-ros2-sdk, permitindo o uso de ROS 2 sem ambiente ROS2.","ru":"Create-Example - это навык, который помогает создавать новые примеры публикации/подписки для zenoh-ros2-sdk, позволяя использовать ROS 2 без среды ROS2 для ИИ Агентов.","ar":"Create-Example هو مهارة تساعدك في إنشاء أمثلة جديدة لنشر/الاستماع لصالح zenoh-ros2-sdk، مما يسمح باستخدام ROS 2 بدون بيئة ROS2 لأدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"create-example: ROS 2 Communication Setup Guide | AI Agen...","zh":"创建示例设置指南 - 使用Zenoh的ROS 2通信Python SDK","ja":"Create Example設定ガイド - Zenohを使用したROS 2通信Python SDK","ko":"예제 생성 설정 가이드 - Zenoh를 사용한 ROS 2 통신 Python SDK","es":"Guía de configuración de create-example para ROS 2 con Zenoh","fr":"Guide de démarrage de create-example pour ROS 2 avec Zenoh","de":"Einrichtungsleitfaden für create-example mit ROS 2 und Zenoh","pt":"Guia de Configuração do Create-Example: Comunicação ROS 2...","ru":"Настройка Create-Example: ROS 2 через Zenoh для ИИ Агентов","ar":"دليل إعداد Create-Example: التواصل مع ROS 2 عبر Zenoh لأد..."},"description":{"en":"Unlock seamless ROS 2 communication via Zenoh with our create-example skill. Dive into our tutorial to get started with publish/subscribe examples today!","zh":"学习如何使用Zenoh的ROS 2通信Python SDK创建新的发布/订阅示例，无需ROS2环境","ja":"Zenohを使用したROS 2通信Python SDKで新しいパブリッシュ/サブスクライブ例を作成する方法を学びます","ko":"Zenoh를 사용한 ROS 2 통신 Python SDK로 새로운 발행/구독 예제를 생성하는 방법을 배우세요","es":"Aprende a crear ejemplos de publicación y suscripción para Zenoh-ROS2-SDK sin entorno ROS2","fr":"Découvrez comment créer des exemples de publication et d''abonnement pour Zenoh-ROS2-SDK sans environnement ROS2","de":"Erfahren Sie, wie Sie Beispiele für die Veröffentlichung und das Abonnieren für Zenoh-ROS2-SDK ohne ROS2-Umgebung erstellen","pt":"Aprenda a criar exemplos de publicação/assinatura para o zenoh-ros2-sdk e use ROS 2 sem ambiente ROS2","ru":"Узнайте, как создавать примеры публикации/подписки для zenoh-ros2-sdk и использовать ROS 2 без среды ROS2 для ИИ Агентов","ar":"تعلم كيفية إنشاء أمثلة لنشر/الاستماع لصالح zenoh-ros2-sdk واستخدام ROS 2 بدون بيئة ROS2 لأدوات الذكاء الاصطناعي"},"definition":{"en":"create-example is a Python SDK for ROS 2 communication via Zenoh, allowing users to add new examples for message types and create publishers/subscribers.","zh":"创建示例是一种技能，用于指导创建新的发布/订阅示例，用于Zenoh的ROS 2通信Python SDK","ja":"Create Exampleは、ZenohのROS 2通信Python SDK用の新しいパブリッシュ/サブスクライブ例を作成するためのスキルです","ko":"예제 생성은 Zenoh의 ROS 2 통신 Python SDK용 새로운 발행/구독 예제를 생성하는 스킬입니다","es":"Create-example es un skill que facilita la creación de ejemplos de publicación y suscripción para Zenoh-ROS2-SDK","fr":"Create-example est un skill qui facilite la création d''exemples de publication et d''abonnement pour Zenoh-ROS2-SDK","de":"Create-example ist ein Skill, der die Erstellung von Beispielen für die Veröffentlichung und das Abonnieren für Zenoh-ROS2-SDK erleichtert","pt":"O Create-Example é uma habilidade que fornece um guia para criar exemplos de publicação/assinatura para o zenoh-ros2-sdk.","ru":"Create-Example - это навык, который предоставляет руководство по созданию примеров публикации/подписки для zenoh-ros2-sdk.","ar":"Create-Example هو مهارة يقدم إرشادات لإنشاء أمثلة لنشر/الاستماع لصالح zenoh-ros2-sdk."},"features":{"en":["Generates publish/subscribe examples for the zenoh-ros2-sdk","Supports creation of publishers and subscribers for new ROS2 messages","Enables adding support for trajectory, sensor, geometry, and other message types","Organizes examples in a structured project format within the `examples/` directory","Differentiates between publishers and subscribers using odd and even numbered filenames"],"zh":["使用Zenoh的ROS 2通信Python SDK","创建新的发布/订阅示例","无需ROS2环境","支持trajectory、sensor、geometry等消息类型","创建publisher/subscriber用于新的ROS2消息类型"],"ja":["ZenohのROS 2通信Python SDKを使用","新しいパブリッシュ/サブスクライブ例を作成","ROS2環境不要","トラジェクトリ、センサー、ジオメトリなどのメッセージタイプをサポート","新しいROS2メッセージタイプのpublisher/subscriberを作成"],"ko":["Zenoh의 ROS 2 통신 Python SDK 사용","新的 발행/구독 예제 생성","ROS2 환경 필요 없음","트래เจ克토리, 센서, 기하학 등 메시지 유형 지원","新的 ROS2 메시지 유형의 발행자/구독자 생성"],"es":["Creación de ejemplos de publicación y suscripción para Zenoh-ROS2-SDK","Uso de Python para la comunicación ROS 2 vía Zenoh","Estructura de proyecto con ejemplos en la carpeta examples/","Compatibilidad con mensajes de tipo trajectory, sensor, geometry y otros","Creación de publicadores y suscriptores para nuevos mensajes ROS2"],"fr":["Création d''exemples de publication et d''abonnement pour Zenoh-ROS2-SDK","Utilisation de Python pour la communication ROS 2 via Zenoh","Structure de projet avec des exemples dans le répertoire examples/","Compatibilité avec des messages de type trajectory, sensor, geometry et autres","Création de publication et d''abonnement pour de nouveaux messages ROS2"],"de":["Erstellung von Beispielen für die Veröffentlichung und das Abonnieren für Zenoh-ROS2-SDK","Verwendung von Python für die ROS 2-Kommunikation via Zenoh","Projektstruktur mit Beispielen im Verzeichnis examples/","Kompatibilität mit Nachrichten des Typs trajectory, sensor, geometry und anderen","Erstellung von Veröffentlichern und Abonnenten für neue ROS2-Nachrichten"],"pt":["Criação de exemplos de publicação/assinatura para o zenoh-ros2-sdk","Uso de ROS 2 sem ambiente ROS2","Suporte para mensagens de trajetória, sensor e geometria","Estrutura de projeto com exemplos em `examples/`","Arquivos de exemplo com nomes numerados para publicadores e assinantes"],"ru":["Создание примеров публикации/подписки для zenoh-ros2-sdk","Использование ROS 2 без среды ROS2 для ИИ Агентов","Поддержка сообщений траектории, датчика и геометрии","Структура проекта с примерами в `examples/`","Файлы примеров с пронумерованными именами для издателей и подписчиков"],"ar":["إنشاء أمثلة لنشر/الاستماع لصالح zenoh-ros2-sdk","استخدام ROS 2 بدون بيئة ROS2 لأدوات الذكاء الاصطناعي","دعم رسائل المسار والمتحسس والهندسة","هيكل المشروع مع الأمثلة في `examples/`","ملفات الأمثلة بأسماء مرقمة لناشري والمشتركين"]},"keywords":{"en":["how to use create-example","create-example alternative","create-example install","what is create-example","create-example vs ros2","create-example setup guide","ros 2 communication tutorial","zenoh-ros2-sdk examples"],"zh":["ROS 2","Zenoh","Python SDK","创建示例","发布/订阅","ROS2消息类型","trajectory","sensor","geometry"],"ja":["ROS 2","Zenoh","Python SDK","Create Example","パブリッシュ/サブスクライブ","ROS2メッセージタイプ","トラジェクトリ","センサー","ジオメトリ"],"ko":["ROS 2","Zenoh","Python SDK","예제 생성","발행/구독","ROS2 메시지 유형","트래제크토리","센서","기하학"],"es":["create-example","ROS 2","Zenoh","Python SDK","publicación y suscripción","ejemplos de ROS2","comunicación ROS 2","Herramientas de AI como Agentes","desarrollo de software"],"fr":["create-example","ROS 2","Zenoh","SDK Python","publication et abonnement","exemples de ROS2","communication ROS 2","Outils d''IA comme Agents","développement de logiciels"],"de":["create-example","ROS 2","Zenoh","Python-SDK","Veröffentlichung und Abonnement","Beispiele für ROS2","ROS 2-Kommunikation","KI-Tools wie Agenten","Softwareentwicklung"],"pt":["create-example","ros 2","zenoh-ros2-sdk","publicação/assinatura","python","SDK","desenvolvimento de software","iot","robótica"],"ru":["create-example","ros 2","zenoh-ros2-sdk","публикация/подписка","python","sdk","разработка программного обеспечения","ии агенты","робототехника"],"ar":["create-example","ros 2","zenoh-ros2-sdk","نشر/الاستماع","python","sdk","تطوير البرمجيات","أدوات الذكاء الاصطناعي","الروبوتات"]}},"owner":"ROBOTIS-GIT","repo":"zenoh_ros2_sdk","repoPath":"ROBOTIS-GIT/zenoh_ros2_sdk","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.348Z","topics":[],"category":"community","skillMd":{"name":"create-example","description":"Create new publish/subscribe examples for ROS2 message types. Use when the user wants to add a new example, create pub/sub for a new message type, or add trajectory/sensor/geometry message examples.","bodyPreview":"# Create Example\n\nThis skill guides you through creating new publish/subscribe examples for the zenoh-ros2-sdk.\n\n## When to Use\n\n- User wants to add a new example for a message type\n- User wants to create publisher/subscriber for a new ROS2 message\n- Adding support for trajectory, sensor, geometry, or other message types\n\n## Project Structure\n\nExamples are in `examples/` with numbered filenames:\n- Odd numbers: publishers (e.g., `11_publish_*.py`)\n- Even numbers: subscribers (e.g., `12_subscribe_","body":"# Create Example\n\nThis skill guides you through creating new publish/subscribe examples for the zenoh-ros2-sdk.\n\n## When to Use\n\n- User wants to add a new example for a message type\n- User wants to create publisher/subscriber for a new ROS2 message\n- Adding support for trajectory, sensor, geometry, or other message types\n\n## Project Structure\n\nExamples are in `examples/` with numbered filenames:\n- Odd numbers: publishers (e.g., `11_publish_*.py`)\n- Even numbers: subscribers (e.g., `12_subscribe_*.py`)\n\n## 1. Determine Next Example Numbers\n\nCheck existing examples in `examples/` directory. Use the next available odd number for publisher, next even for subscriber.\n\n## 2. Look Up Message Definition\n\nFind the ROS2 message definition. Key resources:\n- https://docs.ros2.org/foxy/api/{package}/msg/{MessageName}.html\n- Common packages: `std_msgs`, `geometry_msgs`, `sensor_msgs`, `trajectory_msgs`, `nav_msgs`\n\n## 3. Publisher Template\n\nCreate `examples/{NN}_publish_{msg_name}.py`:\n\n```python\n#!/usr/bin/env python3\n\"\"\"\n{NN} - Publish {MessageName} Messages\n\nDemonstrates how to publish {package}/msg/{MessageName} messages to a ROS2 topic.\n{Brief description of what this message type is used for.}\n\"\"\"\nimport time\nimport numpy as np\n\nfrom zenoh_ros2_sdk import ROS2Publisher, get_message_class\n\n\ndef main():\n    print(\"{NN} - Publish {MessageName} Messages\")\n    print(\"Publishing to /{topic_name} topic...\\n\")\n\n    # Get message classes for easy object creation\n    Header = get_message_class(\"std_msgs/msg/Header\")\n    Time = get_message_class(\"builtin_interfaces/msg/Time\")\n    {MessageName} = get_message_class(\"{package}/msg/{MessageName}\")\n    # Add nested message classes as needed\n\n    if not all([Header, Time, {MessageName}]):\n        print(\"Error: Failed to get message classes\")\n        return\n\n    # Create publisher\n    pub = ROS2Publisher(\n        topic=\"/{topic_name}\",\n        msg_type=\"{package}/msg/{MessageName}\"\n    )\n\n    try:\n        print(\"Publishing {MessageName} messages...\")\n        print(\"Press Ctrl+C to stop\\n\")\n\n        counter = 0\n        while True:\n            # Get current time\n            now = time.time()\n            sec = int(now)\n            nanosec = int((now - sec) * 1e9)\n\n            # Create header with timestamp\n            header = Header(\n                stamp=Time(sec=sec, nanosec=nanosec),\n                frame_id=\"base_link\"\n            )\n\n            # Create and populate message fields\n            # Note: Arrays need to be numpy arrays for proper serialization\n\n            # Publish message - pass fields as kwargs matching message structure\n            pub.publish(\n                header=header,\n                # ... other fields\n            )\n\n            print(f\"Published {MessageName} {counter}\")\n            counter += 1\n            time.sleep(0.1)  # 10 Hz\n\n    except KeyboardInterrupt:\n        print(\"\\nInterrupted by user\")\n    finally:\n        pub.close()\n        print(\"Publisher closed\")\n\n\nif __name__ == \"__main__\":\n    main()\n```\n\n## 4. Subscriber Template\n\nCreate `examples/{NN+1}_subscribe_{msg_name}.py`:\n\n```python\n#!/usr/bin/env python3\n\"\"\"\n{NN+1} - Subscribe to {MessageName} Messages\n\nDemonstrates how to subscribe to a ROS2 topic and receive {package}/msg/{MessageName} messages.\n{Brief description of what this message type is used for.}\n\"\"\"\nimport time\n\nfrom zenoh_ros2_sdk import ROS2Subscriber\n\n\ndef main():\n    print(\"{NN+1} - Subscribe to {MessageName} Messages\")\n    print(\"Subscribing to /{topic_name} topic...\\n\")\n\n    message_count = [0]  # Use list to allow modification in nested function\n\n    def on_message(msg):\n        \"\"\"Callback function called when a {MessageName} message is received.\"\"\"\n        message_count[0] += 1\n\n        # Extract information from the message\n        timestamp = msg.header.stamp\n        frame_id = msg.header.frame_id\n        # ... extract other fields\n\n        # Display received data\n        print(f\"\\n--- {MessageName} Message #{message_count[0]} ---\")\n        print(f\"Timestamp: {timestamp.sec}.{timestamp.nanosec:09d}\")\n        print(f\"Frame ID: {frame_id}\")\n        # ... print other fields\n\n    # Create subscriber\n    sub = ROS2Subscriber(\n        topic=\"/{topic_name}\",\n        msg_type=\"{package}/msg/{MessageName}\",\n        callback=on_message\n    )\n\n    try:\n        print(\"Waiting for {MessageName} messages... Press Ctrl+C to stop\")\n        while True:\n            time.sleep(0.1)\n    except KeyboardInterrupt:\n        print(\"\\nInterrupted by user\")\n    finally:\n        sub.close()\n        print(\"Subscriber closed\")\n\n\nif __name__ == \"__main__\":\n    main()\n```\n\n## 5. Update README\n\nAdd entries to `examples/README.md`:\n\n```markdown\n### [`{NN}_publish_{msg_name}.py`]({NN}_publish_{msg_name}.py)\nDemonstrates how to publish `{package}/msg/{MessageName}` messages. {Description}.\n\n**Usage:**\n\\```bash\npython3 examples/{NN}_publish_{msg_name}.py\n\\```\n\n### [`{NN+1}_subscribe_{msg_name}.py`]({NN+1}_subscribe_{msg_name}.py)\nDemonstrates how to subscribe to `{package}/msg/{MessageName}` messages. {Description}.\n\n**Usage:**\n\\```bash\npython3 examples/{NN+1}_subscribe_{msg_name}.py\n\\```\n```\n\n## 6. Key Patterns\n\n### Arrays\nUse numpy arrays for proper CDR serialization:\n```python\npositions = np.array([0.0, 0.1, 0.2], dtype=np.float64)\n```\n\n### Nested Messages\nGet nested message classes and construct them:\n```python\nPoint = get_message_class(\"trajectory_msgs/msg/JointTrajectoryPoint\")\nDuration = get_message_class(\"builtin_interfaces/msg/Duration\")\n\npoint = Point(\n    positions=np.array([0.0, 0.1], dtype=np.float64),\n    time_from_start=Duration(sec=1, nanosec=0)\n)\n```\n\n### Common Topic Names\n- `/joint_states` - JointState\n- `/cmd_vel` - Twist\n- `/joint_trajectory` - JointTrajectory\n- `/odom` - Odometry\n- `/tf` - TransformStamped\n"},"lastSynced":"2026-03-08T02:03:40.921Z","agentAnalysis":{"suitability":{"en":"Perfect for ROS 2 Agents needing streamlined publish/subscribe example creation for the zenoh-ros2-sdk.","zh":"非常适合需要为 zenoh-ros2-sdk 简化发布/订阅示例创建的 ROS 2 Agents。","ja":"zenoh-ros2-sdk の簡略化されたパブリッシュ/サブスクライブの例の作成が必要な ROS 2 エージェントに最適です。","ko":"zenoh-ros2-sdk를 위한 발행/구독 예제 생성을 간소화해야 하는 ROS 2 에이전트에 적합합니다.","es":"Perfecto para agentes de ROS 2 que necesitan una creación de ejemplos de publicación/suscripción simplificada para el zenoh-ros2-sdk.","fr":"Parfait pour les agents ROS 2 ayant besoin d''une création d''exemples de publication/abonnement simplifiée pour le zenoh-ros2-sdk.","de":"Perfekt für ROS 2-Agents, die eine vereinfachte Erstellung von Veröffentlichungs-/Abonnementsbeispielen für das zenoh-ros2-sdk benötigen.","pt":"Perfeito para agentes ROS 2 que necessitam de criação de exemplos de publicação/assinatura simplificados para o zenoh-ros2-sdk.","ru":"Идеально подходит для агентов ROS 2, которым требуется упрощенный пример публикации/подписки для zenoh-ros2-sdk.","ar":"مثالي لعمليات ROS 2 التي تحتاج إلى إنشاء أمثلة للنشر والاشتراك المُبسّطة لبرنامج zenoh-ros2-sdk."},"recommendation":{"en":"Empowers agents to generate and manage publish/subscribe examples for various ROS 2 message types, including trajectory, sensor, and geometry messages, using the zenoh-ros2-sdk protocol.","zh":"赋予代理生成和管理各种 ROS 2 消息类型（包括轨迹、传感器和几何消息）的发布/订阅示例的能力，使用 zenoh-ros2-sdk 协议。","ja":"エージェントが、zenoh-ros2-sdk プロトコルを使用して、トラジェクトリ、センサー、幾何学メッセージを含むさまざまな ROS 2 メッセージタイプのパブリッシュ/サブスクライブの例を生成および管理する機能を提供します。","ko":"에이전트가 zenoh-ros2-sdk 프로토콜을 사용하여 다양한 ROS 2 메시지 유형(트라젝토리, 센서, 기하 메시지 등)의 발행/구독 예제를 생성하고 관리할 수 있는 기능을 부여합니다.","es":"Habilita a los agentes a generar y gestionar ejemplos de publicación/suscripción para varios tipos de mensajes ROS 2, incl