INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('paul-macfarlane/competiscore-web/generate-icons', 'generate-icons', 'paul-macfarlane', 'competiscore-web', 'community', 'generate-icons paul-macfarlane competiscore-web community The generate-icons skill generates high-quality, hand-crafted SVG icons for the Competiscore competitive scoring app, benefiting developers and designers. It creates visually distinct and professional icons. Competiscore SVG图标生成器是用于生成高质量SVG图标的AI工具。它支持多种类型，包括avatar、team、game-type、tournament和all Competiscore SVGアイコン生成は、高品質のSVGアイコンを生成するためのAIエージェントです。複数のタイプをサポートしています。avatar、team、game-type、tournament、all Competiscore SVG 아이콘 생성기는 고품질 SVG 아이콘을 생성하기 위한 AI 도구입니다. 여러 유형을 지원합니다. 아바타, 팀, 게임 유형, 토너먼트, 모두 El generador de iconos SVG crea iconos personalizados para Competiscore. Puedes generar iconos de avatar, equipo, tipo de juego, torneo o todos Le générateur d''icônes SVG crée des icônes sur mesure pour Competiscore. Vous pouvez générer des icônes d''avatar, d''équipe, de type de jeu, de tournoi ou tous Der SVG-Icon-Generator erstellt benutzerdefinierte Icons für Competiscore. Sie können Avatar-, Team-, Spieltyp-, Turnier- oder alle Icons generieren O gerador de ícones SVG é uma ferramenta para criar ícones SVG personalizados para o aplicativo Competiscore Генератор иконок SVG - это инструмент для создания пользовательских иконок SVG для приложения Competiscore أداة生成 الأيقونات SVG هي أداة لإنشاء أيقونات SVG مخصصة لبرنامج Competiscore how to use generate-icons generate-icons setup guide generate-icons alternative generate-icons vs icon generators generate-icons install what is generate-icons generate-icons for Competiscore SVG icon generation Competiscore icon design AI工具 SVG图标生成 Competiscore 手工设计 CLI命令行界面 图标生成器 SVG图标 avatar图标 team图标 game-type图标 tournament图标 Generates SVG icons for Competiscore using specific icon types Supports generation of individual icons or the full set using the `$1` argument Allows specification of icon name or type using the `$0` argument Outputs icons to designated locations based on icon type Enables users to generate icons without arguments, prompting for type and name generate-icons is a skill that generates high-quality SVG icons for Competiscore, supporting various icon types such as avatar, team, game-type, tournament, or all.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dudusoar/skillOS/project-logger', 'community', 'dudusoar', 'skillOS', 'dudusoar/skillOS', 'project-logger', 0, 0, 48, '2026-03-08T01:57:15.352Z', '2026-03-08T02:03:54.825Z', 'a92d3fb70b0a7cc0206e858848e714e4f61764c3448105b6ef00d4fd7e07d7a4', '{"id":"dudusoar/skillOS/project-logger","name":"project-logger","description":{"en":"The project-logger skill maintains a structured project log, tracking progress and important updates. It benefits AI developers by providing a personal operating system for managing AI skills.","zh":"Project Logger 是一个用于管理 AI 工具的个人操作系统，通过结构化的项目日志和上下文分离来支持生命周期管理","ja":"Project Logger は、AI エージェントのライフサイクルを管理するためのパーソナルオペレーティングシステムです","ko":"Project Logger는 AI 에이전트를 위한 개인 운영 체제로, 구조화된 프로젝트 로그와 컨텍스트 분리를 통해 생명주기 관리를 지원합니다","es":"Project-logger es un sistema operativo personal para gestionar habilidades de IA con soporte de ciclo de vida, separación de contexto y aprendizaje evolutivo.","fr":"Project-logger est un système d''exploitation personnel pour gérer des compétences d''IA avec prise en charge du cycle de vie, séparation de contexte et apprentissage évolutif.","de":"Project-logger ist ein persönliches Betriebssystem für die Verwaltung von KI-Fähigkeiten mit Lebenszyklus-Unterstützung, Kontexttrennung und evolutionärem Lernen.","pt":"O Project Logger é uma ferramenta de registro de projetos que ajuda a gerenciar projetos com eficiência, criando entradas de log com timestamp para acompanhar o progresso.","ru":"Project Logger - это инструмент для управления проектами, который помогает отслеживать прогресс и решения, создавая записи журнала с меткой времени.","ar":"مشروع محول هو أداة لتسجيل المشاريع التي تساعد في إدارة المشاريع بفعالية، من خلال إنشاء إدخالات سجل مع توقيت للتحديثات"},"seo":{"title":{"en":"project-logger: Setup Guide for AI Agents | AI Agent Skill","zh":"Project Logger 设置指南：AI 工具项目管理","ja":"Project Logger を使用した AI エージェントのプロジェクト管理ベストプラクティス","ko":"Project Logger 사용법: AI 에이전트 프로젝트 관리 설정 가이드","es":"Guía de configuración de project-logger para agentes de IA","fr":"Configurer project-logger pour les outils d''IA","de":"Einrichtungsleitfaden für project-logger in KI-Agenten","pt":"Guia de Configuração do Project Logger: Ferramenta de Reg...","ru":"ИИ Агенты: Настройка Project Logger для Управления Проектами","ar":"إعداد مشروع محول: أداة تسجيل مشاريع ذكية"},"description":{"en":"Discover how project-logger streamlines AI skill management with lifecycle support and context separation. Learn how to implement it today!","zh":"了解 Project Logger 如何通过结构化的项目日志和上下文分离来支持 AI 工具的生命周期管理","ja":"Project Logger は、AI エージェントのライフサイクルを管理するための構造化されたプロジェクトログとコンテキスト分離を提供します","ko":"Project Logger를 사용하여 AI 에이전트의 생명주기를 관리하고 프로젝트 진행 상황을 추적하는 방법을 알아보세요","es":"Aprende a utilizar project-logger para gestionar habilidades de IA con soporte de ciclo de vida y aprendizaje evolutivo","fr":"Découvrez comment utiliser project-logger pour gérer des compétences d''IA avec prise en charge du cycle de vie et apprentissage évolutif","de":"Erfahren Sie, wie Sie project-logger verwenden, um KI-Fähigkeiten mit Lebenszyklus-Unterstützung und evolutionärem Lernen zu verwalten","pt":"Aprenda a usar o Project Logger para gerenciar projetos com eficiência. Ferramenta de registro de projetos para acompanhar progresso e decisões.","ru":"Узнайте, как использовать Project Logger для эффективного управления проектами. Инструмент для отслеживания прогресса и решений.","ar":"تعرف على كيفية استخدام مشروع محول لتسجيل وتتبع المشاريع بفعالية. أداة لتسجيل وتتبع التقدم والقرارات"},"definition":{"en":"project-logger is a personal operating system for managing AI skills with features like lifecycle support, context separation, and evolutionary learning.","zh":"Project Logger 是一种 AI 工具，用于维护结构化的项目日志以跟踪进度和决策","ja":"Project Logger は、進度と決定を追跡するための構造化されたプロジェクトログを保持する AI エージェントです","ko":"Project Logger는 진행 상황과 결정 사항을 추적하기 위한 구조화된 프로젝트 로그를 유지하는 AI 에이전트입니다","es":"Project-logger es un sistema que mantiene un registro estructurado de proyectos con seguimiento de progreso y documentación de decisiones","fr":"Project-logger est un système qui maintient un journal de projet structuré avec suivi de progression et documentation de décisions","de":"Project-logger ist ein System, das ein strukturiertes Projektprotokoll mit Fortschrittsverfolgung und Dokumentation von Entscheidungen aufrechterhält","pt":"O Project Logger é uma ferramenta de registro de projetos que cria um log estruturado para acompanhar o progresso e as decisões de um projeto.","ru":"Project Logger - это инструмент для создания структурированного журнала для отслеживания прогресса и решений проекта.","ar":"مشروع محول هو أداة لتسجيل مشاريع tạo سجل منظم لتتبع التقدم والقرارات للمشروع"},"features":{"en":["Maintains a structured project log (LOG.md) to track progress and updates","Reads CLAUDE.md to understand project context","Creates timestamped entries documenting project evolution","Supports tracking completed tasks, decisions, and important updates","Enables evolutionary learning through log analysis","Separates context for organized project management"],"zh":["结构化的项目日志（LOG.md）","读取 CLAUDE.md 以了解项目上下文","创建时间戳的条目以记录项目的演进","生命周期管理支持","上下文分离"],"ja":["構造化されたプロジェクトログ（LOG.md）","CLAUDE.md の読み取りによるプロジェクトコンテキストの理解","プロジェクトの進化を記録するタイムスタンプ付きのエントリの作成","ライフサイクル管理のサポート","コンテキスト分離"],"ko":["구조화된 프로젝트 로그（LOG.md）","CLAUDE.md 읽기 통해 프로젝트 컨텍스트 이해","프로젝트의 진화 기록을 위한 타임스탬프가 있는 항목 생성","생명주기 관리 지원","컨텍스트 분리"],"es":["Mantiene un registro estructurado de proyectos (LOG.md)","Lee CLAUDE.md para entender el contexto del proyecto","Crea entradas con marca de tiempo para documentar la evolución del proyecto","Soporta ciclo de vida de habilidades de IA","Permite separación de contexto para proyectos","Apoya aprendizaje evolutivo en habilidades de IA"],"fr":["Maintient un journal de projet structuré (LOG.md)","Lit CLAUDE.md pour comprendre le contexte du projet","Crée des entrées avec horodatage pour documenter l''évolution du projet","Prend en charge le cycle de vie des compétences d''IA","Permet la séparation de contexte pour les projets","Soutient l''apprentissage évolutif dans les compétences d''IA"],"de":["Hält ein strukturiertes Projektprotokoll (LOG.md) auf","Liest CLAUDE.md, um den Projektzusammenhang zu verstehen","Erstellt Einträge mit Zeitstempel, um die Projektentwicklung zu dokumentieren","Unterstützt den Lebenszyklus von KI-Fähigkeiten","Ermöglicht Kontexttrennung für Projekte","Unterstützt evolutionäres Lernen in KI-Fähigkeiten"],"pt":["Criação de entradas de log com timestamp","Leitura do arquivo CLAUDE.md para entender o contexto do projeto","Registro de progresso e decisões importantes","Suporte a ciclo de vida do projeto","Separação de contexto para projetos diferentes"],"ru":["Создание записей журнала с меткой времени","Чтение файла CLAUDE.md для понимания контекста проекта","Отслеживание прогресса и важных решений","Поддержка жизненного цикла проекта","Разделение контекста для разных проектов"],"ar":["إنشاء إدخالات سجل مع توقيت","قراءة ملف CLAUDE.md لفهم سياق المشروع","تسجيل التقدم والقرارات المهمة","دعم دورة حياة المشروع","فصل السياق للمشاريع المختلفة"]},"keywords":{"en":["how to use project-logger","project-logger setup guide","project-logger alternative","project-logger vs other AI skills","project-logger install","what is project-logger","project-logger for AI agents","project-logger lifecycle support","project-logger context separation"],"zh":["AI 工具","Project Logger","项目管理","生命周期管理","结构化项目日志","上下文分离","AI 项目管理","个人操作系统"],"ja":["AI エージェント","Project Logger","プロジェクト管理","ライフサイクル管理","構造化されたプロジェクトログ","コンテキスト分離","AI プロジェクト管理","パーソナルオペレーティングシステム"],"ko":["AI 에이전트","Project Logger","프로젝트 관리","생명주기 관리","구조화된 프로젝트 로그","컨텍스트 분리","AI 프로젝트 관리","개인 운영 체제"],"es":["agentes de IA","herramientas de IA","project-logger","gestión de habilidades de IA","soporte de ciclo de vida","aprendizaje evolutivo","separación de contexto","registro de proyectos","documentación de decisiones"],"fr":["outils d''IA","agents d''IA","project-logger","gestion de compétences d''IA","prise en charge du cycle de vie","apprentissage évolutif","séparation de contexte","journal de projet","documentation de décisions"],"de":["KI-Agenten","KI-Tools","project-logger","Verwaltung von KI-Fähigkeiten","Lebenszyklus-Unterstützung","evolutionäres Lernen","Kontexttrennung","Projektprotokoll","Dokumentation von Entscheidungen"],"pt":["Project Logger","ferramenta de registro de projetos","gerenciamento de projetos","ciclo de vida do projeto","separação de contexto","registro de progresso","decisões importantes","CLAUDE.md","timestamps"],"ru":["Project Logger","ИИ Агенты","инструмент для управления проектами","жизненный цикл проекта","разделение контекста","отслеживание прогресса","важные решения","CLAUDE.md","метка времени"],"ar":["مشروع محول","أداة تسجيل مشاريع","إدارة مشاريع","دورة حياة المشروع","فصل السياق","تسجيل التقدم","القرارات المهمة","CLAUDE.md","توقيت"]}},"owner":"dudusoar","repo":"skillOS","repoPath":"dudusoar/skillOS","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.352Z","topics":[],"category":"community","skillMd":{"name":"project-logger","description":"Manages project progress tracking and maintains a chronological log of completed tasks, decisions, and updates. Use when completing milestones, making architectural decisions, or documenting project evolution. Creates and updates LOG.md file based on CLAUDE.md context.","bodyPreview":"# Project Logger\n\n## Overview\n\nThis skill maintains a structured project log (LOG.md) that tracks progress, completed tasks, decisions, and important updates. It reads CLAUDE.md to understand project context and creates timestamped entries documenting the project''s evolution.\n\n## When to Use This Skill\n\nUse this skill when:\n- Completing a significant task or milestone\n- Making important architectural or technical decisions\n- Encountering and resolving issues\n- Adding new features or capabilities","body":"# Project Logger\n\n## Overview\n\nThis skill maintains a structured project log (LOG.md) that tracks progress, completed tasks, decisions, and important updates. It reads CLAUDE.md to understand project context and creates timestamped entries documenting the project''s evolution.\n\n## When to Use This Skill\n\nUse this skill when:\n- Completing a significant task or milestone\n- Making important architectural or technical decisions\n- Encountering and resolving issues\n- Adding new features or capabilities\n- Updating project dependencies or configuration\n- Need to review project history\n\n## Workflow\n\n### Step 1: Locate CLAUDE.md\n\nFind and read the project''s CLAUDE.md file to understand:\n- Project name and goals\n- Current phase and milestones\n- Technical architecture\n- Known issues\n\nDefault location: `./.claude/CLAUDE.md`\n\n### Step 2: Determine Log Entry Type\n\nIdentify what type of entry to create:\n\n**Task Completion:**\n- Feature implemented\n- Bug fixed\n- Refactoring completed\n- Tests added\n\n**Decision:**\n- Architectural choice made\n- Technology/library selected\n- Design pattern adopted\n- Convention established\n\n**Update:**\n- Dependency upgraded\n- Configuration changed\n- Documentation updated\n- Milestone reached\n\n**Issue:**\n- Problem encountered\n- Workaround applied\n- Known limitation documented\n\n### Step 3: Create or Update LOG.md\n\nCheck if LOG.md exists in `.claude/` directory:\n\n**If LOG.md doesn''t exist:**\n- Create it using the template in `references/log_template.md`\n- Add project header with name from CLAUDE.md\n- Create first entry\n\n**If LOG.md exists:**\n- Read existing content\n- Add new entry at the top (reverse chronological order)\n- Preserve existing entries\n\n### Step 4: Format Log Entry\n\nEach entry should include:\n\n```markdown\n## YYYY-MM-DD HH:MM\n\n### [TYPE] Title\n\n**Context:** Brief explanation of why this happened\n\n**What Changed:**\n- Specific change 1\n- Specific change 2\n- Specific change 3\n\n**Impact:**\n- How this affects the project\n- Any breaking changes\n- Follow-up actions needed\n\n**Related:**\n- Links to commits, PRs, or issues (if applicable)\n- References to relevant files or documentation\n```\n\n**Entry Types:**\n- `[FEAT]` - New feature\n- `[FIX]` - Bug fix\n- `[DECISION]` - Architectural/technical decision\n- `[REFACTOR]` - Code refactoring\n- `[DOCS]` - Documentation update\n- `[DEPS]` - Dependency update\n- `[CONFIG]` - Configuration change\n- `[MILESTONE]` - Milestone reached\n- `[ISSUE]` - Problem or limitation\n\n### Step 5: Add Entry Example\n\n**Good entry:**\n```markdown\n## 2025-12-30 15:30\n\n### [FEAT] Added skill-analyzer meta-skill\n\n**Context:** Need automated skill selection when starting projects. Manual skill\ndiscovery is time-consuming and error-prone.\n\n**What Changed:**\n- Created skill-analyzer meta-skill in `.claude/skills/`\n- Implemented workflow to scan SkillOS library\n- Added skill matching heuristics based on project context\n- Updates CLAUDE.md sections 5 (Available Skills) and 6 (Missing Skills)\n\n**Impact:**\n- Automates skill selection for new projects\n- Identifies gaps requiring project-specific skills\n- Completes the project setup workflow (works with project-context-generator)\n\n**Related:**\n- Commit: b27c2ea\n- Files: `.claude/skills/skill-analyzer/SKILL.md`\n```\n\n**Avoid vague entries:**\n```markdown\n## 2025-12-30\n\nUpdated some files.\n```\n\n### Step 6: Update Maintenance Notes in CLAUDE.md\n\nAfter logging, optionally update the \"Maintenance Notes\" section in CLAUDE.md:\n- Update \"Last Updated\" date\n- Add entry to \"Recent Changes\"\n- Update \"Known Issues\" if relevant\n\n## Log Organization\n\n### Reverse Chronological Order\n\nMost recent entries appear first:\n```markdown\n# Project Log: SkillOS\n\n## 2025-12-30 16:00\n[Most recent]\n\n## 2025-12-30 14:00\n\n## 2025-12-29 10:00\n[Oldest at bottom]\n```\n\n### Grouping by Date\n\nFor multiple entries on the same day, use subheadings:\n```markdown\n## 2025-12-30\n\n### 16:00 - [FEAT] Added feature X\n...\n\n### 14:00 - [FIX] Fixed bug Y\n...\n```\n\n## Best Practices\n\n### Be Specific\n\n- Include file paths, function names, or specific components\n- Mention exact version numbers for dependencies\n- Reference commits, PRs, or issues\n\n### Explain \"Why\"\n\n- Document the rationale behind decisions\n- Explain trade-offs considered\n- Note what alternatives were rejected\n\n### Track Impact\n\n- Note what breaks (breaking changes)\n- Identify follow-up work needed\n- Update known issues\n\n### Regular Updates\n\n- Log after completing significant work\n- Don''t batch too many changes into one entry\n- Update while details are fresh\n\n## Example LOG.md Structure\n\nSee `references/log_template.md` for the complete template and examples.\n\n## Resources\n\n### references/log_template.md\n\nTemplate for creating LOG.md files with:\n- Header structure\n- Entry format examples\n- Best practices\n- Sample entries for different types\n"},"lastSynced":"2026-03-08T02:03:54.825Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude, AutoGPT, and LangChain needing structured project logging and progress tracking.","zh":"适合像 Claude、AutoGPT 和 LangChain 这样的 AI Agents，需要结构化的项目日志记录和进度跟踪。","ja":"Claude、AutoGPT、LangChain などの構造化されたプロジェクトログ記録と進度追跡が必要な AI エージェントに適しています。","ko":"Claude, AutoGPT, LangChain과 같은 구조화된 프로젝트 로그 기록 및 진행 상황 추적이 필요한 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA como Claude, AutoGPT y LangChain que necesitan registro de proyecto estructurado y seguimiento de progreso.","fr":"Idéal pour les agents d''IA comme Claude, AutoGPT et LangChain nécessitant un enregistrement de projet structuré et un suivi de progression.","de":"Ideal für KI-Agents wie Claude, AutoGPT und LangChain, die ein strukturiertes Projektprotokoll und eine Fortschrittsverfolgung benötigen.","pt":"Ideal para Agentes de IA como Claude, AutoGPT e LangChain que necessitam de registro de projetos estruturados e rastreamento de progresso.","ru":"Идеально для агентов ИИ, таких как Claude, AutoGPT и LangChain, требующих структурированного ведения журнала проектов и отслеживания прогресса.","ar":"مثالي للوكلاء الذكية مثل Claude و AutoGPT و LangChain الذين يحتاجون إلى تسجيل مشروع منظم وتتبع التقدم."},"recommendation":{"en":"Empowers agents to maintain a comprehensive project log, utilizing timestamped entries in LOG.md files to track progress, decisions, and updates, while reading CLAUDE.md for project context.","zh":"赋予代理维护综合项目日志的能力，利用 LOG.md 文件中的时间戳条目来跟踪进度、决策和更新，同时读取 CLAUDE.md 以获取项目背景。","ja":"エージェントが包括的なプロジェクトログを保持する能力を与え、LOG.md ファイル内のタイムスタンプ付きのエントリを使用して進度、決定、更新を追跡し、プロジェクトのコンテキストを取得するために CLAUDE.md を読み取ります。","ko":"에이전트가 포괄적인 프로젝트 로그를 유지하도록 하는 기능을 제공하여 LOG.md 파일의 타임스탬프가 있는 항목을 사용하여 진행 상황, 결정 및 업데이트를 추적하고 프로젝트의 컨텍스트를 얻기 위해 CLAUDE.md를 읽습니다.","es":"Habilita a los agentes a mantener un registro de proyecto integral, utilizando entradas con marca de tiempo en archivos LOG.md para realizar un seguimiento del progreso, las decisiones y las actualizaciones, mientras lee el archivo CLAUDE.md para obtener el contexto del proyecto.","fr":"Permet aux agents de maintenir un journal de projet complet, en utilisant des entrées avec horodatage dans les fichiers LOG.md pour suivre les progrès, les décisions et les mises à jour, tout en lisant le fichier CLAUDE.md pour obtenir le contexte du projet.","de":"Ermöglicht es den Agents, ein umfassendes Projektprotokoll zu führen, indem sie mit Zeitstempel versehene Einträge in LOG.md-Dateien verwenden, um den Fortschritt, die Entscheidungen und die Aktualisierungen zu verfolgen, während sie die CLAUDE.md-Datei für den Projektzusammenhang lesen.","pt":"Permite que os agentes mantenham um registro de projeto abrangente, utilizando entradas com carimbo de data e hora em arquivos LOG.md para rastrear o progresso, decisões e atualizações, enquanto lê o arquivo CLAUDE.md para contexto do projeto.","ru":"Позволяет агентам вести всесторонний журнал проекта, используя записи с меткой времени в файлах LOG.md для отслеживания прогресса, решений и обновлений, а также читая файл CLAUDE.md для контекста проекта.","ar":"يمكن للوكلاء الحفاظ على سجل مشروع شامل باستخدام إدخالات مطبوعة بالتاريخ والوقت في ملفات LOG.md لتتبع التقدم والقرارات والتحديثات، وقراءة ملف CLAUDE.md لسياق المشروع."},"useCases":{"en":["Documenting significant task completions and milestones","Logging important architectural or technical decisions","Recording issue resolutions and new feature additions"],"zh":["记录重要任务的完成和里程碑","记录重要的架构或技术决策","记录问题解决和新功能添加"],"ja":["重要なタスクの完了とマイルストーンを記録する","重要なアーキテクチャや技術的な決定を記録する","問題の解決と新しい機能の追加を記録する"],"ko":["중요한 작업의 완료 및 里程碑를 기록","중요한 아키텍처 또는 기술적인 결정을 기록","문제의 해결 및 새로운 기능 추가를 기록"],"es":["Documentar la finalización de tareas y hitos importantes","Registrar decisiones arquitectónicas o técnicas importantes","Grabar resoluciones de problemas y nuevas adiciones de características"],"fr":["Documenter les achèvements de tâches et les jalons importants","Enregistrer les décisions architecturales ou techniques importantes","Enregistrer les résolutions de problèmes et les nouvelles additions de fonctionnalités"],"de":["Dokumentieren der Fertigstellung von Aufgaben und wichtigen Meilensteinen","Aufzeichnen wichtiger architektonischer oder technischer Entscheidungen","Aufzeichnen der Lösung von Problemen und neuer Hinzufügungen von Funktionen"],"pt":["Documentar conclusões de tarefas importantes e marcos","Registrar decisões arquiteturais ou técnicas importantes","Gravar resoluções de problemas e adições de novos recursos"],"ru":["Документирование значимых завершений задач и вех","Учет важных архитектурных или технических решений","Запись решений проблем и добавлений новых функций"],"ar":["توثيق إكمال المهام المهمة والمراحل الرئيسية","تسجيل القرارات الهيكلية أو التقنية المهمة","تسجيل حلول المشكلات وإضافات الميزات الجديدة"]},"limitations":{"en":["Requires access to CLAUDE.md for project context","Limited to logging in LOG.md file format"],"zh":["需要访问 CLAUDE.md 以获取项目背景","仅限于 LOG.md 文件格式的日志记录"],"ja":["プロジェクトのコンテキストを取得するために CLAUDE.md へのアクセスが必要","LOG.md ファイル形式のログ記録のみが可能"],"ko":["프로젝트의 컨텍스트를 얻기 위해 CLAUDE.md에 대한 액세스가 필요","LOG.md 파일 형식의 로그 기록만 가능"],"es":["Requiere acceso a CLAUDE.md para obtener el contexto del proyecto","Limitado a la registrazione en formato de archivo LOG.md"],"fr":["Nécessite un accès à CLAUDE.md pour obtenir le contexte du projet","Limité à l''enregistrement dans le format de fichier LOG.md"],"de":["Benötigt Zugriff auf CLAUDE.md für den Projektzusammenhang","Begrenzt auf die Aufzeichnung im LOG.md-Dateiformat"],"pt":["Requer acesso ao arquivo CLAUDE.md para contexto do projeto","Limitado ao registro no formato de arquivo LOG.md"],"ru":["Требует доступа к файлу CLAUDE.md для контекста проекта","Ограничен ведением журнала в формате файла LOG.md"],"ar":["يتطلب الوصول إلى ملف CLAUDE.md لسياق المشروع","محدود بتسجيل في تنسيق ملف LOG.md"]},"version":4},"contentHash":"a92d3fb70b0a7cc0206e858848e714e4f61764c3448105b6ef00d4fd7e07d7a4","qualityScore":48}');
