INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dudusoar/skillOS/project-logger', 'project-logger', 'dudusoar', 'skillOS', 'community', 'project-logger dudusoar skillOS community The project-logger skill maintains a structured project log, tracking progress and important updates. It benefits AI developers by providing a personal operating system for managing AI skills. Project Logger 是一个用于管理 AI 工具的个人操作系统，通过结构化的项目日志和上下文分离来支持生命周期管理 Project Logger は、AI エージェントのライフサイクルを管理するためのパーソナルオペレーティングシステムです Project Logger는 AI 에이전트를 위한 개인 운영 체제로, 구조화된 프로젝트 로그와 컨텍스트 분리를 통해 생명주기 관리를 지원합니다 Project-logger es un sistema operativo personal para gestionar habilidades de IA con soporte de ciclo de vida, separación de contexto y aprendizaje evolutivo. Project-logger est un système d''exploitation personnel pour gérer des compétences d''IA avec prise en charge du cycle de vie, séparation de contexte et apprentissage évolutif. Project-logger ist ein persönliches Betriebssystem für die Verwaltung von KI-Fähigkeiten mit Lebenszyklus-Unterstützung, Kontexttrennung und evolutionärem Lernen. O Project Logger é uma ferramenta de registro de projetos que ajuda a gerenciar projetos com eficiência, criando entradas de log com timestamp para acompanhar o progresso. Project Logger - это инструмент для управления проектами, который помогает отслеживать прогресс и решения, создавая записи журнала с меткой времени. مشروع محول هو أداة لتسجيل المشاريع التي تساعد في إدارة المشاريع بفعالية، من خلال إنشاء إدخالات سجل مع توقيت للتحديثات how to use project-logger project-logger setup guide project-logger alternative project-logger vs other AI skills project-logger install what is project-logger project-logger for AI agents project-logger lifecycle support project-logger context separation AI 工具 Project Logger 项目管理 生命周期管理 结构化项目日志 上下文分离 AI 项目管理 个人操作系统 Maintains a structured project log (LOG.md) to track progress and updates Reads CLAUDE.md to understand project context Creates timestamped entries documenting project evolution Supports tracking completed tasks, decisions, and important updates Enables evolutionary learning through log analysis Separates context for organized project management project-logger is a personal operating system for managing AI skills with features like lifecycle support, context separation, and evolutionary learning.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MenachemShanowitz/LubavitchRV/create-lwc-tab', 'community', 'MenachemShanowitz', 'LubavitchRV', 'MenachemShanowitz/LubavitchRV', 'create-lwc-tab', 0, 0, 48, '2026-03-08T01:57:15.352Z', '2026-03-08T02:03:55.029Z', '412e177557ff03bc708b050cd967efa5b1c0d1a7cf77c85177208e78feaa7494', '{"id":"MenachemShanowitz/LubavitchRV/create-lwc-tab","name":"create-lwc-tab","description":{"en":"The create-lwc-tab skill creates a new Lightning Web Component along with necessary tab and flexipage metadata. It benefits developers by streamlining the creation of standalone pages.","zh":"create-lwc-tab技能创建新的Lightning Web Component和必要的选项卡元数据","ja":"create-lwc-tabスキルは、LWCとタブメタデータを作成します","ko":"create-lwc-tab 스킬은 LWC와 탭 메타데이터를 생성합니다","es":"Create-lwc-tab es una herramienta de AI que permite a los desarrolladores crear componentes Lightning Web con pestañas de forma rápida y sencilla","fr":"Create-lwc-tab est un outil d''IA qui permet aux développeurs de créer des composants Lightning Web avec onglets de manière rapide et simple","de":"Create-lwc-tab ist ein KI-Tool, das es Entwicklern ermöglicht, Lightning-Web-Componente mit Registerkarten schnell und einfach zu erstellen","pt":"O create-lwc-tab cria um novo componente Lightning Web com a necessária metadata de guia e flexipage para acessá-lo como página autônoma","ru":"Create-lwc-tab создает новый компонент Lightning Web с необходимой метаданными вкладки и flexipage для доступа к нему как к самостоятельной странице с помощью ИИ Агентов","ar":"إنشاء مكون ويب باهر مع علامات التبويب ومتادات Flexipage اللازمة لجعلها страницة مستقلة لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"create-lwc-tab: LWC Tab Creation Setup Guide | AI Agent S...","zh":"创建LWC选项卡设置指南","ja":"LWCタブを作成するベストプラクティス - AIエージェント","ko":"LWC 탭 생성 가이드 - AI 도구","es":"Guía de configuración de create-lwc-tab para desarrolladores","fr":"Guide de configuration de create-lwc-tab pour les dévelop...","de":"Einrichtungsanleitung für create-lwc-tab-Entwickler","pt":"Guia de Configuração do create-lwc-tab para Desenvolvedores","ru":"Настройка create-lwc-tab: Руководство для Разработчиков И...","ar":"دليل إعداد create-lwc-tab لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to create Lightning Web Components with tabs using create-lwc-tab. Learn to generate necessary metadata for standalone pages and get started wit...","zh":"使用create-lwc-tab技能创建新的Lightning Web Component和必要的选项卡元数据","ja":"LWCタブを作成するためのスキル - create-lwc-tabを使用してLightning Web Componentとタブメタデータを作成","ko":"LWC 탭을 생성하는 방법 - create-lwc-tab 스킬을 사용하여 Lightning Web Component와 탭 메타데이터를 생성","es":"Aprende a crear un componente Lightning Web con pestaña utilizando create-lwc-tab. Descubre cómo configurar y utilizar esta herramienta de AI para desarrolla...","fr":"Découvrez comment créer un composant Lightning Web avec onglet à l''aide de create-lwc-tab. Apprenez à configurer et utiliser cet outil d''IA pour les développ...","de":"Erfahren Sie, wie Sie ein Lightning-Web-Component mit Registerkarte mithilfe von create-lwc-tab erstellen. Entdecken Sie, wie Sie diese KI-Tool für Entwickle...","pt":"Aprenda a criar um componente Lightning Web com guias usando o create-lwc-tab. Descubra como configurar e implementar com facilidade","ru":"Изучите, как создать компонент Lightning Web с вкладками, используя create-lwc-tab. Настройка и реализация за несколько шагов с ИИ Агентами","ar":"اكتشف كيفية إنشاء مكون ويب باهر مع علامات التبويب باستخدام create-lwc-tab. إعداد وتثبيت سهل لأدوات الذكاء الاصطناعي"},"definition":{"en":"create-lwc-tab is a skill that generates a new Lightning Web Component along with the necessary tab and flexipage metadata to make it accessible as a standalone page.","zh":"create-lwc-tab是创建LWC和选项卡元数据的技能","ja":"create-lwc-tabは、LWCとタブメタデータを作成するスキルです","ko":"create-lwc-tab는 LWC와 탭 메타데이터를 생성하는 스킬입니다","es":"Create-lwc-tab es una herramienta de AI que crea componentes Lightning Web con pestañas y metadatos de flexipage","fr":"Create-lwc-tab est un outil d''IA qui crée des composants Lightning Web avec onglets et des métadonnées de flexipage","de":"Create-lwc-tab ist ein KI-Tool, das Lightning-Web-Componente mit Registerkarten und Flexipage-Metadaten erstellt","pt":"O create-lwc-tab é uma ferramenta que cria componentes Lightning Web com guias","ru":"Create-lwc-tab - это инструмент, создающий компоненты Lightning Web с вкладками для ИИ Агентов","ar":"إنشاء مكون ويب باهر مع علامات التبويب هو أداة لإنشاء مكونات الويب الباهرة مع علامات التبويب لأدوات الذكاء الاصطناعي"},"features":{"en":["Creates a new Lightning Web Component using JavaScript and LightningElement","Generates necessary tab and flexipage metadata for standalone pages","Creates a directory structure for the component, including a force-app/main/default/lwc/{componentName} folder","Supports camelCase component names, such as pledgeList","Exports a default class that extends LightningElement"],"zh":["创建新的Lightning Web Component","生成必要的选项卡元数据","支持camelCase命名风格","创建目录和文件结构","使用LightningElement类"],"ja":["LWCの作成","タブメタデータの生成","camelCase命名スタイルのサポート","ディレクトリとファイル構造の作成","LightningElementクラスの使用"],"ko":["LWC 생성","탭 메타데이터 생성","camelCase命名 스타일 지원","디렉토리와 파일 구조 생성","LightningElement 클래스 사용"],"es":["Crea componentes Lightning Web con pestañas","Genera metadatos de flexipage para acceso como página independiente","Utiliza JavaScript y LightningElement para la creación de componentes","Permite la creación de directorios y archivos personalizados","Soporta la configuración de componentes con nombres en camelCase"],"fr":["Crée des composants Lightning Web avec onglets","Génère des métadonnées de flexipage pour accéder comme page indépendante","Utilise JavaScript et LightningElement pour la création de composants","Permet la création de dossiers et de fichiers personnalisés","Prend en charge la configuration de composants avec des noms en camelCase"],"de":["Erstellt Lightning-Web-Componente mit Registerkarten","Generiert Flexipage-Metadaten für den Zugriff als eigenständige Seite","Verwendet JavaScript und LightningElement für die Erstellung von Componenten","Ermöglicht die Erstellung von benutzerdefinierten Verzeichnissen und Dateien","Unterstützt die Konfiguration von Componenten mit Namen in camelCase"],"pt":["Criação de componente Lightning Web com guias","Geração de metadata de guia e flexipage","Acesso como página autônoma","Uso de JavaScript para desenvolvimento","Integração com LightningElement"],"ru":["Создание компонента Lightning Web с вкладками","Генерация метаданных вкладки и flexipage","Доступ как самостоятельная страница","Использование JavaScript для разработки","Интеграция с LightningElement для ИИ Агентов"],"ar":["إنشاء مكون ويب باهر مع علامات التبويب","توليد بيانات وصفية للعلامات التبويب و Flexipage","الوصول كموقع مستقل","استخدام جافاسكريبت للتنمية","التكامل مع LightningElement لأدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use create-lwc-tab","create-lwc-tab setup guide","create-lwc-tab alternative","create-lwc-tab vs lightning web component builder","create-lwc-tab install","what is create-lwc-tab","create-lwc-tab tutorial","create-lwc-tab for developers","create-lwc-tab and lightning web components"],"zh":["create-lwc-tab","LWC","Lightning Web Component","选项卡元数据","AI工具","AIエージェント","JavaScript","LightningElement"],"ja":["create-lwc-tab","LWC","Lightning Web Component","タブメタデータ","AIエージェント","JavaScript","LightningElement","Salesforce"],"ko":["create-lwc-tab","LWC","Lightning Web Component","탭 메타데이터","AI 도구","JavaScript","LightningElement","Salesforce"],"es":["create-lwc-tab","herramientas de AI para desarrolladores","componentes Lightning Web","pestañas en Lightning Web","metadatos de flexipage","JavaScript en Lightning Web","desarrollo de aplicaciones en Salesforce"],"fr":["create-lwc-tab","outils d''IA pour les développeurs","composants Lightning Web","onglets dans Lightning Web","métadonnées de flexipage","JavaScript dans Lightning Web","développement d''applications sur Salesforce"],"de":["create-lwc-tab","KI-Tools für Entwickler","Lightning-Web-Componente","Registerkarten in Lightning Web","Flexipage-Metadaten","JavaScript in Lightning Web","Anwendungsentwicklung in Salesforce"],"pt":["create-lwc-tab","componente Lightning Web","guias","metadata","flexipage","desenvolvimento web","JavaScript","LightningElement","ferramentas de desenvolvimento"],"ru":["create-lwc-tab","компонент Lightning Web","вкладки","метаданные","flexipage","разработка веб-приложений","JavaScript","LightningElement","инструменты разработки для ИИ Агентов"],"ar":["create-lwc-tab","مكون ويب باهر","علامات التبويب","بيانات وصفية","Flexipage","تطوير الويب","جافاسكريبت","LightningElement","أدوات التطوير لأدوات الذكاء الاصطناعي"]}},"owner":"MenachemShanowitz","repo":"LubavitchRV","repoPath":"MenachemShanowitz/LubavitchRV","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.352Z","topics":[],"category":"community","skillMd":{"name":"create-lwc-tab","description":"Creates a new Lightning Web Component with a tab and flexipage for display. Use when you need to create a new standalone page/tab with an LWC component.","bodyPreview":"# Create LWC with Tab\n\nCreates a new Lightning Web Component along with the necessary tab and flexipage metadata to make it accessible as a standalone page.\n\n## Arguments\n\n`$ARGUMENTS` should be the component name in camelCase (e.g., `pledgeList`)\n\n## Files to Create\n\n### 1. LWC Component\n\nCreate directory: `force-app/main/default/lwc/{componentName}/`\n\n**{componentName}.js**:\n```javascript\nimport { LightningElement } from ''lwc'';\n\nexport default class ComponentName extends LightningElement {","body":"# Create LWC with Tab\n\nCreates a new Lightning Web Component along with the necessary tab and flexipage metadata to make it accessible as a standalone page.\n\n## Arguments\n\n`$ARGUMENTS` should be the component name in camelCase (e.g., `pledgeList`)\n\n## Files to Create\n\n### 1. LWC Component\n\nCreate directory: `force-app/main/default/lwc/{componentName}/`\n\n**{componentName}.js**:\n```javascript\nimport { LightningElement } from ''lwc'';\n\nexport default class ComponentName extends LightningElement {\n    // Component logic\n}\n```\n\n**{componentName}.html**:\n```html\n<template>\n    <!-- Component template -->\n</template>\n```\n\n**{componentName}.js-meta.xml**:\n```xml\n<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<LightningComponentBundle xmlns=\"http://soap.sforce.com/2006/04/metadata\">\n    <apiVersion>62.0</apiVersion>\n    <isExposed>true</isExposed>\n    <targets>\n        <target>lightning__Tab</target>\n        <target>lightning__AppPage</target>\n        <target>lightning__HomePage</target>\n    </targets>\n</LightningComponentBundle>\n```\n\n### 2. Custom Tab (Optional)\n\nCreate: `force-app/main/default/tabs/{TabName}.tab-meta.xml`\n\n```xml\n<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<CustomTab xmlns=\"http://soap.sforce.com/2006/04/metadata\">\n    <label>Tab Label</label>\n    <lwcComponent>{componentName}</lwcComponent>\n    <motif>Custom70: Handsaw</motif>\n</CustomTab>\n```\n\n### 3. Lightning App Page (Recommended)\n\nCreate: `force-app/main/default/flexipages/{Page_Name}.flexipage-meta.xml`\n\n**Important**: Component instances MUST have an `<identifier>` element or deployment fails.\n\n```xml\n<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<FlexiPage xmlns=\"http://soap.sforce.com/2006/04/metadata\">\n    <flexiPageRegions>\n        <itemInstances>\n            <componentInstance>\n                <componentName>c:{componentName}</componentName>\n                <identifier>{componentName}1</identifier>\n            </componentInstance>\n        </itemInstances>\n        <name>main</name>\n        <type>Region</type>\n    </flexiPageRegions>\n    <masterLabel>Page Label</masterLabel>\n    <template>\n        <name>flexipage:defaultAppHomeTemplate</name>\n    </template>\n    <type>AppPage</type>\n</FlexiPage>\n```\n\n## Deploy\n\n```bash\nsf project deploy start \\\n  --source-dir force-app/main/default/lwc/{componentName} \\\n  --source-dir force-app/main/default/flexipages/{Page_Name}.flexipage-meta.xml \\\n  --target-org lubavitchrv_partial \\\n  --wait 10\n```\n\n## After Deployment\n\nNew flexipages require activation before appearing in App Launcher. Use the `activate-lightning-page` skill if needed.\n"},"lastSynced":"2026-03-08T02:03:55.029Z","agentAnalysis":{"suitability":{"en":"Perfect for Salesforce Agents needing streamlined Lightning Web Component creation.","zh":"非常适合需要简化Lightning Web Component创建的Salesforce Agents。","ja":"Lightning Web Componentの作成を簡略化する必要があるSalesforceエージェントに最適です。","ko":"Lightning Web Component 생성을 간소화해야 하는 Salesforce 에이전트에게 완벽합니다.","es":"Perfecto para agentes de Salesforce que necesitan una creación de componentes de Lightning Web Component optimizada.","fr":"Parfait pour les agents Salesforce ayant besoin d''une création de composants Lightning Web Component rationalisée.","de":"Perfekt für Salesforce-Agenten, die eine optimierte Erstellung von Lightning-Web-Komponenten benötigen.","pt":"Perfeito para agentes do Salesforce que precisam de criação de componentes de Lightning Web Component simplificados.","ru":"Идеально для агентов Salesforce, которым необходима упрощенная создания компонентов Lightning Web Component.","ar":"مثالي لعمال Salesforce الذين يحتاجون إلى إنشاء مكونات Lightning Web Component مبسطة."},"recommendation":{"en":"Empowers agents to generate Lightning Web Components with necessary tab and flexipage metadata, utilizing LightningElement from ''lwc'', to create standalone pages in Salesforce environments, supporting camelCase component names and directory structures like ''force-app/main/default/lwc/{componentName}/''.","zh":"赋予代理生成带有必要标签和flexipage元数据的Lightning Web Components，利用''lwc''中的LightningElement，在Salesforce环境中创建独立页面，支持驼峰式命名的组件名称和目录结构，如''force-app/main/default/lwc/{componentName}/''。","ja":"エージェントが必要なタブとflexipageメタデータを使用してLightning Web Componentsを生成できるようにし、''lwc''内のLightningElementを使用して、Salesforce環境でスタンドアロンページを作成し、''force-app/main/default/lwc/{componentName}/''のようなカメルケースのコンポーネント名とディレクトリ構造をサポートする。","ko":"에이전트가 필요한 탭 및 flexipage 메타데이터를 사용하여 Lightning Web Components를 생성할 수 있도록 하며, ''lwc'' 내의 LightningElement를 사용하여 Salesforce 환경에서 독립页面를 생성하며, ''force-app/main/default/lwc/{componentName}/''와 같은 카멜케이스 컴포넌트 이름 및 디렉토리 구조를 지원합니다.","es":"Habilita a los agentes para generar componentes de Lightning Web con los metadatos de pestaña y flexipage necesarios, utilizando LightningElement desde ''lwc'', para crear páginas independientes en entornos de Salesforce, que admiten nombres de componentes en camelCase y estructuras de directorios como ''force-app/main/default/lwc/{componentName}/''.","fr":"Permet aux agents de générer des composants Lightning Web avec les métadonnées de l''onglet et de flexipage nécessaires, en utilisant LightningElement à partir de ''lwc'', pour créer des pages autonomes dans les environnements Salesforce, en prenant en charge les noms de composants en camelCase et les structures de répertoires comme ''force-app/main/default/lwc/{componentName}/''.","de":"Ermöglicht es Agenten, Lightning-Web-Komponenten mit den notwendigen Registerkarten- und Flexipage-Metadaten zu generieren, indem LightningElement von ''lwc'' verwendet wird, um eigenständige Seiten in Salesforce-Umgebungen zu erstellen, die camelCase-Komponentennamen und Verzeichnisstrukturen wie ''force-app/main/default/lwc/{componentName}/'' unterstützen.","pt":"Habilita os agentes a gerar componentes de Lightning Web Component com metadados de guia e flexipage necessários, utilizando LightningElement do ''lwc'', para criar páginas autônomas em ambientes do Salesforce, com suporte a nomes de componentes em camelCase e estruturas de diretório como ''force-app/main/default/lwc/{componentName}/''.","ru":"Наделяет агентов возможностью генерировать компоненты Lightning Web Component с необходимыми метаданными вкладки и flexipage, используя LightningElement из ''lwc'', для создания самостоятельных страниц в средах Salesforce, поддерживающих имена компонентов в camelCase и структуры директорий как ''force-app/main/default/lwc/{componentName}/''.","ar":"تمكّن الوكلاء من генераlightning web component مع البيانات الوصفية الضرورية للعلامة والصفحة المرنة، باستخدام LightningElement من ''lwc''، لإنشاء صفحات مستقلة في بيئات Salesforce، مع دعم أسماء المكونات بالحالة الحمير (camelCase) وهياكل الدلائل مثل ''force-app/main/default/lwc/{componentName}/''."},"useCases":{"en":["Automating LWC component creation with tab and flexipage setup","Generating standalone pages in Salesforce using LWC","Streamlining development workflows for Salesforce developers by creating directory structures and necessary metadata"],"zh":["使用标签和flexipage设置自动创建LWC组件","在Salesforce中使用LWC生成独立页面","通过创建目录结构和必要的元数据来简化Salesforce开发人员的开发工作流"],"ja":["タブとflexipageの設定でLWCコンポーネントの自動生成","SalesforceでLWCを使用してスタンドアロンページを生成","ディレクトリ構造と必要なメタデータの作成によってSalesforce開発者の開発ワークフローを簡略化"],"ko":["탭 및 flexipage 설정으로 LWC 컴포넌트 자동 생성","Salesforce에서 LWC를 사용하여 독립 페이지 생성","디렉토리 구조 및 필요한 메타데이터 생성을 통해 Salesforce 개발자의 개발 워크플ロー 간소화"],"es":["Automatización de la creación de componentes LWC con configuración de pestaña y flexipage","Generación de páginas independientes en Salesforce mediante LWC","Optimización de flujos de trabajo de desarrollo para desarrolladores de Salesforce mediante la creación de estructuras de directorios y metadatos necesarios"],"fr":["Automatisation de la création de composants LWC avec configuration de l''onglet et de flexipage","Génération de pages autonomes dans Salesforce à l''aide de LWC","Optimisation des flux de travail de développement pour les développeurs Salesforce en créant des structures de répertoires et des métadonnées nécessaires"],"de":["Automatisierung der Erstellung von LWC-Komponenten mit Registerkarten- und Flexipage-Konfiguration","Generierung von eigenständigen Seiten in Salesforce mithilfe von LWC","Optimierung von Entwicklungsworkflows für Salesforce-Entwickler durch die Erstellung von Verzeichnisstrukturen und notwendigen Metadaten"],"pt":["Automatizar a criação de componentes LWC com configuração de guia e flexipage","Gerar páginas autônomas no Salesforce usando LWC","Simplificar fluxos de trabalho de desenvolvimento para desenvolvedores do Salesforce, criando estruturas de diretório e metadados necessários"],"ru":["Автоматизировать создание компонентов LWC с настройкой вкладки и flexipage","Генерировать самостоятельные страницы в Salesforce, используя LWC","Упростить рабочие потоки разработки для разработчиков Salesforce, создавая структуры директорий и необходимые метаданные"],"ar":["توفير автомاتيزيرون لإنشاء مكونات LWC مع إعداد علامة وصفحة مرنة","генерировать صفحات مستقلة في Salesforce باستخدام LWC","تسهيل سير عمل التطوير لمطوري Salesforce، من خلال إنشاء هياكل دلائل وبيانات وصفية ضرورية"]},"limitations":{"en":["Requires Salesforce environment setup","Limited to Lightning Web Components","Component name must be in camelCase"],"zh":["需要Salesforce环境设置","仅限Lightning Web Components","组件名称必须是驼峰式"],"ja":["Salesforce環境の設定が必要","Lightning Web Componentsのみ","コンポーネント名はカメルケースでなければならない"],"ko":["Salesforce 환경 설정이 필요","Lightning Web Components만 해당","컴포넌트 이름은 카멜케이스여야 함"],"es":["Requiere configuración del entorno de Salesforce","Limitado a componentes de Lightning Web","El nombre del componente debe estar en camelCase"],"fr":["Nécessite une configuration de l''environnement Salesforce","Limité aux composants Lightning Web","Le nom du composant doit être en camelCase"],"de":["Benötigt eine Konfiguration der Salesforce-Umgebung","Begrenzt auf Lightning-Web-Komponenten","Der Komponentenname muss in camelCase sein"],"pt":["Requer configuração de ambiente do Salesforce","Limitado a componentes de Lightning Web Component","O nome do componente deve estar em camelCase"],"ru":["Требует настройки среды Salesforce","Ограничен компонентами Lightning Web Component","Имя компонента должно быть в camelCase"],"ar":["يتطلب إعداد بيئة Salesforce","محدود بمكونات Lightning Web Component","يجب أن يكون اسم المكون بالحالة الحمير (camelCase)"]},"version":4},"contentHash":"412e177557ff03bc708b050cd967efa5b1c0d1a7cf77c85177208e78feaa7494","qualityScore":48}');
