INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MenachemShanowitz/LubavitchRV/create-lwc-tab', 'create-lwc-tab', 'MenachemShanowitz', 'LubavitchRV', 'community', 'create-lwc-tab MenachemShanowitz LubavitchRV community The create-lwc-tab skill creates a new Lightning Web Component along with necessary tab and flexipage metadata. It benefits developers by streamlining the creation of standalone pages. create-lwc-tab技能创建新的Lightning Web Component和必要的选项卡元数据 create-lwc-tabスキルは、LWCとタブメタデータを作成します create-lwc-tab 스킬은 LWC와 탭 메타데이터를 생성합니다 Create-lwc-tab es una herramienta de AI que permite a los desarrolladores crear componentes Lightning Web con pestañas de forma rápida y sencilla Create-lwc-tab est un outil d''IA qui permet aux développeurs de créer des composants Lightning Web avec onglets de manière rapide et simple Create-lwc-tab ist ein KI-Tool, das es Entwicklern ermöglicht, Lightning-Web-Componente mit Registerkarten schnell und einfach zu erstellen O create-lwc-tab cria um novo componente Lightning Web com a necessária metadata de guia e flexipage para acessá-lo como página autônoma Create-lwc-tab создает новый компонент Lightning Web с необходимой метаданными вкладки и flexipage для доступа к нему как к самостоятельной странице с помощью ИИ Агентов إنشاء مكون ويب باهر مع علامات التبويب ومتادات Flexipage اللازمة لجعلها страницة مستقلة لأدوات الذكاء الاصطناعي how to use create-lwc-tab create-lwc-tab setup guide create-lwc-tab alternative create-lwc-tab vs lightning web component builder create-lwc-tab install what is create-lwc-tab create-lwc-tab tutorial create-lwc-tab for developers create-lwc-tab and lightning web components create-lwc-tab LWC Lightning Web Component 选项卡元数据 AI工具 AIエージェント JavaScript LightningElement Creates a new Lightning Web Component using JavaScript and LightningElement Generates necessary tab and flexipage metadata for standalone pages Creates a directory structure for the component, including a force-app/main/default/lwc/{componentName} folder Supports camelCase component names, such as pledgeList Exports a default class that extends LightningElement create-lwc-tab is a skill that generates a new Lightning Web Component along with the necessary tab and flexipage metadata to make it accessible as a standalone page.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('stacklok/toolhive-studio/testing-api-overrides', 'community', 'stacklok', 'toolhive-studio', 'stacklok/toolhive-studio', 'testing-api-overrides', 0, 0, 48, '2026-03-08T01:57:15.384Z', '2026-03-08T02:05:44.958Z', 'db8ec95881acc231201437d8793f86bf9456fc5fd63c1a38f15c86c32c30fae7', '{"id":"stacklok/toolhive-studio/testing-api-overrides","name":"testing-api-overrides","description":{"en":"The testing-api-overrides skill allows developers to test API parameters using conditional overrides, ensuring accurate user-facing behavior. This skill benefits developers working with AI agents and MCP servers.","zh":"ToolHive允许您安装、管理和运行MCP服务器，并将其连接到AI代理，使用条件覆盖测试来验证API参数","ja":"ToolHiveはMCPサーバーをインストール、管理、実行し、AIエージェントに接続します。条件付きオーバーライドテストを使用してAPIパラメータを検証します","ko":"ToolHive는 MCP 서버를 설치, 관리 및 실행하고 AI 에이전트에 연결합니다. 조건부 오버라이드 테스트를 사용하여 API 매개 변수를 검증합니다","es":"El testing-api-overrides permite probar APIs con overrides condicionales para verificar el comportamiento de los Agentes de IA. Esto implica configurar mocks condicionales que responden basados en la solicitud.","fr":"Le testing-api-overrides permet de tester les API avec des overrides conditionnels pour vérifier le comportement des Outils d''IA. Cela implique de configurer des mocks conditionnels qui répondent en fonction de la requête.","de":"Das testing-api-overrides ermöglicht das Testen von APIs mit bedingten Overrides, um das Verhalten von AI-Tools zu überprüfen. Dies beinhaltet die Konfiguration von bedingten Mocks, die basierend auf der Anfrage reagieren.","pt":"O teste de API com sobrescrita permite verificar se o código envia parâmetros de API corretos em ToolHive e MCP servers","ru":"Тестирование API с переопределением позволяет проверить, отправляет ли код правильные параметры API в ToolHive и серверах MCP","ar":"اختبار واجهة برمجة التطبيقات مع الإغراق يسمح بفحص 