INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ahmed3elshaer/everything-claude-code-mobile/ktor-patterns', 'ktor-patterns', 'ahmed3elshaer', 'everything-claude-code-mobile', 'community', 'ktor-patterns ahmed3elshaer everything-claude-code-mobile community The ktor-patterns skill makes Claude code mobile-first, providing a modern HTTP client for Kotlin. It benefits developers working with Kotlin and HTTP clients. ktor-patterns是Kotlin的现代HTTP客户端，提供JSON序列化和超时设置等功能，帮助开发者实现移动优先的开发 ktor-patternsはKotlinのモダンHTTPクライアントであり、JSONシリアル化やタイムアウト設定などの機能を提供し、開発者がモバイルファーストの開発を実現するのに役立ちます ktor-patterns는 Kotlin의 현대적인 HTTP 클라이언트로서 JSON 직렬화 및 타임아웃 설정 등의 기능을 제공하며 개발자가 모바일 ファースト의 개발을 구현하는 데 도움이 됩니다 ktor-patterns es una habilidad que permite a los desarrolladores crear clientes HTTP modernos con Kotlin y OkHttp ktor-patterns est une compétence qui permet aux développeurs de créer des clients HTTP modernes avec Kotlin et OkHttp ktor-patterns ist eine Fähigkeit, die es Entwicklern ermöglicht, moderne HTTP-Clients mit Kotlin und OkHttp zu erstellen O Ktor-Patterns é uma biblioteca que ajuda a criar clientes HTTP modernos em Kotlin com recursos como serialização JSON e timeouts personalizáveis Ktor-Patterns - это библиотека, которая помогает создавать современные HTTP-клиенты на Kotlin с функциями, такими как сериализация JSON и настраиваемые таймауты كتور-باتيرنز هي مكتبة تساعد على إنشاء عملاء HTTP حديثة في كوتلين مع ميزات مثل تسلسل JSON وقيم الوقت المعدلة how to use ktor-patterns ktor-patterns setup guide ktor-patterns alternative ktor-patterns vs OkHttp ktor-patterns install what is ktor-patterns ktor-patterns for Kotlin ktor-patterns JSON serialization ktor-patterns HttpTimeout configuration ktor-patterns Kotlin HTTP客户端 移动优先开发 JSON序列化 超时设置 OkHttp ContentNegotiation HTTP客户端设置 Installs ContentNegotiation for JSON serialization Configures HttpTimeout for request, connect, and socket timeouts Utilizes OkHttp for HTTP client functionality Enables JSON serialization with ignoreUnknownKeys and isLenient options Supports prettyPrint option for JSON output Sets up HttpClient with specific timeout values ktor-patterns is a skill that enables mobile-first development using a modern HTTP client for Kotlin, utilizing technologies like OkHttp and JSON serialization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lilliangreenberg/valuations-autonomous_coding/feature-status', 'community', 'lilliangreenberg', 'valuations-autonomous_coding', 'lilliangreenberg/valuations-autonomous_coding', 'feature-status', 0, 0, 48, '2026-03-08T01:57:15.407Z', '2026-03-08T02:06:56.758Z', 'f02a75c851d090f02253b5aa6a628c420caef78bcc5df148579a0b8be4cc4aac', '{"id":"lilliangreenberg/valuations-autonomous_coding/feature-status","name":"feature-status","description":{"en":"The feature-status skill counts features marked as @failing and writes the count to a JSON file, aiding autonomous coding harness in determining loop termination. This benefits AI agent developers in streamlining their implementation process","zh":"Feature Status AI工具用于计算被标记为@failing的功能数量，并将计数写入JSON文件，用于自动化编码","ja":"Feature Status AIエージェントは、@failingとマークされた機能の数をカウントし、JSONファイルに書き込むことで自動化コーディングを実現","ko":"Feature Status AI 에이전트는 @failing으로 표시된 기능의 수를 계산하여 JSON 파일에 쓰고 자동화된 코딩을 구현합니다","es":"El estado de características es una habilidad que cuenta el número de características marcadas como @failing y escribe el recuento en un archivo JSON","fr":"L''état des fonctionnalités est une compétence qui compte le nombre de fonctionnalités marquées comme @failing et écrit le décompte dans un fichier JSON","de":"Der Funktionstatus ist eine Fähigkeit, die die Anzahl der als @failing markierten Funktionen zählt und die Zahl in eine JSON-Datei schreibt","pt":"O Feature Status é uma habilidade que conta recursos marcados como @failing e grava a contagem em um arquivo JSON","ru":"Feature Status — это навык, который подсчитывает функции, помеченные как @failing, и записывает счет в файл JSON","ar":"وضع الميزة هو مهارة تحسب الميزات المُعلّمة @failing وتسجل العدد في ملف JSON"},"seo":{"title":{"en":"feature-status: Loop Termination Setup Guide | AI Agent S...","zh":"Feature Status AI工具配置指南","ja":"Feature Status AIエージェントのセットアップガイド","ko":"Feature Status AI 에이전트 구현 가이드","es":"Configuración de Estado de Características: Guía de Imple...","fr":"État des Fonctionnalités: Guide de Configuration pour les...","de":"Funktionstatus: Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do Feature Status para Ferramentas d...","ru":"Настройка ИИ Агентов с помощью Feature Status","ar":"دليل إعداد وضع الميزة لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how feature-status skill automates loop termination logic. Learn to setup and utilize feature-status for efficient AI agent development","zh":"了解Feature Status AI工具的工作原理，实现自动化编码并优化开发流程","ja":"Feature Status AIエージェントの機能と使い方をマスターし、開発プロセスを最適化する","ko":"Feature Status AI 에이전트의 기능과 구현 방법을 알아보고 개발 프로세스를 최적화 하세요","es":"Aprenda a configurar el estado de características para su proyecto con nuestra guía paso a paso y mejore la eficiencia de su flujo de trabajo de codificación","fr":"Découvrez comment configurer l''état des fonctionnalités pour améliorer votre flux de travail de codage et atteindre la mise en œuvre réussie de vos projets","de":"Erfahren Sie, wie Sie den Funktionstatus für Ihr Projekt konfigurieren und Ihren Codierungs-Workflow optimieren können","pt":"Aprenda a configurar o Feature Status para contabilizar recursos marcados como @failing e otimizar o processo de codificação","ru":"Узнайте, как настроить Feature Status для подсчета функций, помеченных как @failing, и оптимизации процесса кодирования","ar":"تعرف على كيفية إعداد وضع الميزة لحساب الميزات المعلمة @failing وتحسين عملية الكود"},"definition":{"en":"feature-status is a skill that counts the number of features marked as @failing and generates a JSON output file for loop termination logic","zh":"Feature Status AI工具是一种用于自动化编码的技能，计算@failing功能数量","ja":"Feature Status AIエージェントは、@failing機能の数をカウントする自動化コーディングスキル","ko":"Feature Status AI 에이전트는 @failing 기능의 수를 계산하는 자동화된 코딩 스킬입니다","es":"El estado de características es una habilidad de AI que cuenta y registra el estado de implementación de características en un proyecto","fr":"L''état des fonctionnalités est une compétence d''IA qui compte et enregistre l''état de mise en œuvre des fonctionnalités dans un projet","de":"Der Funktionstatus ist eine KI-Fähigkeit, die den Implementierungsstatus von Funktionen in einem Projekt zählt und registriert","pt":"O que é Feature Status? É uma habilidade que contabiliza recursos marcados como @failing","ru":"Что такое Feature Status? Это навык, который подсчитывает функции, помеченные как @failing","ar":"ما هو وضع الميزة؟ هي مهارة تحسب الميزات المُعلّمة @failing"},"features":{"en":["Counts features marked as @failing","Writes count to a JSON file named feature-status.json","Determines loop termination logic based on failing_count","Supports autonomous coding harness","Outputs JSON file with failing_count for loop control","Automates loop termination when failing_count reaches 0"],"zh":["计算被标记为@failing的功能数量","将计数写入JSON文件","用于自动化编码和优化开发流程","支持JSON文件格式","实现循环终止逻辑"],"ja":["@failingとマークされた機能の数をカウント","カウントをJSONファイルに書き込む","自動化コーディングと開発プロセスの最適化","JSONファイル形式のサポート","ループ終了ロジックの実現"],"ko":["@failing으로 표시된 기능의 수를 계산","계산을 JSON 파일에 쓰기","자동화된 코딩과 개발 프로세스 최적화","JSON 파일 형식 지원","루프 종료 로직 구현"],"es":["Cuenta el número de características marcadas como @failing","Escribe el recuento en un archivo JSON llamado feature-status.json","Permite la terminación de la lógica de bucle cuando el recuento de errores llega a 0","Se utiliza en el arnés de codificación autónomo para determinar el final del bucle de implementación","Soporta la implementación de características hasta que todas estén completadas"],"fr":["Compte le nombre de fonctionnalités marquées comme @failing","Écrit le décompte dans un fichier JSON appelé feature-status.json","Permet la terminaison de la logique de boucle lorsque le décompte d''erreurs atteint 0","Est utilisé dans le harnais de codage autonome pour déterminer la fin de la boucle de mise en œuvre","Prend en charge la mise en œuvre de fonctionnalités jusqu''à ce que toutes soient terminées"],"de":["Zählt die Anzahl der als @failing markierten Funktionen","Schreibt die Zahl in eine JSON-Datei mit dem Namen feature-status.json","Ermöglicht die Beendigung der Schleifenlogik, wenn die Fehlerzahl 0 erreicht","Wird im autonomen Codierharnais verwendet, um das Ende der Implementierungsschleife zu bestimmen","Unterstützt die Implementierung von Funktionen, bis alle abgeschlossen sind"],"pt":["Contagem de recursos marcados como @failing","Gravação da contagem em um arquivo JSON","Integração com o autonomous coding harness","Lógica de término de loop baseada em contagem de recursos","Suporte a arquivo JSON de saída"],"ru":["Подсчет функций, помеченных как @failing","Запись счета в файл JSON","Интеграция с autonomous coding harness","Логика завершения цикла на основе счета функций","Поддержка файла JSON вывода"],"ar":["حساب الميزات المُعلّمة @failing","تسجيل العدد في ملف JSON","التكامل مع حزمة البرمجة الذاتية","منطق انتهاء الحلقة بناءً على عدد الميزات","دعم ملف JSON الإخراج"]},"keywords":{"en":["how to use feature-status","feature-status setup guide","what is feature-status","feature-status alternative","feature-status vs autonomous coding","feature-status install","feature-status loop termination","feature-status JSON output","autonomous coding harness feature-status"],"zh":["Feature Status AI工具","自动化编码","JSON文件","AI工具配置","开发流程优化","Feature Status技能"],"ja":["Feature Status AIエージェント","自動化コーディング","JSONファイル","AIエージェントのセットアップ","開発プロセスの最適化","Feature Statusスキル"],"ko":["Feature Status AI 에이전트","자동화된 코딩","JSON 파일","AI 에이전트 구현","개발 프로세스 최적화","Feature Status 스킬"],"es":["estado de características","AI Agentes","Herramientas de codificación","Implementación de características","Arnés de codificación autónomo","feature-status.json","Lógica de bucle","Recuento de errores","Desarrollo de software"],"fr":["état des fonctionnalités","Outils d''IA","Outils de codage","Mise en œuvre de fonctionnalités","Harnais de codage autonome","feature-status.json","Logique de boucle","Décompte d''erreurs","Développement de logiciels"],"de":["Funktionstatus","KI-Tools","Codierwerkzeuge","Implementierung von Funktionen","Autonomes Codierharnais","feature-status.json","Schleifenlogik","Fehlerzählung","Software-Entwicklung"],"pt":["Feature Status","Ferramentas de IA","Autonomous coding harness","Arquivo JSON","Contagem de recursos","Lógica de término de loop","Desenvolvimento de software","Otimização de codificação"],"ru":["Feature Status","ИИ Агенты","Autonomous coding harness","Файл JSON","Подсчет функций","Логика завершения цикла","Разработка программного обеспечения","Оптимизация кодирования"],"ar":["وضع الميزة","أدوات الذكاء الاصطناعي","حزمة البرمجة الذاتية","ملف JSON","حساب الميزات","منطق انتهاء الحلقة","تطوير البرمجيات","تحسين الكود"]}},"owner":"lilliangreenberg","repo":"valuations-autonomous_coding","repoPath":"lilliangreenberg/valuations-autonomous_coding","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.407Z","topics":[],"category":"community","skillMd":{"name":"feature-status","description":"Count features marked as @failing and write to status JSON file. Used to determine when the autonomous coding loop should end.","bodyPreview":"# Feature Status Skill\n\n## Purpose\n\nThis skill counts the number of features marked as `@failing` and writes the count to a JSON file. This is used by the autonomous coding harness to determine when the implementation loop should end (when `failing_count` reaches 0).\n\n## Output File\n\n**File**: `feature-status.json`\n\n**Format**:\n```json\n{\n  \"failing_count\": 3\n}\n```\n\n**Loop Termination Logic**:\n- If `failing_count > 0` → Continue coding sessions\n- If `failing_count == 0` → All features implemented","body":"# Feature Status Skill\n\n## Purpose\n\nThis skill counts the number of features marked as `@failing` and writes the count to a JSON file. This is used by the autonomous coding harness to determine when the implementation loop should end (when `failing_count` reaches 0).\n\n## Output File\n\n**File**: `feature-status.json`\n\n**Format**:\n```json\n{\n  \"failing_count\": 3\n}\n```\n\n**Loop Termination Logic**:\n- If `failing_count > 0` → Continue coding sessions\n- If `failing_count == 0` → All features implemented, end loop\n\n## How It Works\n\n### Step 1: Find Feature Files\n\nUse Glob to find all Gherkin feature files:\n```\nPattern: gherkin.feature_*.feature\n```\n\n### Step 2: Count @failing Tags\n\nFor each feature file:\n1. Read the first few lines\n2. Look for `@failing` tag\n3. If found, increment the failing counter\n\n**Tag Detection**:\n```\n@failing\nFeature: Some Feature Name\n  ...\n```\n\nRead lines until you find either:\n- `@failing` → Count this feature as failing\n- `@passing` → Skip (not failing)\n- `Feature:` line → Stop searching (assume no tag = passing)\n\n### Step 3: Write JSON\n\nWrite `feature-status.json` with just the failing count:\n```json\n{\n  \"failing_count\": <count>\n}\n```\n\n## Usage\n\nSimply invoke the skill:\n```\n/feature-status\n```\n\nThis will:\n1. Scan all `gherkin.feature_*.feature` files in the current directory\n2. Count how many have `@failing` tags\n3. Write the count to `feature-status.json`\n\n## Example Implementation\n\n```python\n# Pseudocode for reference\ndef count_failing_features(directory):\n    failing_count = 0\n\n    # Find all feature files\n    feature_files = glob(\"gherkin.feature_*.feature\")\n\n    for file in feature_files:\n        with open(file) as f:\n            for line in f:\n                line = line.strip()\n\n                if line.startswith(\"@failing\"):\n                    failing_count += 1\n                    break\n                elif line.startswith(\"@passing\"):\n                    break\n                elif line.startswith(\"Feature:\"):\n                    # No tag found, assume passing\n                    break\n\n    return failing_count\n```\n\n## Integration with Autonomous Coding Harness\n\nThe harness can check the status file to decide whether to continue:\n\n```python\nimport json\n\ndef should_continue_loop():\n    with open(\"feature-status.json\") as f:\n        status = json.load(f)\n    return status[\"failing_count\"] > 0\n```\n\n## Best Practices\n\n1. **Run after each coding session** to update the failing count\n2. **Commit the status file** to track progress over time\n3. **Check before starting a new session** to avoid unnecessary runs\n4. **Use as a termination condition** in automation scripts\n"},"lastSynced":"2026-03-08T02:06:56.758Z","agentAnalysis":{"suitability":{"en":"Ideal for Autonomous Coding Agents requiring efficient loop termination logic and JSON file handling.","zh":"适用于需要高效循环终止逻辑和JSON文件处理的自主编码代理。","ja":"効率的なループ終了ロジックとJSONファイルハンドリングを必要とする自律的なコーディングエージェントに最適です。","ko":"효율적인 루프 종료 로직과 JSON 파일 처리가 필요한 자율 코딩 에이전트에 적합합니다.","es":"Ideal para Agentes de Codificación Autónomos que requieren una lógica de terminación de bucle eficiente y manejo de archivos JSON.","fr":"Idéal pour les Agents de Codage Autonomes nécessitant une logique de terminaison de boucle efficace et une gestion de fichiers JSON.","de":"Ideal für Autonome Codierungsagenten, die eine effiziente Schleifenterminierunglogik und eine JSON-Dateihandhabung erfordern.","pt":"Ideal para Agentes de Codificação Autônoma que requerem lógica de término de loop eficiente e manipulação de arquivos JSON.","ru":"Идеально подходит для автономных агентов кодирования, требующих эффективной логики завершения цикла и обработки файлов JSON.","ar":"مثالي لعميل الترميز المستقل الذي يتطلب منطق انتهاء الحلقات بكفاءة ومعالجة ملفات JSON."},"recommendation":{"en":"Empowers agents to streamline implementation processes by tracking feature statuses and writing counts to JSON files, leveraging `@failing` markers and autonomous coding harness integration via `feature-status.json` files.","zh":"通过跟踪功能状态和将计数写入JSON文件，利用`@failing`标记和自主编码测试工具集成通过`feature-status.json`文件，赋予代理简化实现过程的能力。","ja":"`@failing`マーカーと自律的なコーディングハーネスとの統合を通じて`feature-status.json`ファイルを使用して、機能のステータスを追跡し、JSONファイルにカウントを書き込むことで、エージェントは実装プロセスを合理化することができます。","ko":"`@failing` 마커와 자율 코딩 하네스를통한 `feature-status.json` 파일을 사용하여 기능 상태를 추적하고 JSON 파일에 카운트를 작성함으로써, 에이전트는 구현 프로세스를 간소화할 수 있습니다.","es":"Permite a los agentes simplificar los procesos de implementación al realizar un seguimiento del estado de las características y escribir recuentos en archivos JSON, aprovechando los marcadores `@failing` y la integración del arnés de codificación autónoma a través de archivos `feature-status.json`.","fr":"Permet aux agents de rationaliser les processus de mise en œuvre en suivant les statuts de fonctionnalités et en écrivant des décomptes dans des fichiers JSON, en exploitant les marqueurs `@failing` et l''intégration du harnais de codage autonome via des fichiers `feature-status.json`.","de":"Ermöglicht es den Agenten, Implementierungsprozesse zu rationalisieren, indem sie den Status von Funktionen verfolgen und Zähler in JSON-Dateien schreiben, indem sie die Marker `@failing` und die Integration des autonomen Codierungs-Harness über `feature-status.json`-Dateien nutzen.","pt":"Permite que os agentes simplifiquem os processos de implementação, rastreando o status das funcionalidades e escrevendo contagens em arquivos JSON, utilizando marcadores `@failing` e integração de harness de codificação autônoma via arquivos `feature-status.json`.","ru":"Позволяет агентам упростить процессы реализации, отслеживая статус функций и записывая счетчики в файлы JSON, используя маркеры `@failing` и интеграцию с автономным кодированием через файлы `feature-status.json`.","ar":"يمكن للعميل بتصميم العمليات التنفيذية من خلال تتبع حالة الميزات وكتابتها إلى ملفات JSON، مع استخدام علامات `@failing` وتكامل حزمة الترميز الذاتي عبر ملفات `feature-status.json`."},"useCases":{"en":["Automating loop termination based on feature implementation status","Generating JSON reports for feature status tracking","Debugging implementation loops with data-driven termination logic"],"zh":["根据功能实现状态自动化循环终止","生成JSON报告用于功能状态跟踪","使用数据驱动的终止逻辑调试实现循环"],"ja":["機能の実装状況に基づいてループの終了を自動化する","機能のステータストラッキングのためのJSONレポートを生成する","データ駆動の終了ロジックを使用して実装ループをデバッグする"],"ko":["기능 구현 상태에 따라 루프 종료를 자동화","기능 상태 추적을 위한 JSON 보고서 생성","데이터 주도 종료 로직을 사용하여 구현 루프 디버깅"],"es":["Automatizar la terminación de bucles en función del estado de implementación de las características","Generar informes JSON para realizar un seguimiento del estado de las características","Depurar bucles de implementación con una lógica de terminación basada en datos"],"fr":["Automatiser la terminaison de boucles en fonction du statut de mise en œuvre des fonctionnalités","Générer des rapports JSON pour suivre le statut des fonctionnalités","Déboguer les boucles de mise en œuvre avec une logique de terminaison basée sur les données"],"de":["Automatisierung der Schleifenterminierung basierend auf dem Implementierungsstatus von Funktionen","Generierung von JSON-Berichten zur Nachverfolgung des Funktionsstatus","Fehlersuche in Implementierungsschleifen mit datengetriebener Terminierunglogik"],"pt":["Automatizar a terminação de loop com base no status de implementação da funcionalidade","Gerar relatórios JSON para rastreamento do status da funcionalidade","Depurar loops de implementação com lógica de término baseada em dados"],"ru":["Автоматизация завершения цикла на основе статуса реализации функции","Генерирование отчетов JSON для отслеживания статуса функции","Отладка циклов реализации с логикой завершения на основе данных"],"ar":["تأتمة إنهاء الحلقة بناءً على حالة تنفيذ الميزة","توليد تقارير JSON لتتبع حالة الميزة","تصحيح أخطاء الحلقات التنفيذية بالأ منطق إنتهاء الحلقات القائم على البيانات"]},"limitations":{"en":["Requires access to write JSON files","Dependent on `@failing` feature markers","Specific to autonomous coding harness integration"],"zh":["需要访问写入JSON文件","依赖于`@failing`功能标记","特定于自主编码测试工具集成"],"ja":["JSONファイルへの書き込みアクセスが必要","`@failing`機能マーカーに依存する","自律的なコーディングハーネスとの統合に特化している"],"ko":["JSON 파일에 쓰기 액세스가 필요","`@failing` 기능 마커에 의존","자율 코딩 하네스와의 통합에 특화"],"es":["Requiere acceso para escribir archivos JSON","Dependiente de los marcadores de características `@failing`","Específico de la integración del arnés de codificación autónoma"],"fr":["Nécessite un accès pour écrire des fichiers JSON","Dépendant des marqueurs de fonctionnalités `@failing`","Spécifique à l''intégration du harnais de codage autonome"],"de":["Erfordert Zugriff zum Schreiben von JSON-Dateien","Abhängig von den Funktionsmarkern `@failing`","Spezifisch für die Integration des autonomen Codierungs-Harness"],"pt":["Requer acesso para gravar arquivos JSON","Depende de marcadores de funcionalidade `@failing`","Específico para integração de harness de codificação autônoma"],"ru":["Требует доступа для записи файлов JSON","Зависит от маркеров функций `@failing`","Конкретно для интеграции с автономным кодированием"],"ar":["يتطلب الوصول إلى كتابة ملفات JSON","يعتمد على علامات الميزة `@failing`","محدد لتكامل حزمة الترميز الذاتي"]},"version":4},"contentHash":"f02a75c851d090f02253b5aa6a628c420caef78bcc5df148579a0b8be4cc4aac","qualityScore":48}');
