INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lilliangreenberg/valuations-autonomous_coding/feature-status', 'feature-status', 'lilliangreenberg', 'valuations-autonomous_coding', 'community', 'feature-status lilliangreenberg valuations-autonomous_coding community The feature-status skill counts features marked as @failing and writes the count to a JSON file, aiding autonomous coding harness in determining loop termination. This benefits AI agent developers in streamlining their implementation process Feature Status AI工具用于计算被标记为@failing的功能数量，并将计数写入JSON文件，用于自动化编码 Feature Status AIエージェントは、@failingとマークされた機能の数をカウントし、JSONファイルに書き込むことで自動化コーディングを実現 Feature Status AI 에이전트는 @failing으로 표시된 기능의 수를 계산하여 JSON 파일에 쓰고 자동화된 코딩을 구현합니다 El estado de características es una habilidad que cuenta el número de características marcadas como @failing y escribe el recuento en un archivo JSON L''état des fonctionnalités est une compétence qui compte le nombre de fonctionnalités marquées comme @failing et écrit le décompte dans un fichier JSON Der Funktionstatus ist eine Fähigkeit, die die Anzahl der als @failing markierten Funktionen zählt und die Zahl in eine JSON-Datei schreibt O Feature Status é uma habilidade que conta recursos marcados como @failing e grava a contagem em um arquivo JSON Feature Status — это навык, который подсчитывает функции, помеченные как @failing, и записывает счет в файл JSON وضع الميزة هو مهارة تحسب الميزات المُعلّمة @failing وتسجل العدد في ملف JSON how to use feature-status feature-status setup guide what is feature-status feature-status alternative feature-status vs autonomous coding feature-status install feature-status loop termination feature-status JSON output autonomous coding harness feature-status Feature Status AI工具 自动化编码 JSON文件 AI工具配置 开发流程优化 Feature Status技能 Counts features marked as @failing Writes count to a JSON file named feature-status.json Determines loop termination logic based on failing_count Supports autonomous coding harness Outputs JSON file with failing_count for loop control Automates loop termination when failing_count reaches 0 feature-status is a skill that counts the number of features marked as @failing and generates a JSON output file for loop termination logic');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Clay-Ferguson/mkbrowser/app-pages', 'community', 'Clay-Ferguson', 'mkbrowser', 'Clay-Ferguson/mkbrowser', 'app-pages', 0, 0, 48, '2026-03-08T01:57:15.413Z', '2026-03-08T02:07:07.235Z', '4ba25210120247ed5147cb47e881eb98e2461a9746b423fdaaa90c5b680c84e9', '{"id":"Clay-Ferguson/mkbrowser/app-pages","name":"app-pages","description":{"en":"The app-pages skill provides a File Explorer and Markdown Browser/Editor as an Electron Desktop App, benefiting developers who need to manage files and edit Markdown documents efficiently.","zh":"App Pages 是一个 Electron 桌面应用，提供 Markdown 浏览器/编辑器功能。它包括多个顶级视图，如浏览器、搜索结果和设置","ja":"App Pages は Electron デスクトップ アプリで、Markdown ブラウザ/エディタ機能を提供します。ブラウザ、検索結果、設定など複数のトップレベル ビューを含みます","ko":"App Pages는 Electron 데스크톱 애플리케이션으로 Markdown 브라우저/편집기 기능을 제공합니다. 브라우저, 검색 결과, 설정 등 여러 가지 최상위 뷰를 포함합니다","es":"app-pages es un componente de Electron que permite crear aplicaciones de escritorio con navegadores y editores de Markdown. Aprende a configurar y personalizar","fr":"app-pages est un composant Electron qui permet de créer des applications de bureau avec des navigateurs et des éditeurs de Markdown. Découvrez comment configurer et personnaliser","de":"app-pages ist ein Electron-Komponente, mit dem Sie Desktop-Anwendungen mit Browsern und Markdown-Editoren erstellen können. Erfahren Sie, wie Sie konfigurieren und anpassen","pt":"O skill app-pages permite a criação de páginas de aplicativos personalizadas com navegação em markdown e exploração de arquivos","ru":"Навык app-pages позволяет создавать пользовательские страницы приложений с просмотром markdown и файловым браузером","ar":"المهارة app-pages تمكن من إنشاء صفحات تطبيقات مخصصة مع متصفح Markdown ومستكشف الملفات"},"seo":{"title":{"en":"app-pages: Electron Desktop App Setup Guide | AI Agent Skill","zh":"AIエージェント - App Pages 设定指南","ja":"AIエージェント - App Pages セットアップガイド","ko":"AI 에이전트 - App Pages 설정 가이드","es":"Guía de configuración de app-pages para desarrolladores","fr":"Guide de démarrage rapide pour app-pages","de":"Einrichtungsanleitung für app-pages-Entwickler","pt":"Guia de Configuração de Páginas de Aplicativos com Ferram...","ru":"Настройка страниц приложений с помощью ИИ Агентов","ar":"دليل إعداد صفحات التطبيقات باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to leverage app-pages for efficient file exploration and Markdown editing. Learn to navigate its components and setup your Electron desktop app ...","zh":"了解 App Pages 的技术细节，包括 Electron 桌面应用和 Markdown 浏览器/编辑器","ja":"App Pages の技術的詳細を学ぶ、Electron デスクトップ アプリと Markdown ブラウザ/エディタを含む","ko":"App Pages의 기술적 세부 사항을 알아보세요. Electron 데스크톱 애플리케이션 및 Markdown 브라우저/편집기를 포함합니다","es":"Aprende a configurar y personalizar app-pages con Electron y Markdown para crear aplicaciones de escritorio personalizadas","fr":"Découvrez comment configurer et personnaliser app-pages avec Electron et Markdown pour créer des applications de bureau sur mesure","de":"Erfahren Sie, wie Sie app-pages mit Electron und Markdown konfigurieren und anpassen, um individuelle Desktop-Anwendungen zu erstellen","pt":"Aprenda a configurar páginas de aplicativos com o skill app-pages, incluindo navegação em markdown e exploração de arquivos","ru":"Узнайте, как настроить страницы приложений с помощью навыка app-pages, включая просмотр markdown и файловый браузер","ar":"تعرف على كيفية إعداد صفحات التطبيقات باستخدام مهارة app-pages، بما في ذلك متصفح Markdown ومستكشف الملفات"},"definition":{"en":"app-pages is a skill that enables file exploration and Markdown editing within an Electron desktop application, utilizing components like AppView and pages defined in src/store/types.ts","zh":"App Pages 是一个 Electron 桌面应用，提供多个顶级视图和 Markdown 浏览器/编辑器功能","ja":"App Pages は Electron デスクトップ アプリで、複数のトップレベル ビューと Markdown ブラウザ/エディタ機能を提供する","ko":"App Pages는 Electron 데스크톱 애플리케이션으로 여러 가지 최상위 뷰와 Markdown 브라우저/편집기 기능을 제공합니다","es":"app-pages es un componente de Electron que permite crear vistas de aplicación personalizadas con navegadores y editores de Markdown","fr":"app-pages est un composant Electron qui permet de créer des vues d''application personnalisées avec des navigateurs et des éditeurs de Markdown","de":"app-pages ist ein Electron-Komponente, der die Erstellung von benutzerdefinierten Anwendungsvistas mit Browsern und Markdown-Editoren ermöglicht","pt":"O que é app-pages? É um skill que permite a criação de páginas de aplicativos personalizadas","ru":"Что такое app-pages? Это навык, который позволяет создавать пользовательские страницы приложений","ar":"ما هي app-pages؟ هي مهارة تمكن من إنشاء صفحات تطبيقات مخصصة"},"features":{"en":["Utilizes Electron for desktop application development","Employs Markdown for document editing and browsing","Defines AppView types in src/store/types.ts for page management","Follows a component pattern similar to src/components/SearchResultsView for page structure","Supports multiple top-level views, including ''browser'', ''search-results'', and ''settings'' pages"],"zh":["Electron 桌面应用","Markdown 浏览器/编辑器","多个顶级视图（浏览器、搜索结果、设置）","基于 TypeScript 的应用视图类型定义","src/App.tsx 中的主应用页面","src/components/SearchResultsView 中的搜索结果视图"],"ja":["Electron デスクトップ アプリ","Markdown ブラウザ/エディタ","複数のトップレベル ビュー（ブラウザ、検索結果、設定）","TypeScript に基づくアプリケーション ビューの型定義","src/App.tsx 中のメイン アプリケーション ページ","src/components/SearchResultsView 中の検索結果ビュー"],"ko":["Electron 데스크톱 애플리케이션","Markdown 브라우저/편집기","여러 가지 최상위 뷰（브라우저, 검색 결과, 설정）","TypeScript 기반의 애플리케이션 뷰 타입 정의","src/App.tsx中的 메인 애플리케이션 페이지","src/components/SearchResultsView中的 검색 결과 뷰"],"es":["Creación de vistas de aplicación personalizadas con Electron","Integración de navegadores y editores de Markdown","Configuración de tipos de vistas de aplicación en src/store/types.ts","Uso de patrones de componentes en src/components/SearchResultsView","Compatibilidad con TypeScript en src/App.tsx"],"fr":["Création de vues d''application personnalisées avec Electron","Intégration de navigateurs et d''éditeurs de Markdown","Configuration des types de vues d''application dans src/store/types.ts","Utilisation de modèles de composants dans src/components/SearchResultsView","Compatibilité avec TypeScript dans src/App.tsx"],"de":["Erstellung von benutzerdefinierten Anwendungsvistas mit Electron","Integration von Browsern und Markdown-Editoren","Konfiguration von Anwendungsvistatypen in src/store/types.ts","Verwendung von Komponentenmustern in src/components/SearchResultsView","Unterstützung von TypeScript in src/App.tsx"],"pt":["Navegação em markdown","Exploração de arquivos com Electron Desktop App","Criação de páginas de aplicativos personalizadas","Tipos de visualização de aplicativos definidos em src/store/types.ts","Componentes de página personalizados em src/components/SearchResultsView"],"ru":["Просмотр markdown","Файловый браузер с Electron Desktop App","Создание пользовательских страниц приложений","Типы представления приложений, определенные в src/store/types.ts","Пользовательские компоненты страницы в src/components/SearchResultsView"],"ar":["متصفح Markdown","مستكشف الملفات مع Electron Desktop App","إنشاء صفحات تطبيقات مخصصة","أنواع عرض التطبيقات المحددة في src/store/types.ts","مكونات صفحة مخصصة في src/components/SearchResultsView"]},"keywords":{"en":["how to use app-pages","app-pages alternative","app-pages setup guide","Electron desktop app development","Markdown editor for developers","app-pages vs Electron","app-pages install","what is app-pages","app-pages tutorial"],"zh":["App Pages","Electron 桌面应用","Markdown 浏览器/编辑器","TypeScript","React","JavaScript","桌面应用开发","Markdown 编辑器"],"ja":["App Pages","Electron デスクトップ アプリ","Markdown ブラウザ/エディタ","TypeScript","React","JavaScript","デスクトップ アプリ開発","Markdown エディタ"],"ko":["App Pages","Electron 데스크톱 애플리케이션","Markdown 브라우저/편집기","TypeScript","React","JavaScript","데스크톱 애플리케이션 개발","Markdown 편집기"],"es":["app-pages","Electron","Markdown","desarrollo de aplicaciones de escritorio","configuración de app-pages","personalización de vistas de aplicación","TypeScript","navegadores y editores de Markdown"],"fr":["app-pages","Electron","Markdown","développement d''applications de bureau","configuration de app-pages","personnalisation de vues d''application","TypeScript","navigateurs et éditeurs de Markdown"],"de":["app-pages","Electron","Markdown","Entwicklung von Desktop-Anwendungen","Konfiguration von app-pages","Anpassung von Anwendungsvistas","TypeScript","Browser und Markdown-Editoren"],"pt":["app-pages","Ferramentas de IA","Desenvolvimento de aplicativos","Navegação em markdown","Exploração de arquivos","Electron Desktop App","Criação de páginas de aplicativos personalizadas"],"ru":["app-pages","ИИ Агенты","Разработка приложений","Просмотр markdown","Файловый браузер","Electron Desktop App","Создание пользовательских страниц приложений"],"ar":["app-pages","أدوات الذكاء الاصطناعي","تطوير التطبيقات","متصفح Markdown","مستكشف الملفات","Electron Desktop App","إنشاء صفحات تطبيقات مخصصة"]}},"owner":"Clay-Ferguson","repo":"mkbrowser","repoPath":"Clay-Ferguson/mkbrowser","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.413Z","topics":[],"category":"community","skillMd":{"name":"app-pages","description":"Pattern for application pages","bodyPreview":"# Instructions\n\n## Page Name and Component Location\n\nPages are the different top level views (aka panels) that we display in the application. Their names are defined in file `src/store/types.ts` in the following line of code.\n\n```\nexport type AppView = ''browser'' | ''search-results'' | ''settings'';\n```\n\nThe ''browser'' one is the main default application `src/App.tsx`, but any pages other than the main (browser) page should follow a pattern similar to what you find in `src/components/SearchResultsView","body":"# Instructions\n\n## Page Name and Component Location\n\nPages are the different top level views (aka panels) that we display in the application. Their names are defined in file `src/store/types.ts` in the following line of code.\n\n```\nexport type AppView = ''browser'' | ''search-results'' | ''settings'';\n```\n\nThe ''browser'' one is the main default application `src/App.tsx`, but any pages other than the main (browser) page should follow a pattern similar to what you find in `src/components/SearchResultsView.tsx`\n\n## Tab Navigation\n\nEach page has a corresponding tab button in the tab panel at the top of the screen (Browse, Search, Settings). When the user clicks a tab button, we update the `currentView` in the global `AppState`, and that causes the page to display at next render.\n\n## React Global State Management\n\nExample: `setCurrentView(''search-results'');`\n"},"lastSynced":"2026-03-08T02:07:07.235Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing efficient Markdown editing and file management capabilities within Electron Desktop Apps.","zh":"非常适合需要在 Electron Desktop App 内进行高效 Markdown 编辑和文件管理功能的 Developer Agents。","ja":"Electron Desktop App 内で効率的な Markdown 編集とファイル管理機能を必要とする Developer Agents に最適です。","ko":"Electron Desktop App 내에서 효율적인 Markdown 편집 및 파일 관리 기능이 필요한 Developer Agents에 완벽합니다.","es":"Ideal para agentes de desarrollo que necesitan capacidades eficientes de edición de Markdown y gestión de archivos dentro de aplicaciones de escritorio Electron.","fr":"Parfait pour les agents développeurs ayant besoin de capacités efficaces d''édition Markdown et de gestion de fichiers dans les applications de bureau Electron.","de":"Perfekt für Entwickler-Agents, die effiziente Markdown-Bearbeitung und Dateiverwaltungsfähigkeiten innerhalb von Electron Desktop Apps benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de edição de Markdown eficiente e capacidades de gerenciamento de arquivos dentro de Aplicativos de Desktop Electron.","ru":"Идеально подходит для агентов разработчиков, которым необходима эффективная редакция Markdown и возможности управления файлами в приложениях Electron для рабочего стола.","ar":"مثالي لعميل المطور الذي يحتاج إلى تحرير Markdown فعال وإمكانيات إدارة الملفات داخل تطبيقات سطح المكتب الإلكترونية."},"recommendation":{"en":"Empowers agents to manage files and edit Markdown documents efficiently using a File Explorer and Markdown Browser/Editor, leveraging Electron and TypeScript for seamless integration, and utilizing specific components like ''browser'', ''search-results'', and ''settings'' views.","zh":"赋能代理利用 Electron 和 TypeScript 实现无缝集成，并使用诸如 ''browser''、''search-results'' 和 ''settings'' 视图等特定组件，通过 File Explorer 和 Markdown Browser/Editor 高效管理文件和编辑 Markdown 文档。","ja":"Electron と TypeScript を活用したシームレスな統合を実現し、''browser''、''search-results''、''settings'' ビューなどの特定コンポーネントを利用して、File Explorer と Markdown Browser/Editor を使用してファイルを管理し、Markdown ドキュメントを効率的に編集する能力をエージェントに提供します。","ko":"Electron과 TypeScript를 활용한 원활한 통합을 구현하고, ''browser'', ''search-results'', ''settings'' 뷰와 같은 특정 컴포넌트를 사용하여 File Explorer 및 Markdown Browser/Editor를 통해 파일을 관리하고 Markdown 문서를 효율적으로 편집할 수 있는 능력을 에이전트에게 부여합니다.","es":"Permite a los agentes gestionar archivos y editar documentos Markdown de manera eficiente utilizando un Explorador de archivos y un Editor/Navegador de Markdown, aprovechando Electron y TypeScript para una integración perfecta, y utilizando componentes específicos como las vistas ''browser'', ''search-results'' y ''settings''.","fr":"Permet aux agents de gérer les fichiers et de modifier les documents Markdown efficacement en utilisant un Explorateur de fichiers et un Éditeur/Navigateur Markdown, tirant parti d''Electron et de TypeScript pour une intégration transparente, et utilisant des composants spécifiques comme les vues ''browser'', ''search-results'' et ''settings''.","de":"Ermöglicht Agents, Dateien zu verwalten und Markdown-Dokumente effizient zu bearbeiten, indem ein Datei-Explorer und ein Markdown-Browser/Editor verwendet werden, wobei Electron und TypeScript für nahtlose Integration genutzt werden, und spezifische Komponenten wie ''browser'', ''search-results'' und ''settings''-Ansichten verwendet werden.","pt":"Habilita os agentes a gerenciar arquivos e editar documentos Markdown de forma eficiente utilizando um Explorador de Arquivos e um Navegador/Editor de Markdown, aproveitando Electron e TypeScript para integração sem problemas, e utilizando componentes específicos como visualizações ''browser'', ''search-results'' e ''settings''.","ru":"Наделяет агентов возможностью эффективно управлять файлами и редактировать документы Markdown, используя Проводник файлов и Браузер/Редактор Markdown, используя Electron и TypeScript для бесперебойной интеграции, и используя конкретные компоненты, такие как представления ''browser'', ''search-results'' и ''settings''.","ar":"يمنح الوكلاء القدرة على إدارة الملفات وتحرير مستندات Markdown بفعالية باستخدام مستكشف الملفات ومتصفح/محرر Markdown، مستفيداً من الإلكترون و TypeScript من أجل التكامل السلس، واستخدام مكونات محددة مثل عروض ''browser'' و ''search-results'' و ''settings''."},"useCases":{"en":["Managing Markdown documents within the app","Navigating file systems using the File Explorer","Customizing app views such as ''browser'' and ''search-results''"],"zh":["在应用程序内管理 Markdown 文档","使用 File Explorer 导航文件系统","自定义应用程序视图，例如 ''browser'' 和 ''search-results''"],"ja":["アプリケーション内での Markdown ドキュメントの管理","File Explorer を使用したファイルシステムのナビゲーション","''browser'' や ''search-results'' などのアプリビューのカスタマイズ"],"ko":["앱 내에서 Markdown 문서 관리","File Explorer를 사용한 파일 시스템 탐색","''browser'' 및 ''search-results''와 같은 앱 뷰 커스터마이징"],"es":["Gestionar documentos Markdown dentro de la aplicación","Navegar por sistemas de archivos utilizando el Explorador de archivos","Personalizar vistas de la aplicación como ''browser'' y ''search-results''"],"fr":["Gérer les documents Markdown dans l''application","Naviguer dans les systèmes de fichiers à l''aide de l''Explorateur de fichiers","Personnaliser les vues de l''application telles que ''browser'' et ''search-results''"],"de":["Verwalten von Markdown-Dokumenten innerhalb der App","Navigieren in Dateisystemen mit dem Datei-Explorer","Anpassen von App-Ansichten wie ''browser'' und ''search-results''"],"pt":["Gerenciar documentos Markdown dentro do aplicativo","Navegar sistemas de arquivos usando o Explorador de Arquivos","Personalizar visualizações de aplicativos, como ''browser'' e ''search-results''"],"ru":["Управление документами Markdown внутри приложения","Навигация по файловым системам с помощью Проводника файлов","Настройка представлений приложения, таких как ''browser'' и ''search-results''"],"ar":["إدارة مستندات Markdown داخل التطبيق","تنقل أنظمة الملفات باستخدام مستكشف الملفات","تخصيص عروض التطبيق، مثل ''browser'' و ''search-results''"]},"limitations":{"en":["Requires Electron Desktop App environment","Limited to Markdown document editing"],"zh":["需要 Electron Desktop App 环境","仅限于 Markdown 文档编辑"],"ja":["Electron Desktop App 環境が必要","Markdown ドキュメントの編集に限定"],"ko":["Electron Desktop App 환경이 필요함","Markdown 문서 편집으로 제한됨"],"es":["Requiere un entorno de aplicación de escritorio Electron","Limitado a la edición de documentos Markdown"],"fr":["Nécessite un environnement d''application de bureau Electron","Limité à l''édition de documents Markdown"],"de":["Erfordert eine Electron Desktop App-Umgebung","Beschränkt sich auf die Bearbeitung von Markdown-Dokumenten"],"pt":["Requer ambiente de Aplicativo de Desktop Electron","Limitado à edição de documentos Markdown"],"ru":["Требуется среда Electron для рабочего стола","Ограничен редактированием документов Markdown"],"ar":["يتطلب بيئة تطبيق سطح المكتب الإلكتروني","محدود بتحرير مستندات Markdown"]},"version":4},"contentHash":"4ba25210120247ed5147cb47e881eb98e2461a9746b423fdaaa90c5b680c84e9","qualityScore":48}');
