INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Clay-Ferguson/mkbrowser/app-pages', 'app-pages', 'Clay-Ferguson', 'mkbrowser', 'community', 'app-pages Clay-Ferguson mkbrowser community The app-pages skill provides a File Explorer and Markdown Browser/Editor as an Electron Desktop App, benefiting developers who need to manage files and edit Markdown documents efficiently. App Pages 是一个 Electron 桌面应用，提供 Markdown 浏览器/编辑器功能。它包括多个顶级视图，如浏览器、搜索结果和设置 App Pages は Electron デスクトップ アプリで、Markdown ブラウザ/エディタ機能を提供します。ブラウザ、検索結果、設定など複数のトップレベル ビューを含みます App Pages는 Electron 데스크톱 애플리케이션으로 Markdown 브라우저/편집기 기능을 제공합니다. 브라우저, 검색 결과, 설정 등 여러 가지 최상위 뷰를 포함합니다 app-pages es un componente de Electron que permite crear aplicaciones de escritorio con navegadores y editores de Markdown. Aprende a configurar y personalizar app-pages est un composant Electron qui permet de créer des applications de bureau avec des navigateurs et des éditeurs de Markdown. Découvrez comment configurer et personnaliser app-pages ist ein Electron-Komponente, mit dem Sie Desktop-Anwendungen mit Browsern und Markdown-Editoren erstellen können. Erfahren Sie, wie Sie konfigurieren und anpassen O skill app-pages permite a criação de páginas de aplicativos personalizadas com navegação em markdown e exploração de arquivos Навык app-pages позволяет создавать пользовательские страницы приложений с просмотром markdown и файловым браузером المهارة app-pages تمكن من إنشاء صفحات تطبيقات مخصصة مع متصفح Markdown ومستكشف الملفات how to use app-pages app-pages alternative app-pages setup guide Electron desktop app development Markdown editor for developers app-pages vs Electron app-pages install what is app-pages app-pages tutorial App Pages Electron 桌面应用 Markdown 浏览器/编辑器 TypeScript React JavaScript 桌面应用开发 Markdown 编辑器 Utilizes Electron for desktop application development Employs Markdown for document editing and browsing Defines AppView types in src/store/types.ts for page management Follows a component pattern similar to src/components/SearchResultsView for page structure Supports multiple top-level views, including ''browser'', ''search-results'', and ''settings'' pages app-pages is a skill that enables file exploration and Markdown editing within an Electron desktop application, utilizing components like AppView and pages defined in src/store/types.ts');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gpad1234/skills-imaginary-guide-agent/system-health', 'community', 'gpad1234', 'skills-imaginary-guide-agent', 'gpad1234/skills-imaginary-guide-agent', 'system-health', 0, 0, 48, '2026-03-08T01:57:15.413Z', '2026-03-08T02:07:09.101Z', '2c2d88ffaee233d2bace4eb64ea7dc2f094c7a5aa4d9c87b5864616f0b5eb6e7', '{"id":"gpad1234/skills-imaginary-guide-agent/system-health","name":"system-health","description":{"en":"The system-health skill runs checks on system status, resource utilization, and performance monitoring, benefiting developers and system administrators. It provides detailed JSON output on system information and usage.","zh":"系统健康检查技能提供系统状态、资源利用率、性能监控等技术细节，使用Python和CLI实现","ja":"システムヘルスチェックスキルは、システム状態、リソース利用率、パフォーマンス監視などの技術的な詳細を提供し、PythonとCLIを使用して実現します","ko":"시스템 헬스 체크 스킬은 시스템 상태, 리소스 사용률, 성능 모니터링 등의 기술적인 세부 정보를 제공하며, Python 및 CLI를 사용하여 구현합니다","es":"System-health es un skill que proporciona información detallada sobre el estado del sistema, incluyendo memoria, CPU y recursos de red","fr":"System-health est un skill qui fournit des informations détaillées sur l''état du système, y compris la mémoire, le CPU et les ressources réseau","de":"System-health ist ein Skill, der detaillierte Informationen über den Systemzustand liefert, einschließlich Speicher, CPU und Netzwerkressourcen","pt":"O System Health Check é uma habilidade que fornece informações sobre o status do sistema, utilização de recursos e desempenho","ru":"System Health Check - это навык, который предоставляет информацию о состоянии системы, использовании ресурсов и производительности","ar":"نظام الصحة هو مهارة توفر معلومات حول حالة النظام واستخدام الموارد والأداء"},"seo":{"title":{"en":"system-health: System Monitoring Setup Guide | AI Agent S...","zh":"系统健康检查 Setup Guide - AIエージェント","ja":"システムヘルスチェックベストプラクティス - AIエージェント","ko":"시스템 헬스 체크 Setup Guide - AI 에이전트","es":"Guía de Configuración de system-health para Monitoreo de ...","fr":"Configurer system-health pour le Monitoring des Ressources","de":"System-Health-Setup-Leitfaden für Ressourcenüberwachung","pt":"Guia de Configuração do System Health Check","ru":"ИИ Агенты: Настройка System Health Check","ar":"إعداد نظام الصحة Setup Guide"},"description":{"en":"Discover how to run system-health checks with Python scripts and get JSON output on system info, memory usage, CPU info, and more - learn how to set it up now!","zh":"了解系统健康检查的技术细节，包括系统状态、资源利用率、性能监控等，使用Python和CLI实现","ja":"システムヘルスチェックの技術的な詳細を学び、PythonとCLIを使用してシステム状態、リソース利用率、パフォーマンス監視などを実現する","ko":"시스템 헬스 체크의 기술적인 세부 정보를 알아보며, Python 및 CLI를 사용하여 시스템 상태, 리소스 사용률, 성능 모니터링 등을 구현합니다","es":"Aprenda a configurar system-health para monitorear el estado del sistema, recursos y rendimiento con Python y CLI","fr":"Découvrez comment configurer system-health pour surveiller l''état du système, les ressources et les performances avec Python et CLI","de":"Erfahren Sie, wie Sie system-health konfigurieren, um den Systemzustand, Ressourcen und Leistung mit Python und CLI zu überwachen","pt":"Aprenda a configurar o System Health Check para monitorar o status do sistema, utilização de recursos e desempenho","ru":"Узнайте, как настроить System Health Check для мониторинга состояния системы, использования ресурсов и производительности","ar":"تعلم كيفية إعداد نظام الصحة لمراقبة حالة النظام واستخدام الموارد والأداء"},"definition":{"en":"system-health is a skill that checks and monitors system status, resource utilization, and performance, providing detailed output on system information, memory usage, and CPU usage.","zh":"系统健康检查是指检查系统的状态、资源利用率、性能监控等技术细节的过程","ja":"システムヘルスチェックとは、システムの状態、リソース利用率、パフォーマンス監視などの技術的な詳細を確認するプロセスです","ko":"시스템 헬스 체크란 시스템의 상태, 리소스 사용률, 성능 모니터링 등의 기술적인 세부 정보를 확인하는 프로세스입니다","es":"System-health es un skill de agente de inteligencia artificial que monitorea el estado del sistema y los recursos","fr":"System-health est un skill d''agent d''intelligence artificielle qui surveille l''état du système et les ressources","de":"System-health ist ein Skill von künstlicher Intelligenz, der den Systemzustand und die Ressourcen überwacht","pt":"O que é System Health Check? É uma ferramenta que verifica o status do sistema e recursos","ru":"Что такое System Health Check? Это инструмент, который проверяет состояние системы и ресурсы","ar":"ما هو نظام الصحة؟ هو أداة تحقق من حالة النظام والموارد"},"features":{"en":["Runs system health checks using Python scripts","Provides JSON output with system information, including OS, hostname, and uptime","Monitors memory usage and CPU information","Lists top processes by memory consumption","Displays disk usage and network interfaces"],"zh":["系统状态检查","资源利用率监控","性能监控","内存使用情况检查","CPU信息检查","磁盘使用情况检查"],"ja":["システム状態の確認","リソース利用率の監視","パフォーマンスの監視","メモリ使用状況の確認","CPU情報の確認","ディスク使用状況の確認"],"ko":["시스템 상태 확인","리소스 사용률 모니터링","성능 모니터링","메모리 사용状況 확인","CPU 정보 확인","디스크 사용状況 확인"],"es":["Monitoreo de memoria y CPU","Información detallada sobre el estado del sistema","Análisis de procesos en ejecución y su consumo de recursos","Monitoreo de disco y redes","Compatibilidad con Python y CLI"],"fr":["Surveillance de la mémoire et du CPU","Informations détaillées sur l''état du système","Analyse des processus en cours d''exécution et de leur consommation de ressources","Surveillance du disque et des réseaux","Compatibilité avec Python et CLI"],"de":["Überwachung von Speicher und CPU","Detaillierte Informationen über den Systemzustand","Analyse von laufenden Prozessen und deren Ressourcenverbrauch","Überwachung von Festplatte und Netzwerk","Kompatibilität mit Python und CLI"],"pt":["Verificação do status do sistema","Monitoramento da utilização de recursos","Análise do desempenho do sistema","Informações sobre memória e CPU","Listagem dos processos em execução e consumo de recursos"],"ru":["Проверка состояния системы","Мониторинг использования ресурсов","Анализ производительности системы","Информация о памяти и CPU","Список запущенных процессов и потребление ресурсов"],"ar":["تحقق من حالة النظام","مراقبة استخدام الموارد","تحليل أداء النظام","معلومات حول الذاكرة والمعالج","قائمة العمليات التي يتم تشغيلها واستهلاك الموارد"]},"keywords":{"en":["how to use system-health","system-health setup guide","system monitoring with Python","system-health alternative","system-health vs Nagios","install system-health","system-health JSON output","what is system-health","system-health for AI agents"],"zh":["系统健康检查","AIエージェント","Python系统状态检查","CLI性能监控","系统资源利用率","内存使用情况","CPU信息","磁盘使用情况"],"ja":["システムヘルスチェック","AIエージェント","Pythonシステム状態の確認","CLIパフォーマンスの監視","システムリソース利用率","メモリ使用状況","CPU情報","ディスク使用状況"],"ko":["시스템 헬스 체크","AI 에이전트","Python 시스템 상태 확인","CLI 성능 모니터링","시스템 리소스 사용률","메모리 사용 상황","CPU 정보","디스크 사용 상황"],"es":["system-health","monitoreo de recursos","agente de inteligencia artificial","Python","CLI","monitoreo de sistema","rendimiento","recursos de red","información de sistema"],"fr":["system-health","surveillance des ressources","agent d''intelligence artificielle","Python","CLI","surveillance du système","performances","ressources réseau","informations de système"],"de":["system-health","Ressourcenüberwachung","künstliche Intelligenz","Python","CLI","Systemüberwachung","Leistung","Netzwerkressourcen","Systeminformationen"],"pt":["System Health Check","Monitoramento de sistema","Utilização de recursos","Desempenho do sistema","Python","CLI","Script de saúde do sistema"],"ru":["System Health Check","Мониторинг системы","Использование ресурсов","Производительность системы","Python","CLI","Скрипт здоровья системы"],"ar":["نظام الصحة","مراقبة النظام","استخدام الموارد","أداء النظام","Python","CLI","سครبت صحة النظام"]}},"owner":"gpad1234","repo":"skills-imaginary-guide-agent","repoPath":"gpad1234/skills-imaginary-guide-agent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.413Z","topics":[],"category":"community","skillMd":{"name":"system-health","description":"Query system health metrics including CPU, memory, disk usage, and running processes. Use this when the user asks about system status, performance monitoring, or resource utilization.","bodyPreview":"# System Health Check\n\nRun this skill when the user asks about:\n- System status or health\n- Resource utilization\n- Performance monitoring\n- Memory or CPU usage\n- Running processes and their consumption\n\n## Run using:\n\n```bash\n# Ensure venv is activated\nsource venv/bin/activate\npython scripts/check_system_health.py\n```\n\n## Output\n\nReturns JSON with:\n- System information (OS, hostname, uptime)\n- Memory usage\n- CPU information\n- Top processes by memory consumption\n- Disk usage\n- Network interfaces","body":"# System Health Check\n\nRun this skill when the user asks about:\n- System status or health\n- Resource utilization\n- Performance monitoring\n- Memory or CPU usage\n- Running processes and their consumption\n\n## Run using:\n\n```bash\n# Ensure venv is activated\nsource venv/bin/activate\npython scripts/check_system_health.py\n```\n\n## Output\n\nReturns JSON with:\n- System information (OS, hostname, uptime)\n- Memory usage\n- CPU information\n- Top processes by memory consumption\n- Disk usage\n- Network interfaces\n\n## Dependencies\n\nRequires the MCP osquery server to be available. Install dependencies with:\n```bash\nsource venv/bin/activate\npip install -r requirements.txt\n```\n\n## Environment\n\nNo environment variables required for basic usage.\n"},"lastSynced":"2026-03-08T02:07:09.101Z","agentAnalysis":{"suitability":{"en":"Ideal for System Monitoring Agents requiring detailed JSON output on system information and usage for advanced system administration tasks","zh":"适用于需要详细JSON输出的系统信息和使用情况的系统监控代理，用于高级系统管理任务","ja":"システム情報と使用状況の詳細なJSON出力を必要とするシステムモニタリングエージェントに最適","ko":"시스템 정보와 사용 현황에 대한 자세한 JSON 출력이 필요한 시스템 모니터링 에이전트에 적합","es":"Ideal para Agentes de Monitoreo de Sistema que requieren una salida JSON detallada sobre la información y el uso del sistema para tareas de administración de sistema avanzadas","fr":"Idéal pour les agents de surveillance du système nécessitant une sortie JSON détaillée sur les informations et l''utilisation du système pour des tâches d''administration de système avancées","de":"Ideal für Systemüberwachungsagenten, die eine detaillierte JSON-Ausgabe über Systeminformationen und -nutzung für erweiterte Systemadministrationsaufgaben benötigen","pt":"Ideal para Agentes de Monitoramento de Sistema que exigem saída JSON detalhada sobre informações e uso do sistema para tarefas avançadas de administração de sistema","ru":"Идеально для агентов мониторинга системы, требующих подробного вывода JSON об информации системы и использовании для продвинутых задач системного администрирования","ar":"مثالية لعميل مراقبة النظام الذي يتطلب إخراج JSON مفصل عن معلومات النظام واستخدامه لأداء مهام إدارة النظام المتقدمة"},"recommendation":{"en":"Empowers agents to run comprehensive system health checks, providing insights into resource utilization, performance monitoring, and system status using JSON output, leveraging Python scripting for seamless integration","zh":"使代理能够运行全面系统健康检查，提供资源利用率、性能监控和系统状态的见解，使用JSON输出，并利用Python脚本实现无缝集成","ja":"エージェントが包括的なシステムヘルスチェックを実行できるようにし、JSON出力を使用してリソース使用状況、パフォーマンス監視、システム状態に関する洞察を提供し、Pythonスクリプティングを使用してシームレスな統合を実現する","ko":"에이전트가 포괄적인 시스템 상태 점검을 실행할 수 있도록 하여 JSON 출력을 사용하여 리소스 사용량, 성능 모니터링 및 시스템 상태에 대한 정보를 제공하며, 파이썬 스크립팅을 사용하여 무중단 통합을 구현","es":"Permite a los agentes ejecutar controles de salud del sistema integrales, proporcionando información sobre la utilización de recursos, el monitoreo del rendimiento y el estado del sistema mediante la salida JSON, aprovechando la scripting de Python para una integración fluida","fr":"Permet aux agents d''exécuter des contrôles de santé du système complets, fournissant des informations sur l''utilisation des ressources, la surveillance des performances et l''état du système à l''aide de la sortie JSON, en exploitant la scripting Python pour une intégration fluide","de":"Ermächtigt Agenten, umfassende Systemgesundheitschecks durchzuführen, Erkenntnisse über die Ressourcenauslastung, Leistungsüberwachung und Systemstatus unter Verwendung der JSON-Ausgabe bereitzustellen, indem Python-Skripting für eine nahtlose Integration genutzt wird","pt":"Habilita agentes a executar verificações abrangentes de saúde do sistema, fornecendo insights sobre utilização de recursos, monitoramento de desempenho e status do sistema usando saída JSON, aproveitando a scriptação Python para integração transparente","ru":"Наделяет агентов возможностью выполнять комплексные проверки здоровья системы, предоставляя информацию об использовании ресурсов, мониторинге производительности и состоянии системы с помощью вывода JSON, используя скриптинг Python для бесшовной интеграции","ar":"تمكين الوكلاء من تشغيل فحوصات شاملة لصحة النظام، وتقديم رؤى حول استخدام الموارد ومراقبة الأداء وحالة النظام باستخدام إخراج JSON، واستخدام كتابة البرامج النصية Python من أجل التكامل السلس"},"useCases":{"en":["Monitoring system resource utilization","Debugging performance issues","Tracking memory and CPU usage","Identifying top processes by memory consumption"],"zh":["监控系统资源使用情况","调试性能问题","跟踪内存和CPU使用情况","根据内存消耗识别顶级进程"],"ja":["システムリソース使用状況の監視","パフォーマンスの問題のデバッグ","メモリとCPU使用状況の追跡","メモリ消費量によってトッププロセスを識別"],"ko":["시스템 리소스 사용량 모니터링","성능 문제 디버깅","메모리 및 CPU 사용량 추적","메모리 소비량에 따라 상위 프로세스 식별"],"es":["Monitoreo de la utilización de recursos del sistema","Depuración de problemas de rendimiento","Seguimiento del uso de memoria y CPU","Identificación de los procesos principales por consumo de memoria"],"fr":["Surveillance de l''utilisation des ressources du système","Débogage des problèmes de performances","Suivi de l''utilisation de la mémoire et du CPU","Identification des processus principaux par consommation de mémoire"],"de":["Überwachung der Ressourcenauslastung des Systems","Fehlerbehebung bei Leistungsproblemen","Nachverfolgung der Speicher- und CPU-Auslastung","Identifizierung der Hauptprozesse nach Speicherbedarf"],"pt":["Monitoramento da utilização de recursos do sistema","Depuração de problemas de desempenho","Rastreamento da utilização de memória e CPU","Identificação dos principais processos por consumo de memória"],"ru":["Мониторинг использования ресурсов системы","Отладка проблем производительности","Отслеживание использования памяти и CPU","Определение топ-процессов по потреблению памяти"],"ar":["مراقبة استخدام موارد النظام","تصحيح أخطاء الأداء","تتبع استخدام الذاكرة ووحدة المعالجة المركزية","تحديد العمليات العلوية حسب استهلاك الذاكرة"]},"limitations":{"en":["Requires Python 3.x and virtual environment (venv)","Limited to system information and resource utilization data","Needs execution of Python script (check_system_health.py)"],"zh":["需要Python 3.x和虚拟环境(venv)","仅限系统信息和资源利用率数据","需要执行Python脚本(check_system_health.py)"],"ja":["Python 3.xと仮想環境(venv)が必要","システム情報とリソース使用状況データのみ","Pythonスクリプト(check_system_health.py)の実行が必要"],"ko":["파이썬 3.x와 가상 환경(venv)가 필요","시스템 정보 및 리소스 사용량 데이터만","파이썬 스크립트(check_system_health.py) 실행이 필요"],"es":["Requiere Python 3.x y entorno virtual (venv)","Limitado a datos de información y utilización de recursos del sistema","Requiere la ejecución del script de Python (check_system_health.py)"],"fr":["Nécessite Python 3.x et un environnement virtuel (venv)","Limité aux données d''information et d''utilisation des ressources du système","Nécessite l''exécution du script Python (check_system_health.py)"],"de":["Benötigt Python 3.x und virtuelle Umgebung (venv)","Begrenzt auf Systeminformationen und Ressourcenauslastungsdaten","Benötigt die Ausführung des Python-Skripts (check_system_health.py)"],"pt":["Exige Python 3.x e ambiente virtual (venv)","Limitado a informações de sistema e dados de utilização de recursos","Necessita execução de script Python (check_system_health.py)"],"ru":["Требует Python 3.x и виртуальной среды (venv)","Ограничен информацией о системе и данными об испол