INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gpad1234/skills-imaginary-guide-agent/system-health', 'system-health', 'gpad1234', 'skills-imaginary-guide-agent', 'community', 'system-health gpad1234 skills-imaginary-guide-agent community The system-health skill runs checks on system status, resource utilization, and performance monitoring, benefiting developers and system administrators. It provides detailed JSON output on system information and usage. 系统健康检查技能提供系统状态、资源利用率、性能监控等技术细节，使用Python和CLI实现 システムヘルスチェックスキルは、システム状態、リソース利用率、パフォーマンス監視などの技術的な詳細を提供し、PythonとCLIを使用して実現します 시스템 헬스 체크 스킬은 시스템 상태, 리소스 사용률, 성능 모니터링 등의 기술적인 세부 정보를 제공하며, Python 및 CLI를 사용하여 구현합니다 System-health es un skill que proporciona información detallada sobre el estado del sistema, incluyendo memoria, CPU y recursos de red System-health est un skill qui fournit des informations détaillées sur l''état du système, y compris la mémoire, le CPU et les ressources réseau System-health ist ein Skill, der detaillierte Informationen über den Systemzustand liefert, einschließlich Speicher, CPU und Netzwerkressourcen O System Health Check é uma habilidade que fornece informações sobre o status do sistema, utilização de recursos e desempenho System Health Check - это навык, который предоставляет информацию о состоянии системы, использовании ресурсов и производительности نظام الصحة هو مهارة توفر معلومات حول حالة النظام واستخدام الموارد والأداء how to use system-health system-health setup guide system monitoring with Python system-health alternative system-health vs Nagios install system-health system-health JSON output what is system-health system-health for AI agents 系统健康检查 AIエージェント Python系统状态检查 CLI性能监控 系统资源利用率 内存使用情况 CPU信息 磁盘使用情况 Runs system health checks using Python scripts Provides JSON output with system information, including OS, hostname, and uptime Monitors memory usage and CPU information Lists top processes by memory consumption Displays disk usage and network interfaces system-health is a skill that checks and monitors system status, resource utilization, and performance, providing detailed output on system information, memory usage, and CPU usage.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('santosrai/santosrai.github.io/blog-post-formatter', 'community', 'santosrai', 'santosrai.github.io', 'santosrai/santosrai.github.io', 'blog-post-formatter', 0, 0, 48, '2026-03-08T01:57:15.425Z', '2026-03-08T02:07:28.294Z', '25eab15d5f7dbf2598685c764cc73d0e8245e1dd3c26d9ef94810945847cb9e5', '{"id":"santosrai/santosrai.github.io/blog-post-formatter","name":"blog-post-formatter","description":{"en":"The blog-post-formatter skill formats blog content into properly structured markdown files for Next.js portfolio websites, benefiting developers and content creators. It automates MDX processing for efficient content management.","zh":"博客文章格式化工具用于格式化Next.js网站的博客内容，实现结构化的markdown文件。","ja":"ブログポストフォーマッターはNext.jsのブログコンテンツを構造化されたmarkdownファイルに整形します。","ko":"블로그 게시물 형식 지정하기는 Next.js 웹사이트의 블로그 내용을 구조화된 markdown 파일로 형식화합니다.","es":"Este AI Agent formatea contenido de blog en archivos markdown estructurados para portafolios en Next.js. Procesa posts automáticamente con MDX y los almacena en el directorio _posts/ con slugs y frontmatter correctos.","fr":"Cet outil IA formate le contenu de blog en fichiers markdown structurés pour des portfolios Next.js. Il traite automatiquement les articles avec MDX et les stocke dans le répertoire _posts/ avec des slugs et un frontmatter corrects.","de":"Dieses KI-Tool formatiert Blog-Inhalte in strukturierte Markdown-Dateien für Next.js-Portfolios. Es verarbeitet Beiträge automatisch mit MDX und speichert sie im _posts/-Verzeichnis mit korrekten Slugs und Frontmatter.","pt":"O blog-post-formatter é uma ferramenta que formata conteúdo de blog em markdown para sites Next.js, utilizando o sistema MDX.","ru":"ИИ Агент blog-post-formatter - это инструмент, который форматирует контент блога в markdown для сайтов Next.js, используя систему MDX.","ar":"أداة تنسيق المنشورات بالمدونة blog-post-formatter هي أداة لتنسيق المحتوى بالمدونة في صيغة markdown لمواقع Next.js، وتستخدم نظام MDX."},"seo":{"title":{"en":"blog-post-formatter: Next.js Portfolio Setup Guide | AI A...","zh":"博客文章格式化工具Setup Guide - AIエージェント","ja":"ブログポストフォーマッターのベストプラクティス - AIエージェント","ko":"블로그 게시물 형식 지정하기 Setup Guide - AI 에이전트","es":"blog-post-formatter: Guía de configuración para Next.js MDX","fr":"blog-post-formatter: Guide de configuration pour Next.js MDX","de":"blog-post-formatter: Setup Guide für Next.js MDX","pt":"Guia de Configuração do blog-post-formatter para Desenvol...","ru":"Настройка ИИ Агента blog-post-formatter: Руководство для ...","ar":"دليل إعداد أداة تنسيق المنشورات بالمدونة blog-post-formatter"},"description":{"en":"Discover how to streamline your blog content formatting with blog-post-formatter. Learn how to automate MDX processing and optimize your Next.js portfolio we...","zh":"使用博客文章格式化工具自动处理Next.js网站的MDX系统，实现结构化的markdown文件。","ja":"ブログポストフォーマッターを使ってNext.jsのMDXシステムを自動処理し、構造化されたmarkdownファイルを作成します。","ko":"블로그 게시물 형식 지정하기를 사용하여 Next.js 웹사이트의 MDX 시스템을 자동으로 처리하고 구조화된 markdown 파일을 생성합니다.","es":"Automatiza el formato de posts en markdown para tu sitio Next.js. Este AI Agent genera slugs en kebab-case y frontmatter estructurado para el directorio _pos...","fr":"Automatisez le formatage des articles en markdown pour votre site Next.js. Cet outil IA génère des slugs kebab-case et un frontmatter structuré pour le réper...","de":"Automatisieren Sie die Formatierung von Markdown-Beiträgen für Ihre Next.js-Website. Dieses KI-Tool generiert kebab-case Slugs und strukturiertes Frontmatter...","pt":"Aprenda a configurar o blog-post-formatter para formatar conteúdo de blog em markdown para sites Next.js","ru":"Узнайте, как настроить ИИ Агент blog-post-formatter для форматирования контента блога в markdown для сайтов Next.js","ar":"تعرف على كيفية إعداد أداة تنسيق المنشورات بالمدونة blog-post-formatter لتنسيق المحتوى بالمدونة في صيغة markdown لمواقع Next.js"},"definition":{"en":"blog-post-formatter is a skill that formats blog content into markdown files for Next.js portfolio websites, using a specific frontmatter format and template.","zh":"博客文章格式化工具是一种自动处理Next.js网站MDX系统的工具，用于创建结构化的markdown文件。","ja":"ブログポストフォーマッターはNext.jsのMDXシステムを自動処理して構造化されたmarkdownファイルを作成するツールです。","ko":"블로그 게시물 형식 지정하기는 Next.js 웹사이트의 MDX 시스템을 자동으로 처리하여 구조화된 markdown 파일을 생성하는 도구입니다.","es":"blog-post-formatter es un agente de IA que convierte contenido de blog en archivos markdown correctamente estructurados para sitios web Next.js. Gestiona automáticamente el frontmatter, genera slugs en kebab-case y coloca los archivos en el directorio _posts/ para su procesamiento MDX.","fr":"blog-post-formatter est un outil IA qui convertit le contenu de blog en fichiers markdown correctement structurés pour les sites web Next.js. Il gère automatiquement le frontmatter, génère des slugs kebab-case et place les fichiers dans le répertoire _posts/ pour traitement MDX.","de":"blog-post-formatter ist ein KI-Tool, das Blog-Inhalte in strukturierte Markdown-Dateien für Next.js-Websites konvertiert. Es verwaltet automatisch Frontmatter, generiert kebab-case Slugs und speichert Dateien im _posts/-Verzeichnis für die MDX-Verarbeitung.","pt":"O blog-post-formatter é uma ferramenta de formatação de conteúdo de blog em markdown","ru":"ИИ Агент blog-post-formatter - это инструмент форматирования контента блога в markdown","ar":"أداة تنسيق المنشورات بالمدونة blog-post-formatter هي أداة لتنسيق المحتوى بالمدونة في صيغة markdown"},"features":{"en":["Automates MDX processing for Next.js portfolio websites","Formats blog content into properly structured markdown files","Uses a specific frontmatter format for consistency","Stores blog posts in the `_posts/` directory","Supports kebab-case slug formatting for file names"],"zh":["自动处理Next.js网站的MDX系统","创建结构化的markdown文件","支持_frontmatter_格式","使用模板创建博客文章","自动将博客文章存储在_posts/目录中","支持kebab-case的slug格式"],"ja":["Next.jsのMDXシステムを自動処理","構造化されたmarkdownファイルを作成","Frontmatter形式をサポート","テンプレートを使用してブログポストを作成","ブログポストを自動的に_posts/ディレクトリに保存","ケバブケースのスラッグ形式をサポート"],"ko":["Next.js 웹사이트의 MDX 시스템을 자동으로 처리","구조화된 markdown 파일을 생성","프론트매터 형식을 지원","템플릿을 사용하여 블로그 게시물を作成","블로그 게시물을 자동으로 _posts/ 디렉토리에 저장","케밥ケース의 슬러그 형식을 지원"],"es":["Generación automática de slugs en kebab-case a partir del título","Formato de frontmatter estructurado según referencia específica","Almacenamiento en directorio _posts/ para procesamiento MDX nativo","Uso de plantillas predefinidas para consistencia de posts","Integración directa con el flujo de trabajo de portafolios Next.js","Procesamiento automático de contenido markdown existente"],"fr":["Génération automatique de slugs kebab-case à partir du titre","Formatage de frontmatter structuré selon une référence spécifique","Stockage dans le répertoire _posts/ pour traitement MDX natif","Utilisation de modèles prédéfinis pour la cohérence des articles","Intégration directe avec le flux de travail des portfolios Next.js","Traitement automatique du contenu markdown existant"],"de":["Automatische Generierung von kebab-case Slugs aus dem Titel","Strukturiertes Frontmatter-Format gemäß spezifischer Referenz","Speicherung im _posts/-Verzeichnis für native MDX-Verarbeitung","Verwendung vordefinierter Vorlagen für Beitragskonsistenz","Direkte Integration in Next.js-Portfolio-Workflows","Automatische Verarbeitung vorhandener Markdown-Inhalte"],"pt":["Formatação de conteúdo de blog em markdown","Integração com o sistema MDX do Next.js","Armazenamento de posts em diretório `_posts/`","Utilização de frontmatter para metadados","Modelo de post disponível em `assets/template.md`"],"ru":["Форматирование контента блога в markdown","Интеграция с системой MDX в Next.js","Хранение постов в директории `_posts/`","Использование frontmatter для метаданных","Шаблон поста доступен в `assets/template.md`"],"ar":["تنسيق المحتوى بالمدونة في صيغة markdown","التكامل مع نظام MDX في Next.js","تخزين المنشورات في الدليل `_posts/`","استخدام.frontmatter لبيانات التعريف","نموذج المنشور متاح في `assets/template.md`"]},"keywords":{"en":["how to use blog-post-formatter","blog-post-formatter setup guide","Next.js portfolio website optimization","MDX processing automation","blog-post-formatter alternative","blog-post-formatter vs manual formatting","install blog-post-formatter","blog-post-formatter for developers","blog-post-formatter tutorial"],"zh":["AIエージェント","博客文章格式化","Next.js","MDX系统","markdown文件","Frontmatter格式","模板创建","自动处理","结构化markdown"],"ja":["AIエージェント","ブログポストフォーマッター","Next.js","MDXシステム","markdownファイル","Frontmatter形式","テンプレート作成","自動処理","構造化markdown"],"ko":["AI 에이전트","블로그 게시물 형식 지정하기","Next.js","MDX 시스템","markdown 파일","프론트매터 형식","템플릿 생성","자동 처리","구조화된 markdown"],"es":["nextjs mdx blog formatter","agente ia formato markdown","directorio _posts nextjs","frontmatter estructura blog","generador slug kebab-case","automatización contenido blog","plantilla markdown nextjs","procesamiento mdx automático"],"fr":["nextjs mdx blog formatter","outil ia formatage markdown","répertoire _posts nextjs","frontmatter structure blog","générateur slug kebab-case","automatisation contenu blog","modèle markdown nextjs","traitement mdx automatique"],"de":["nextjs mdx blog formatter","ki-tool markdown formatierung","_posts verzeichnis nextjs","frontmatter struktur blog","kebab-case slug generator","blog content automatisierung","markdown vorlage nextjs","automatische mdx verarbeitung"],"pt":["blog-post-formatter","Next.js","MDX","formatação de conteúdo de blog","markdown","ferramentas de desenvolvimento web","desenvolvimento de sites","otimização de SEO"],"ru":["ИИ Агент blog-post-formatter","Next.js","MDX","форматирование контента блога","markdown","инструменты веб-разработки","разработка сайтов","оптимизация SEO"],"ar":["أداة تنسيق المنشورات بالمدونة blog-post-formatter","Next.js","MDX","تنسيق المحتوى بالمدونة","markdown","أدوات تطوير الويب","تطوير المواقع","تحسين محركات البحث"]}},"owner":"santosrai","repo":"santosrai.github.io","repoPath":"santosrai/santosrai.github.io","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.425Z","topics":[],"category":"community","skillMd":{"name":"blog-post-formatter","description":"Format blog content into properly structured markdown files for Next.js portfolio blog. Use when user wants to: (1) Format raw blog content into markdown with frontmatter, (2) Create new blog posts from topics or titles, (3) Generate blog post files with proper metadata (title, excerpt, date, author) and save to _posts/ directory. Automatically generates excerpts, converts titles to kebab-case filenames, and ensures proper frontmatter format.","bodyPreview":"Format blog content into properly structured markdown files for the Next.js portfolio website. All blog posts are stored in `_posts/` directory and automatically processed by the site''s MDX system.\n\n## Quick Reference\n\n- **File location**: `_posts/{slug}.md` (slug is kebab-case of title)\n- **Frontmatter format**: See [references/post-structure.md](references/post-structure.md)\n- **Template**: See [assets/template.md](assets/template.md)\n\n## Workflow\n\n### 1. Format Existing Content\n\nWhen user pro","body":"Format blog content into properly structured markdown files for the Next.js portfolio website. All blog posts are stored in `_posts/` directory and automatically processed by the site''s MDX system.\n\n## Quick Reference\n\n- **File location**: `_posts/{slug}.md` (slug is kebab-case of title)\n- **Frontmatter format**: See [references/post-structure.md](references/post-structure.md)\n- **Template**: See [assets/template.md](assets/template.md)\n\n## Workflow\n\n### 1. Format Existing Content\n\nWhen user provides raw blog content:\n\n1. **Extract or generate title**:\n   - If first line is a heading (H1), use it as title\n   - If content starts with text, extract first sentence or generate from content\n   - Ensure title is clear and descriptive\n\n2. **Generate excerpt**:\n   - Extract first meaningful paragraph (150-200 characters)\n   - Remove markdown formatting from excerpt\n   - If no suitable paragraph, generate summary from first few sentences\n   - Keep excerpt concise and engaging\n\n3. **Set metadata**:\n   - **Date**: Use current date in `YYYY-MM-DD` format if not provided\n   - **Author**: Default to `''Santosh Rai''` (wrapped in single quotes)\n   - **Title**: Wrap in single quotes in frontmatter\n\n4. **Format content**:\n   - Do NOT include an H1 heading in the content (the page component already displays the title from frontmatter)\n   - Start content directly with paragraphs or H2 headings\n   - Preserve user''s original markdown formatting\n   - Validate markdown syntax (code blocks, lists, links)\n\n5. **Generate filename**:\n   - Convert title to kebab-case (lowercase, hyphens for spaces)\n   - Remove special characters, keep only alphanumeric and hyphens\n   - Example: \"Understanding JavaScript\" → `understanding-javascript.md`\n\n6. **Save file**: Write to `_posts/{slug}.md`\n\n### 2. Create New Post\n\nWhen user provides topic/title:\n\n1. **Generate frontmatter**:\n   - Use provided title or generate from topic\n   - Create excerpt placeholder or generate from topic description\n   - Set date to current date\n   - Set author to `''Santosh Rai''`\n\n2. **Create structure**:\n   - Do NOT add an H1 heading (the page component already displays the title from frontmatter)\n   - Start content directly with paragraphs or H2 headings\n   - Add placeholder sections or basic outline\n   - Use template from `assets/template.md` as starting point\n\n3. **Save file**: Write to `_posts/{slug}.md`\n\n### 3. Auto-Generation Rules\n\n**Excerpt generation**:\n- Extract first paragraph (up to 200 characters)\n- Remove markdown syntax (links, bold, code)\n- If paragraph is too short, include next sentence\n- Ensure excerpt is complete and grammatically correct\n\n**Title to slug conversion**:\n- Convert to lowercase\n- Replace spaces with hyphens\n- Remove special characters (keep only alphanumeric and hyphens)\n- Remove leading/trailing hyphens\n- Examples:\n  - \"What is JavaScript?\" → `what-is-javascript`\n  - \"Design Patterns With VBA\" → `design-patterns-with-vba`\n  - \"Simple calculator in javascript using MVC pattern\" → `simple-calculator-in-javascript-using-mvc-pattern`\n\n**Date format**: Always use `YYYY-MM-DD` (e.g., `''2024-01-20''`)\n\n## Frontmatter Format\n\nAll posts must include this exact frontmatter structure:\n\n```yaml\n---\ntitle: ''Post Title''\nexcerpt: ''Brief description''\ndate: ''YYYY-MM-DD''\nauthor: ''Santosh Rai''\n---\n```\n\n**Important**: All values must be wrapped in single quotes.\n\n## Validation\n\nBefore saving, verify:\n- Frontmatter has all required fields (title, excerpt, date, author)\n- Date is in YYYY-MM-DD format\n- All frontmatter values are wrapped in single quotes\n- Content does NOT start with an H1 heading (title is displayed from frontmatter)\n- Filename is valid kebab-case slug\n- File will be saved in `_posts/` directory\n\n## Examples\n\n**Example 1: Format existing content**\n```\nUser: \"Here''s my blog post about JavaScript closures...\"\n\nOutput: Creates _posts/javascript-closures.md with:\n- Title extracted/generated from content\n- Excerpt from first paragraph\n- Current date\n- Properly formatted markdown\n```\n\n**Example 2: Create new post**\n```\nUser: \"Create a blog post about React hooks\"\n\nOutput: Creates _posts/react-hooks.md with:\n- Title: \"React Hooks\"\n- Generated excerpt about React hooks\n- Current date\n- Basic structure starting with content (no H1 heading)\n```\n\n## Reference Files\n\n- **Post structure details**: See [references/post-structure.md](references/post-structure.md) for complete format specification and examples\n- **Template**: See [assets/template.md](assets/template.md) for reusable blog post template\n\n## Integration\n\nThe formatted files integrate automatically with the existing blog system:\n- `lib/mdx.ts` reads all `.md` files from `_posts/`\n- Posts are sorted by date (newest first)\n- Individual posts accessible at `/blog/[slug]`\n- Blog listing at `/blog` displays all posts\n"},"lastSynced":"2026-03-08T02:07:28.294Z","agentAnalysis":{"suitability":{"en":"Perfect for Content Automation Agents specializing in Next.js portfolio development.","zh":"非常适合专注于 Next.jsfolio 开发的内容自动化代理。","ja":"Next.js ポートフォリオ開発を専門とするコンテンツ自動化エージェントに最適です。","ko":"Next.js 포트폴리오 개발을 전문으로 하는 콘텐츠 자동화 에이전트에게 완벽합니다.","es":"Perfecto para Agentes de Automatización de Contenido que se especializan en el desarrollo de portfolios de Next.js.","fr":"Parfait pour les Agents d''Automatisation de Contenu spécialisés dans le développement de portfolios Next.js.","de":"Perfekt für Inhaltsautomatisierungsagenten, die sich auf die Entwicklung von Next.js-Portfolios spezialisieren.","pt":"Perfeito para Agentes de Automação de Conteúdo especializados no desenvolvimento de portfólio do Next.js.","ru":"Идеально подходит для агентов автоматизации контента, специализирующихся на разработке портфолио Next.js.","ar":"مثالي لعميل تقنيات الأتمتة التخصصي في تطوير محفظة Next.js."},"recommendation":{"en":"Automates MDX frontmatter formatting and file structure creation for Next.js blogs, ensuring proper slug generation and frontmatter compliance. Streamlines content management by handling markdown file creation in the `_posts/` directory with kebab-case slug conventions.","zh":"自动化MDX前置格式和文件结构创建，用于Next.js博客，确保正确的slug生成和前置格式的遵守。通过处理markdown文件的创建在 `_posts/` 目录中，使用短横线命名约定，简化内容管理。","ja":"Next.jsブログ用のMDX前置形式の自動化とファイル構造の作成を自動化し、適切なスラッグの生成と前置形式の準拠を保証する。 `_posts/` ディレクトリ内のマークダウンファイルの作成を処理し、ケバブケースのスラッグ規則を使用して、コンテンツ管理を簡素化する。","ko":"Next.js 블로그용 MDX 전면 형식 자동화 및 파일 구조 생성을 자동화하고, 올바른 슬러그 생성 및 전면 형식 준수를 보장합니다. `_posts/` 디렉토리 내의 마크다운 파일 생성을 처리하여, 케밥 케이스 슬러그 규칙을 사용하여 콘텐츠 관리를 간소화합니다.","es":"Automatiza el formato de frontmatter de MDX y la creación de estructura de archivos para blogs de Next.js, garantizando la generación adecuada de slug y el cumplimiento de frontmatter. Simplifica la administración de contenido al manejar la creación de archivos markdown en el directorio `_posts/` con convenciones de slug con kebab-case.","fr":"Automatise la mise en forme du frontmatter MDX et la création de structure de fichiers pour les blogs Next.js, en garantissant une génération de slug appropriée et une conformité du frontmatter. Rationalise la gestion de contenu en gérant la création de fichiers markdown dans le répertoire `_posts/` avec des conventions de slug en kebab-case.","de":"Automatisiert die Formatierung des MDX-Frontmatters und die Erstellung der Dateistruktur für Next.js-Blogs, wodurch eine ordnungsgemäße Slug-Generierung und Frontmatter-Konformität gewährleistet wird. Vereinfacht die Inhaltsverwaltung, indem die Erstellung von Markdown-Dateien im `_posts/`-Verzeichnis mit Kebab-Case-Slug-Konventionen gehandhabt wird.","pt":"Automatiza a formatação do frontmatter MDX e a criação da estrutura de arquivos para blogs do Next.js, garantindo a geração adequada de slug e o cumprimento do frontmatter. Simplifica a gestão de conteúdo ao lidar com a criação de arquivos markdown no diretório `_posts/` com convenções de slug em kebab-case.","ru":"Автоматизирует форматирование frontmatter MDX и создание структуры файлов для блогов Next.js, обеспечивая правильную генерацию slug и соблюдение формата frontmatter. Упрощает управление контентом, обрабатывая создание файлов markdown в директории `_posts/` с соглашениями об именовании slug в kebab-case.","ar":"يتم 자동ًا تنسيق frontmatter MDX وإنشاء هيكل الملفات لمدونات Next.js، مما يضمن توليد slug مناسب وموافقة frontmatter. يبسط إدارة المحتوى عن طريق التعامل مع إنشاء ملفات markdown في الدليل `_posts/` مع اتفاقيات تسمية slug في kebab-case."},"useCases":{"en":["Formatting raw blog content into structured MDX files","Generating kebab-case slugs from post titles","Automating frontmatter creation for Next.js MDX systems"],"zh":["将原始博客内容格式化为结构化的MDX文件","从帖子标题生成短横线命名的slug","自动化Next.js MDX系统的前置形式创建"],"ja":["生のブログコンテンツを構造化されたMDXファイルにフォーマットする","投稿タイトルからケバブケースのスラッグを生成する","Next.js MDXシステムの前置形式の作成を自動化する"],"ko":["原始 블로그 콘텐츠를 구조화된 MDX 파일로 형식화하는 것","게시물 제목에서 케밥 케이스 슬러그를 생성하는 것","Next.js MDX 시스템의 전면 형식 생성을 자동화하는 것"],"es":["Formato de contenido de blog sin procesar en archivos MDX estructurados","Generación de slugs con kebab-case a partir de títulos de publicaciones","Automatización de la creación de frontmatter para sistemas MDX de Next.js"],"fr":["Mise en forme de contenu de blog brut en fichiers MDX structurés","Génération de slugs en kebab-case à partir de titres de publications","Automatisation de la création de frontmatter pour les systèmes MDX de Next.js"],"de":["Formatierung von rohem Blog-Inhalt in strukturierte MDX-Dateien","Generierung von Kebab-Case-Slugs aus Beitragsnamen","Automatisierung der Erstellung von Frontmatter für Next.js-MDX-Systeme"],"pt":["Formatar conteúdo bruto de blog em arquivos MDX estruturados","Gerar slugs em kebab-case a partir de títulos de postagens","Automatizar a criação de frontmatter para sistemas MDX do Next.js"],"ru":["Форматировать сырой контент блога в структурированные файлы MDX","Генерировать slug в kebab-case из названий постов","Автоматизировать создание frontmatter для систем MDX Next.js"],"ar":["تنسيق المحتوى الخام للمدونة في ملفات MDX المنظمة","توليد slugs في kebab-case من عناوين المنشورات","تتم أتمتة إنشاء frontmatter لأنظمة MDX Next.js"]},"limitations":{"en":["Requires filesystem access to _posts/ directory","Limited to Next.js MDX frontmatter format","Depends on predefined template structure"],"zh":["需要 `_posts/` 目录的文件系统访问","仅限于Next.js MDX前置形式格式","依赖于预定义的模板结构"],"ja":[" `_posts/` ディレクトリへのファイルシステムアクセスが必要","Next.js MDX前置形式形式に限定される","事前に定義されたテンプレート構造に依存する"],"ko":[" `_posts/` 디렉토리에 대한 파일 시스템 액세스가 필요함","Next.js MDX 전면 형식 형식으로 제한됨","사전에 정의된 템플릿 구조에 의존함"],"es":["Requiere acceso al sistema de archivos del directorio _posts/","Limitado al formato de frontmatter de MDX de Next.js","Depende de una estructura de plantilla predefinida"],"fr":["Nécessite un accès au système de fichiers du répertoire _posts/","Limité au format de frontmatter MDX de Next.js","Dépend d''une structure de modèle pré définie"],"de":["Benötigt Zugriff auf das Dateisystem des `_posts/`-Verzeichnisses","Begrenzt auf das Frontmatter-Format von Next.js-MDX","Hängt von einer vordefinierten Vorlagenstruktur ab"],"pt":["Requer acesso ao sistema de arquivos do diretório `_posts/`","Limitado ao formato de frontmatter do Next.js MDX","Depende de estrutura de modelo predefinida"],"ru":["Требует доступа к файловой системе директории `_posts/`","Ограничен форматом frontmatter MDX Next.js","Зависит от предварительно определенной структуры шаблона"],"ar":["يتطلب الوصول إلى نظام الملفات في الدليل `_posts/`","محدود بتنسيق frontmatter MDX Next.js","يعتمد على هيكل نموذج محدد مسبقًا"]},"version":4},"contentHash":"25eab15d5f7dbf2598685c764cc73d0e8245e1dd3c26d9ef94810945847cb9e5","qualityScore":48}');
DELETE FROM skills_fts WHERE id = 'santosrai/santosrai.github.io/blog-post-formatter';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('santosrai/santosrai.github.io/blog-post-formatter', 'blog-post-formatter', 'santosrai', 'santosrai.github.io', 'community', 'blog-post-formatter santosrai santosrai.github.io community The blog-post-formatter skill formats blog content into properly structured markdown files for Next.js portfolio websites, benefiting developers and content creators. It automates MDX processing for efficient content management. 博客文章格式化工具用于格式化Next.js网站的博客内容，实现结构化的markdown文件。 ブログポストフォーマッターはNext.jsのブログコンテンツを構造化されたmarkdownファイルに整形します。 블로그 게시물 형식 지정하기는 Next.js 웹사이트의 블로그 내용을 구조화된 markdown 파일로 형식화합니다. Este AI Agent formatea contenido de blog en archivos markdown estructurados para portafolios en Next.js. Procesa posts automáticamente con MDX y los almacena en el directorio _posts/ con slugs y frontmatter correctos. Cet outil IA formate le contenu de blog en fichiers markdown structurés pour des portfolios Next.js. Il traite automatiquement les articles avec MDX et les stocke dans le répertoire _posts/ avec des slugs et un frontmatter corrects. Dieses KI-Tool formatiert Blog-Inhalte in strukturierte Markdown-Dateien für Next.js-Portfolios. Es verarbeitet Beiträge automatisch mit MDX und speichert sie im _posts/-Verzeichnis mit korrekten Slugs und Frontmatter. O blog-post-formatter é uma ferramenta que formata conteúdo de blog em markdown para sites Next.js, utilizando o sistema MDX. ИИ Агент blog-post-formatter - это инструмент, который форматирует контент блога в markdown для сайтов Next.js, используя систему MDX. أداة تنسيق المنشورات بالمدونة blog-post-formatter هي أداة لتنسيق المحتوى بالمدونة في صيغة markdown لمواقع Next.js، وتستخدم نظام MDX. how to use blog-post-formatter blog-post-formatter setup guide Next.js portfolio website optimization MDX processing automation blog-post-formatter alternative blog-post-formatter vs manual formatting install blog-post-formatter blog-post-formatter for developers blog-post-formatter tutorial AIエージェント 博客文章格式化 Next.js MDX系统 markdown文件 Frontmatter格式 模板创建 自动处理 结构化markdown Automates MDX processing for Next.js portfolio websites Formats blog content into properly structured markdown files Uses a specific frontmatter format for consistency Stores blog posts in the `_posts/` directory Supports kebab-case slug formatting for file names blog-post-formatter is a skill that formats blog content into markdown files for Next.js portfolio websites, using a specific frontmatter format and template.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('GadCoder/BikeRoutes/pr-creator', 'community', 'GadCoder', 'BikeRoutes', 'GadCoder/BikeRoutes', 'pr-creator', 0, 0, 48, '2026-03-08T01:57:15.426Z', '2026-03-08T02:07:28.726Z', '94cc27c996da908e787cb4b692e7ff5d1e23804f02504e2ab96c599b624d7875', '{"id":"GadCoder/BikeRoutes/pr-creator","name":"pr-creator","description":{"en":"The pr-creator skill automates PR body generation for developers, extracting intent, scope, and risk from changed files and commit history to create structured PR bodies.","zh":"PR创建器是一种自动化代码审查的工具，通过分析代码变更和提交历史来生成高质量的PR内容","ja":"PR作成ツールは、コードの変更とコミット履歴を分析して、高品質のPR内容を自動生成するツールです","ko":"PR 생성기는 코드 변경과 커밋 기록을 분석하여 고품질의 PR 내용을 자동 생성하는 도구입니다","es":"pr-creator es una herramienta de AI que automatiza la creación de solicitudes de pull. Inspecciona los cambios en la rama y genera un cuerpo de solicitud de pull con resumen, motivos y consideraciones","fr":"pr-creator est un outil d''IA qui automatise la création de demandes de pull. Il inspecte les modifications apportées à la branche et génère un corps de demande de pull avec résumé, motifs et considérations","de":"pr-creator ist ein AI-Tool, das die Erstellung von Pull-Anfragen automatisiert. Es überprüft die Änderungen im Branch und generiert einen Anfrage-Text mit Zusammenfassung, Gründen und Überlegungen","pt":"O PR Creator é uma ferramenta que ajuda a criar pull requests personalizados. Ele inspeciona as alterações no branch e extrai informações para criar um corpo de PR estruturado.","ru":"PR Creator - это инструмент, который помогает создавать индивидуальные запросы на слияние. Он проверяет изменения в ветке и извлекает информацию для создания структурированного тела PR.","ar":"PR Creator هو أداة تساعد في إنشاء طلبات سحب مخصصة. يقوم بفحص التغييرات في الفرع واستخراج المعلومات لإنشاء جسم طلب سحب منظم"},"seo":{"title":{"en":"pr-creator: Automated PR Body Generation | AI Agent Skill","zh":"PR 创建器设置指南 - 自动化代码审查","ja":"PR作成ツールのベストプラクティス - コードレビューの自動化","ko":"PR 생성기 설정 가이드 - 코드 리뷰 자동화","es":"Guía de Configuración de pr-creator: Automatización de So...","fr":"Guide d''Installation de pr-creator : Outil d''Automatisati...","de":"Einrichtungsleitfaden für pr-creator: Automatisierung von...","pt":"Guia de Configuração do PR Creator: Melhores Práticas par...","ru":"Настройка PR Creator: Руководство для разработчиков по ИИ...","ar":"دليل إعداد PR Creator: أفضل الممارسات للاستفادة من أدوات ..."},"description":{"en":"Discover how pr-creator streamlines your workflow by automatically generating PR bodies with intent, scope, and risk analysis - learn more and get started to...","zh":"通过PR创建器实现代码审查自动化，提高开发效率。了解如何设置和使用PR创建器，优化代码审查流程","ja":"PR作成ツールを使用してコードレビューを自動化し、開発効率を向上させます。設定方法と使い方を学び、コードレビューのワークフローを最適化しましょう","ko":"PR 생성기를 사용하여 코드 리뷰를 자동화하고 개발 효율성을 높여보세요. 설정 방법과 사용 방법을 알아보고 코드 리뷰 워크플로를 최적화하세요","es":"Aprende a configurar pr-creator para automatizar tus solicitudes de pull con esta guía paso a paso. Mejora tu flujo de trabajo con esta herramienta de AI","fr":"Découvrez comment installer pr-creator pour automatiser vos demandes de pull avec ce guide étape par étape. Améliorez votre flux de travail avec cet outil d''IA","de":"Erfahren Sie, wie Sie pr-creator einrichten, um Ihre Pull-Anfragen zu automatisieren. Verbessern Sie Ihren Arbeitsablauf mit diesem AI-Tool","pt":"Aprenda a configurar o PR Creator para melhorar a colaboração e a qualidade do código. Descubra as melhores práticas para desenvolvedores.","ru":"Узнайте, как настроить PR Creator для улучшения сотрудничества и качества кода. Откройте для себя лучшие практики для разработчиков по ИИ Агентам.","ar":"تعلم كيفية إعداد PR Creator لتحسين التعاون وجودة الكود. اكتشف أفضل الممارسات للاستفادة من أدوات الإي الأجنت"},"definition":{"en":"pr-creator is a skill that automates the generation of pull request bodies, following a structured format with sections for summary, why, what changed, and considerations.","zh":"PR创建器是一种AI工具，用于自动生成代码审查内容","ja":"PR作成ツールは、AIエージェントの一種で、コードレビュー内容を自動生成する","ko":"PR 생성기는 AI 도구 중 하나로 코드 리뷰 내용을 자동 생성합니다","es":"pr-creator es una herramienta de AI que ayuda a los desarrolladores a automatizar la creación de solicitudes de pull","fr":"pr-creator est un outil d''IA qui aide les développeurs à automatiser la création de demandes de pull","de":"pr-creator ist ein AI-Tool, das Entwicklern hilft, die Erstellung von Pull-Anfragen zu automatisieren","pt":"O PR Creator é uma ferramenta de código aberto que automatiza a criação de pull requests.","ru":"PR Creator - это инструмент с открытым исходным кодом, который автоматизирует создание запросов на слияние.","ar":"PR Creator هو أداة مصدر مفتوح تautomatiza إنشاء طلبات سحب"},"features":{"en":["Extracts intent, scope, and risk from changed files and commit history","Generates PR bodies with sections for summary, why, what changed, and considerations","Keeps summary to one line by default for clarity","Includes technical bullet points with concrete modules/files in what changed section","Considers edge cases, setup notes, and breaking behavior in PR body"],"zh":["自动分析代码变更和提交历史","生成高质量的PR内容，包括摘要、原因、变更内容和考虑因素","支持自定义PR模板","集成多种代码版本控制系统","提供代码审查的工作流优化建议"],"ja":["コードの変更とコミット履歴を自動分析","高品質のPR内容を生成、要約、理由、変更内容、考慮事項を含む","カスタムPRテンプレートのサポート","多種のコードバージョン管理システムとの統合","コードレビューのワークフロー最適化の提案"],"ko":["코드 변경과 커밋 기록을 자동 분석","고품질의 PR 내용을 생성، 요약, 이유, 변경 내용, 고려 사항을 포함","사용자 정의 PR 템플릿 지원","다양한 코드 버전 관리 시스템との 통합","코드 리뷰의 워크플로 최적화 제안"],"es":["Inspección de cambios en la rama antes de escribir la solicitud de pull","Extracción de intención, alcance y riesgo de los archivos y el historial de commits modificados","Generación de un cuerpo de solicitud de pull con secciones de resumen, motivos y consideraciones","Mantenimiento del resumen en una línea por defecto, con extensión solo si es necesario para la claridad","Inclusión de casos de borde, notas de configuración y comportamiento de ruptura en la sección de consideraciones"],"fr":["Inspection des modifications apportées à la branche avant de rédiger la demande de pull","Extraction de l''intention, de la portée et du risque des fichiers et de l''historique des commits modifiés","Génération d''un corps de demande de pull avec des sections de résumé, de motifs et de considérations","Maintenance du résumé en une ligne par défaut, avec extension uniquement si nécessaire pour la clarté","Inclusion de cas de bord, de notes de configuration et de comportement de rupture dans la section des considérations"],"de":["Überprüfung der Änderungen im Branch vor der Erstellung der Pull-Anfrage","Extraktion von Intention, Umfang und Risiko aus den geänderten Dateien und dem Commit-Historie","Generierung eines Anfrage-Textes mit Abschnitten für Zusammenfassung, Gründe und Überlegungen","Beibehaltung der Zusammenfassung in einer Zeile per Vorgabe, mit Erweiterung nur bei Bedarf für Klarheit","Einbeziehung von Randfällen, Konfigurationshinweisen und Bruchverhalten in den Überlegungen-Abschnitt"],"pt":["Inspeciona alterações no branch antes de criar o PR","Extrai intent, escopo e risco das alterações","Cria corpo de PR estruturado com resumo, motivos e alterações","Inclui considerações e casos de bordo","Permite personalização do resumo e das alterações","Suporta tecnologias como Git e CLI"],"ru":["Проверяет изменения в ветке перед созданием PR","Извлекает намерение, объем и риск изменений","Создает структурированное тело PR с резюме, причинами и изменениями","Включает соображения и граничные случаи","Позволяет настраивать резюме и изменения","Поддерживает технологии như Git и CLI"],"ar":["يفحص التغييرات في الفرع قبل إنشاء طلب السحب","يستخرج النية، النطاق والمخاطر من التغييرات","ينشئ جسم طلب سحب منظم مع ملخص، أسباب وتغييرات","يشمل الاعتبارات والحالات الحدية","يسمح بتعديل الملخص والتغييرات","يدعم تقنيات مثل Git وCLI"]},"keywords":{"en":["how to use pr-creator","pr-creator setup guide","automated PR body generation","pr-creator vs manual PR writing","pr-creator install","what is pr-creator","pr-creator alternative","pr-creator workflow automation"],"zh":["PR创建器","代码审查自动化","AI工具","代码版本控制","代码审查流程优化","自动化代码审查","PR内容生成","代码变更分析"],"ja":["PR作成ツール","コードレビューの自動化","AIエージェント","コードバージョン管理","コードレビューのワークフロー最適化","自動コードレビュー","PR内容の自動生成","コードの変更分析"],"ko":["PR 생성기","코드 리뷰 자동화","AI 도구","코드 버전 관리","코드 리뷰 워크플로 최적화","자동 코드 리뷰","PR 내용 자동 생성","코드 변경 분석"],"es":["pr-creator","herramienta de AI para solicitudes de pull","automatización de solicitudes de pull","flujo de trabajo de desarrollo","herramientas de AI para desarrolladores","creación de solicitudes de pull automatizada","inspección de cambios en la rama","extraction de intención y riesgo"],"fr":["pr-creator","outil d''IA pour demandes de pull","automatisation de demandes de pull","flux de travail de développement","outils d''IA pour développeurs","création de demandes de pull automatisée","inspection des modifications apportées à la branche","extraction de l''intention et du risque"],"de":["pr-creator","AI-Tool für Pull-Anfragen","Automatisierung von Pull-Anfragen","Arbeitsablauf von Entwicklern","AI-Tools für Entwickler","Erstellung von Pull-Anfragen automatisiert","Überprüfung der Änderungen im Branch","Extraktion von Intention und Risiko"],"pt":["PR Creator","ferramenta de código aberto","automatização de pull requests","colaboração de desenvolvedores","qualidade de código","Git","CLI","desenvolvimento de software"],"ru":["PR Creator","инструмент с открытым исходным кодом","автоматизация запросов на слияние","сотрудничество разработчиков","качество кода","Git","CLI","разработка программного обеспечения"],"ar":["PR Creator","أداة مصدر مفتوح","تأتمتة طلبات السحب","تعاون المطورين","جودة الكود","Git","CLI","تطوير البرمجيات"]}},"owner":"GadCoder","repo":"BikeRoutes","repoPath":"GadCoder/BikeRoutes","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.426Z","topics":[],"category":"community","skillMd":{"name":"pr-creator","description":"Create or update pull request descriptions in a strict four-section format: Summary, Why, What Changed, and Considerations. Use when a user asks to draft a PR, improve PR text, or standardize PR messaging before opening a PR.","bodyPreview":"# PR Creator\n\n## Workflow\n\n1. Inspect the branch changes before writing.\n2. Extract intent, scope, and risk from changed files and commit history.\n3. Write the PR body using exactly these sections and order:\n- `## 1. Summary`\n- `## 2. Why`\n- `## 3. What Changed`\n- `## 4. Considerations`\n4. Keep `Summary` to one line by default; extend only if needed for clarity.\n5. Keep `What Changed` as technical bullet points with concrete modules/files.\n6. Include edge cases, setup notes, breaking behavior, a","body":"# PR Creator\n\n## Workflow\n\n1. Inspect the branch changes before writing.\n2. Extract intent, scope, and risk from changed files and commit history.\n3. Write the PR body using exactly these sections and order:\n- `## 1. Summary`\n- `## 2. Why`\n- `## 3. What Changed`\n- `## 4. Considerations`\n4. Keep `Summary` to one line by default; extend only if needed for clarity.\n5. Keep `What Changed` as technical bullet points with concrete modules/files.\n6. Include edge cases, setup notes, breaking behavior, and warnings in `Considerations`.\n\n## Output Template\n\nUse this template verbatim:\n\n```md\n## 1. Summary\n<one-line summary>\n\n## 2. Why\n<context and motivation>\n\n## 3. What Changed\n- <technical change 1>\n- <technical change 2>\n\n## 4. Considerations\n- <edge case or risk>\n- <setup/migration note>\n- <breaking change or warning, if any>\n```\n\n## Rules\n\n- Do not omit any section.\n- Do not reorder section numbers.\n- Prefer concrete behavior and implementation details over vague statements.\n- If no breaking changes exist, explicitly say `- No breaking changes.` in `Considerations`.\n"},"lastSynced":"2026-03-08T02:07:28.726Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated PR body generation with intent, scope, and risk analysis.","zh":"非常适合需要自动化PR正文生成（包括意图、范围和风险分析）的开发代理","ja":"開発エージェントが自動化されたPR本文の生成（意図、スコープ、リスク分析を含む）を必要とする場合に最適","ko":"의도, 범위 및 위험 분석을 포함한 자동화된 PR 본문 생성이 필요한 개발 에이전트에게 적합함","es":"Perfecto para Agentes de Desarrollo que necesitan generación automática de cuerpo de PR con análisis de intención, alcance y riesgo.","fr":"Parfait pour les agents de développement ayant besoin d''une génération automatique de corps de PR avec analyse d''intention, de portée et de risque.","de":"Perfekt für Entwicklungssagenten, die eine automatisierte PR-Body-Generierung mit Intent-, Scope- und Risikoanalyse benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de geração automática de corpo de PR com análise de intenção, escopo e risco.","ru":"Идеально подходит для агентов разработки, которым требуется автоматизированная генерация тела PR с анализом намерений, объема и рисков.","ar":"مثالي لعمليات وكيل التطوير التي تحتاج إلى توليد جسم自动ي لطلبات السحب مع تحليل النية والنطاق والمخاطر."},"recommendation":{"en":"Empowers agents to generate structured PR bodies using commit history and changed files analysis, including technical details like edge cases, setup notes, and breaking behavior, all formatted into standardized sections like Summary, Why, What Changed, and Considerations.","zh":"赋予代理生成结构化的PR正文的能力，使用提交历史和更改文件分析，包括技术细节，如边缘情况、设置说明和破坏行为，所有这些都格式化为标准化的部分，如摘要、原因、更改内容和考虑因素","ja":"コミット履歴と変更ファイルの分析を使用して、エージェントが構造化されたPR本文を生成する能力を提供します。技術的な詳細、例えばエッジケース、設定ノート、破壊的な動作などを含み、これらはすべて、サマリー、理由、変更内容、考慮事項などの標準化されたセクションに整形されています","ko":"에이전트가 구조화된 PR 본문을 생성할 수 있는 기능을 제공함으로써, 커밋 기록 및 변경 파일 분석을 사용하여 기술적인 세부 정보를 포함하는 것들, 예를 들어 에지 케이스, 설정 노트 및 중단 동작을 포함하고, 요약, 이유, 변경 내용 및 고려 사항과 같은 표준화된 섹션으로 형식화된 모든 것","es":"Habilita a los agentes a generar cuerpos de PR estructurados utilizando el historial de commits y el análisis de archivos modificados, incluyendo detalles técnicos como casos de borde, notas de configuración y comportamiento de ruptura, todos formateados en secciones estandarizadas como Resumen, Por qué, Qué cambió y Consideraciones.","fr":"Permet aux agents de générer des corps de PR structurés en utilisant l''historique des commits et l''analyse des fichiers modifiés, y compris des détails techniques tels que les cas de limite, les notes de configuration et le comportement de rupture, le tout formaté dans des sections standardisées comme Résumé, Pourquoi, Ce qui a changé et Considérations.","de":"Ermächtigt Agenten, strukturierte PR-Body mithilfe der Commit-Historie und der Analyse geänderter Dateien zu generieren, einschließlich technischer Details wie Randfälle, Einrichtungshinweise und Brechverhalten, alle formatiert in standardisierten Abschnitten wie Zusammenfassung, Warum, Was geändert wurde und Überlegungen.","pt":"Habilita os agentes a gerar corpos de PR estruturados usando análise de histórico de commits e arquivos alterados, incluindo detalhes técnicos como casos de bordo, notas de configuração e comportamento de quebra, todos formatados em seções padronizadas como Resumo, Por quê, O que mudou e Considerações.","ru":"Позволяет агентам генерировать структурированные тела PR, используя анализ истории коммитов и измененных файлов, включая технические детали, такие как граничные случаи, заметки настройки и поведение при разрыве, все отформатированные в стандартизированные разделы, такие как Сводка, Почему, Что изменилось и Рассмотрения.","ar":"تمكن الوكلاء من توليد أجسام طلبات السحب المنظمة باستخدام تحليل سجل الالتزام وتحليل الملفات المعدلة، بما في ذلك التفاصيل الفنية مثل الحالات الحدودية وملاحظات الإعداد وسلوك الكسر، جميعها مصفوفة في أقسام معيارية مثل ملخص و почему و ماغير و اعتبارات."},"useCases":{"en":["Automating PR body generation for code changes","Extracting intent and scope from commit history","Generating technical bullet points for changed modules and files"],"zh":["代码更改的自动化PR正文生成","从提交历史中提取意图和范围","为更改的模块和文件生成技术性项目符号"],"ja":["コードの変更の自動化されたPR本文の生成","コミット履歴から意図とスコープを抽出","変更されたモジュールとファイルの技術的な項目の生成"],"ko":["코드 변경에 대한 자동화된 PR 본문 생성","커밋 기록에서 의도 및 범위를 추출","변경된 모듈 및 파일에 대한 기술적인 항목 생성"],"es":["Automatización de la generación de cuerpo de PR para cambios de código","Extracción de intención y alcance del historial de commits","Generación de puntos técnicos para módulos y archivos modificados"],"fr":["Automatisation de la génération de corps de PR pour les modifications de code","Extraction de l''intention et de la portée de l''historique des commits","Génération de points techniques pour les modules et les fichiers modifiés"],"de":["Automatisierung der PR-Body-Generierung für Codeänderungen","Extraktion von Intent und Scope aus der Commit-Historie","Generierung von technischen Punkten für geänderte Module und Dateien"],"pt":["Automatizar a geração de corpo de PR para alterações de código","Extrair intenção e escopo do histórico de commits","Gerar pontos técnicos para módulos e arquivos alterados"],"ru":["Автоматизировать генерацию тела PR для изменений кода","Извлекать намерения и объем из истории коммитов","Генерировать технические пункты для измененных модулей и файлов"],"ar":["توليد جسم طلب السحب تلقائيًا لتحديثات الشفرة","استخراج النية والنطاق من سجل الالتزام","توليد النقاط الفنية للأقسام والملفات المعدلة"]},"limitations":{"en":["Requires access to branch changes and commit history","Limited to generating PR bodies in a specific format"],"zh":["需要访问分支更改和提交历史","仅限于生成特定格式的PR正文"],"ja":["ブランチの変更とコミット履歴へのアクセスが必要","特定の形式のPR本文の生成のみ"],"ko":["분기 변경 및 커밋 기록에 대한 액세스가 필요함","특정 형식의 PR 본문 생성만 제한"],"es":["Requiere acceso a los cambios de rama y al historial de commits","Limitado a la generación de cuerpos de PR en un formato específico"],"fr":["Nécessite un accès aux modifications de branche et à l''historique des commits","Limité à la génération de corps de PR dans un format spécifique"],"de":["Erfordert Zugriff auf Änderungen der Zweig und die Commit-Historie","Begrenzt auf die Generierung von PR-Body in einem bestimmten Format"],"pt":["Requer acesso às alterações de branch e histórico de commits","Limitado a gerar corpos de PR em um formato específico"],"ru":["Требует доступа к изменениям ветки и истории коммитов","Ограничен генерацией тел PR в определенном формате"],"ar":["يتطلب الوصول إلى تغييرات الفرع وسجل الالتزام","محدود بتوليد أجسام طلبات السحب في تنسيق محدد"]},"version":4},"contentHash":"94cc27c996da908e787cb4b692e7ff5d1e23804f02504e2ab96c599b624d7875","qualityScore":48}');
