INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('GadCoder/BikeRoutes/pr-creator', 'pr-creator', 'GadCoder', 'BikeRoutes', 'community', 'pr-creator GadCoder BikeRoutes community The pr-creator skill automates PR body generation for developers, extracting intent, scope, and risk from changed files and commit history to create structured PR bodies. PR创建器是一种自动化代码审查的工具，通过分析代码变更和提交历史来生成高质量的PR内容 PR作成ツールは、コードの変更とコミット履歴を分析して、高品質のPR内容を自動生成するツールです PR 생성기는 코드 변경과 커밋 기록을 분석하여 고품질의 PR 내용을 자동 생성하는 도구입니다 pr-creator es una herramienta de AI que automatiza la creación de solicitudes de pull. Inspecciona los cambios en la rama y genera un cuerpo de solicitud de pull con resumen, motivos y consideraciones pr-creator est un outil d''IA qui automatise la création de demandes de pull. Il inspecte les modifications apportées à la branche et génère un corps de demande de pull avec résumé, motifs et considérations pr-creator ist ein AI-Tool, das die Erstellung von Pull-Anfragen automatisiert. Es überprüft die Änderungen im Branch und generiert einen Anfrage-Text mit Zusammenfassung, Gründen und Überlegungen O PR Creator é uma ferramenta que ajuda a criar pull requests personalizados. Ele inspeciona as alterações no branch e extrai informações para criar um corpo de PR estruturado. PR Creator - это инструмент, который помогает создавать индивидуальные запросы на слияние. Он проверяет изменения в ветке и извлекает информацию для создания структурированного тела PR. PR Creator هو أداة تساعد في إنشاء طلبات سحب مخصصة. يقوم بفحص التغييرات في الفرع واستخراج المعلومات لإنشاء جسم طلب سحب منظم how to use pr-creator pr-creator setup guide automated PR body generation pr-creator vs manual PR writing pr-creator install what is pr-creator pr-creator alternative pr-creator workflow automation PR创建器 代码审查自动化 AI工具 代码版本控制 代码审查流程优化 自动化代码审查 PR内容生成 代码变更分析 Extracts intent, scope, and risk from changed files and commit history Generates PR bodies with sections for summary, why, what changed, and considerations Keeps summary to one line by default for clarity Includes technical bullet points with concrete modules/files in what changed section Considers edge cases, setup notes, and breaking behavior in PR body pr-creator is a skill that automates the generation of pull request bodies, following a structured format with sections for summary, why, what changed, and considerations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('joshcirre/larrykonn/developing-with-fortify', 'community', 'joshcirre', 'larrykonn', 'joshcirre/larrykonn', 'developing-with-fortify', 0, 0, 48, '2026-03-08T01:57:15.438Z', '2026-03-08T02:07:39.958Z', 'd7dfca5fad472ae64de40ec550f9ba9606ba34c23129e18f3daabc894e1c7014', '{"id":"joshcirre/larrykonn/developing-with-fortify","name":"developing-with-fortify","description":{"en":"Developing-with-Fortify is a personal assistant and RAG service for Laravel AI SDK, providing authentication routes and controllers. It benefits Laravel developers seeking to implement secure authentication.","zh":"Laravel Fortify是一个头部认证后端，提供认证路由和控制器，用于Laravel应用程序的开发","ja":"Laravel Fortifyはヘッドレス認証バックエンドで、Laravelアプリケーションの認証ルートとコントローラを提供する","ko":"Laravel Fortify는 헤드리스 인증 백엔드로, Laravel 애플리케이션의 인증 路由와 컨트롤러를 제공합니다","es":"Desarrollar con Fortify es una forma eficiente de agregar autenticación a sus aplicaciones Laravel. Ofrece rutas y controladores de autenticación personalizables.","fr":"Développer avec Fortify est un moyen efficace d''ajouter une authentification à vos applications Laravel. Il propose des routes et des contrôleurs d''authentification personnalisables.","de":"Die Entwicklung mit Fortify ist eine effiziente Möglichkeit, Authentifizierung zu Ihren Laravel-Anwendungen hinzuzufügen. Es bietet personalisierbare Authentifizierungsrouten und -controller.","pt":"Fortify é um backend de autenticação headless para aplicações Laravel. Fornece rotas e controllers de autenticação","ru":"Fortify - это бессерверный бэкенд аутентификации для приложений Laravel. Предоставляет маршруты и контроллеры аутентификации","ar":"Fortify هو خلفية بدون رأس للتحقق من تطبيقات Laravel. يوفر مسارات ومراقبة للتحقق"},"seo":{"title":{"en":"Developing-with-Fortify: Laravel Authentication Setup Gui...","zh":"Laravel Fortify开发指南 - AIエージェント集成","ja":"Laravel Fortify開発セットアップガイド - AIエージェント","ko":"Laravel Fortify 개발 가이드 - AI 도구 통합","es":"Guía de configuración de Developing with Fortify para Lar...","fr":"Guide de mise en route de Developing with Fortify pour La...","de":"Einrichtungsleitfaden für Developing with Fortify mit Lar...","pt":"Desenvolvendo com Fortify: Guia de Configuração","ru":"Разработка с Fortify: Руководство по настройке ИИ Агентов","ar":"التطوير مع Fortify: دليل الإعداد للآلات الذكية"},"description":{"en":"Discover how to implement Laravel Fortify for secure authentication. Learn how to use search-docs, list-routes, and customize business logic with our AI agen...","zh":"了解Laravel Fortify的功能和用途，实现头部认证后端，并探索其在AI代理中的应用","ja":"Laravel Fortifyの機能と使い方をマスターし、ヘッドレス認証バックエンドを実現する","ko":"Laravel Fortify의 기능과 사용 방법을 익히고, 헤드리스 인증 백엔드를 구현하여 AI 도구와의 통합을 탐색하십시오","es":"Aprenda a desarrollar con Fortify, un servicio de autenticación headless para Laravel. Descubra cómo configurar y personalizar sus aplicaciones.","fr":"Découvrez comment développer avec Fortify, un service d''authentification headless pour Laravel. Apprenez à configurer et personnaliser vos applications.","de":"Erfahren Sie, wie Sie mit Fortify, einem headless Authentifizierungsdienst für Laravel, entwickeln. Entdecken Sie, wie Sie Ihre Anwendungen konfigurieren und...","pt":"Aprenda a desenvolver aplicações Laravel com Fortify, um backend de autenticação headless. Descubra como configurar rotas e controllers","ru":"Узнайте, как разработать приложения Laravel с помощью Fortify, бессерверного бэкенда аутентификации. Понимайте, как настроить маршруты и контроллеры с ИИ Аге...","ar":"تعرف على كيفية تطوير تطبيقات Laravel مع Fortify، وهو خلفية بدون رأس للتحقق. اكتشف كيفية ضبط المسارات والمراقبة مع الآلات الذكية"},"definition":{"en":"Developing-with-fortify is a headless authentication backend for Laravel applications, offering customizable business logic and authentication routes.","zh":"Laravel Fortify是什么：一个提供认证路由和控制器的头部认证后端","ja":"Laravel Fortifyとは：認証ルートとコントローラを提供するヘッドレス認証バックエンド","ko":"Laravel Fortify는 무엇인가: 인증 路由와 컨트롤러를 제공하는 헤드리스 인증 백엔드","es":"Desarrollar con Fortify es un servicio de autenticación headless para aplicaciones Laravel que proporciona rutas y controladores de autenticación personalizables.","fr":"Développer avec Fortify est un service d''authentification headless pour les applications Laravel qui propose des routes et des contrôleurs d''authentification personnalisables.","de":"Die Entwicklung mit Fortify ist ein headless Authentifizierungsdienst für Laravel-Anwendungen, der personalisierbare Authentifizierungsrouten und -controller bereitstellt.","pt":"Fortify é um backend de autenticação headless para aplicações Laravel","ru":"Fortify - это бессерверный бэкенд аутентификации для приложений Laravel","ar":"Fortify هو خلفية بدون رأس للتحقق من تطبيقات Laravel"},"features":{"en":["Provides authentication routes and controllers for Laravel applications","Allows customization of business logic via app/Actions/Fortify/","Supports searching documentation with search-docs","Lists registered endpoints with list-routes and only_vendor: true","Enables customizable user creation and password validation"],"zh":["提供认证路由和控制器","支持自定义业务逻辑","集成Laravel AI SDK","使用`list-routes`查看注册的端点","检查`app/Actions/Fortify/`中的可定制业务逻辑"],"ja":["認証ルートとコントローラを提供する","カスタムビジネスロジックをサポートする","Laravel AI SDKとの統合","`list-routes`で登録されたエンドポイントを表示する","`app/Actions/Fortify/`内のカスタマイズ可能なビジネスロジックを確認する"],"ko":["인증 路由와 컨트롤러를 제공합니다","사용자 지정 비즈니스 로직을 지원합니다","Laravel AI SDK와의 통합","`list-routes`로 등록된 엔드ポイント를 표시합니다","`app/Actions/Fortify/`의 사용자 지정 가능한 비즈니스 로직을 확인합니다"],"es":["Rutas de autenticación personalizables con Laravel","Controladores de autenticación configurable","Lógica de negocio personalizable para la creación de usuarios y la validación de contraseñas","Uso de `search-docs` para obtener documentación detallada","Uso de `list-routes` para ver los puntos de conexión registrados"],"fr":["Routes d''authentification personnalisables avec Laravel","Contrôleurs d''authentification configurable","Logique métier personnalisable pour la création d''utilisateurs et la validation des mots de passe","Utilisation de `search-docs` pour obtenir une documentation détaillée","Utilisation de `list-routes` pour voir les points de connexion enregistrés"],"de":["Personalisierbare Authentifizierungsrouten mit Laravel","Konfigurierbare Authentifizierungscontroller","Personalisierbare Geschäftslogik für die Benutzererstellung und die Passwortvalidierung","Verwendung von `search-docs` für detaillierte Dokumentation","Verwendung von `list-routes` für die Anzeige der registrierten Endpunkte"],"pt":["Rotas de autenticação personalizáveis","Controllers de autenticação headless","Lógica de negócios personalizável com Actions","Integração com Laravel AI SDK"],"ru":["Настраиваемые маршруты аутентификации","Бессерверные контроллеры аутентификации","Пользовательская логика бизнеса с Actions","Интеграция с Laravel AI SDK и ИИ Агентами"],"ar":["مسارات التحقق القابلة للتعديل","مراقبة التحقق بدون رأس","منطق العمل القابل للتعديل مع الإجراءات","التكامل مع Laravel AI SDK و الآلات الذكية"]},"keywords":{"en":["how to use developing-with-fortify","laravel fortify authentication","developing-with-fortify alternative","developing-with-fortify vs laravel sanctum","developing-with-fortify install","developing-with-fortify setup guide","laravel ai sdk authentication","customizable business logic laravel","headless authentication backend laravel"],"zh":["Laravel Fortify","头部认证后端","AI代理","Laravel AI SDK","认证路由","控制器","自定义业务逻辑","list-routes","app/Actions/Fortify/"],"ja":["Laravel Fortify","ヘッドレス認証バックエンド","AIエージェント","Laravel AI SDK","認証ルート","コントローラ","カスタムビジネスロジック","list-routes","app/Actions/Fortify/"],"ko":["Laravel Fortify","헤드리스 인증 백엔드","AI 도구","Laravel AI SDK","인증 路由","컨트롤러","사용자 지정 비즈니스 로직","list-routes","app/Actions/Fortify/"],"es":["desarrollar con Fortify","autenticación headless Laravel","rutas de autenticación personalizables","controladores de autenticación configurable","Laravel AI SDK","desarrollo de aplicaciones Laravel","autenticación en aplicaciones web","seguridad en aplicaciones Laravel","Fortify Laravel"],"fr":["développer avec Fortify","authentification headless Laravel","routes d''authentification personnalisables","contrôleurs d''authentification configurable","Laravel AI SDK","développement d''applications Laravel","authentification dans les applications web","sécurité dans les applications Laravel","Fortify Laravel"],"de":["Entwicklung mit Fortify","headless Authentifizierung Laravel","personalisierbare Authentifizierungsrouten","konfigurierbare Authentifizierungscontroller","Laravel AI SDK","Entwicklung von Laravel-Anwendungen","Authentifizierung in Webanwendungen","Sicherheit in Laravel-Anwendungen","Fortify Laravel"],"pt":["desenvolvimento com Fortify","Laravel Fortify","autenticação headless","rotas de autenticação","controllers de autenticação","Laravel AI SDK"],"ru":["разработка с Fortify","Laravel Fortify","бессерверная аутентификация","маршруты аутентификации","контроллеры аутентификации","Laravel AI SDK и ИИ Агенты"],"ar":["تطوير مع Fortify","Laravel Fortify","التحقق بدون رأس","مسارات التحقق","مراقبة التحقق","Laravel AI SDK و الآلات الذكية"]}},"owner":"joshcirre","repo":"larrykonn","repoPath":"joshcirre/larrykonn","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.438Z","topics":[],"category":"community","skillMd":{"name":"developing-with-fortify","description":"Laravel Fortify headless authentication backend development. Activate when implementing authentication features including login, registration, password reset, email verification, two-factor authentication (2FA/TOTP), profile updates, headless auth, authentication scaffolding, or auth guards in Laravel applications.","bodyPreview":"# Laravel Fortify Development\n\nFortify is a headless authentication backend that provides authentication routes and controllers for Laravel applications.\n\n## Documentation\n\nUse `search-docs` for detailed Laravel Fortify patterns and documentation.\n\n## Usage\n\n- **Routes**: Use `list-routes` with `only_vendor: true` and `action: \"Fortify\"` to see all registered endpoints\n- **Actions**: Check `app/Actions/Fortify/` for customizable business logic (user creation, password validation, etc.)\n- **Confi","body":"# Laravel Fortify Development\n\nFortify is a headless authentication backend that provides authentication routes and controllers for Laravel applications.\n\n## Documentation\n\nUse `search-docs` for detailed Laravel Fortify patterns and documentation.\n\n## Usage\n\n- **Routes**: Use `list-routes` with `only_vendor: true` and `action: \"Fortify\"` to see all registered endpoints\n- **Actions**: Check `app/Actions/Fortify/` for customizable business logic (user creation, password validation, etc.)\n- **Config**: See `config/fortify.php` for all options including features, guards, rate limiters, and username field\n- **Contracts**: Look in `Laravel\\Fortify\\Contracts\\` for overridable response classes (`LoginResponse`, `LogoutResponse`, etc.)\n- **Views**: All view callbacks are set in `FortifyServiceProvider::boot()` using `Fortify::loginView()`, `Fortify::registerView()`, etc.\n\n## Available Features\n\nEnable in `config/fortify.php` features array:\n\n- `Features::registration()` - User registration\n- `Features::resetPasswords()` - Password reset via email\n- `Features::emailVerification()` - Requires User to implement `MustVerifyEmail`\n- `Features::updateProfileInformation()` - Profile updates\n- `Features::updatePasswords()` - Password changes\n- `Features::twoFactorAuthentication()` - 2FA with QR codes and recovery codes\n\n> Use `search-docs` for feature configuration options and customization patterns.\n\n## Setup Workflows\n\n### Two-Factor Authentication Setup\n\n```\n- [ ] Add TwoFactorAuthenticatable trait to User model\n- [ ] Enable feature in config/fortify.php\n- [ ] Run migrations for 2FA columns\n- [ ] Set up view callbacks in FortifyServiceProvider\n- [ ] Create 2FA management UI\n- [ ] Test QR code and recovery codes\n```\n\n> Use `search-docs` for TOTP implementation and recovery code handling patterns.\n\n### Email Verification Setup\n\n```\n- [ ] Enable emailVerification feature in config\n- [ ] Implement MustVerifyEmail interface on User model\n- [ ] Set up verifyEmailView callback\n- [ ] Add verified middleware to protected routes\n- [ ] Test verification email flow\n```\n\n> Use `search-docs` for MustVerifyEmail implementation patterns.\n\n### Password Reset Setup\n\n```\n- [ ] Enable resetPasswords feature in config\n- [ ] Set up requestPasswordResetLinkView callback\n- [ ] Set up resetPasswordView callback\n- [ ] Define password.reset named route (if views disabled)\n- [ ] Test reset email and link flow\n```\n\n> Use `search-docs` for custom password reset flow patterns.\n\n### SPA Authentication Setup\n\n```\n- [ ] Set ''views'' => false in config/fortify.php\n- [ ] Install and configure Laravel Sanctum\n- [ ] Use ''web'' guard in fortify config\n- [ ] Set up CSRF token handling\n- [ ] Test XHR authentication flows\n```\n\n> Use `search-docs` for integration and SPA authentication patterns.\n\n## Best Practices\n\n### Custom Authentication Logic\n\nOverride authentication behavior using `Fortify::authenticateUsing()` for custom user retrieval or `Fortify::authenticateThrough()` to customize the authentication pipeline. Override response contracts in `AppServiceProvider` for custom redirects.\n\n### Registration Customization\n\nModify `app/Actions/Fortify/CreateNewUser.php` to customize user creation logic, validation rules, and additional fields.\n\n### Rate Limiting\n\nConfigure via `fortify.limiters.login` in config. Default configuration throttles by username + IP combination.\n\n## Key Endpoints\n\n| Feature                | Method   | Endpoint                                    |\n|------------------------|----------|---------------------------------------------|\n| Login                  | POST     | `/login`                                    |\n| Logout                 | POST     | `/logout`                                   |\n| Register               | POST     | `/register`                                 |\n| Password Reset Request | POST     | `/forgot-password`                          |\n| Password Reset         | POST     | `/reset-password`                           |\n| Email Verify Notice    | GET      | `/email/verify`                             |\n| Resend Verification    | POST     | `/email/verification-notification`          |\n| Password Confirm       | POST     | `/user/confirm-password`                    |\n| Enable 2FA             | POST     | `/user/two-factor-authentication`           |\n| Confirm 2FA            | POST     | `/user/confirmed-two-factor-authentication` |\n| 2FA Challenge          | POST     | `/two-factor-challenge`                     |\n| Get QR Code            | GET      | `/user/two-factor-qr-code`                  |\n| Recovery Codes         | GET/POST | `/user/two-factor-recovery-codes`           |"},"lastSynced":"2026-03-08T02:07:39.958Z","agentAnalysis":{"suitability":{"en":"Ideal for Laravel-focused AI Agents seeking to implement secure authentication mechanisms using Fortify","zh":"适用于关注Laravel的AI代理，寻求使用Fortify实现安全的身份验证机制","ja":"Laravelに焦点を当てたAIエージェントがFortifyを使用して安全な認証メカニズムを実装するのに適しています","ko":"Laravel에 중점을 둔 AI 에이전트가 Fortify를 사용하여 안전한 인증 메커니즘을 구현하기에 적합합니다","es":"Ideal para agentes de IA centrados en Laravel que buscan implementar mecanismos de autenticación seguros utilizando Fortify","fr":"Idéal pour les agents d''IA axés sur Laravel qui cherchent à mettre en œuvre des mécanismes d''authentification sécurisés à l''aide de Fortify","de":"Ideal für Laravel-fokussierte KI-Agents, die sichere Authentifizierungsmechanismen mit Fortify implementieren möchten","pt":"Ideal para Agentes de IA focados em Laravel que buscam implementar mecanismos de autenticação seguros usando Fortify","ru":"Идеально для агентов ИИ, ориентированных на Laravel, которые стремятся реализовать безопасные механизмы аутентификации с помощью Fortify","ar":"مثالي لعميل الذكاء الاصطناعي المُركّز على Laravel الذين يسعون إلى تنفيذ آليّات التحقق من الصلاحية الآمنة باستخدام Fortify"},"recommendation":{"en":"Empowers agents to leverage Laravel Fortify''s headless authentication backend, providing customizable authentication routes and controllers, and utilizing Laravel AI SDK for enhanced security features, including authentication routes and controllers","zh":"赋予代理使用Laravel Fortify的无头认证后端的能力，提供可自定义的认证路由和控制器，并利用Laravel AI SDK实现增强的安全功能，包括认证路由和控制器","ja":"Laravel Fortifyのヘッドレス認証バックエンドを利用できるようにエージェントをEmpowerし、カスタマイズ可能な認証ルートとコントローラーを提供し、認証ルートとコントローラーを含む強化されたセキュリティ機能のためにLaravel AI SDKを利用する","ko":"에이전트가 Laravel Fortify의 헤드리스 인증 백엔드를 활용할 수 있도록 하여, 사용자 지정 가능한 인증 경로와 컨트롤러를 제공하고, 인증 경로 및 컨트롤러를 포함한 보안 기능을 강화하기 위해 Laravel AI SDK를 활용한다","es":"Habilita a los agentes a aprovechar el backend de autenticación headless de Laravel Fortify, proporcionando rutas y controladores de autenticación personalizables, y utilizando el SDK de AI de Laravel para funciones de seguridad mejoradas, incluyendo rutas y controladores de autenticación","fr":"Permet aux agents d''utiliser le backend d''authentification headless de Laravel Fortify, offrant des routes et des contrôleurs d''authentification personnalisables, et utilisant le SDK d''AI de Laravel pour des fonctionnalités de sécurité améliorées, notamment des routes et des contrôleurs d''authentification","de":"Ermächtigt Agents, den headless-Authentifizierungs-Backend von Laravel Fortify zu nutzen, wodurch benutzerdefinierte Authentifizierungs-Routen und -Controller bereitgestellt werden und das Laravel AI SDK für verbesserte Sicherheitsfunktionen verwendet wird, einschließlich Authentifizierungs-Routen und -Controllern","pt":"Habilita os agentes a aproveitar o backend de autenticação headless do Laravel Fortify, fornecendo rotas e controladores de autenticação personalizáveis e utilizando o SDK de IA do Laravel para recursos de segurança aprimorados, incluindo rotas e controladores de autenticação","ru":"Наделяет агентов возможностью использовать безголовый бэкенд аутентификации Laravel Fortify, предоставляя настраиваемые маршруты и контроллеры аутентификации, и использует SDK ИИ Laravel для расширенных функций безопасности, включая маршруты и контроллеры аутентификации","ar":"تمكّن الوكيل من استخدام خلفية التحقق من الصلاحية بدون رأس لشركة Laravel Fortify، وتوفير مسارات ومراقبة التحقق من الصلاحية التي يمكن تعديلها، واستخدام SDK الذكاء الاصطناعي من Laravel لميزات أمان محسّنة، بما في ذلك مسارات ومراقبة التحقق من الصلاحية"},"useCases":{"en":["Customizing user creation and password validation logic","Implementing secure authentication routes for Laravel applications","Utilizing Fortify''s authentication backend for enhanced security"],"zh":["自定义用户创建和密码验证逻辑","为Laravel应用程序实现安全的认证路由","利用Fortify的认证后端实现增强的安全性"],"ja":["ユーザー作成とパスワード検証ロジックのカスタマイズ","Laravelアプリケーションのための安全な認証ルートの実装","Fortifyの認証バックエンドを使用した強化されたセキュリティの実現"],"ko":["사용자 생성 및 비밀번호 유효성 검사 논리를 사용자 지정하는 것","Laravel 애플리케이션에 대한 보안 인증 경로 구현","Fortify의 인증 백엔드를 사용한 보안 강화"],"es":["Personalizar la lógica de creación de usuarios y validación de contraseñas","Implementar rutas de autenticación seguras para aplicaciones Laravel","Utilizar el backend de autenticación de Fortify para una mayor seguridad"],"fr":["Personnaliser la logique de création d''utilisateurs et de validation de mots de passe","Mettre en œuvre des routes d''authentification sécurisées pour les applications Laravel","Utiliser le backend d''authentification de Fortify pour une sécurité améliorée"],"de":["Benutzerdefinierte Logik für die Erstellung von Benutzern und die Validierung von Passwörtern","Implementierung sicherer Authentifizierungs-Routen für Laravel-Anwendungen","Verwendung des Authentifizierungs-Backends von Fortify für verbesserte Sicherheit"],"pt":["Personalizar a lógica de criação de usuário e validação de senha","Implementar rotas de autenticação seguras para aplicações Laravel","Utilizar o backend de autenticação do Fortify para segurança aprimorada"],"ru":["Настроить логику создания пользователя и проверки пароля","Реализовать безопасные маршруты аутентификации для приложений Laravel","Использовать бэкенд аутентификации Fortify для повышения безопасности"],"ar":["تخصيص منطق إنشاء المستخدم وتحقق من كلمة المرور","تنفيذ مسارات التحقق من الصلاحية الآمنة لتطبيقات Laravel","استخدام خلفية التحقق من الصلاحية من Fortify لتعزيز الأمان"]},"limitations":{"en":["Requires Laravel AI SDK integration","Limited to Laravel applications","Needs access to app/Actions/Fortify/ directory for customization"],"zh":["需要Laravel AI SDK集成","仅限于Laravel应用程序","需要访问app/Actions/Fortify/目录以进行自定义"],"ja":["Laravel AI SDKの統合が必要","Laravelアプリケーションに限定される","カスタマイズのためにapp/Actions/Fortify/ディレクトリへのアクセスが必要"],"ko":["Laravel AI SDK 통합이 필요하다","Laravel 애플리케이션에만 제한된다","사용자 지정하기 위해 app/Actions/Fortify/ 디렉토리에 액세스해야 한다"],"es":["Requiere la integración del SDK de AI de Laravel","Limitado a aplicaciones Laravel","Necesita acceso al directorio app/Actions/Fortify/ para la personalización"],"fr":["Nécessite l''intégration du SDK d''AI de Laravel","Limité aux applications Laravel","Nécessite un accès au répertoire app/Actions/Fortify/ pour la personnalisation"],"de":["Erfordert die Integration des Laravel AI SDK","Begrenzt auf Laravel-Anwendungen","Benötigt Zugriff auf das Verzeichnis app/Actions/Fortify/ für die Anpassung"],"pt":["Exige integração com SDK de IA do Laravel","Limitado a aplicações Laravel","Necessita acesso ao diretório app/Actions/Fortify/ para personalização"],"ru":["Требует интеграции с SDK ИИ Laravel","Ограничен для приложений Laravel","Требует доступа к каталогу app/Actions/Fortify/ для настройки"],"ar":["يتطلب تكاملًا مع SDK الذكاء الاصطناعي من Laravel","محدود لتطبيقات Laravel","يحتاج إلى الوصول إلى الدليل app/Actions/Fortify/ للتخصيص"]},"version":4},"contentHash":"d7dfca5fad472ae64de40ec550f9ba9606ba34c23129e18f3daabc894e1c7014","qualityScore":48}');
