INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('joshcirre/larrykonn/developing-with-fortify', 'developing-with-fortify', 'joshcirre', 'larrykonn', 'community', 'developing-with-fortify joshcirre larrykonn community Developing-with-Fortify is a personal assistant and RAG service for Laravel AI SDK, providing authentication routes and controllers. It benefits Laravel developers seeking to implement secure authentication. Laravel Fortify是一个头部认证后端，提供认证路由和控制器，用于Laravel应用程序的开发 Laravel Fortifyはヘッドレス認証バックエンドで、Laravelアプリケーションの認証ルートとコントローラを提供する Laravel Fortify는 헤드리스 인증 백엔드로, Laravel 애플리케이션의 인증 路由와 컨트롤러를 제공합니다 Desarrollar con Fortify es una forma eficiente de agregar autenticación a sus aplicaciones Laravel. Ofrece rutas y controladores de autenticación personalizables. Développer avec Fortify est un moyen efficace d''ajouter une authentification à vos applications Laravel. Il propose des routes et des contrôleurs d''authentification personnalisables. Die Entwicklung mit Fortify ist eine effiziente Möglichkeit, Authentifizierung zu Ihren Laravel-Anwendungen hinzuzufügen. Es bietet personalisierbare Authentifizierungsrouten und -controller. Fortify é um backend de autenticação headless para aplicações Laravel. Fornece rotas e controllers de autenticação Fortify - это бессерверный бэкенд аутентификации для приложений Laravel. Предоставляет маршруты и контроллеры аутентификации Fortify هو خلفية بدون رأس للتحقق من تطبيقات Laravel. يوفر مسارات ومراقبة للتحقق how to use developing-with-fortify laravel fortify authentication developing-with-fortify alternative developing-with-fortify vs laravel sanctum developing-with-fortify install developing-with-fortify setup guide laravel ai sdk authentication customizable business logic laravel headless authentication backend laravel Laravel Fortify 头部认证后端 AI代理 Laravel AI SDK 认证路由 控制器 自定义业务逻辑 list-routes app/Actions/Fortify/ Provides authentication routes and controllers for Laravel applications Allows customization of business logic via app/Actions/Fortify/ Supports searching documentation with search-docs Lists registered endpoints with list-routes and only_vendor: true Enables customizable user creation and password validation Developing-with-fortify is a headless authentication backend for Laravel applications, offering customizable business logic and authentication routes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('calimero-network/core/core-pr-helper', 'community', 'calimero-network', 'core', 'calimero-network/core', 'core-pr-helper', 0, 0, 48, '2026-03-08T01:57:15.441Z', '2026-03-08T02:07:44.652Z', '7624184ec25ab20e931202285fddf6946698721939f655287e52a07453fb9379', '{"id":"calimero-network/core/core-pr-helper","name":"core-pr-helper","description":{"en":"The core-pr-helper skill generates branch names and PR descriptions based on conversation context, following a specific format. It benefits developers by automating repetitive tasks and ensuring consistency in their repositories.","zh":"Core PR Helper 是一种自动化 Git 分支和 PR 描述的工具，支持infer change、输出branch name和PR body","ja":"Core PR Helper は、Git ブランチと PR 説明の自動化を支援するツールです。infer change、branch name、PR bodyの出力をサポートしています","ko":"Core PR Helper는 Git 브랜치와 PR 설명의 자동화를 지원하는 툴입니다. infer change, branch name, PR body의 출력을 지원합니다","es":"core-pr-helper es una herramienta que ayuda a crear solicitudes de extracción con nombres de ramas y descripciones personalizadas según el tipo de cambio y el alcance del proyecto","fr":"core-pr-helper est un outil qui aide à créer des demandes d''extraction de code avec des noms de branches et des descriptions personnalisées en fonction du type de modification et de la portée du projet","de":"core-pr-helper ist ein Tool, das dabei hilft, Pull-Requests mit benutzerdefinierten Branch-Namen und Beschreibungen zu erstellen, basierend auf dem Änderungstyp und dem Projektumfang","pt":"O core-pr-helper é uma ferramenta que ajuda a criar nomes de branch e descrições de PR consistentes, seguindo um padrão específico","ru":"ИИ Агент core-pr-helper помогает создавать последовательные имена веток и описания PR, следуя определенному шаблону","ar":"أداة مساعدة لإنشاء طلبات السحب core-pr-helper تساعد في إنشاء أسماء الفروع ووصف طلبات السحب بشكل متسق، متبعة نمطا محددا"}