INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('calimero-network/core/core-pr-helper', 'core-pr-helper', 'calimero-network', 'core', 'community', 'core-pr-helper calimero-network core community The core-pr-helper skill generates branch names and PR descriptions based on conversation context, following a specific format. It benefits developers by automating repetitive tasks and ensuring consistency in their repositories. Core PR Helper 是一种自动化 Git 分支和 PR 描述的工具，支持infer change、输出branch name和PR body Core PR Helper は、Git ブランチと PR 説明の自動化を支援するツールです。infer change、branch name、PR bodyの出力をサポートしています Core PR Helper는 Git 브랜치와 PR 설명의 자동화를 지원하는 툴입니다. infer change, branch name, PR body의 출력을 지원합니다 core-pr-helper es una herramienta que ayuda a crear solicitudes de extracción con nombres de ramas y descripciones personalizadas según el tipo de cambio y el alcance del proyecto core-pr-helper est un outil qui aide à créer des demandes d''extraction de code avec des noms de branches et des descriptions personnalisées en fonction du type de modification et de la portée du projet core-pr-helper ist ein Tool, das dabei hilft, Pull-Requests mit benutzerdefinierten Branch-Namen und Beschreibungen zu erstellen, basierend auf dem Änderungstyp und dem Projektumfang O core-pr-helper é uma ferramenta que ajuda a criar nomes de branch e descrições de PR consistentes, seguindo um padrão específico ИИ Агент core-pr-helper помогает создавать последовательные имена веток и описания PR, следуя определенному шаблону أداة مساعدة لإنشاء طلبات السحب core-pr-helper تساعد في إنشاء أسماء الفروع ووصف طلبات السحب بشكل متسق، متبعة نمطا محددا how to use core-pr-helper core-pr-helper setup guide automated branch naming PR description generation core-pr-helper vs manual naming what is core-pr-helper core-pr-helper install standardized repository formatting Core PR Helper AI 工具 Git 分支 PR 描述 infer change branch name PR body 自动化开发工具 Generates branch names in lowercase with hyphens, following the {type}-{scope}-{short-summary} pattern Outputs PR descriptions in a standardized format Infer changes from conversation context, including recent edits and stated scope Supports multiple types, including feat, fix, docs, and more Ensures consistency in repository naming conventions core-pr-helper is a skill that automates the generation of branch names and PR descriptions, using a standardized format of {type}-{scope}-{short-summary} to ensure consistency and readability in code repositories.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hexianWeb/Third-Person-MC/vtj-debug-panel', 'community', 'hexianWeb', 'Third-Person-MC', 'hexianWeb/Third-Person-MC', 'vtj-debug-panel', 0, 0, 48, '2026-03-08T01:57:15.443Z', '2026-03-08T02:08:43.095Z', 'dfa7c6040c8b8d02659e509cfe4ad487c9c69d78dff1f2f4a7d8bba11c2f9e87', '{"id":"hexianWeb/Third-Person-MC/vtj-debug-panel","name":"vtj-debug-panel","description":{"en":"The vtj-debug-panel skill enables developers to create real-time parameter adjustment panels using Tweakpane, simplifying the debugging process for AI agents. It benefits developers working with Vite and Three.js.","zh":"vtj-debug-panel是一个使用Tweakpane创建实时参数调整面板的工具，支持颜色和分组等功能。","ja":"vtj-debug-panelはTweakpaneを使用してリアルタイムパラメータ調整パネルを作成するツールです。色やグループなどの機能をサポートしています。","ko":"vtj-debug-panel은 Tweakpane을 사용하여 실시간 매개 변수 조정 패널을 생성하는 도구입니다. 색상 및 그룹 등과 같은 기능을 지원합니다.","es":"El panel de depuración vtj-debug-panel permite ajustar parámetros en tiempo real con Tweakpane. Activa el panel mediante el hash de URL #debug.","fr":"Le panneau de débogage vtj-debug-panel permet d''ajuster les paramètres en temps réel avec Tweakpane. Activez le panneau via le hash d''URL #debug.","de":"Das Debugging-Panel vtj-debug-panel ermöglicht Echtzeit-Parameteranpassungen mit Tweakpane. Aktivieren Sie das Panel über den URL-Hash #debug.","pt":"O vtj-debug-panel é uma ferramenta de depuração que permite ajustar parâmetros em tempo real com Tweakpane. Saiba mais sobre como configurá-lo","ru":"Втj-debug-panel - это инструмент отладки, который позволяет регулировать параметры в режиме реального времени с помощью Tweakpane. Узнайте больше о его настройке","ar":"لوحة调试 vtj هي أداة فحص تسمح بتعديل المعلمات في الوقت الفعلي باستخدام Tweakpane. تعرف على المزيد حول إعدادها"},"seo":{"title":{"en":"vtj-debug-panel: Real-Time Debugging Setup Guide | AI Age...","zh":"vtj-debug-panel 调试面板设置指南","ja":"vtj-debug-panel デバッグパネルのベストプラクティス","ko":"vtj-debug-panel 디버그 패널 구축 가이드","es":"vtj-debug-panel: Guía de Configuración para Paneles de De...","fr":"vtj-debug-panel: Guide de Configuration pour les Paneaux ...","de":"vtj-debug-panel: Einrichtungsleitfaden für Echtzeit-Debug...","pt":"Guia de Configuração do vtj-debug-panel para Desenvolvedores","ru":"Настройка vtj-debug-panel: Руководство по ИИ Агентам","ar":"إعداد لوحة调试 vtj для معماريي التطبيقات"},"description":{"en":"Unlock efficient debugging with vtj-debug-panel. Discover how to create real-time parameter adjustment panels using Tweakpane and activate via #debug URL hash.","zh":"了解vtj-debug-panel的功能和特点，掌握调试面板的设置和使用方法，AIエージェント","ja":"vtj-debug-panelの機能と特徴を紹介します。デバッグパネルの設定と使用方法をマスターしてください。AIエージェント","ko":"vtj-debug-panel의 기능과 특징을 살펴보고 디버그 패널의 설정과 사용 방법을 익히세요. AI Tools","es":"Aprende a configurar el panel de depuración vtj-debug-panel para ajustar parámetros en tiempo real con Tweakpane","fr":"Découvrez comment configurer le panneau de débogage vtj-debug-panel pour ajuster les paramètres en temps réel avec Tweakpane","de":"Erfahren Sie, wie Sie das Debugging-Panel vtj-debug-panel für Echtzeit-Parameteranpassungen mit Tweakpane einrichten","pt":"Aprenda a configurar o vtj-debug-panel para ajustar parâmetros em tempo real com Tweakpane e maximize a experiência do usuário","ru":"Узнайте, как настроить vtj-debug-panel для регулирования параметров в режиме реального времени с помощью Tweakpane и ИИ Агентов","ar":"اكتشف كيفية إعداد لوحة调试 vtj لتعديل المعلمات في الوقت الفعلي باستخدام Tweakpane ووسائل الإعلام التفاعلية"},"definition":{"en":"vtj-debug-panel is a debugging tool that creates real-time parameter adjustment panels using Tweakpane, activated via #debug URL hash, for efficient debugging of AI agents.","zh":"vtj-debug-panel是一种使用Tweakpane的调试面板工具，允许实时调整参数","ja":"vtj-debug-panelはTweakpaneを使用したデバッグパネルのツールで、リアルタイムパラメータ調整を可能にします","ko":"vtj-debug-panel은 Tweakpane을 사용하는 디버그 패널 도구로 실시간 매개 변수 조정을 허용합니다","es":"El vtj-debug-panel es un panel de depuración que utiliza Tweakpane para ajustar parámetros en tiempo real","fr":"Le vtj-debug-panel est un panneau de débogage qui utilise Tweakpane pour ajuster les paramètres en temps réel","de":"Das vtj-debug-panel ist ein Debugging-Panel, das Tweakpane zur Echtzeit-Parameteranpassung verwendet","pt":"O vtj-debug-panel é uma ferramenta de depuração que cria painéis de ajuste de parâmetros em tempo real","ru":"Втj-debug-panel - это инструмент отладки, который создает панели регулирования параметров в режиме реального времени","ar":"لوحة调试 vtj هي أداة فحص تعمل على إنشاء لوحات تحكم بمعلمات الوقت الفعلي"},"features":{"en":["Creates real-time parameter adjustment panels using Tweakpane","Activates via #debug URL hash for efficient debugging","Groups panels hierarchically up to 3 levels for organized debugging","Utilizes view: ''color'' for color parameter tuning","Integrates with Vite for seamless development experience"],"zh":["支持实时参数调整","使用Tweakpane创建调试面板","支持颜色和分组等功能","最大3级分组","支持view: ''color''颜色选择"],"ja":["リアルタイムパラメータ調整をサポート","Tweakpaneを使用してデバッグパネルを作成","色やグループなどの機能をサポート","最大3レベルグループ","view: ''color''色選択をサポート"],"ko":["실시간 매개 변수 조정을 지원","Tweakpane을 사용하여 디버그 패널을 생성","색상 및 그룹 등과 같은 기능을 지원","최대 3레벨 그룹","view: ''color'' 색상 선택을 지원"],"es":["Ajuste de parámetros en tiempo real con Tweakpane","Activación del panel mediante el hash de URL #debug","Uso de controles para cada parámetro ajustable","Agrupación jerárquica de paneles (hasta 3 niveles)","Compatibilidad con colores mediante ''view: ''color''''"],"fr":["Ajustement des paramètres en temps réel avec Tweakpane","Activation du panneau via le hash d''URL #debug","Utilisation de contrôles pour chaque paramètre ajustable","Regroupement hiérarchique des panneaux (jusqu''à 3 niveaux)","Compatibilité avec les couleurs via ''view: ''color''''"],"de":["Echtzeit-Parameteranpassung mit Tweakpane","Aktivierung des Panels über den URL-Hash #debug","Verwendung von Kontrollen für jedes anpassbare Parameter","Hierarchische Gruppierung von Panels (bis zu 3 Ebenen)","Kompatibilität mit Farben über ''view: ''color''''"],"pt":["Cria painéis de ajuste de parâmetros em tempo real com Tweakpane","Permite a ativação via URL hash #debug","Utiliza controles hierárquicos com no máximo 3 níveis","Suporta cores com ''view: color''","Fornece uma experiência de depuração personalizada"],"ru":["Создает панели регулирования параметров в режиме реального времени с помощью Tweakpane","Позволяет активировать через URL-хэш #debug","Использует иерархические контролы с максимум 3 уровнями","Поддерживает цвета с ''view: color''","Предоставляет настраиваемый опыт отладки"],"ar":["إنشاء لوحات تحكم بمعلمات الوقت الفعلي مع Tweakpane","التنشيط عبر الهاش URL #debug","استخدام التحكم الهرمي بأقصى 3 مستويات","دعم الألوان مع ''view: color''","توفير تجربة فحص مخصصة"]},"keywords":{"en":["how to use vtj-debug-panel","vtj-debug-panel setup guide","vtj-debug-panel alternative","vtj-debug-panel vs Tweakpane","vtj-debug-panel install","what is vtj-debug-panel","vtj-debug-panel tutorial","vtj-debug-panel for AI agents","vtj-debug-panel and Vite integration"],"zh":["vtj-debug-panel","Tweakpane","调试面板","实时参数调整","AIエージェント","JavaScript调试","前端开发工具"],"ja":["vtj-debug-panel","Tweakpane","デバッグパネル","リアルタイムパラメータ調整","AIエージェント","JavaScriptデバッグ","フロントエンド開発ツール"],"ko":["vtj-debug-panel","Tweakpane","디버그 패널","실시간 매개 변수 조정","AI Tools","JavaScript 디버깅","프론트엔드 개발 도구"],"es":["vtj-debug-panel","Tweakpane","depuración en tiempo real","ajuste de parámetros","paneles de depuración","herramientas de desarrollo","IA herramientas","Agentes de IA"],"fr":["vtj-debug-panel","Tweakpane","débogage en temps réel","ajustement de paramètres","panneaux de débogage","outils de développement","outils d''IA","Agents d''IA"],"de":["vtj-debug-panel","Tweakpane","Echtzeit-Debugging","Parameteranpassung","Debugging-Panel","Entwickler-Tools","KI-Tools","KI-Agenten"],"pt":["vtj-debug-panel","Tweakpane","depuração em tempo real","painéis de ajuste de parâmetros","URL hash #debug","controles hierárquicos","cores com view: color","experiência de depuração personalizada","ferramentas de desenvolvimento"],"ru":["Втj-debug-panel","Tweakpane","отладка в режиме реального времени","панели регулирования параметров","URL-хэш #debug","иерархические контролы","цвета с view: color","настраиваемый опыт отладки","инструменты разработки","ИИ Агенты"],"ar":["لوحة调试 vtj","Tweakpane","فحص الوقت الفعلي","لوحات تحكم بمعلمات","التنشيط عبر الهاش URL #debug","التحكم الهرمي","الألوان مع view: color","تجربة فحص مخصصة","أدوات التطوير","وسائل الإعلام التفاعلية"]}},"owner":"hexianWeb","repo":"Third-Person-MC","repoPath":"hexianWeb/Third-Person-MC","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.443Z","topics":[],"category":"community","skillMd":{"name":"vtj-debug-panel","description":"Configures Tweakpane debug panels for 3D components. Use when adding debug controls, monitoring component state, or adjusting parameters in real-time via the #debug interface.","bodyPreview":"# vite-threejs Debug Panel (Tweakpane)\n\n## Overview\n\nCreates real-time parameter adjustment panels using Tweakpane. Activated via `#debug` URL hash.\n\n**Core principles:**\n- Every tunable parameter gets a control\n- Colors must use `view: ''color''`\n- Group panels hierarchically (max 3 levels)\n\n## Quick Start\n\n```javascript\nconstructor() {\n  this.experience = new Experience()\n  this.debug = this.experience.debug\n  \n  this.params = { intensity: 1.0, color: ''#ffffff'' }\n  \n  if (this.debug.active) {","body":"# vite-threejs Debug Panel (Tweakpane)\n\n## Overview\n\nCreates real-time parameter adjustment panels using Tweakpane. Activated via `#debug` URL hash.\n\n**Core principles:**\n- Every tunable parameter gets a control\n- Colors must use `view: ''color''`\n- Group panels hierarchically (max 3 levels)\n\n## Quick Start\n\n```javascript\nconstructor() {\n  this.experience = new Experience()\n  this.debug = this.experience.debug\n  \n  this.params = { intensity: 1.0, color: ''#ffffff'' }\n  \n  if (this.debug.active) {\n    this.debugInit()\n  }\n}\n\ndebugInit() {\n  this.debugFolder = this.debug.ui.addFolder({\n    title: ''Component Name'',\n    expanded: false,\n  })\n  \n  this.debugFolder.addBinding(this.params, ''intensity'', {\n    min: 0, max: 10, step: 0.1,\n  })\n}\n```\n\n## When to Use\n\n- Creating new 3D components\n- Adding ShaderMaterial uniform controls\n- Monitoring runtime state\n- Adding action buttons\n\n## Control Types\n\n| Type | Key Config |\n|------|------------|\n| Number | `min`, `max`, `step` |\n| Color | `view: ''color''` (required) |\n| 3D Point | `view: ''point3d''` |\n| Boolean | No extra config |\n| Select | `options: { label: value }` |\n| Button | `addButton({ title })` |\n\n**Detailed examples:** See [references/controls.md](references/controls.md)\n\n## ShaderMaterial Integration\n\nAll ShaderMaterial uniforms must have debug controls:\n\n```javascript\nfolder.addBinding(this.params, ''color'', { view: ''color'' })\n  .on(''change'', (ev) => {\n    this.material.uniforms.uColor.value.set(ev.value)\n  })\n```\n\n**Full patterns:** See [references/shader-debug.md](references/shader-debug.md)\n\n## Common Mistakes\n\n- ❌ Colors without `view: ''color''`\n- ❌ Direct `this.debug.ui` extraction\n- ❌ Calling `debugInit()` without checking `debug.active`\n- ❌ Nesting deeper than 3 levels\n- ❌ All panels expanded by default\n\n**Complete error catalog:** See [references/common-mistakes.md](references/common-mistakes.md)\n\n## Quick Reference\n\n| Need | Code |\n|------|------|\n| Access debug | `this.debug = this.experience.debug` |\n| Check active | `if (this.debug.active)` |\n| Create folder | `this.debug.ui.addFolder({ title })` |\n| Bind parameter | `folder.addBinding(params, ''key'', options)` |\n| Handle change | `.on(''change'', callback)` |\n| Method name | `debugInit()` |\n\n**Advanced patterns:** See [references/advanced-patterns.md](references/advanced-patterns.md)\n"},"lastSynced":"2026-03-08T02:08:43.095Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents working with Vite and Three.js, needing streamlined debugging capabilities.","zh":"非常适合使用 Vite 和 Three.js 的前端代理，需要简化的调试功能。","ja":"Vite と Three.js を使用するフロントエンド エージェントに最適で、ストリームライン化されたデバッグ機能が必要です。","ko":"Vite와 Three.js를 사용하는 프론트엔드 에이전트에게 적합하며, 간소화된 디버깅 기능이 필요합니다.","es":"Perfecto para Agentes de Frontend que trabajan con Vite y Three.js, que necesitan capacidades de depuración simplificadas.","fr":"Parfait pour les agents Frontend qui travaillent avec Vite et Three.js, ayant besoin de capacités de débogage simplifiées.","de":"Perfekt für Frontend-Agenten, die mit Vite und Three.js arbeiten und vereinfachte Debugging-Funktionen benötigen.","pt":"Perfeito para Agentes Frontend que trabalham com Vite e Three.js, necessitando de capacidades de depuração otimizadas.","ru":"Идеален для фронтенд-агентов, работающих с Vite и Three.js, требующих оптимизированных возможностей отладки.","ar":"مثالي للوكلاء الأماميين الذين يعملون مع Vite و Three.js، وهم بحاجة إلى إمكانيات تصحيح أخطاء مبسطة."},"recommendation":{"en":"Empowers agents to create real-time parameter adjustment panels using Tweakpane, simplifying the debugging process with hierarchical group panels and color controls via ''view: color'' protocol, ideal for developers working with vite-threejs.","zh":"赋予代理创建实时参数调整面板的能力，使用 Tweakpane 简化调试过程，采用分层组面板和颜色控制，通过 ''view: color'' 协议，非常适合使用 vite-threejs 的开发者。","ja":"エージェントが Tweakpane を使用してリアルタイム パラメータ調整パネルを作成できるようになり、階層グループ パネルと ''view: color'' プロトコルによる色制御でデバッグ プロセスを簡素化します。vite-threejs を使用する開発者に最適です。","ko":"에이전트가 Tweakpane을 사용하여 실시간 매개변수 조정 패널을 만들 수 있도록하여, 계층적 그룹 패널 및 ''view: color'' 프로토콜을 통한 색상 제어로 디버깅 과정을 단순화합니다. vite-threejs를 사용하는 개발자에게 적합합니다.","es":"Habilita a los agentes a crear paneles de ajuste de parámetros en tiempo real utilizando Tweakpane, simplificando el proceso de depuración con paneles de grupo jerárquicos y controles de color a través del protocolo ''view: color'', ideal para desarrolladores que trabajan con vite-threejs.","fr":"Permet aux agents de créer des panneaux d''ajustement de paramètres en temps réel à l''aide de Tweakpane, simplifiant le processus de débogage avec des panneaux de groupe hiérarchiques et des contrôles de couleur via le protocole ''view: color'', idéal pour les développeurs qui travaillent avec vite-threejs.","de":"Ermächtigt Agenten, Echtzeit-Parameteranpassungsfelder mit Tweakpane zu erstellen, wodurch der Debugging-Prozess mit hierarchischen Gruppenfeldern und Farbkontrollen über das ''view: color''-Protokoll vereinfacht wird, ideal für Entwickler, die mit vite-threejs arbeiten.","pt":"Habilita os agentes a criarem painéis de ajuste de parâmetros em tempo real usando Tweakpane, simplificando o processo de depuração com painéis de grupo hierárquicos e controles de cor via protocolo ''view: color'', ideal para desenvolvedores que trabalham com vite-threejs.","ru":"Наделяет агентов возможностью создавать панели регулировки параметров в реальном времени с помощью Tweakpane, упрощая процесс отладки с помощью иерархических групповых панелей и цветовых контролей через протокол ''view: color'', идеально для разработчиков, работающих с vite-threejs.","ar":"يمنح الوكلاء القدرة على إنشاء لوحات تحكم للت调ية في الوقت الفعلي باستخدام Tweakpane، وبذلك يسهل عملية تصحيح الأخطاء باستخدام لوحات تحكم هرمية ومقاييس ألوان عبر بروتوكول ''view: color''، مثالية للمطورين الذين يعملون مع vite-threejs."},"useCases":{"en":["Debugging Three.js scenes with real-time parameter adjustments","Creating hierarchical control panels for complex web applications","Simplifying color palette management with ''view: color''"],"zh":["使用实时参数调整调试 Three.js 场景","为复杂的 web 应用程序创建分层控制面板","使用 ''view: color'' 简化色板管理"],"ja":["リアルタイム パラメータ調整を使用して Three.js シーンをデバッグする","複雑な Web アプリケーションに階層コントロール パネルを作成する","''view: color'' を使用してカラーパレット管理を簡素化する"],"ko":["실시간 매개변수 조정을 사용하여 Three.js 씬을 디버깅하는 것","복잡한 웹 애플리케이션에 대한 계층적 제어 패널を作成하는 것","''view: color''를 사용하여 색상 팔레트 관리를 단순화하는 것"],"es":["Depuración de escenas Three.js con ajustes de parámetros en tiempo real","Creación de paneles de control jerárquicos para aplicaciones web complejas","Simplificación de la gestión de paletas de colores con ''view: color''"],"fr":["Débogage de scènes Three.js avec des ajustements de paramètres en temps réel","Création de panneaux de contrôle hiérarchiques pour des applications web complexes","Simplification de la gestion des palettes de couleurs avec ''view: color''"],"de":["Debugging von Three.js-Szenen mit Echtzeit-Parameteranpassungen","Erstellung von hierarchischen Steuerungsfeldern für komplexe Webanwendungen","Vereinfachung der Farbpalettenverwaltung mit ''view: color''"],"pt":["Depuração de cenas Three.js com ajustes de parâmetros em tempo real","Criação de painéis de controle hierárquicos para aplicações web complexas","Simplificação da gestão de paletas de cor com ''view: color''"],"ru":["Отладка сцен Three.js с регулировкой параметров в реальном времени","Создание иерархических панелей управления для сложных веб-приложений","Упрощение управления цветовыми палитрами с помощью ''view: color''"],"ar":["تصحيح أخطاء مشاهد Three.js مع الت điều chỉnhات في الوقت الفعلي","إنشاء لوحات تحكم هرمية لتطبيقات الويب المعقدة","تسهيل إدارة لوحات الألوان مع ''view: color''"]},"limitations":{"en":["Requires Vite and Three.js setup","Limited to 3 levels of hierarchical grouping","Activated via ''#debug'' URL hash"],"zh":["需要 Vite 和 Three.js 设置","仅限 3 级分层分组","通过 ''#debug'' URL 哈希激活"],"ja":["Vite と Three.js の設定が必要","階層グループは 3 レベルに限定される"," ''#debug'' URL ハッシュで有効化"],"ko":["Vite 및 Three.js 설정이 필요합니다.","계층적 그룹은 3레벨로 제한됩니다.","''#debug'' URL 해시를 통해 활성화됩니다."],"es":["Requiere configuración de Vite y Three.js","Limitado a 3 niveles de agrupación jerárquica","Activado a través de ''#debug'' URL hash"],"fr":["Nécessite une configuration Vite et Three.js","Limité à 3 niveaux de regroupement hiérarchique","Activé via ''#debug'' URL hash"],"de":["Benötigt Vite- und Three.js-Setup","Begrenzt auf 3 Ebenen hierarchischer Gruppierung","Aktiviert über ''#debug'' URL-Hash"],"pt":["Requer configuração do Vite e Three.js","Limitado a 3 níveis de agrupamento hierárquico","Ativado via ''#debug'' hash de URL"],"ru":["Требует настройки Vite и Three.js","Ограничен 3 уровнями иерархической группировки","Активируется через ''#debug'' хэш URL"],"ar":["يتطلب إعداد Vite و Three.js","محدود بـ 3 مستويات من التجميع الهرمي","تمكين عبر ''#debug'' هاش URL"]},"version":4},"contentHash":"dfa7c6040c8b8d02659e509cfe4ad487c9c69d78dff1f2f4a7d8bba11c2f9e87","qualityScore":48}');
