INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ruvnet/agentic-flow/V3 Core Implementation', 'V3 Core Implementation', 'ruvnet', 'agentic-flow', 'community', 'V3 Core Implementation ruvnet agentic-flow community V3 Core Implementation enables developers to easily switch between alternative low-cost AI models and deploy fully hosted agents. It implements core TypeScript modules following Domain-Driven Design principles. V3 Core Implementation提供了TypeScript模块的核心实现，遵循Domain-Driven Design原则和clean architecture模式 V3 Core Implementationは、Domain-Driven Design原則とclean architectureパターンに基づいたTypeScriptモジュールの核心実装を提供する V3 Core Implementation는 Domain-Driven Design 원칙과 clean architecture 패턴을 따르는 TypeScript 모듈의 핵심 구현을 제공 V3 Core Implementation es una habilidad que permite implementar módulos de TypeScript para claude-flow v3, siguiendo principios de diseño de dominio y patrones de arquitectura limpia V3 Core Implementation est une compétence qui permet d''implémenter des modules TypeScript pour claude-flow v3, suivant les principes de conception de domaine et les modèles d''architecture propre V3 Core Implementation ist eine Fähigkeit, die die Implementierung von TypeScript-Modulen für claude-flow v3 ermöglicht, unter Berücksichtigung von Domain-Driven-Design-Prinzipien und sauberen Architekturmuster O V3 Core Implementation é uma habilidade que permite implementar módulos TypeScript para claude-flow v3, seguindo princípios de Domain-Driven Design e arquitetura limpa V3 Core Implementation - это навык, позволяющий реализовать модули TypeScript для claude-flow v3, следуя принципам Domain-Driven Design и чистой архитектуры V3 Core Implementation هو مهارة تسمح بتنفيذ وحدة TypeScript لclaude-flow v3، مع اتباع مبادئ Domain-Driven Design والهيكلة النظيفة V3 Core Implementation setup guide how to use V3 Core Implementation what is V3 Core Implementation V3 Core Implementation alternative V3 Core Implementation vs Claude SDK V3 Core Implementation install TypeScript AI model deployment claude-flow v3 implementation Domain-Driven Design principles V3 Core Implementation AIエージェント TypeScript Domain-Driven Design clean architecture comprehensive test coverage AI工具 TypeScript开发 Implements core TypeScript modules for claude-flow v3 Follows Domain-Driven Design principles and clean architecture patterns Supports comprehensive test coverage Enables deployment of fully hosted agents Allows switching between alternative low-cost AI models Utilizes Claude Code for agent setup and deployment V3 Core Implementation is a skill that implements core TypeScript modules for claude-flow v3, following Domain-Driven Design principles and clean architecture patterns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('publishpress/publishpress-future/prepare-changelog-release', 'community', 'publishpress', 'publishpress-future', 'publishpress/publishpress-future', 'prepare-changelog-release', 0, 0, 48, '2026-03-08T01:57:15.471Z', '2026-03-08T02:09:35.552Z', '4a63f4a3db3db4b258eedc2d28d835846434546dd929ebd448dad848fefe5ba0', '{"id":"publishpress/publishpress-future/prepare-changelog-release","name":"prepare-changelog-release","description":{"en":"The prepare-changelog-release skill updates the unreleased section of CHANGELOG.md with the current plugin version and date. It benefits developers by automating the changelog process.","zh":"prepare-changelog-release AI工具用于更新 CHANGELOG.md 文件，包括当前插件版本和日期","ja":"prepare-changelog-release AIエージェントは CHANGELOG.md ファイルを更新し、現在のプラグインバージョンと日付を含みます","ko":"prepare-changelog-release는 CHANGELOG.md 파일을 업데이트 하여 현재 플러그인 버전과 날짜를 포함합니다","es":"Prepare-changelog-release es una herramienta que actualiza la sección de lanzamiento no publicada del archivo CHANGELOG.md con la versión y fecha actuales del plugin","fr":"Prepare-changelog-release est un outil qui met à jour la section de publication non publiée du fichier CHANGELOG.md avec la version et la date actuelles du plugin","de":"Prepare-changelog-release ist ein Tool, das die nicht veröffentlichte Sektion der Datei CHANGELOG.md mit der aktuellen Version und dem Datum des Plugins aktualisiert","pt":"O prepare-changelog-release atualiza a seção de lançamento não liberada do CHANGELOG.md com a versão e data atuais do plugin","ru":"Prepare-changelog-release обновляет раздел непубликованных изменений в CHANGELOG.md с текущей версией и датой плагина","ar":"يحديث prepare-changelog-release قسم الإصدارات غير المنشورة في CHANGELOG.md مع الإصدار و التاريخ الحاليين للإضافة"},"seo":{"title":{"en":"prepare-changelog-release: Automated Changelog Setup Guid...","zh":"准备变更日志发布指南 - prepare-changelog-release","ja":"リリースのための変更ログの準備 - prepare-changelog-release AIエージェント","ko":"릴리스를 위한 변경 로그 준비 설정 - prepare-changelog-release","es":"Guía de configuración para prepare-changelog-release","fr":"Configurer prepare-changelog-release: Guide étape par étape","de":"Einrichten von prepare-changelog-release: Schritt-für-Sch...","pt":"Guia de Configuração do prepare-changelog-release","ru":"Настройка prepare-changelog-release: ИИ Агенты для автома...","ar":"إعداد prepare-changelog-release: أدوات ذكاء اصطناعي للتحد..."},"description":{"en":"Streamline your release process with prepare-changelog-release. Learn how to automate changelog updates and simplify your workflow. Get started now!","zh":"了解如何使用 prepare-changelog-release AI工具更新 CHANGELOG.md 文件，包括当前插件版本和日期","ja":"prepare-changelog-release AIエージェントを使用して CHANGELOG.md ファイルを更新する方法を学びます","ko":"prepare-changelog-release를 사용하여 CHANGELOG.md 파일을 업데이트 하는 방법에 대해 알아보세요","es":"Aprende a utilizar prepare-changelog-release para actualizar el registro de cambios de tu plugin con facilidad","fr":"Découvrez comment utiliser prepare-changelog-release pour mettre à jour votre journal des modifications de plugin","de":"Erfahren Sie, wie Sie prepare-changelog-release verwenden, um das Änderungsprotokoll Ihres Plugins zu aktualisieren","pt":"Aprenda a configurar o prepare-changelog-release para atualizar o CHANGELOG.md com a versão e data atuais do plugin","ru":"Узнайте, как настроить prepare-changelog-release для автоматического обновления CHANGELOG.md с версией и датой плагина","ar":"تعرف على كيفية إعداد prepare-changelog-release لتحديث CHANGELOG.md تلقائيًا مع إصدار و تاريخ الإضافة الحاليين"},"definition":{"en":"prepare-changelog-release is a plugin that automates the process of updating the unreleased section of CHANGELOG.md with the current plugin version and date.","zh":"prepare-changelog-release 是一个 AI 工具，用于更新 CHANGELOG.md 文件","ja":"prepare-changelog-release は CHANGELOG.md ファイルを更新する AI エージェントです","ko":"prepare-changelog-release는 CHANGELOG.md 파일을 업데이트 하는 AI 에이전트입니다","es":"Prepare-changelog-release es una herramienta de línea de comandos que ayuda a mantener actualizado el registro de cambios de un plugin","fr":"Prepare-changelog-release est un outil en ligne de commande qui aide à maintenir à jour le journal des modifications d''un plugin","de":"Prepare-changelog-release ist ein Befehlszeilentool, das hilft, das Änderungsprotokoll eines Plugins auf dem neuesten Stand zu halten","pt":"O prepare-changelog-release é uma ferramenta que atualiza o CHANGELOG.md com a versão e data atuais do plugin","ru":"Prepare-changelog-release - это инструмент, который обновляет CHANGELOG.md с версией и датой плагина","ar":"prepare-changelog-release هو أداة تحديث CHANGELOG.md مع إصدار و تاريخ الإضافة الحاليين"},"features":{"en":["Reads the current plugin version from publishpress-hub-statistics.php","Updates the unreleased section of CHANGELOG.md with the current plugin version and date","Follows the project''s changelog format","Identifies the [Unreleased] section in CHANGELOG.md","Processes bullet points between [Unreleased] entries"],"zh":["从 publishpress-hub-statistics.php 文件中读取当前插件版本","更新 CHANGELOG.md 文件的未发布部分","支持特定的 changelog 格式","识别 [Unreleased] 部分和其下的条目","使用当前日期和插件版本更新 changelog"],"ja":["publishpress-hub-statistics.php ファイルから現在のプラグインバージョンを読み取ります","CHANGELOG.md ファイルの未发布セクションを更新します","特定の changelog フォーマットをサポートします","[Unreleased] セクションとその下のエントリを識別します","現在の日付とプラグインバージョンを使用して changelog を更新します"],"ko":["publishpress-hub-statistics.php 파일에서 현재 플러그인 버전을 읽습니다","CHANGELOG.md 파일의 미발표 섹션을 업데이트합니다","특정 changelog 형식을 지원합니다","[미발표] 섹션과 그 아래 항목을 식별합니다","현재 날짜와 플러그인 버전을 사용하여 changelog를 업데이트합니다"],"es":["Lectura de la versión actual del plugin desde publishpress-hub-statistics.php","Actualización de la sección de lanzamiento no publicada en CHANGELOG.md","Compatibilidad con el formato de registro de cambios del proyecto","Uso de la línea de comandos para automatizar tareas","Integración con herramientas de desarrollo como CLI"],"fr":["Lecture de la version actuelle du plugin à partir de publishpress-hub-statistics.php","Mise à jour de la section de publication non publiée dans CHANGELOG.md","Compatibilité avec le format de journal des modifications du projet","Utilisation de la ligne de commande pour automatiser les tâches","Intégration avec des outils de développement tels que CLI"],"de":["Lese die aktuelle Version des Plugins aus publishpress-hub-statistics.php","Aktualisieren der nicht veröffentlichten Sektion in CHANGELOG.md","Kompatibilität mit dem Änderungsprotokoll-Format des Projekts","Verwendung der Befehlszeile zur Automatisierung von Aufgaben","Integration mit Entwicklungstools wie CLI"],"pt":["Leitura da versão atual do plugin em publishpress-hub-statistics.php","Atualização da seção de lançamento não liberada em CHANGELOG.md","Inserção da data e versão atuais do plugin","Compatibilidade com o formato de changelog do projeto","Automatização do processo de atualização do changelog"],"ru":["Чтение текущей версии плагина из publishpress-hub-statistics.php","Обновление раздела непубликованных изменений в CHANGELOG.md","Вставка текущей даты и версии плагина","Совместимость с форматом changelog проекта","Автоматизация процесса обновления changelog"],"ar":["قراءة الإصدار الحالي للإضافة من publishpress-hub-statistics.php","تحديث قسم الإصدارات غير المنشورة في CHANGELOG.md","إدراج التاريخ و الإصدار الحاليين للإضافة","التوافق مع تنسيق changelog المشروع","تأتمتة عملية تحديث changelog"]},"keywords":{"en":["how to use prepare-changelog-release","prepare-changelog-release setup guide","automated changelog updates","prepare-changelog-release alternative","prepare-changelog-release vs Post Expirator","prepare-changelog-release install","what is prepare-changelog-release","prepare-changelog-release tutorial","prepare-changelog-release best practices"],"zh":["prepare-changelog-release","AI 工具","CHANGELOG.md","插件版本","发布日志","AIエージェント","自动更新","版本控制"],"ja":["prepare-changelog-release","AIエージェント","CHANGELOG.md","プラグインバージョン","リリースログ","自動更新","バージョン管理"],"ko":["prepare-changelog-release","AI 에이전트","CHANGELOG.md","플러그인 버전","발표 로그","자동 업데이트","버전 관리"],"es":["prepare-changelog-release","herramientas de línea de comandos","registro de cambios","plugins","desarrollo de software","CLI","publishpress","herramientas de desarrollo","automatización de tareas"],"fr":["prepare-changelog-release","outils en ligne de commande","journal des modifications","plugins","développement de logiciels","CLI","publishpress","outils de développement","automatisation de tâches"],"de":["prepare-changelog-release","Befehlszeilentools","Änderungsprotokoll","Plugins","Softwareentwicklung","CLI","publishpress","Entwicklungstools","Automatisierung von Aufgaben"],"pt":["prepare-changelog-release","CHANGELOG.md","plugin","versão","data","ferramenta","automatização","desenvolvimento","programação"],"ru":["prepare-changelog-release","CHANGELOG.md","плагин","версия","дата","инструмент","автоматизация","разработка","программирование","ИИ Агенты"],"ar":["prepare-changelog-release","CHANGELOG.md","إضافة","إصدار","تاريخ","أداة","تأتمتة","برمجة","تطوير","أدوات ذكاء اصطناعي"]}},"owner":"publishpress","repo":"publishpress-future","repoPath":"publishpress/publishpress-future","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.471Z","topics":[],"category":"community","skillMd":{"name":"prepare-changelog-release","description":"Prepares the CHANGELOG.md file for release by updating the [Unreleased] section with the current plugin version and date. Use when the user asks to prepare changelog for release, update changelog for release, or finalize changelog entries.","bodyPreview":"# Prepare Changelog for Release\n\nUpdates the unreleased section of CHANGELOG.md with the current plugin version and date, following the project''s changelog format.\n\n## Instructions\n\nWhen preparing the changelog for release:\n\n1. **Read the current plugin version** from `publishpress-hub-statistics.php` (Version field in the file header)\n\n2. **Read CHANGELOG.md** to identify:\n   - The [Unreleased] section (typically starts at line 4)\n   - All entries under [Unreleased] (bullet points between [Unre","body":"# Prepare Changelog for Release\n\nUpdates the unreleased section of CHANGELOG.md with the current plugin version and date, following the project''s changelog format.\n\n## Instructions\n\nWhen preparing the changelog for release:\n\n1. **Read the current plugin version** from `publishpress-hub-statistics.php` (Version field in the file header)\n\n2. **Read CHANGELOG.md** to identify:\n   - The [Unreleased] section (typically starts at line 4)\n   - All entries under [Unreleased] (bullet points between [Unreleased] and the next version)\n\n3. **Update the changelog** by replacing the [Unreleased] header with:\n   ```\n   [VERSION] - DD MMM, YYYY\n   ```\n   Where:\n   - VERSION is the current version from the plugin file\n   - DD is the day (2 digits)\n   - MMM is the month (3-letter abbreviation: Jan, Feb, Mar, Apr, May, Jun, Jul, Aug, Sep, Oct, Nov, Dec)\n   - YYYY is the 4-digit year\n\n4. **Add a new [Unreleased] section** at the top (after line 3) with empty content:\n   ```\n   [Unreleased]\n\n   ```\n\n## Format Requirements\n\n- Use exactly one blank line between sections\n- Maintain the existing bullet point format for entries\n- Follow the format: `[VERSION] - DD MMM, YYYY` (e.g., `[1.0.0] - 02 Feb, 2026`)\n- Add comma after day in the date\n- Use 3-letter month abbreviation\n\n## Example Transformation\n\n**Before:**\n```markdown\nThe format is based on [Keep a Changelog](http://keepachangelog.com/)\nand this project adheres to [Semantic Versioning](http://semver.org/).\n\n[Unreleased]\n\n- Added: New feature X\n- Fixed: Bug in feature Y\n\n[1.0.0] - 02 Feb, 2026\n```\n\n**After (assuming version 1.1.0 and date 05 Feb, 2026):**\n```markdown\nThe format is based on [Keep a Changelog](http://keepachangelog.com/)\nand this project adheres to [Semantic Versioning](http://semver.org/).\n\n[Unreleased]\n\n[1.1.0] - 05 Feb, 2026\n\n- Added: New feature X\n- Fixed: Bug in feature Y\n\n[1.0.0] - 02 Feb, 2026\n```\n\n## Month Abbreviations Reference\n\n| Month | Abbreviation |\n|-------|--------------|\n| January | Jan |\n| February | Feb |\n| March | Mar |\n| April | Apr |\n| May | May |\n| June | Jun |\n| July | Jul |\n| August | Aug |\n| September | Sep |\n| October | Oct |\n| November | Nov |\n| December | Dec |\n"},"lastSynced":"2026-03-08T02:09:35.552Z","agentAnalysis":{"suitability":{"en":"Ideal for Release Automation Agents handling WordPress plugin deployments and version management.","zh":"非常适合处理WordPress插件部署和版本管理的Release Automation Agents。","ja":"WordPressプラグインのデプロイメントとバージョン管理を扱うRelease Automation Agentsに理想的です。","ko":"WordPress 플러그인 배포 및 버전 관리를 처리하는 Release Automation Agents에 이상적입니다.","es":"Ideal para Agentes de Automatización de Lanzamiento que manejan implementaciones y administración de versiones de plugins de WordPress.","fr":"Idéal pour les agents d''automatisation de version gérant les déploiements de plugins WordPress et la gestion de versions.","de":"Ideal für Release-Automationsagenten, die WordPress-Plugin-Deployments und Versionen verwalten.","pt":"Ideal para Agentes de Automação de Lançamento que lidam com implantações de plugins do WordPress e gerenciamento de versões.","ru":"Идеально подходит для агентов автоматизации выпуска, которые обрабатывают развертывание плагинов WordPress и управление версиями.","ar":"مثالي لعمليات إصدار التلقائي التي تتعامل مع عمليات نشر الإضافات وإدارة الإصدارات في ووردبريس."},"recommendation":{"en":"Automates CHANGELOG.md updates by parsing plugin version headers from PHP files and restructuring unreleased sections with proper version tagging and date formatting. Eliminates manual changelog maintenance during release cycles.","zh":"通过解析PHP文件中的插件版本头信息，并重新构建带有适当版本标记和日期格式的未发布部分，实现CHANGELOG.md更新的自动化。在发布周期中消除了手动维护更新日志的需要。","ja":"PHPファイルからプラグインバージョンヘッダーを解析し、適切なバージョンタグ付けと日付フォーマットで未リリースセクションを再構築することで、CHANGELOG.mdの更新を自動化します。リリースサイクルにおける手動の変更履歴メンテナンスを排除します。","ko":"PHP 파일에서 플러그인 버전 헤더를 파싱하고 적절한 버전 태깅 및 날짜 형식으로 미출시 섹션을 재구성하여 CHANGELOG.md 업데이트를 자동화합니다. 릴리스 주기 동안 수동 변경 로그 유지 관리를 제거합니다.","es":"Automatiza las actualizaciones de CHANGELOG.md analizando los encabezados de versión de plugins desde archivos PHP y reestructurando secciones sin lanzar con etiquetado de versión y formato de fecha adecuados. Elimina el mantenimiento manual de registros de cambios durante los ciclos de lanzamiento.","fr":"Automatise les mises à jour de CHANGELOG.md en analysant les en-têtes de version de plugins à partir de fichiers PHP et en restructurant les sections non publiées avec un étiquetage de version et un format de date appropriés. Élimine la maintenance manuelle des journaux des modifications pendant les cycles de publication.","de":"Automatisiert die Aktualisierungen von CHANGELOG.md, indem es Plugin-Versionsköpfe aus PHP-Dateien analysiert und nicht veröffentlichte Abschnitte mit ordnungsgemäßer Versionstaggung und Datumsformatierung neu strukturiert. Beseitigt manuelle Wartung von Änderungsprotokollen während Release-Zyklen.","pt":"Automatiza atualizações do CHANGELOG.md analisando cabeçalhos de versão de plugins de PHP e reestruturando seções não lançadas com marcação de versão e formatação de data adequadas. Elimina a manutenção manual do changelog durante os ciclos de lançamento.","ru":"Автоматизирует обновления CHANGELOG.md, анализируя заголовки версий плагинов из файлов PHP и переструктурируя нерелизные разделы с правильной версионностью и форматированием даты. Исключает ручное обслуживание changelog во время циклов выпуска.","ar":"يعمل تلقائيًا على تحديث CHANGELOG.md من خلال تحليل رؤوس الإصدارات الخاصة بالإضافات من الملفات PHP وإعادة هيكلة الأقسام غير المنشورة مع تعيين إصدار مناسب وتحويل تاريخ مناسب. يحذف الحاجة إلى صيانة يدوية للчينجلوج خلال دورات الإصدار."},"useCases":{"en":["Automating version-tagged changelog updates for plugin releases","Parsing WordPress plugin header metadata for version detection","Restructuring CHANGELOG.md unreleased sections into versioned entries"],"zh":["为插件发布自动化带有版本标签的更新日志更新","解析WordPress插件头元数据以进行版本检测","将CHANGELOG.md的未发布部分重构为带版本的条目"],"ja":["プラグインリリース用のバージョンタグ付き変更履歴更新の自動化","バージョン検出のためのWordPressプラグインヘッダーメタデータの解析","CHANGELOG.mdの未リリースセクションをバージョン付きエントリに再構築"],"ko":["플러그인 릴리스용 버전 태깅된 변경 로그 업데이트 자동화","버전 감지를 위한 WordPress 플러그인 헤더 메타데이터 파싱","CHANGELOG.md의 미출시 섹션을 버전이 지정된 항목으로 재구성"],"es":["Automatizar actualizaciones de registros de cambios con etiquetas de versión para lanzamientos de plugins","Analizar metadatos de encabezados de plugins de WordPress para la detección de versiones","Reestructurar secciones sin lanzar en CHANGELOG.md en entradas con versiones"],"fr":["Automatiser les mises à jour des journaux des modifications avec des balises de version pour les publications de plugins","Analyser les métadonnées des en-têtes de plugins WordPress pour la détection de versions","Restructurer les sections non publiées dans CHANGELOG.md en entrées avec des versions"],"de":["Automatisieren von Änderungsprotokoll-Aktualisierungen mit Versions-Tags für Plugin-Veröffentlichungen","Analysieren von WordPress-Plugin-Kopfmetadaten zur Erkennung von Versionen","Umstrukturieren von nicht veröffentlichten Abschnitten in CHANGELOG.md in versionierte Einträge"],"pt":["Automatizar atualizações de changelog com marcação de versão para lançamentos de plugins","Analisar metadados de cabeçalho de plugins do WordPress para detecção de versão","Reestruturar seções não lançadas do CHANGELOG.md em entradas com versão"],"ru":["Автоматизировать обновления changelog с версионной маркировкой для выпусков плагинов","Анализировать метаданные заголовков плагинов WordPress для обнаружения версий","Переструктурировать нерелизные разделы CHANGELOG.md в версионные записи"],"ar":["تحديث آلي لتشangelog بإضافة علامات إصدار للنشرات الإضافية","تحليل بيانات رأس الإضافات في ووردبريس لتحديد الإصدارات","إعادة هيكلة الأقسام غير المنشورة من CHANGELOG.md إلى مدخلات الإصدار"]},"limitations":{"en":["Requires specific CHANGELOG.md format with [Unreleased] section at line 4","Dependent on WordPress plugin header structure in PHP files","Limited to projects using semantic versioning in changelogs"],"zh":["要求特定的CHANGELOG.md格式，其中第4行必须为[Unreleased]部分","依赖于PHP文件中的WordPress插件头结构","仅限于在更新日志中使用语义化版本控制的项目"],"ja":["4行目に[Unreleased]セクションが必要な特定のCHANGELOG.mdフォーマットを要求","PHPファイル内のWordPressプラグインヘッダー構造に依存","変更履歴でセマンティックバージョニングを使用するプロジェクトに限定"],"ko":["4번째 줄에 [Unreleased] 섹션이 있는 특정 CHANGELOG.md 형식 필요","PHP 파일 내 WordPress 플러그인 헤더 구조에 종속적","변경 로그에서 시맨틱 버저닝을 사용하는 프로젝트로 제한됨"],"es":["Requiere un formato CHANGELOG.md específico con una sección [No lanzado] en la línea 4","Dependiente de la estructura de encabezados de plugins de WordPress en archivos PHP","Limitado a proyectos que utilizan versiones semánticas en registros de cambios"],"fr":["Nécessite un format CHANGELOG.md spécifique avec une section [Non publié] à la ligne 4","Dépend de la structure des en-têtes de plugins WordPress dans les fichiers PHP","Limité aux projets utilisant une version sémantique dans les journaux des modifications"],"de":["Benötigt ein spezifisches CHANGELOG.md-Format mit einem [Unreleased]-Abschnitt in Zeile 4","Abhängig von der Struktur von WordPress-Plugin-Köpfen in PHP-Dateien","Begrenzt auf Projekte, die semantische Versionierung in Änderungsprotokollen verwenden"],"pt":["Exige formato específico do CHANGELOG.md com seção [Unreleased] na linha 4","Dependente da estrutura de cabeçalho do plugin do WordPress nos arquivos PHP","Limitado a projetos que usam versionamento semântico nos changelogs"],"ru":["Требует конкретного формата CHANGELOG.md с разделом [Unreleased] на строке 4","Зависит от структуры заголовка плагина WordPress в файлах PHP","Ограничен проектами, которые используют семантическое версионирование в changelogs"],"ar":["يتطلب تنسيقًا محددًا لملف CHANGELOG.md مع قسم [غير منشور] في السطر 4","يعتمد على هيكل رأس الإضافة في الملفات PHP","محدود بالمشاريع التي تستخدم إصدارًا معنويًا في سجلات التغيير"]},"version":4},"contentHash":"4a63f4a3db3db4b258eedc2d28d835846434546dd929ebd448dad848fefe5ba0","qualityScore":48}');
