INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('publishpress/publishpress-future/prepare-changelog-release', 'prepare-changelog-release', 'publishpress', 'publishpress-future', 'community', 'prepare-changelog-release publishpress publishpress-future community The prepare-changelog-release skill updates the unreleased section of CHANGELOG.md with the current plugin version and date. It benefits developers by automating the changelog process. prepare-changelog-release AI工具用于更新 CHANGELOG.md 文件，包括当前插件版本和日期 prepare-changelog-release AIエージェントは CHANGELOG.md ファイルを更新し、現在のプラグインバージョンと日付を含みます prepare-changelog-release는 CHANGELOG.md 파일을 업데이트 하여 현재 플러그인 버전과 날짜를 포함합니다 Prepare-changelog-release es una herramienta que actualiza la sección de lanzamiento no publicada del archivo CHANGELOG.md con la versión y fecha actuales del plugin Prepare-changelog-release est un outil qui met à jour la section de publication non publiée du fichier CHANGELOG.md avec la version et la date actuelles du plugin Prepare-changelog-release ist ein Tool, das die nicht veröffentlichte Sektion der Datei CHANGELOG.md mit der aktuellen Version und dem Datum des Plugins aktualisiert O prepare-changelog-release atualiza a seção de lançamento não liberada do CHANGELOG.md com a versão e data atuais do plugin Prepare-changelog-release обновляет раздел непубликованных изменений в CHANGELOG.md с текущей версией и датой плагина يحديث prepare-changelog-release قسم الإصدارات غير المنشورة في CHANGELOG.md مع الإصدار و التاريخ الحاليين للإضافة how to use prepare-changelog-release prepare-changelog-release setup guide automated changelog updates prepare-changelog-release alternative prepare-changelog-release vs Post Expirator prepare-changelog-release install what is prepare-changelog-release prepare-changelog-release tutorial prepare-changelog-release best practices prepare-changelog-release AI 工具 CHANGELOG.md 插件版本 发布日志 AIエージェント 自动更新 版本控制 Reads the current plugin version from publishpress-hub-statistics.php Updates the unreleased section of CHANGELOG.md with the current plugin version and date Follows the project''s changelog format Identifies the [Unreleased] section in CHANGELOG.md Processes bullet points between [Unreleased] entries prepare-changelog-release is a plugin that automates the process of updating the unreleased section of CHANGELOG.md with the current plugin version and date.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('skysheng7/tech_summary_llm_arena/api-rules', 'community', 'skysheng7', 'tech_summary_llm_arena', 'skysheng7/tech_summary_llm_arena', 'api-rules', 0, 0, 48, '2026-03-08T01:57:15.472Z', '2026-03-08T02:09:37.122Z', '3b24f746c0b438fa28bfdfa90afb0f061f4ffea47d30df0870b779194b3b2d43', '{"id":"skysheng7/tech_summary_llm_arena/api-rules","name":"api-rules","description":{"en":"The api-rules skill provides a Python programming assistant for LLM evaluation tasks, utilizing OpenAI API and libraries like Pandas and NumPy. It benefits developers working with LLMs.","zh":"API 规则为 LLM 评估任务提供了高效的解决方案，使用 Python 编程助手可以简化开发流程","ja":"API ルールは LLM 評価タスクに効率的な解決策を提供し、Python プログラミングアシスタントを使用すると開発プロセスを簡素化できます","ko":"API 규칙은 LLM 평가 태스크에 효율적인 해결책을 제공하며, 파이썬 프로그래밍 어시스턴트를 사용하면 개발 프로세스를 단순화할 수 있습니다","es":"API-Rules es un conjunto de reglas para evaluar LLMs con Python y OpenAI API. Incluye integración con Pandas y NumPy.","fr":"API-Rules est un ensemble de règles pour évaluer les LLM avec Python et OpenAI API. Il inclut une intégration avec Pandas et NumPy.","de":"API-Rules ist ein Satz von Regeln zur Bewertung von LLMs mit Python und OpenAI API. Er umfasst eine Integration mit Pandas und NumPy.","pt":"A API Rules é uma ferramenta para desenvolvedores que necessitam integrar a OpenAI API em seus projetos, utilizando bibliotecas Python como Pandas e NumPy.","ru":"ИИ Агенты с помощью API Rules - это инструмент для разработчиков, которые нуждаются в интеграции OpenAI API в свои проекты, используя библиотеки Python, такие как Pandas и NumPy.","ar":"قواعد واجهة برمجة التطبيقات هي أداة للطورين الذين يحتاجون إلى دمج OpenAI API في مشاريعهم، باستخدام مكتبات Python مثل Pandas و NumPy."},"seo":{"title":{"en":"api-rules: Python Coding Assistant Setup Guide | AI Agent...","zh":"API 规则集成指南 -  Python 编程助手","ja":"API ルールセットアップガイド - Python プログラミングアシスタント","ko":"API 규칙 설정 가이드 - 파이썬 프로그래밍 어시스턴트","es":"Guía de configuración de API-Rules para Agentes de Inteli...","fr":"Guide d''installation d''API-Rules pour les Outils d''Intell...","de":"Einrichtungsleitfaden für API-Rules in KI-Agents","pt":"Guia de Configuração da API Rules para Desenvolvedores","ru":"Настройка ИИ Агентов: Руководство по API Rules","ar":"دليل إعداد قواعد واجهة برمجة التطبيقات للطورين"},"description":{"en":"Discover how to evaluate LLMs with api-rules. Get started with OpenAI API and Python to streamline your workflow. Learn more now!","zh":"了解 API 规则的技术细节，并使用 Python 编程助手构建高效的 LLM 评估任务","ja":"API ルールの技術的な詳細を学び、Python プログラミングアシスタントを使用して効率的な LLM 評価タスクを構築する","ko":"API 규칙의 기술적인 세부 정보를 배우고 파이썬 프로그래밍 어시스턴트를 사용하여 효율적인 LLM 평가 태스크를 구축하십시오","es":"Aprende a configurar API-Rules para evaluar LLMs con Python, OpenAI API y Pandas. Mejora tus habilidades en desarrollo de IA.","fr":"Découvrez comment configurer API-Rules pour évaluer les LLM avec Python, OpenAI API et Pandas. Améliorez vos compétences en développement d''IA.","de":"Erfahren Sie, wie Sie API-Rules für die Bewertung von LLMs mit Python, OpenAI API und Pandas konfigurieren. Verbessern Sie Ihre Fähigkeiten in der KI-Entwick...","pt":"Aprenda a configurar a API Rules para desenvolvedores com nosso guia passo a passo, incluindo integração com OpenAI API e bibliotecas Python como Pandas e Nu...","ru":"Узнайте, как настроить ИИ Агенты с помощью API Rules, включая интеграцию с OpenAI API и библиотеками Python, такими как Pandas и NumPy.","ar":"تعلم كيفية إعداد قواعد واجهة برمجة التطبيقات للطورين باستخدام دليلنا خطوة بخطوة، بما في ذلك التكامل مع OpenAI API و مكتبات Python مثل Pandas و NumPy."},"definition":{"en":"api-rules is a Python-based skill for evaluating different Large Language Models (LLMs) using the OpenAI API and supporting libraries.","zh":"API 规则是指使用 Python 编程助手为 LLM 评估任务定义的规则集","ja":"API ルールとは、Python プログラミングアシスタントを使用して LLM 評価タスクに定義されるルールの集合","ko":"API 규칙은 파이썬 프로그래밍 어시스턴트를 사용하여 LLM 평가 태스크에 정의되는 규칙 세트입니다","es":"API-Rules es un conjunto de reglas para evaluar LLMs con tecnologías como Python y OpenAI API.","fr":"API-Rules est un ensemble de règles pour évaluer les LLM avec des technologies comme Python et OpenAI API.","de":"API-Rules ist ein Satz von Regeln zur Bewertung von LLMs mit Technologien wie Python und OpenAI API.","pt":"API Rules é uma ferramenta de programação que ajuda desenvolvedores a integrar a OpenAI API em seus projetos.","ru":"ИИ Агенты с помощью API Rules - это инструмент программирования, который помогает разработчикам интегрировать OpenAI API в свои проекты.","ar":"قواعد واجهة برمجة التطبيقات هي أداة برمجة تساعد الطورين على دمج OpenAI API في مشاريعهم."},"features":{"en":["Utilizes OpenAI API for LLM evaluation","Supports file attachments via OpenAI API","Leverages Pandas for data manipulation","Employs NumPy for numerical computations","Provides well-documented and modular Python code"],"zh":["使用 OpenAI API 进行 LLM 评估","支持 Pandas 和 NumPy 库","提供简单的 Python 编程助手","支持 API 文件附件","使用 Python 编程助手简化开发流程"],"ja":["OpenAI API を使用した LLM 評価","Pandas と NumPy ライブラリのサポート","シンプルな Python プログラミングアシスタントの提供","API ファイル添付のサポート","Python プログラミングアシスタントを使用した開発プロセスの簡素化"],"ko":["OpenAI API를 사용한 LLM 평가","Pandas 및 NumPy 라이브러리의 지원","간단한 파이썬 프로그래밍 어시스턴트의 제공","API 파일 첨부의 지원","파이썬 프로그래밍 어시스턴트를 사용한 개발 프로세스의 단순화"],"es":["Integración con OpenAI API","Soporte para Pandas y NumPy","Evaluación de LLMs con Python","Documentación detallada","Código modular y limpio"],"fr":["Intégration avec OpenAI API","Prise en charge de Pandas et NumPy","Évaluation de LLM avec Python","Documentation détaillée","Code modulaire et propre"],"de":["Integration mit OpenAI API","Unterstützung für Pandas und NumPy","Bewertung von LLMs mit Python","Detaillierte Dokumentation","Modulares und sauberes Code"],"pt":["Integração com OpenAI API","Suporte a bibliotecas Python como Pandas e NumPy","Desenvolvimento de projetos com LLMs","Análise de dados com Pandas","Cálculos numéricos com NumPy"],"ru":["Интеграция с OpenAI API","Поддержка библиотек Python, таких как Pandas и NumPy","Разработка проектов с LLMs","Анализ данных с Pandas","Численные вычисления с NumPy"],"ar":["التكامل مع OpenAI API","دعم مكتبات Python مثل Pandas و NumPy","تطوير مشاريع مع LLMs","تحليل البيانات مع Pandas","الحسابات العددية مع NumPy"]},"keywords":{"en":["how to use api-rules","what is api-rules","api-rules alternative","api-rules vs OpenAI API","api-rules install","api-rules setup guide","LLM evaluation with Python","OpenAI API for LLMs","api-rules documentation"],"zh":["API 规则","LLM 评估","Python 编程助手","OpenAI API","Pandas","NumPy","AI 工具","AI 编程"],"ja":["API ルール","LLM 評価","Python プログラミングアシスタント","OpenAI API","Pandas","NumPy","AI エージェント","AI プログラミング"],"ko":["API 규칙","LLM 평가","파이썬 프로그래밍 어시스턴트","OpenAI API","Pandas","NumPy","AI 도구","AI 프로그래밍"],"es":["API-Rules","Agentes de Inteligencia Artificial","LLM","Python","OpenAI API","Pandas","NumPy","evaluación de LLM","desarrollo de IA"],"fr":["API-Rules","Outils d''Intelligence Artificielle","LLM","Python","OpenAI API","Pandas","NumPy","évaluation de LLM","développement d''IA"],"de":["API-Rules","KI-Agents","LLM","Python","OpenAI API","Pandas","NumPy","Bewertung von LLM","KI-Entwicklung"],"pt":["API Rules","OpenAI API","Pandas","NumPy","LLMs","Desenvolvimento de projetos","Análise de dados","Cálculos numéricos"],"ru":["ИИ Агенты","OpenAI API","Pandas","NumPy","LLMs","Разработка проектов","Анализ данных","Численные вычисления"],"ar":["قواعد واجهة برمجة التطبيقات","OpenAI API","Pandas","NumPy","LLMs","تطوير مشاريع","تحليل البيانات","الحسابات العددية"]}},"owner":"skysheng7","repo":"tech_summary_llm_arena","repoPath":"skysheng7/tech_summary_llm_arena","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.472Z","topics":[],"category":"community","skillMd":{"name":"api-rules","description":"","bodyPreview":"# Python Programming Assistant\n\n## Your Role\n\nYou are a helpful coding assistant for a LLM-as-a-judge evaluation task. You will write well-documented, simple, modular, clean python code to help the user evaluate different LLMs.\n\n### Key Documentation\n\n- OpenAI API: <https://platform.openai.com/docs/api-reference>\n- OpenAI API file attachments: <https://platform.openai.com/docs/guides/pdf-files>\n- Pandas: <https://pandas.pydata.org/docs/>\n- NumPy: <https://numpy.org/doc/stable/>\n\n### Model Inform","body":"# Python Programming Assistant\n\n## Your Role\n\nYou are a helpful coding assistant for a LLM-as-a-judge evaluation task. You will write well-documented, simple, modular, clean python code to help the user evaluate different LLMs.\n\n### Key Documentation\n\n- OpenAI API: <https://platform.openai.com/docs/api-reference>\n- OpenAI API file attachments: <https://platform.openai.com/docs/guides/pdf-files>\n- Pandas: <https://pandas.pydata.org/docs/>\n- NumPy: <https://numpy.org/doc/stable/>\n\n### Model Information\n\n- **Current Model:** GPT-5.2 (released December 11, 2025)\n- **Model Name:** `gpt-5.2-2025-12-11`\n\n### Code Simplicity\n\n- Use the simplest code possible\n- Minimize package dependencies, only use what''s absolutely necessary\n- Avoid advanced Python features, no list comprehensions unless specifically taught, no complex lambda functions\n- Break down complex operations into simple, readable steps\n- Add clear comments explaining what code does\n- Use blank lines to separate logical sections\n- Keep lines under 88 characters when possible\n\n### Variable Naming\n\n- Use descriptive names: `generated_images` not `img` or `x`\n- Use snake_case: `api_key`, NOT `apiKey` NOT `ApiKey`\n- Make names meaningful: `user_prompts`, NOT `data1`\n\n### Function Design\n\n- Each function should do ONE thing\n- Write modular code, break complex tasks into small, reusable functions\n- Always include NumPy-style docstrings explaining purpose, parameters, and returns\n- Use type hints to make code clearer\n- Include default parameter values where appropriate\n\n### API Key Management\n\n**CRITICAL:** Never hardcode API keys in code! Reminder users of this when necessary.\n\n**You will:**\n\n1. Create a `.env` file in project root\n2. Add: `OPENAI_API_KEY=your-actual-key-here`\n3. Add `.env` to `.gitignore`\n4. Use `python-dotenv` to load it\n5. Prompt the user to create the API key and paste the key themselves to the `.env` file before proceeding.\n\nCorrect example of using API key:\n\n```python\nimport os\nfrom dotenv import load_dotenv\n\n# Load environment variables from .env file\nload_dotenv()\napi_key = os.getenv(''OPENAI_API_KEY'')\n\nif not api_key:\n    raise ValueError(\"OPENAI_API_KEY not found in environment variables\")\n```\n\n### Error Handling\n\nAlways wrap API calls and file operations in try-except blocks:\n\n```python\ntry:\n    response = client.chat.completions.create(\n        model=\"gpt-5.2-2025-12-11\",\n        messages=[\n            {\"role\": \"system\", \"content\": \"You are a helpful assistant.\"},\n            {\"role\": \"user\", \"content\": \"Hello!\"}\n        ]\n    )\n    result = response.choices[0].message.content\nexcept Exception as e:\n    print(f\"Error calling API: {e}\")\n    result = None\n```\n"},"lastSynced":"2026-03-08T02:09:37.122Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Analysis Agents specializing in LLM-as-a-judge evaluation tasks.","zh":"非常适合专门从事LLM-as-a-judge评估任务的Python分析代理。","ja":"Python分析エージェントがLLM-as-a-judge評価タスクを専門とする場合に最適です。","ko":"LLM-as-a-judge 평가 태스크를 전문으로 하는 Python 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis de Python que se especializan en tareas de evaluación de LLM como juez.","fr":"Parfait pour les agents d''analyse Python spécialisés dans les tâches d''évaluation de LLM en tant que juge.","de":"Perfekt für Python-Analyse-Agenten, die sich auf LLM-Bewertungsaufgaben als Richter spezialisieren.","pt":"Perfeito para Agentes de Análise Python especializados em tarefas de avaliação LLM-as-a-judge.","ru":"Идеально подходит для агентов анализа Python, специализирующихся на задачах оценки LLM-as-a-judge.","ar":"مثالي لعميل تحليل بايثون المتخصص في مهام تقييم LLM-as-a-judge."},"recommendation":{"en":"Enables comprehensive LLM evaluation workflows using OpenAI API integration with Pandas and NumPy for data processing. Provides structured code generation for modular evaluation pipelines and supports file attachments for batch processing.","zh":"启用使用OpenAI API集成的Pandas和NumPy进行数据处理的综合LLM评估工作流。提供用于模块化评估管道的结构化代码生成，并支持文件附件以实现批处理。","ja":"OpenAI APIを使用したPandasとNumPyによるデータ処理を含む包括的なLLM評価ワークフローを有効にします。モジュラー評価パイプライン用の構造化コード生成を提供し、バッチ処理のためのファイル添付をサポートします。","ko":"Pandas와 NumPy를 사용한 데이터 처리를 포함한 OpenAI API 통합을 통해 포괄적인 LLM 평가 워크플ロー가 가능합니다. 모듈식 평가 파이프라인을 위한 구조화된 코드 생성을 제공하며, 배치 처리를 위한 파일 첨부를 지원합니다.","es":"Habilita flujos de trabajo de evaluación de LLM integrales utilizando la integración de la API de OpenAI con Pandas y NumPy para el procesamiento de datos. Proporciona generación de código estructurado para tuberías de evaluación modulares y admite archivos adjuntos para el procesamiento por lotes.","fr":"Permet des flux de travail d''évaluation de LLM complets en utilisant l''intégration de l''API OpenAI avec Pandas et NumPy pour le traitement des données. Fournit une génération de code structurée pour des pipelines d''évaluation modulaires et prend en charge les pièces jointes pour le traitement par lots.","de":"Ermöglicht umfassende LLM-Bewertungs-Workflows unter Verwendung der OpenAI-API-Integration mit Pandas und NumPy für die Datenverarbeitung. Bietet strukturierte Codegenerierung für modulare Bewertungspipelines und unterstützt Dateianhänge für den Batchverarbeitung.","pt":"Permite fluxos de trabalho de avaliação LLM abrangentes usando integração da API OpenAI com Pandas e NumPy para processamento de dados. Fornece geração de código estruturado para pipelines de avaliação modulares e suporta anexos de arquivos para processamento em lotes.","ru":"Позволяет выполнять комплексные рабочие процессы оценки LLM с использованием интеграции API OpenAI с Pandas и NumPy для обработки данных. Предоставляет структурированную генерацию кода для модульных конвейеров оценки и поддерживает вложения файлов для пакетной обработки.","ar":"يسمح بإجراء عمليات تقييم LLM الشاملة باستخدام دمج API OpenAI مع Pandas و NumPy لمعالجة البيانات. يوفر توليد شفرة منظم لخطوط أنابيب التقييم المعدلة ودعم مرفقات الملفات لمعالجة الدُفعات."},"useCases":{"en":["Automating LLM performance benchmarking","Generating evaluation datasets from PDF attachments","Processing results with Pandas data analysis","Creating modular evaluation scripts for multiple models"],"zh":["自动化LLM性能基准测试","从PDF附件生成评估数据集","使用Pandas数据分析处理结果","为多个模型创建模块化评估脚本"],"ja":["LLM性能ベンチマークテストの自動化","PDF添付から評価データセットを生成する","Pandasデータ分析を使用して結果を処理する","複数のモデル用のモジュラー評価スクリプトを作成する"],"ko":["LLM 성능 벤치마크 테스트 자동화","PDF 첨부 파일에서 평가 데이터 세트 생성","Pandas 데이터 분석을 사용하여 결과 처리","여러 모델에 대한 모듈식 평가 스크립트 생성"],"es":["Automatización de la benchmarking del rendimiento de LLM","Generación de conjuntos de datos de evaluación a partir de archivos adjuntos PDF","Procesamiento de resultados con análisis de datos de Pandas","Creación de scripts de evaluación modulares para varios modelos"],"fr":["Automatisation de la benchmarking des performances de LLM","Génération de jeux de données d''évaluation à partir de pièces jointes PDF","Traitement des résultats avec l''analyse de données de Pandas","Création de scripts d''évaluation modulaires pour plusieurs modèles"],"de":["Automatisierung der Leistungsbewertung von LLM","Erzeugung von Bewertungsdatensätzen aus PDF-Anhängen","Verarbeitung von Ergebnissen mit Pandas-Datenanalyse","Erstellung von modularen Bewertungsskripten für mehrere Modelle"],"pt":["Automatizar a benchmarking do desempenho LLM","Gerar conjuntos de dados de avaliação a partir de anexos PDF","Processar resultados com análise de dados Pandas","Criar scripts de avaliação modulares para vários modelos"],"ru":["Автоматизировать тестирование производительности LLM","Генерировать наборы данных для оценки из вложений PDF","Обрабатывать результаты с помощью анализа данных Pandas","Создавать модульные сценарии оценки для нескольких моделей"],"ar":["توفير التقييم الآلي لأداء LLM","توليد مجموعات بيانات التقييم من مرفقات PDF","معالجة النتائج باستخدام تحليل بيانات Pandas","إنشاء سكريبتات تقييم مُعدّلة لمُختلف النماذج"]},"limitations":{"en":["Requires OpenAI API Key","Depends on Pandas and NumPy libraries","Python-specific implementation only"],"zh":["需要OpenAI API密钥","依赖Pandas和NumPy库","仅限Python实现"],"ja":["OpenAI APIキーが必要","PandasとNumPyライブラリに依存","Python専用の実装のみ"],"ko":["OpenAI API 키가 필요함","Pandas 및 NumPy 라이브러리에 의존함","Python 전용 구현만"],"es":["Requiere clave de API de OpenAI","Depende de las bibliotecas Pandas y NumPy","Implementación específica de Python solo"],"fr":["Nécessite une clé d''API OpenAI","Dépend des bibliothèques Pandas et NumPy","Implémentation spécifique à Python uniquement"],"de":["Benötigt OpenAI-API-Schlüssel","Hängt von den Bibliotheken Pandas und NumPy ab","Nur Python-spezifische Implementierung"],"pt":["Exige Chave de API OpenAI","Depende das bibliotecas Pandas e NumPy","Implementação específica do Python apenas"],"ru":["Требует ключ API OpenAI","Зависит от библиотек Pandas и NumPy","Реализация только для Python"],"ar":["يتطلب مفتاح API OpenAI","يعتمد على مكتبات Pandas و NumPy","تنفيذ محدد لبيثون فقط"]},"version":4},"contentHash":"3b24f746c0b438fa28bfdfa90afb0f061f4ffea47d30df0870b779194b3b2d43","qualityScore":48}');
