INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('skysheng7/tech_summary_llm_arena/api-rules', 'api-rules', 'skysheng7', 'tech_summary_llm_arena', 'community', 'api-rules skysheng7 tech_summary_llm_arena community The api-rules skill provides a Python programming assistant for LLM evaluation tasks, utilizing OpenAI API and libraries like Pandas and NumPy. It benefits developers working with LLMs. API 规则为 LLM 评估任务提供了高效的解决方案，使用 Python 编程助手可以简化开发流程 API ルールは LLM 評価タスクに効率的な解決策を提供し、Python プログラミングアシスタントを使用すると開発プロセスを簡素化できます API 규칙은 LLM 평가 태스크에 효율적인 해결책을 제공하며, 파이썬 프로그래밍 어시스턴트를 사용하면 개발 프로세스를 단순화할 수 있습니다 API-Rules es un conjunto de reglas para evaluar LLMs con Python y OpenAI API. Incluye integración con Pandas y NumPy. API-Rules est un ensemble de règles pour évaluer les LLM avec Python et OpenAI API. Il inclut une intégration avec Pandas et NumPy. API-Rules ist ein Satz von Regeln zur Bewertung von LLMs mit Python und OpenAI API. Er umfasst eine Integration mit Pandas und NumPy. A API Rules é uma ferramenta para desenvolvedores que necessitam integrar a OpenAI API em seus projetos, utilizando bibliotecas Python como Pandas e NumPy. ИИ Агенты с помощью API Rules - это инструмент для разработчиков, которые нуждаются в интеграции OpenAI API в свои проекты, используя библиотеки Python, такие как Pandas и NumPy. قواعد واجهة برمجة التطبيقات هي أداة للطورين الذين يحتاجون إلى دمج OpenAI API في مشاريعهم، باستخدام مكتبات Python مثل Pandas و NumPy. how to use api-rules what is api-rules api-rules alternative api-rules vs OpenAI API api-rules install api-rules setup guide LLM evaluation with Python OpenAI API for LLMs api-rules documentation API 规则 LLM 评估 Python 编程助手 OpenAI API Pandas NumPy AI 工具 AI 编程 Utilizes OpenAI API for LLM evaluation Supports file attachments via OpenAI API Leverages Pandas for data manipulation Employs NumPy for numerical computations Provides well-documented and modular Python code api-rules is a Python-based skill for evaluating different Large Language Models (LLMs) using the OpenAI API and supporting libraries.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vuthuonghai-steve/KLTN/server-sent-events', 'community', 'vuthuonghai-steve', 'KLTN', 'vuthuonghai-steve/KLTN', 'server-sent-events', 0, 0, 48, '2026-03-08T01:57:15.477Z', '2026-03-08T02:09:50.593Z', '46743305f42c06aa0ca8194165918a5fe755392bc60a9ef0da5b12ef02d984f0', '{"id":"vuthuonghai-steve/KLTN/server-sent-events","name":"server-sent-events","description":{"en":"Server-sent events enable real-time server-to-client streaming for progress updates, notifications, and live data feeds, benefiting developers who need unidirectional communication.","zh":"Server-Sent Events (SSE) 是一种实时服务器到客户端的数据推送技术，适用于进度更新、通知和直播数据","ja":"Server-Sent Events (SSE) は、サーバーからクライアントへのリアルタイムデータ配信技術です。進度更新、通知、ライブデータに適しています","ko":"서버-SENT 이벤트 (SSE) 는 실시간 서버-클라이언트 데이터 전송 기술로, 진행 상황 업데이트, 알림 및 라이브 데이터에 적합합니다","es":"Server-Sent Events permite actualizaciones en tiempo real y notificaciones en aplicaciones web. Aprende a configurarlo.","fr":"Les Événements Server-Sent permettent des mises à jour en temps réel et des notifications dans les applications web. Découvrez comment les configurer.","de":"Server-Sent Events ermöglichen Echtzeit-Updates und Benachrichtigungen in Webanwendungen. Erfahren Sie, wie Sie es einrichten.","pt":"O Server-Sent Events permite atualizações em tempo real e notificações. Saiba quando usá-lo em vez de WebSockets ou Polling.","ru":"Server-Sent Events позволяет получать обновления в реальном времени и уведомления. Узнайте, когда использовать его вместо WebSockets или Polling для ИИ Агентов.","ar":"أحداث الخادم المرسلة تسمح بالتحديثات في الوقت الفعلي والإشعارات. اعرف متى تستخدمه بدلاً من WebSockets أو Polling للعاملين الإصطناعيين."},"seo":{"title":{"en":"Server-Sent Events: Real-Time Streaming Setup Guide | AI ...","zh":"Server-Sent Events (SSE) 设置指南","ja":"Server-Sent Events (SSE) のベストプラクティス","ko":"서버-SENT 이벤트 (SSE) 구현 가이드","es":"Guía de Configuración de Server-Sent Events para Desarrol...","fr":"Guide de Mise en Place des Événements Server-Sent pour le...","de":"Einrichtungsleitfaden für Server-Sent Events für Entwickler","pt":"Guia de Configuração de Server-Sent Events para Desenvolv...","ru":"Настройка Server-Sent Events: Лучшие Практики для Разрабо...","ar":"دليل إعداد أحداث الخادم المرسلة للعاملين الإصطناعيين"},"description":{"en":"Unlock real-time server-to-client streaming with server-sent events. Learn when to use SSE vs WebSockets and Polling, and get started with our expert guide.","zh":"了解 Server-Sent Events (SSE) 技术，实现实时服务器到客户端的数据推送和更新","ja":"Server-Sent Events (SSE) を使用して、リアルタイムのサーバーからクライアントへのデータ配信を実現します","ko":"서버-SENT 이벤트 (SSE) 를 사용하여 실시간 서버-클라이언트 데이터 전송 및 업데이트 기능을 구현합니다","es":"Aprende a implementar Server-Sent Events para actualizaciones en tiempo real y notificaciones en tus aplicaciones web, con esta guía para desarrolladores de ...","fr":"Découvrez comment mettre en place les Événements Server-Sent pour des mises à jour en temps réel et des notifications dans vos applications web, avec ce guid...","de":"Erfahren Sie, wie Sie Server-Sent Events für Echtzeit-Updates und Benachrichtigungen in Ihren Webanwendungen implementieren, mit diesem Leitfaden für Entwick...","pt":"Aprenda a configurar o Server-Sent Events para atualizações em tempo real e notificações. Descubra as melhores práticas e limitações.","ru":"Узнайте, как настроить Server-Sent Events для обновлений в реальном времени и уведомлений. Изучите лучшие практики и ограничения для ИИ Агентов.","ar":"تعلم كيفية إعداد أحداث الخادم المرسلة للحصول على تحديثات في الوقت الفعلي والإشعارات. اكتشف أفضل الممارسات والقيود للعاملين الإصطناعيين."},"definition":{"en":"Server-sent events is a technology for real-time server-to-client streaming, allowing for progress updates, live feeds, and notifications over HTTP.","zh":"Server-Sent Events (SSE) 是一种允许服务器向客户端推送数据的技术","ja":"Server-Sent Events (SSE) は、サーバーがクライアントにデータをプッシュする技術です","ko":"서버-SENT 이벤트 (SSE) 는 서버가 클라이언트에게 데이터를 푸시하는 기술입니다","es":"Server-Sent Events es una tecnología para streaming de servidor a cliente en tiempo real","fr":"Les Événements Server-Sent sont une technologie de streaming de serveur à client en temps réel","de":"Server-Sent Events ist eine Technologie für Echtzeit-Streaming von Server zu Client","pt":"Server-Sent Events é uma técnica de streaming que permite ao servidor enviar atualizações em tempo real para o cliente.","ru":"Server-Sent Events — это техника потоковой передачи, которая позволяет серверу отправлять обновления в реальном времени клиенту для ИИ Агентов.","ar":"أحداث الخادم المرسلة هي تقنية بث تسمح للخادم بإرسال تحديثات في الوقت الفعلي للعميل."},"features":{"en":["Enables real-time server-to-client streaming for progress updates and live data feeds","Supports unidirectional communication, ideal for server-to-client only use cases","Provides an alternative to WebSockets for simpler, stateless communication","Offers a more efficient solution than Polling for real-time updates","Allows for limited connections, suitable for applications with moderate traffic"," Enables live feeds and notifications over HTTP"],"zh":["支持实时服务器到客户端的数据推送","适用于进度更新、通知和直播数据","与 WebSockets 和 Polling 相比具有不同的使用场景","支持有限连接和单向通信","可以用于实现实时数据更新和推送通知"],"ja":["リアルタイムのサーバーからクライアントへのデータ配信をサポート","進度更新、通知、ライブデータに適しています","WebSockets と Polling と比較して異なる使用シナリオを持っています","有限接続と単方向通信をサポート","リアルタイムデータ更新とプッシュ通知の実現に使用できます"],"ko":["실시간 서버-클라이언트 데이터 전송을 지원","진행 상황 업데이트, 알림 및 라이브 데이터에 적합합니다","WebSockets 와 Polling 과 비교하여 다른 사용 시나리오를 가집니다","제한된 연결과 단방향 통신을 지원","실시간 데이터 업데이트 및 푸시 알림 기능을 구현할 수 있습니다"],"es":["Streaming de servidor a cliente en tiempo real","Actualizaciones de progreso y notificaciones","Compatibilidad con tecnologías como WebSockets y Polling","Uso de SSE para feeds de datos en vivo","Limitaciones de conexiones y uso unidireccional"],"fr":["Streaming de serveur à client en temps réel","Mises à jour de progrès et de notifications","Compatibilité avec des technologies comme WebSockets et Polling","Utilisation de SSE pour les flux de données en direct","Limitations de connexions et utilisation unidirectionnelle"],"de":["Echtzeit-Streaming von Server zu Client","Aktualisierungen von Fortschritten und Benachrichtigungen","Kompatibilität mit Technologien wie WebSockets und Polling","Verwendung von SSE für Live-Daten-Feeds","Begrenzungen von Verbindungen und einrichtungsbedingter Einsatz"],"pt":["Atualizações em tempo real","Notificações","Transmissão unidirecional","Limitações de conexões","Substituição de WebSockets e Polling em alguns casos"],"ru":["Обновления в реальном времени","Уведомления","Унидирекциональная передача","Ограничения соединений","Замена WebSockets и Polling в некоторых случаях для ИИ Агентов"],"ar":["التحديثات في الوقت الفعلي","الإشعارات","بث أحادي الاتجاه","قيود الاتصال","استبدال WebSockets و Polling في بعض الحالات للعاملين الإصطناعيين"]},"keywords":{"en":["how to use server-sent events","server-sent events vs websockets","server-sent events alternative","server-sent events install","server-sent events setup guide","what is server-sent events","server-sent events tutorial","real-time server-to-client streaming","server-sent events vs polling"],"zh":["Server-Sent Events","SSE","实时数据推送","进度更新","通知","直播数据","WebSockets","Polling","AI 에이전트","AI 工具"],"ja":["Server-Sent Events","SSE","リアルタイムデータ配信","進度更新","通知","ライブデータ","WebSockets","Polling","AI エージェント","AI ツール"],"ko":["서버-SENT 이벤트","SSE","실시간 데이터 전송","진행 상황 업데이트","알림","라이브 데이터","WebSockets","Polling","AI 에이전트","AI 도구"],"es":["Server-Sent Events","streaming en tiempo real","actualizaciones de progreso","notificaciones en tiempo real","WebSockets","Polling","desarrollo web","AI Agent","herramientas de desarrollo"],"fr":["Événements Server-Sent","streaming en temps réel","mises à jour de progrès","notifications en temps réel","WebSockets","Polling","développement web","outils d''IA","développement d''applications"],"de":["Server-Sent Events","Echtzeit-Streaming","Aktualisierungen von Fortschritten","Benachrichtigungen in Echtzeit","WebSockets","Polling","Webentwicklung","KI-Tools","Anwendungsentwicklung"],"pt":["Server-Sent Events","atualizações em tempo real","notificações","WebSockets","Polling","desenvolvimento web","tecnologias de streaming","programação de servidor"],"ru":["Server-Sent Events","обновления в реальном времени","уведомления","WebSockets","Polling","разработка веб-приложений","технологии потоковой передачи","программирование сервера для ИИ Агентов"],"ar":["أحداث الخادم المرسلة","التحديثات في الوقت الفعلي","الإشعارات","WebSockets","Polling","تطوير الويب","تقنيات البث","برمجة الخادم للعاملين الإصطناعيين"]}},"owner":"vuthuonghai-steve","repo":"KLTN","repoPath":"vuthuonghai-steve/KLTN","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.477Z","topics":[],"category":"community","skillMd":{"name":"server-sent-events","description":"Server-Sent Events (SSE) for real-time progress updates in Next.js/Vercel. TransformStream patterns, client consumption, progress tracking.","bodyPreview":"# Server-Sent Events (SSE)\n\nReal-time server-to-client streaming for progress updates, notifications, and live data feeds.\n\n## When to Use SSE vs Alternatives\n\n| Technology | Use When | Limitations |\n|------------|----------|-------------|\n| **SSE** | Server → Client only, progress updates, live feeds | Unidirectional, limited connections |\n| **WebSockets** | Bidirectional chat, gaming, collaboration | More complex, stateful |\n| **Polling** | Simple updates, wide compatibility | Inefficient, lat","body":"# Server-Sent Events (SSE)\n\nReal-time server-to-client streaming for progress updates, notifications, and live data feeds.\n\n## When to Use SSE vs Alternatives\n\n| Technology | Use When | Limitations |\n|------------|----------|-------------|\n| **SSE** | Server → Client only, progress updates, live feeds | Unidirectional, limited connections |\n| **WebSockets** | Bidirectional chat, gaming, collaboration | More complex, stateful |\n| **Polling** | Simple updates, wide compatibility | Inefficient, latency |\n| **HTTP Streaming** | Large file downloads | No structured events |\n\n**Choose SSE for:** Progress bars, status updates, notifications, log streaming, live dashboards.\n\n---\n\n## Next.js App Router Implementation\n\n### Server-Side (Route Handler)\n\n```typescript\n// app/api/progress/route.ts\nimport { NextRequest } from ''next/server''\n\ninterface SSEMessage {\n  progress: number\n  message: string\n  status: ''progress'' | ''complete'' | ''error''\n}\n\nexport async function POST(req: NextRequest) {\n  const body = await req.json()\n\n  // SSE Response Headers\n  const headers = {\n    ''Content-Type'': ''text/event-stream'',\n    ''Cache-Control'': ''no-cache'',\n    ''Connection'': ''keep-alive'',\n  }\n\n  // Create transform stream for SSE\n  const stream = new TransformStream()\n  const writer = stream.writable.getWriter()\n  const encoder = new TextEncoder()\n\n  // Helper to send SSE messages\n  async function sendSSE(data: SSEMessage) {\n    await writer.write(encoder.encode(`data: ${JSON.stringify(data)}\\n\\n`))\n  }\n\n  // Execute work with progress updates (async, don''t await)\n  ;(async () => {\n    try {\n      await sendSSE({ progress: 0, message: ''Starting...'', status: ''progress'' })\n\n      // Simulate work with progress updates\n      for (let i = 1; i <= 10; i++) {\n        await doSomeWork(i)\n        await sendSSE({\n          progress: i * 10,\n          message: `Processing step ${i} of 10...`,\n          status: ''progress''\n        })\n      }\n\n      await sendSSE({ progress: 100, message: ''Complete!'', status: ''complete'' })\n    } catch (error) {\n      const message = error instanceof Error ? error.message : ''Unknown error''\n      await sendSSE({ progress: 0, message, status: ''error'' })\n    } finally {\n      await writer.close()\n    }\n  })()\n\n  return new Response(stream.readable, { headers })\n}\n```\n\n### Client-Side Consumption\n\n```typescript\n// React component\n''use client''\n\nimport { useState } from ''react''\n\ninterface ProgressState {\n  progress: number\n  message: string\n  status: ''idle'' | ''progress'' | ''complete'' | ''error''\n}\n\nexport function ProgressTracker() {\n  const [state, setState] = useState<ProgressState>({\n    progress: 0,\n    message: '''',\n    status: ''idle''\n  })\n\n  async function startProcess() {\n    setState({ progress: 0, message: ''Connecting...'', status: ''progress'' })\n\n    const response = await fetch(''/api/progress'', {\n      method: ''POST'',\n      headers: { ''Content-Type'': ''application/json'' },\n      body: JSON.stringify({ /* request data */ })\n    })\n\n    if (!response.body) {\n      setState({ progress: 0, message: ''No response body'', status: ''error'' })\n      return\n    }\n\n    const reader = response.body.getReader()\n    const decoder = new TextDecoder()\n    let buffer = ''''\n\n    while (true) {\n      const { done, value } = await reader.read()\n      if (done) break\n\n      buffer += decoder.decode(value, { stream: true })\n\n      // Parse SSE messages from buffer\n      const lines = buffer.split(''\\n\\n'')\n      buffer = lines.pop() || '''' // Keep incomplete message in buffer\n\n      for (const line of lines) {\n        if (line.startsWith(''data: '')) {\n          const data = JSON.parse(line.slice(6))\n          setState({\n            progress: data.progress,\n            message: data.message,\n            status: data.status\n          })\n        }\n      }\n    }\n  }\n\n  return (\n    <div>\n      <button onClick={startProcess} disabled={state.status === ''progress''}>\n        Start Process\n      </button>\n      <progress value={state.progress} max={100} />\n      <p>{state.message}</p>\n    </div>\n  )\n}\n```\n\n---\n\n## SSE Message Format\n\n### Standard Format\n\n```\ndata: {\"key\": \"value\"}\\n\\n\n```\n\n**Rules:**\n- Each message ends with `\\n\\n` (double newline)\n- Data line starts with `data: `\n- Multiple data lines allowed per message\n- Optional `event:`, `id:`, `retry:` fields\n\n### Named Events\n\n```typescript\n// Server\nasync function sendNamedEvent(event: string, data: object) {\n  await writer.write(encoder.encode(\n    `event: ${event}\\ndata: ${JSON.stringify(data)}\\n\\n`\n  ))\n}\n\n// Send different event types\nawait sendNamedEvent(''progress'', { percent: 50 })\nawait sendNamedEvent(''log'', { message: ''Processing...'' })\nawait sendNamedEvent(''complete'', { result: ''success'' })\n```\n\n```typescript\n// Client with EventSource (for GET endpoints)\nconst source = new EventSource(''/api/events'')\n\nsource.addEventListener(''progress'', (e) => {\n  const data = JSON.parse(e.data)\n  console.log(''Progress:'', data.percent)\n})\n\nsource.addEventListener(''complete'', (e) => {\n  const data = JSON.parse(e.data)\n  console.log(''Done:'', data.result)\n  source.close()\n})\n```\n\n---\n\n## Vercel Considerations\n\n### Critical: Background Task Termination\n\n<EXTREMELY-IMPORTANT>\nOn Vercel, SSE works differently than traditional servers. The function stays alive while the stream is open, but you must manage the lifecycle carefully.\n</EXTREMELY-IMPORTANT>\n\n```typescript\n// CORRECT: Stream keeps function alive until closed\n;(async () => {\n  try {\n    // Do all work here\n    for (const item of items) {\n      await processItem(item)\n      await sendSSE({ progress: calculateProgress(item) })\n    }\n    await sendSSE({ status: ''complete'' })\n  } finally {\n    await writer.close() // MUST close to end function\n  }\n})()\n\nreturn new Response(stream.readable, { headers })\n```\n\n### Timeout Limits\n\n| Plan | Max Duration |\n|------|--------------|\n| Hobby | 10 seconds |\n| Pro | 60 seconds |\n| Enterprise | 900 seconds |\n\nFor long operations, consider:\n- Breaking into smaller chunks\n- Using background jobs (Vercel Cron, external queue)\n- Providing estimated time warnings\n\n---\n\n## Progress Patterns\n\n### Percentage-Based\n\n```typescript\ninterface PercentageProgress {\n  progress: number  // 0-100\n  message: string\n  status: ''progress'' | ''complete'' | ''error''\n}\n\n// Calculate progress for known item count\nconst total = items.length\nfor (let i = 0; i < items.length; i++) {\n  await processItem(items[i])\n  await sendSSE({\n    progress: Math.floor(((i + 1) / total) * 100),\n    message: `Processing ${i + 1} of ${total}...`,\n    status: ''progress''\n  })\n}\n```\n\n### Phase-Based\n\n```typescript\ninterface PhaseProgress {\n  phase: string\n  phaseProgress: number\n  overallProgress: number\n  message: string\n}\n\nconst phases = [\n  { name: ''validate'', weight: 10 },\n  { name: ''process'', weight: 70 },\n  { name: ''finalize'', weight: 20 },\n]\n\n// Track progress across phases\nlet overallProgress = 0\nfor (const phase of phases) {\n  await sendSSE({\n    phase: phase.name,\n    phaseProgress: 0,\n    overallProgress,\n    message: `Starting ${phase.name}...`\n  })\n\n  // Do phase work...\n\n  overallProgress += phase.weight\n}\n```\n\n### Indeterminate with Logs\n\n```typescript\ninterface LogProgress {\n  type: ''log'' | ''warning'' | ''error'' | ''complete''\n  message: string\n  timestamp: string\n}\n\n// For operations where progress can''t be calculated\nawait sendSSE({\n  type: ''log'',\n  message: ''Connecting to external service...'',\n  timestamp: new Date().toISOString()\n})\n```\n\n---\n\n## Error Handling\n\n### Server-Side\n\n```typescript\n;(async () => {\n  try {\n    await riskyOperation()\n    await sendSSE({ status: ''complete'', message: ''Done!'' })\n  } catch (error) {\n    // Always send error to client before closing\n    await sendSSE({\n      status: ''error'',\n      message: error instanceof Error ? error.message : ''Unknown error'',\n      progress: 0\n    })\n  } finally {\n    // ALWAYS close the stream\n    await writer.close()\n  }\n})()\n```\n\n### Client-Side\n\n```typescript\nasync function consumeSSE(url: string, body: object) {\n  try {\n    const response = await fetch(url, {\n      method: ''POST'',\n      body: JSON.stringify(body)\n    })\n\n    if (!response.ok) {\n      throw new Error(`HTTP ${response.status}`)\n    }\n\n    // Process stream...\n  } catch (error) {\n    // Handle network errors, aborts, etc.\n    if (error.name === ''AbortError'') {\n      console.log(''Request cancelled'')\n    } else {\n      console.error(''SSE failed:'', error)\n    }\n  }\n}\n```\n\n### Cancellation\n\n```typescript\n// Client with AbortController\nconst controller = new AbortController()\n\nconst response = await fetch(''/api/progress'', {\n  method: ''POST'',\n  body: JSON.stringify(data),\n  signal: controller.signal\n})\n\n// Cancel button handler\nfunction handleCancel() {\n  controller.abort()\n}\n```\n\n---\n\n## Real-World Example: Batch Processing\n\n```typescript\n// app/api/batch/route.ts\nexport async function POST(req: NextRequest) {\n  const { items } = await req.json()\n\n  const stream = new TransformStream()\n  const writer = stream.writable.getWriter()\n  const encoder = new TextEncoder()\n\n  const sendSSE = async (data: object) => {\n    await writer.write(encoder.encode(`data: ${JSON.stringify(data)}\\n\\n`))\n  }\n\n  ;(async () => {\n    const results = { success: 0, failed: 0, errors: [] as string[] }\n\n    try {\n      await sendSSE({\n        status: ''progress'',\n        progress: 0,\n        message: `Processing ${items.length} items...`\n      })\n\n      for (let i = 0; i < items.length; i++) {\n        try {\n          await processItem(items[i])\n          results.success++\n        } catch (err) {\n          results.failed++\n          results.errors.push(`Item ${i}: ${err.message}`)\n        }\n\n        await sendSSE({\n          status: ''progress'',\n          progress: Math.floor(((i + 1) / items.length) * 100),\n          message: `Processed ${i + 1} of ${items.length}`,\n          results: { ...results }\n        })\n      }\n\n      await sendSSE({\n        status: ''complete'',\n        progress: 100,\n        message: `Complete: ${results.success} succeeded, ${results.failed} failed`,\n        results\n      })\n    } catch (error) {\n      await sendSSE({\n        status: ''error'',\n        message: error instanceof Error ? error.message : ''Batch failed'',\n        results\n      })\n    } finally {\n      await writer.close()\n    }\n  })()\n\n  return new Response(stream.readable, {\n    headers: {\n      ''Content-Type'': ''text/event-stream'',\n      ''Cache-Control'': ''no-cache'',\n      ''Connection'': ''keep-alive'',\n    }\n  })\n}\n```\n\n---\n\n## Quick Reference\n\n```typescript\n// Minimal SSE endpoint\nexport async function POST(req: NextRequest) {\n  const stream = new TransformStream()\n  const writer = stream.writable.getWriter()\n  const encoder = new TextEncoder()\n\n  ;(async () => {\n    await writer.write(encoder.encode(`data: {\"message\":\"Hello\"}\\n\\n`))\n    await writer.close()\n  })()\n\n  return new Response(stream.readable, {\n    headers: { ''Content-Type'': ''text/event-stream'' }\n  })\n}\n```\n\n```typescript\n// Minimal client consumption\nconst res = await fetch(''/api/sse'', { method: ''POST'' })\nconst reader = res.body!.getReader()\nconst decoder = new TextDecoder()\n\nwhile (true) {\n  const { done, value } = await reader.read()\n  if (done) break\n  console.log(decoder.decode(value))\n}\n```\n\n---\n\n## Resources\n\n- [MDN: Server-Sent Events](https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events)\n- [Vercel: Streaming](https://vercel.com/docs/functions/streaming)\n- [Web Streams API](https://developer.mozilla.org/en-US/docs/Web/API/Streams_API)\n"},"lastSynced":"2026-03-08T02:09:50.593Z","agentAnalysis":{"suitability":{"en":"Ideal for Real-Time Update Agents requiring unidirectional server-to-client communication for progress updates and live data feeds.","zh":"适用于需要单向服务器到客户端通信的实时更新代理，用于进度更新和实时数据源。","ja":"リアルタイム更新エージェントが進度更新とライブデータフィードのためにサーバーからクライアントへの単方向通信を必要とする場合に最適です。","ko":"진행 상황 업데이트와 실시간 데이터 피드를 위한 단방향 서버-클라이언트 통신이 필요한 실시간 업데이트 에이전트에 적합합니다.","es":"Ideal para Agentes de Actualización en Tiempo Real que requieren comunicación unidireccional del servidor al cliente para actualizaciones de progreso y fuentes de datos en vivo.","fr":"Idéal pour les Agents de Mise à Jour en Temps Réel nécessitant une communication unidirectionnelle du serveur au client pour les mises à jour de progression et les flux de données en direct.","de":"Ideal für Echtzeit-Update-Agents, die eine unidirektionale Kommunikation vom Server zum Client für Update- und Live-Daten-Feeds benötigen.","pt":"Ideal para Agentes de Atualização em Tempo Real que exigem comunicação unidirecional servidor-cliente para atualizações de progresso e feeds de dados ao vivo.","ru":"Идеально подходит для агентов обновления в реальном времени, требующих одностороннюю связь между сервером и клиентом для обновлений прогресса и живых потоков данных.","ar":"مثالية لعمليات تحديث الوقت الفعلي التي تتطلب اتصالًا أحادي الاتجاه بين الخادم والعميل لتحديثات التقدم وتدفقات البيانات المباشرة."},"recommendation":{"en":"Empowers agents to establish real-time server-sent event streams for progress updates, notifications, and live data feeds using SSE, enabling efficient unidirectional communication and leveraging HTTP protocol for simplicity.","zh":"赋予代理建立实时服务器发送事件流的能力，用于进度更新、通知和实时数据源，使用SSE，实现高效的单向通信，并利用HTTP协议简化通信。","ja":"エージェントがSSEを使用して進度更新、通知、ライブデータフィードのためのリアルタイムサーバーセントイベントストリームを確立できるようにし、効率的な単方向通信を実現し、シンプルさのためにHTTPプロトコルを利用します。","ko":"에이전트가 SSE를 사용하여 진행 상황 업데이트, 알림 및 실시간 데이터 피드 위한 실시간 서버-발송 이벤트 스트림을 설정할 수 있도록 하여 효율적인 단방향 통신을 가능하게 하고, 단순성을 위해 HTTP 프로토콜을 활용합니다.","es":"Habilita a los agentes a establecer flujos de eventos enviados por el servidor en tiempo real para actualizaciones de progreso, notificaciones y fuentes de datos en vivo utilizando SSE, lo que permite una comunicación unidireccional eficiente y aprovecha el protocolo HTTP para la simplicidad.","fr":"Permet aux agents d''établir des flux d''événements envoyés par le serveur en temps réel pour les mises à jour de progression, les notifications et les flux de données en direct en utilisant SSE, ce qui permet une communication unidirectionnelle efficace et tire parti du protocole HTTP pour la simplicité.","de":"Ermöglicht es Agenten, Echtzeit-Server-sent-Event-Streams für Update- und Live-Daten-Feeds mit SSE zu etablieren, wodurch eine effiziente unidirektionale Kommunikation ermöglicht und das HTTP-Protokoll für Einfachheit genutzt wird.","pt":"Habilita os agentes a estabelecer streams de eventos enviados pelo servidor em tempo real para atualizações de progresso, notificações e feeds de dados ao vivo usando SSE, permitindo uma comunicação unidirecional eficiente e aproveitando o protocolo HTTP para simplicidade.","ru":"Наделяет агентов возможностью устанавливать потоки событий, отправляемых сервером в реальном времени, для обновлений прогресса, уведомлений и живых потоков данных, используя SSE, что обеспечивает эффективную одностороннюю связь и использует протокол HTTP для простоты.","ar":"تمكّن الوكلاء من إنشاء تيارات للأحداث المرسلة من الخادم في الوقت الفعلي لتحديثات التقدم والإشعارات وتدفقات البيانات الحية باستخدام SSE، مما يتيح الاتصال الأحادي الاتجاه بفعالية واستغلال بروتوكول HTTP من أجل البساطة."},"useCases":{"en":["Streaming live updates to clients","Sending progress notifications for long-running tasks","Broadcasting real-time data feeds"],"zh":["将实时更新流式传输到客户端","发送长时间运行任务的进度通知","广播实时数据源"],"ja":["クライアントにリアルタイム更新をストリーミングする","長時間実行タスクの進度通知を送信する","リアルタイムデータフィードをブロードキャストする"],"ko":["클라이언트에 실시간 업데이트를 스트리밍하는 것","장시간 실행 작업의 진행 상황 알림을 보내는 것","실시간 데이터 피드를 방송하는 것"],"es":["Transmisión de actualizaciones en vivo a los clientes","Envío de notificaciones de progreso para tareas de larga duración","Difusión de fuentes de datos en tiempo real"],"fr":["Diffusion de mises à jour en direct aux clients","Envoi de notifications de progression pour les tâches à longue durée","Diffusion de flux de données en temps réel"],"de":["Streaming von Live-Updates an Clients","Senden von Fortschrittsbenachrichtigungen für lang laufende Aufgaben","Ausstrahlung von Echtzeit-Daten-Feeds"],"pt":["Transmitir atualizações ao vivo para os clientes","Enviar notificações de progresso para tarefas de longa duração","Transmitir feeds de dados em tempo real"],"ru":["Передача живых обновлений клиентам","Отправка уведомлений о прогрессе для задач длительного выполнения","Трансляция живых потоков данных"],"ar":["بث تحديثات مباشرة للعملاء","إرسال إشعارات التقدم للمهام الطويلة الأجل","بث تدفقات البيانات المباشرة"]},"limitations":{"en":["Unidirectional communication only","Limited connections","Not suitable for bidirectional communication or complex stateful interactions"],"zh":["仅支持单向通信","连接数量有限","不适合双向通信或复杂的有状态交互"],"ja":["単方向通信のみをサポート","接続数が限られている","双方向通信や複雑なステートフルなやりとりには適していない"],"ko":["단방향 통신만 지원","연결 수 제한","양방향 통신 또는 복잡한 상태 저장 상호 작용에는 적합하지 않음"],"es":["Comunicación unidireccional solo","Conexiones limitadas","No adecuado para la comunicación bidireccional o interacciones complejas con estado"],"fr":["Communication unidirectionnelle uniquement","Connexions limitées","Non adapté pour la communication bidirectionnelle ou les interactions complexes à état"],"de":["Nur unidirektionale Kommunikation","Begrenzte Verbindungen","Nicht geeignet für bidirektionale Kommunikation oder komplexe Zustandsinteraktionen"],"pt":["Comunicação unidirecional apenas","Conexões limitadas","Não é adequado para comunicação bidirecional ou interações complexas com estado"],"ru":["Только односторонняя связь","Ограниченные соединения","Не подходит для двусторонней связи или сложных взаимодействий со состоянием"],"ar":["التواصل الأحادي الاتجاه فقط","اتصالات محدودة","غير مناسب للاتصال الثنائي الاتجاه أو التفاعلات المعقدة مع الحالة"]},"version":4},"contentHash":"46743305f42c06aa0ca8194165918a5fe755392bc60a9ef0da5b12ef02d984f0","qualityScore":48}');
