INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vuthuonghai-steve/KLTN/server-sent-events', 'server-sent-events', 'vuthuonghai-steve', 'KLTN', 'community', 'server-sent-events vuthuonghai-steve KLTN community Server-sent events enable real-time server-to-client streaming for progress updates, notifications, and live data feeds, benefiting developers who need unidirectional communication. Server-Sent Events (SSE) 是一种实时服务器到客户端的数据推送技术，适用于进度更新、通知和直播数据 Server-Sent Events (SSE) は、サーバーからクライアントへのリアルタイムデータ配信技術です。進度更新、通知、ライブデータに適しています 서버-SENT 이벤트 (SSE) 는 실시간 서버-클라이언트 데이터 전송 기술로, 진행 상황 업데이트, 알림 및 라이브 데이터에 적합합니다 Server-Sent Events permite actualizaciones en tiempo real y notificaciones en aplicaciones web. Aprende a configurarlo. Les Événements Server-Sent permettent des mises à jour en temps réel et des notifications dans les applications web. Découvrez comment les configurer. Server-Sent Events ermöglichen Echtzeit-Updates und Benachrichtigungen in Webanwendungen. Erfahren Sie, wie Sie es einrichten. O Server-Sent Events permite atualizações em tempo real e notificações. Saiba quando usá-lo em vez de WebSockets ou Polling. Server-Sent Events позволяет получать обновления в реальном времени и уведомления. Узнайте, когда использовать его вместо WebSockets или Polling для ИИ Агентов. أحداث الخادم المرسلة تسمح بالتحديثات في الوقت الفعلي والإشعارات. اعرف متى تستخدمه بدلاً من WebSockets أو Polling للعاملين الإصطناعيين. how to use server-sent events server-sent events vs websockets server-sent events alternative server-sent events install server-sent events setup guide what is server-sent events server-sent events tutorial real-time server-to-client streaming server-sent events vs polling Server-Sent Events SSE 实时数据推送 进度更新 通知 直播数据 WebSockets Polling AI 에이전트 AI 工具 Enables real-time server-to-client streaming for progress updates and live data feeds Supports unidirectional communication, ideal for server-to-client only use cases Provides an alternative to WebSockets for simpler, stateless communication Offers a more efficient solution than Polling for real-time updates Allows for limited connections, suitable for applications with moderate traffic Enables live feeds and notifications over HTTP Server-sent events is a technology for real-time server-to-client streaming, allowing for progress updates, live feeds, and notifications over HTTP.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tcarrio/cursor-voice-plugin/voice-update', 'community', 'tcarrio', 'cursor-voice-plugin', 'tcarrio/cursor-voice-plugin', 'voice-update', 0, 0, 48, '2026-03-08T01:57:15.484Z', '2026-03-08T02:10:00.969Z', '90bfc83a9f4827032d225875b9942efe672b5706b1ab3882a83acecb3eaf7180', '{"id":"tcarrio/cursor-voice-plugin/voice-update","name":"voice-update","description":{"en":"The voice-update skill provides spoken audio feedback using pocket-tts, benefiting developers who need to give brief summaries or status updates. It is ideal for finishing tasks or responding to user requests.","zh":"声更新技能提供使用pocket-tts的语音反馈，适用于任务完成或状态更新时的音频通知","ja":"声更新スキルは、pocket-ttsを使用した音声フィードバックを提供し、タスク完了やステータス更新時の音声通知に適しています","ko":"음성 업데이트 스킬은 pocket-tts를 사용한 음성 피드백을 제공하며, 작업 완료 또는 상태 업데이트시의 오디오 알림에 적합합니다","es":"La habilidad voice-update proporciona retroalimentación de audio hablado utilizando pocket-tts y say script","fr":"La compétence voice-update fournit une rétroaction audio parlée à l''aide de pocket-tts et say script","de":"Die Fähigkeit voice-update bietet gesprochene Audio-Rückmeldung mithilfe von pocket-tts und say script","pt":"O voice-update é uma habilidade que fornece feedback de áudio para os usuários. Ele usa o plugin pocket-tts para fornecer resumos verbais.","ru":"Voice-update - это навык, который предоставляет аудио-обратную связь пользователям. Он использует плагин pocket-tts для предоставления устных суммариев для ИИ Агентов","ar":"صوت التحديث هو مهارة توفر ردود فعل صوتية للمستخدمين. يستخدم إضافة pocket-tts لتزويد ملخصات لفظية لآلات الذكاء الاصطناعي"},"seo":{"title":{"en":"voice-update: Spoken Audio Feedback Setup Guide | AI Agen...","zh":"声更新技能设置指南 - 使用pocket-tts实现语音反馈","ja":"声更新スキルのベストプラクティス - AIエージェントを使用した音声フィードバック","ko":"음성 업데이트 스킬 설정 가이드 - pocket-tts를 사용한 음성 피드백","es":"Guía de configuración de voice-update para agentes de IA","fr":"Guide de mise en œuvre de voice-update pour les outils d''IA","de":"Einrichtungsleitfaden für voice-update in KI-Agents","pt":"Guia de Configuração do voice-update para Ferramentas de IA","ru":"Настройка ИИ Агентов с помощью voice-update","ar":"إعداد وتشغيل صوت التحديث لآلات الذكاء الاصطناعي"},"description":{"en":"Discover how to implement voice-update for AI agents, providing spoken audio feedback with pocket-tts. Learn how to use the say script for concise summaries.","zh":"了解声更新技能的使用方法和技术细节，实现语音反馈和音频通知","ja":"AIエージェントの音声フィードバック機能を実現する声更新スキルの使い方と技術的な詳細","ko":"음성 업데이트 스킬의 사용 방법과 기술적인 상세를 알아보며 음성 피드백과 오디오 알림을 구현하세요","es":"Aprende a implementar voice-update en tus proyectos de agentes de IA con pocket-tts y say script","fr":"Découvrez comment intégrer voice-update dans vos projets d''outils d''IA avec pocket-tts et say script","de":"Erfahren Sie, wie Sie voice-update in Ihre KI-Agents-Projekte mit pocket-tts und say script integrieren","pt":"Aprenda a usar o voice-update para fornecer feedback de áudio para os usuários, incluindo dicas de instalação e uso do plugin pocket-tts","ru":"Узнайте, как использовать voice-update для предоставления аудио-обратной связи пользователям, включая советы по установке и использованию плагина pocket-tts ...","ar":"تعلم كيفية استخدام صوت التحديث لتزويد المستخدمين بردود فعل صوتية، بما في ذلك نصائح حول تثبيت واستخدام الإضافة pocket-tts لآلات الذكاء الاصطناعي"},"definition":{"en":"voice-update is a skill that provides spoken audio feedback using pocket-tts, allowing developers to give concise summaries or status updates through audio.","zh":"声更新技能是一种使用pocket-tts提供语音反馈的技术，用于任务完成或状态更新时的音频通知","ja":"声更新スキルは、pocket-ttsを使用した音声フィードバックを提供する技術であり、タスク完了やステータス更新時の音声通知に使用されます","ko":"음성 업데이트 스킬은 pocket-tts를 사용한 음성 피드백을 제공하는 기술로, 작업 완료 또는 상태 업데이트시의 오디오 알림을 위한 것입니다","es":"Voice-update es una habilidad que proporciona retroalimentación de audio hablado en agentes de IA","fr":"Voice-update est une compétence qui fournit une rétroaction audio parlée dans les outils d''IA","de":"Voice-update ist eine Fähigkeit, die gesprochene Audio-Rückmeldung in KI-Agents bietet","pt":"O voice-update é uma habilidade de IA que fornece resumos verbais para os usuários","ru":"Voice-update - это навык ИИ, который предоставляет устные суммариры пользователям","ar":"صوت التحديث هو مهارة ذكاء اصطناعي توفر ملخصات لفظية للمستخدمين"},"features":{"en":["Uses pocket-tts for spoken audio feedback","Employs the say script for concise summaries","Supports standard install via XDG","Allows for brief spoken summaries in 1-2 sentences","Enables important status updates through audio","Utilizes the say script from the plugin for audio feedback"],"zh":["使用pocket-tts提供语音反馈","适用于任务完成或状态更新时的音频通知","支持标准安装（XDG）","可以调用say脚本实现语音反馈","支持1-2个短句的语音摘要","适用于重要状态更新的音频通知"],"ja":["pocket-ttsを使用した音声フィードバック","タスク完了やステータス更新時の音声通知に適しています","標準インストール（XDG）をサポート","sayスクリプトを呼び出して音声フィードバックを実現","1-2つの短い文の音声サマリーをサポート","重要なステータス更新の音声通知に適しています"],"ko":["pocket-tts를 사용한 음성 피드백","작업 완료 또는 상태 업데이트시의 오디오 알림에 적합합니다","표준 설치（XDG）를 지원","say 스크립트를 호출하여 음성 피드백을 구현","1-2개의 짧은 문장의 음성 요약을 지원","중요한 상태 업데이트의 오디오 알림에 적합합니다"],"es":["Utiliza pocket-tts para proporcionar retroalimentación de audio hablado","Incluye el uso de say script para resumir tareas","Permite resúmenes conversacionales de 1-2 oraciones","Se puede utilizar para tareas finalizadas y actualizaciones de estado importantes","Es compatible con la instalación estándar de XDG"],"fr":["Utilise pocket-tts pour fournir une rétroaction audio parlée","Inclut l''utilisation de say script pour résumer des tâches","Permet des résumés conversationnels de 1-2 phrases","Peut être utilisé pour les tâches terminées et les mises à jour de statut importantes","Est compatible avec l''installation standard de XDG"],"de":["Verwenden von pocket-tts für gesprochene Audio-Rückmeldung","Einschließlich der Verwendung von say script für die Zusammenfassung von Aufgaben","Ermöglicht konversationelle Zusammenfassungen von 1-2 Sätzen","Kann für abgeschlossene Aufgaben und wichtige Status-Updates verwendet werden","Kompatibel mit der Standard-Installation von XDG"],"pt":["Uso do plugin pocket-tts para fornecer resumos verbais","Integração com o script say para fornecer feedback de áudio","Compatibilidade com instalação padrão XDG","Fornecimento de resumos breves e conversacionais","Uso para fornecer atualizações de status importantes"],"ru":["Использование плагина pocket-tts для предоставления устных суммариев","Интеграция со скриптом say для предоставления аудио-обратной связи","Совместимость со стандартной установкой XDG для ИИ Агентов","Предоставление кратких и беседных суммариев","Использование для предоставления важных обновлений статуса"],"ar":["استخدام إضافة pocket-tts لتزويد ملخصات لفظية","التكامل مع سكريبت say لتزويد ردود فعل صوتية","التوافق مع التثبيت المعياري XDG لآلات الذكاء الاصطناعي","تزويد ملخصات قصيرة ومحادثية","استخدام لتزويد تحديثات حالة مهمة"]},"keywords":{"en":["how to use voice-update","what is voice-update","voice-update alternative","voice-update vs text-to-speech","voice-update install","voice-update setup guide","pocket-tts integration","say script usage"],"zh":["声更新技能","pocket-tts","语音反馈","音频通知","AI工具","任务完成","状态更新","音声通知","say脚本","标准安装"],"ja":["声更新スキル","pocket-tts","音声フィードバック","音声通知","AIエージェント","タスク完了","ステータス更新","音声通知","sayスクリプト","標準インストール"],"ko":["음성 업데이트 스킬","pocket-tts","음성 피드백","오디오 알림","AI工具","작업 완료","상태 업데이트","오디오 알림","say 스크립트","표준 설치"],"es":["agentes de IA","voice-update","pocket-tts","say script","retroalimentación de audio hablado","desarrollo de agentes de IA","integración de voice-update","configuración de voice-update"],"fr":["outils d''IA","voice-update","pocket-tts","say script","rétroaction audio parlée","développement d''outils d''IA","intégration de voice-update","configuration de voice-update"],"de":["KI-Agents","voice-update","pocket-tts","say script","gesprochene Audio-Rückmeldung","Entwicklung von KI-Agents","Integration von voice-update","Konfiguration von voice-update"],"pt":["voice-update","pocket-tts","script say","instalação XDG","ferramentas de IA","áudio feedback","resumos verbais","desenvolvimento de IA"],"ru":["voice-update","pocket-tts","скрипт say","установка XDG","ИИ Агенты","аудио-обратная связь","устные суммариры","разработка ИИ"],"ar":["صوت التحديث","pocket-tts","سكريبت say","تثبيت XDG","آلات الذكاء الاصطناعي","ردود فعل صوتية","ملخصات لفظية","تطوير الذكاء الاصطناعي"]}},"owner":"tcarrio","repo":"cursor-voice-plugin","repoPath":"tcarrio/cursor-voice-plugin","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.484Z","topics":[],"category":"community","skillMd":{"name":"voice-update","description":"Use when the agent should give a spoken voice update—e.g. after finishing a task or when the user asks for a spoken summary. Speaks a short summary via pocket-tts.","bodyPreview":"# Voice Update Skill\n\nProvide spoken audio feedback using pocket-tts (say script).\n\n## When to Use\n\n- When finishing a task and you want to give a brief spoken summary\n- When the user asks for a spoken summary or voice update\n- For important status updates that benefit from audio\n\n## How to Use\n\n1. Summarize what was accomplished in 1–2 short, conversational sentences.\n2. Call the say script with that summary.\n\n## Calling the Say Script\n\nUse the say script from the plugin. Standard install (XDG)","body":"# Voice Update Skill\n\nProvide spoken audio feedback using pocket-tts (say script).\n\n## When to Use\n\n- When finishing a task and you want to give a brief spoken summary\n- When the user asks for a spoken summary or voice update\n- For important status updates that benefit from audio\n\n## How to Use\n\n1. Summarize what was accomplished in 1–2 short, conversational sentences.\n2. Call the say script with that summary.\n\n## Calling the Say Script\n\nUse the say script from the plugin. Standard install (XDG): `$XDG_DATA_HOME/voice-plugin-cursor/scripts/say` (default `~/.local/share/voice-plugin-cursor/scripts/say`). If `VOICE_PLUGIN_ROOT` is set, use that.\n\n```bash\n\"${VOICE_PLUGIN_ROOT:-$HOME/.local/share/voice-plugin-cursor}/scripts/say\" \"Your summary here\"\n```\n\nExamples:\n\n```bash\n~/.local/share/voice-plugin-cursor/scripts/say \"I''ve fixed the bug in the login handler and added the unit tests.\"\n~/.local/share/voice-plugin-cursor/scripts/say --voice azure \"Task completed successfully.\"\n```\n\n## Summary Guidelines\n\n- 1–2 sentences max; conversational, not robotic\n- Match the user''s tone\n- Focus on what was accomplished; avoid code, paths, and jargon\n- Examples: \"I''ve updated the config and restarted the server.\" / \"Tests are passing; I fixed three type errors.\"\n\n## Notes\n\n- The say script can auto-start the pocket-tts server (first run may take ~30–60s).\n- Requires `uvx` and `afplay` (macOS), `aplay` or `paplay` (Linux), or similar.\n"},"lastSynced":"2026-03-08T02:10:00.969Z","agentAnalysis":{"suitability":{"en":"Ideal for Conversational Agents needing to provide spoken audio feedback using pocket-tts.","zh":"适用于需要使用 pocket-tts 提供语音音频反馈的对话式代理","ja":"pocket-tts を使用して音声オーディオフィードバックを提供する必要がある会話エージェントに最適","ko":"pocket-tts를 사용하여 음성 오디오 피드백을 제공해야 하는 대화형 에이전트에 적합","es":"Ideal para Agentes Conversacionales que necesitan proporcionar retroalimentación de audio hablado utilizando pocket-tts.","fr":"Idéal pour les Agents Conversationnels ayant besoin de fournir une rétroaction audio parlée en utilisant pocket-tts.","de":"Ideal für Conversational Agents, die eine gesprochene Audio-Rückmeldung mithilfe von pocket-tts benötigen.","pt":"Ideal para Agentes de Conversação que precisam fornecer feedback de áudio falado usando pocket-tts.","ru":"Идеально для Конверсационных Агентов, которым необходимо предоставлять устную аудио-обратную связь, используя pocket-tts.","ar":"مثالي لوكلاء المحادثة الذين يحتاجون إلى تقديم تعليمات صوتية منطوقة باستخدام pocket-tts."},"recommendation":{"en":"Empowers agents to deliver brief spoken summaries or status updates using the say script, enhancing user experience with audio feedback and leveraging pocket-tts for seamless integration.","zh":"赋予代理提供使用 say 脚本的简短语音摘要或状态更新的能力，通过音频反馈增强用户体验，并利用 pocket-tts 实现无缝集成","ja":"say スクリプトを使用して簡単な音声サマリーまたはステータス更新を提供する機能をエージェントに与え、音声フィードバックでユーザーエクスペリエンスを向上させ、pocket-tts でシームレスな統合を実現","ko":"say 스크립트를 사용하여 간단한 음성 요약 또는 상태 업데이트를 제공할 수 있는 기능을 에이전트에 부여하여 음성 피드백으로 사용자 경험을 향상시키고 pocket-tts로 무缝한 통합을 구현","es":"Habilita a los agentes a entregar resúmenes hablados breves o actualizaciones de estado utilizando el script say, mejorando la experiencia del usuario con retroalimentación de audio y aprovechando pocket-tts para una integración sin problemas.","fr":"Permet aux agents de fournir des résumés parlés courts ou des mises à jour de statut en utilisant le script say, améliorant l''expérience utilisateur avec une rétroaction audio et exploitant pocket-tts pour une intégration sans heurts.","de":"Ermächtigt die Agenten, kurze gesprochene Zusammenfassungen oder Statusupdates mithilfe des say-Skripts bereitzustellen, wodurch die Benutzererfahrung durch Audio-Rückmeldungen verbessert und pocket-tts für eine nahtlose Integration genutzt wird.","pt":"Habilita os agentes a fornecer resumos falados breves ou atualizações de status, melhorando a experiência do usuário com feedback de áudio e utilizando pocket-tts para integração transparente.","ru":"Наделяет агентов возможностью предоставлять краткие устные сводки или обновления статуса, улучшая пользовательский опыт с помощью аудио-обратной связи и используя pocket-tts для бесшовной интеграции.","ar":"يُجهز الوكلاء لتزويد ملخصات صوتية منطوقة قصيرة أو تحديثات حالة، مما يعزز تجربة المستخدم مع تعليمات صوتية ويتوافق مع pocket-tts من أجل التكامل السلس."},"useCases":{"en":["Providing spoken task completion summaries","Responding to user requests with voice updates","Delivering important status updates via audio"],"zh":["提供语音任务完成摘要","使用语音更新响应用户请求","通过音频提供重要状态更新"],"ja":["音声タスク完了サマリーを提供","音声更新でユーザー要求に応答","音声で重要なステータス更新を提供"],"ko":["음성 작업 완료 요약을 제공","음성 업데이트로 사용자 요청에 응답","음성으로 중요한 상태 업데이트를 제공"],"es":["Proporcionar resúmenes de tareas completadas habladas","Responder a solicitudes de usuarios con actualizaciones de voz","Entregar actualizaciones importantes de estado a través de audio"],"fr":["Fournir des résumés de tâches complètes parlés","Répondre aux demandes des utilisateurs avec des mises à jour vocales","Fournir des mises à jour importantes de statut via l''audio"],"de":["Bereitstellen von gesprochenen Zusammenfassungen abgeschlossener Aufgaben","Antworten auf Benutzeranfragen mit Sprachupdates","Bereitstellen wichtiger Statusupdates über Audio"],"pt":["Fornecer resumos de conclusão de tarefas falados","Responder a solicitações do usuário com atualizações de voz","Entregar atualizações de status importantes via áudio"],"ru":["Предоставление устных сводок по завершению задач","Ответ на запросы пользователей голосовыми обновлениями","Доставка важных обновлений статуса через аудио"],"ar":["توفير ملخصات إكمال المهام الصوتية المنطوقة","الاستجابة لطلبات المستخدم bằng تحديثات صوتية","توصيل تحديثات حالة هامة من خلال الصوت"]},"limitations":{"en":["Requires pocket-tts installation","Dependent on the say script functionality"],"zh":["需要安装 pocket-tts","依赖 say 脚本功能"],"ja":["pocket-tts のインストールが必要","say スクリプトの機能に依存"],"ko":["pocket-tts 설치가 필요","say 스크립트 기능에 의존"],"es":["Requiere la instalación de pocket-tts","Depende de la funcionalidad del script say"],"fr":["Nécessite l''installation de pocket-tts","Dépend de la fonctionnalité du script say"],"de":["Erfordert die Installation von pocket-tts","Hängt von der Funktionalität des say-Skripts ab"],"pt":["Exige instalação do pocket-tts","Dependente da funcionalidade do script say"],"ru":["Требует установки pocket-tts","Зависит от функциональности скрипта say"],"ar":["يتطلب تثبيت pocket-tts","يعتمد على وظيفة سكريبت say"]},"version":4},"contentHash":"90bfc83a9f4827032d225875b9942efe672b5706b1ab3882a83acecb3eaf7180","qualityScore":48}');
