INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tcarrio/cursor-voice-plugin/voice-update', 'voice-update', 'tcarrio', 'cursor-voice-plugin', 'community', 'voice-update tcarrio cursor-voice-plugin community The voice-update skill provides spoken audio feedback using pocket-tts, benefiting developers who need to give brief summaries or status updates. It is ideal for finishing tasks or responding to user requests. 声更新技能提供使用pocket-tts的语音反馈，适用于任务完成或状态更新时的音频通知 声更新スキルは、pocket-ttsを使用した音声フィードバックを提供し、タスク完了やステータス更新時の音声通知に適しています 음성 업데이트 스킬은 pocket-tts를 사용한 음성 피드백을 제공하며, 작업 완료 또는 상태 업데이트시의 오디오 알림에 적합합니다 La habilidad voice-update proporciona retroalimentación de audio hablado utilizando pocket-tts y say script La compétence voice-update fournit une rétroaction audio parlée à l''aide de pocket-tts et say script Die Fähigkeit voice-update bietet gesprochene Audio-Rückmeldung mithilfe von pocket-tts und say script O voice-update é uma habilidade que fornece feedback de áudio para os usuários. Ele usa o plugin pocket-tts para fornecer resumos verbais. Voice-update - это навык, который предоставляет аудио-обратную связь пользователям. Он использует плагин pocket-tts для предоставления устных суммариев для ИИ Агентов صوت التحديث هو مهارة توفر ردود فعل صوتية للمستخدمين. يستخدم إضافة pocket-tts لتزويد ملخصات لفظية لآلات الذكاء الاصطناعي how to use voice-update what is voice-update voice-update alternative voice-update vs text-to-speech voice-update install voice-update setup guide pocket-tts integration say script usage 声更新技能 pocket-tts 语音反馈 音频通知 AI工具 任务完成 状态更新 音声通知 say脚本 标准安装 Uses pocket-tts for spoken audio feedback Employs the say script for concise summaries Supports standard install via XDG Allows for brief spoken summaries in 1-2 sentences Enables important status updates through audio Utilizes the say script from the plugin for audio feedback voice-update is a skill that provides spoken audio feedback using pocket-tts, allowing developers to give concise summaries or status updates through audio.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yohan-work/testsyncrepo/documentation-templates', 'community', 'yohan-work', 'testsyncrepo', 'yohan-work/testsyncrepo', 'documentation-templates', 0, 0, 48, '2026-03-08T01:57:15.486Z', '2026-03-08T02:10:04.931Z', '6b3f56036c08589c39f74914bbf801b299b72da0a73c082fecc698981a04d856', '{"id":"yohan-work/testsyncrepo/documentation-templates","name":"documentation-templates","description":{"en":"The documentation-templates skill provides a structured approach to initializing projects, benefiting developers by streamlining the setup process with tools like Node.js and npm.","zh":"Documentation-Templates是一个用于提高开发效率和代码质量的工具，提供设置指南和最佳实践","ja":"ドキュメントテンプレートは、開発効率とコード品質を向上させるためのAIエージェントの機能です","ko":"문서 템플릿은 개발 효율성을 높이고 코드 품질을 향상시키는 데 도움이 되는 툴입니다","es":"La plantilla de documentación es una herramienta esencial para los desarrolladores que buscan crear documentación clara y concisa para sus proyectos","fr":"Le modèle de documentation est un outil essentiel pour les développeurs qui cherchent à créer une documentation claire et concise pour leurs projets","de":"Die Dokumentationsvorlage ist ein wichtiges Werkzeug für Entwickler, die klare und präzise Dokumentationen für ihre Projekte erstellen möchten","pt":"O modelo de documentação é uma ferramenta essencial para desenvolvedores, permitindo a criação de documentação de projetos de forma eficiente","ru":"Шаблон документации - это важнейший инструмент для разработчиков, позволяющий создавать документацию проектов эффективно","ar":"قالب الوثائق هو أداة أساسية للمطورين، مما يسمح بإنشاء وثائق مشاريع بطريقة فعالة"},"seo":{"title":{"en":"Documentation-Templates: Setup Guide for AI Agents","zh":"文档模板设置指南 - 了解Documentation-Templates","ja":"ドキュメントテンプレートのベストプラクティス - AIエージェントの活用","ko":"문서 템플릿 설정 가이드 - Documentation-Templates을 사용한 개발 효율화","es":"Plantilla de documentación: Guía de configuración para de...","fr":"Modèle de documentation: Guide de mise en place pour les ...","de":"Dokumentationsvorlage: Einrichtungsanleitung für Entwickler","pt":"Guia de Configuração de Modelos de Documentação","ru":"Настройка шаблонов документации: лучшие практики для ИИ А...","ar":"دليل إعداد قوالب الوثائق: أفضل الممارسات للعمليات"},"description":{"en":"Discover how to utilize documentation-templates for efficient project setup. Learn to clone repos, install dependencies, and run dev servers with ease.","zh":"了解如何使用Documentation-Templates来提高开发效率和代码质量，包括设置指南和最佳实践","ja":"AIエージェントのドキュメントテンプレート機能を活用して、開発効率とコード品質を向上させる方法を紹介します","ko":"문서 템플릿 설정 가이드와 ベストプラクティス를 통해 개발 효율성을 높이고 코드 품질을 향상시키는 방법을 알아보세요","es":"Aprende a configurar y utilizar plantillas de documentación para tus proyectos de desarrollo con Next.js, TypeScript y Tailwind CSS","fr":"Découvrez comment configurer et utiliser des modèles de documentation pour vos projets de développement avec Next.js, TypeScript et Tailwind CSS","de":"Erfahren Sie, wie Sie Dokumentationsvorlagen für Ihre Entwicklungsprojekte mit Next.js, TypeScript und Tailwind CSS konfigurieren und verwenden","pt":"Aprenda a configurar modelos de documentação para seus projetos de desenvolvimento com Next.js, TypeScript e Tailwind CSS","ru":"Узнайте, как настроить шаблоны документации для ваших проектов разработки с помощью ИИ Агентов и технологий seperti Next.js","ar":"تعرف على كيفية إعداد قوالب الوثائق لعمليات تطويرك باستخدام التكنولوجيا مثل Next.js و Tailwind CSS"},"definition":{"en":"Documentation-templates is a skill designed to facilitate project initialization through standardized templates and workflows.","zh":"Documentation-Templates是一种用于生成和管理文档的模板工具","ja":"ドキュメントテンプレートは、文書を生成および管理するためのテンプレート機能です","ko":"문서 템플릿은 문서를 생성하고 관리하는 데 사용되는 템플릿 툴입니다","es":"Una plantilla de documentación es un modelo predefinido que ayuda a los desarrolladores a crear documentación para sus proyectos de software","fr":"Un modèle de documentation est un modèle prédéfini qui aide les développeurs à créer une documentation pour leurs projets de logiciel","de":"Eine Dokumentationsvorlage ist ein vordefinierter Rahmen, der Entwicklern hilft, Dokumentationen für ihre Softwareprojekte zu erstellen","pt":"Um modelo de documentação é um conjunto de diretrizes e estruturas para criar documentação de projetos de software","ru":"Шаблон документации - это набор руководств и структур для создания документации программных проектов","ar":"قالب الوثائق هو مجموعة من الإرشادات والهياكل لإنشاء وثائق مشاريع البرمجيات"},"features":{"en":["Generates README.md templates with project descriptions and feature lists","Supports project setup with Node.js 18+ and package managers like npm or yarn","Utilizes Next.js 14, TypeScript, and Tailwind CSS for robust project structures","Enables environment configuration through .env files","Allows for local development server setup with npm run dev"],"zh":["支持Next.js 14","支持TypeScript","支持Tailwind CSS","提供README.md模板","支持Node.js 18+","支持npm和yarn"],"ja":["Next.js 14に対応","TypeScriptに対応","Tailwind CSSに対応","README.mdテンプレートを提供","Node.js 18+に対応","npmとyarnに対応"],"ko":["Next.js 14 지원","TypeScript 지원","Tailwind CSS 지원","README.md 템플릿 제공","Node.js 18+ 지원","npm과 yarn 지원"],"es":["Compatibilidad con Next.js 14","Soporte para TypeScript","Integración con Tailwind CSS","Estructura de proyecto personalizable","Guía de inicio rápido para desarrolladores"],"fr":["Compatibilité avec Next.js 14","Prise en charge de TypeScript","Intégration avec Tailwind CSS","Structure de projet personnalisable","Guide de démarrage rapide pour les développeurs"],"de":["Kompatibilität mit Next.js 14","Unterstützung für TypeScript","Integration mit Tailwind CSS","Anpassbare Projektstruktur","Schnellstart-Anleitung für Entwickler"],"pt":["Compatibilidade com Next.js 14","Suporte a TypeScript","Integração com Tailwind CSS","Estrutura de projeto personalizável","Instalação e configuração simplificadas"],"ru":["Совместимость с Next.js 14","Поддержка TypeScript","Интеграция с Tailwind CSS","Настраиваемая структура проекта","Упрощенная установка и настройка"],"ar":["التوافق مع Next.js 14","دعم TypeScript","التكامل مع Tailwind CSS","هيكل مشروع مخصص","تثبيت وضبط مبسط"]},"keywords":{"en":["how to use documentation-templates","documentation-templates setup guide","Node.js project templates","npm install documentation-templates","documentation-templates alternative","Next.js project setup"],"zh":["文档模板","Documentation-Templates","开发效率","代码质量","Next.js","TypeScript","Tailwind CSS","README.md","Node.js","npm","yarn"],"ja":["ドキュメントテンプレート","AIエージェント","開発効率","コード品質","Next.js","TypeScript","Tailwind CSS","README.md","Node.js","npm","yarn"],"ko":["문서 템플릿","Documentation-Templates","개발 효율성","코드 품질","Next.js","TypeScript","Tailwind CSS","README.md","Node.js","npm","yarn"],"es":["plantilla de documentación","documentación de software","Next.js","TypeScript","Tailwind CSS","desarrollo de software","guias de configuración"],"fr":["modèle de documentation","documentation de logiciel","Next.js","TypeScript","Tailwind CSS","développement de logiciel","guides de configuration"],"de":["Dokumentationsvorlage","Software-Dokumentation","Next.js","TypeScript","Tailwind CSS","Software-Entwicklung","Konfigurationsanleitungen"],"pt":["modelos de documentação","Next.js","TypeScript","Tailwind CSS","desenvolvimento de software","documentação de projetos","guias de configuração"],"ru":["шаблоны документации","ИИ Агенты","Next.js","TypeScript","Tailwind CSS","разработка программного обеспечения","документация проектов","настройка шаблонов"],"ar":["قوالب الوثائق","العمليات","Next.js","TypeScript","Tailwind CSS","تطوير البرمجيات","وثائق المشاريع","إعداد قوالب"]}},"owner":"yohan-work","repo":"testsyncrepo","repoPath":"yohan-work/testsyncrepo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.486Z","topics":[],"category":"community","skillMd":{"name":"documentation-templates","description":"프로젝트 문서 작성 템플릿을 제공합니다. README, API 문서, 컴포넌트 문서 작성 시 사용합니다. documentation-writer 에이전트와 함께 사용하세요.","bodyPreview":"# 문서 템플릿 스킬\n\n## README.md 템플릿\n\n```markdown\n# 프로젝트명\n\n프로젝트 한 줄 설명\n\n## 주요 기능\n\n- 기능 1\n- 기능 2\n- 기능 3\n\n## 기술 스택\n\n- Next.js 14\n- TypeScript\n- Tailwind CSS\n\n## 시작하기\n\n### 요구사항\n\n- Node.js 18+\n- npm 또는 yarn\n\n### 설치\n\n\\`\\`\\`bash\ngit clone https://github.com/user/repo.git\ncd repo\nnpm install\n\\`\\`\\`\n\n### 환경 설정\n\n\\`\\`\\`bash\ncp .env.example .env.local\n# .env.local 파일 수정\n\\`\\`\\`\n\n### 실행\n\n\\`\\`\\`bash\nnpm run dev\n\\`\\`\\`\n\nhttp://localhost:3000 에서 확인\n\n## 프로젝트 구조\n\n\\`\\`\\`\napp/\n├── components/   # 재사용 컴포넌트\n├── api/","body":"# 문서 템플릿 스킬\n\n## README.md 템플릿\n\n```markdown\n# 프로젝트명\n\n프로젝트 한 줄 설명\n\n## 주요 기능\n\n- 기능 1\n- 기능 2\n- 기능 3\n\n## 기술 스택\n\n- Next.js 14\n- TypeScript\n- Tailwind CSS\n\n## 시작하기\n\n### 요구사항\n\n- Node.js 18+\n- npm 또는 yarn\n\n### 설치\n\n\\`\\`\\`bash\ngit clone https://github.com/user/repo.git\ncd repo\nnpm install\n\\`\\`\\`\n\n### 환경 설정\n\n\\`\\`\\`bash\ncp .env.example .env.local\n# .env.local 파일 수정\n\\`\\`\\`\n\n### 실행\n\n\\`\\`\\`bash\nnpm run dev\n\\`\\`\\`\n\nhttp://localhost:3000 에서 확인\n\n## 프로젝트 구조\n\n\\`\\`\\`\napp/\n├── components/   # 재사용 컴포넌트\n├── api/          # API 라우트\n├── (routes)/     # 페이지 라우트\n└── lib/          # 유틸리티\n\\`\\`\\`\n\n## 라이선스\n\nMIT License\n```\n\n## 컴포넌트 문서 템플릿\n\n```markdown\n# ComponentName\n\n컴포넌트 설명\n\n## Props\n\n| Prop | Type | Default | Description |\n|------|------|---------|-------------|\n| required | string | - | 필수 prop 설명 |\n| optional | number | 0 | 선택 prop 설명 |\n\n## 사용 예시\n\n\\`\\`\\`tsx\nimport { ComponentName } from ''@/components/ComponentName'';\n\n<ComponentName required=\"value\" optional={10} />\n\\`\\`\\`\n\n## 변형\n\n### Primary\n\n\\`\\`\\`tsx\n<ComponentName variant=\"primary\" />\n\\`\\`\\`\n\n### Secondary\n\n\\`\\`\\`tsx\n<ComponentName variant=\"secondary\" />\n\\`\\`\\`\n```\n\n## API 문서 템플릿\n\n```markdown\n# API 엔드포인트\n\n## POST /api/auth/login\n\n사용자 로그인\n\n### Request\n\n\\`\\`\\`json\n{\n  \"email\": \"user@example.com\",\n  \"password\": \"password123\"\n}\n\\`\\`\\`\n\n### Response\n\n**Success (200)**\n\\`\\`\\`json\n{\n  \"success\": true,\n  \"data\": {\n    \"token\": \"jwt-token\",\n    \"user\": { \"id\": 1, \"email\": \"user@example.com\" }\n  }\n}\n\\`\\`\\`\n\n**Error (401)**\n\\`\\`\\`json\n{\n  \"success\": false,\n  \"error\": \"Invalid credentials\"\n}\n\\`\\`\\`\n```\n\n## CHANGELOG 템플릿\n\n```markdown\n# Changelog\n\n## [1.0.0] - 2025-01-28\n\n### Added\n- 새로운 기능\n\n### Changed\n- 변경된 기능\n\n### Fixed\n- 수정된 버그\n\n### Removed\n- 제거된 기능\n```\n\n## 사용 예시\n\n```\ndocumentation-writer 에이전트로 이 프로젝트의 README를 작성해줘\n```\n"},"lastSynced":"2026-03-08T02:10:04.931Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents needing streamlined project initialization with Node.js and npm.","zh":"适用于需要使用 Node.js 和 npm 进行项目初始化的 Developer Agents。","ja":"Node.js と npm を使用してプロジェクトの初期化をストリームライン化する必要がある Developer Agents に適しています。","ko":"Node.js와 npm을 사용하여 프로젝트 초기화를 간소화해야 하는 Developer Agents에 적합합니다.","es":"Ideal para Agentes de Desarrollador que necesitan una inicialización de proyecto optimizada con Node.js y npm.","fr":"Idéal pour les agents de développement ayant besoin d''une initialisation de projet rationalisée avec Node.js et npm.","de":"Ideal für Entwicklungsagenten, die eine optimierte Projektinitialisierung mit Node.js und npm benötigen.","pt":"Ideal para Agentes de Desenvolvedor que precisam de inicialização de projeto otimizada com Node.js e npm.","ru":"Идеально для агентов разработчиков, которым требуется оптимизированная инициализация проекта с Node.js и npm.","ar":"مثالي 위해 وكلاء المطورين الذين يحتاجون إلى تهيئة مشروع مجدولة مع Node.js و npm."},"recommendation":{"en":"Empowers agents to generate standardized project documentation using Markdown, including README.md templates with features like project descriptions, technical stacks, and setup instructions, leveraging tools such as Next.js, TypeScript, and Tailwind CSS.","zh":"赋予代理生成使用 Markdown 的标准化项目文档的能力，包括 README.md 模板，具有项目描述、技术栈和设置说明等功能，利用诸如 Next.js、TypeScript 和 Tailwind CSS 之类的工具。","ja":"エージェントに、Markdown を使用した標準化されたプロジェクトのドキュメントを生成する能力を付与します。README.md テンプレートを含み、プロジェクトの説明、技術スタック、設定手順などの機能があり、Next.js、TypeScript、Tailwind CSS などのツールを利用します。","ko":"에이전트가 Markdown를 사용하여 표준화된 프로젝트 문서를 생성할 수 있는 능력을 부여합니다. README.md 템플릿을 포함하며, 프로젝트 설명, 기술 스택, 설정 지침 등의 기능을 가지며, Next.js, TypeScript, Tailwind CSS 등의 도구를 활용합니다.","es":"Habilita a los agentes a generar documentación de proyecto estandarizada utilizando Markdown, incluyendo plantillas de README.md con características como descripciones de proyectos, pilas técnicas y instrucciones de configuración, aprovechando herramientas como Next.js, TypeScript y Tailwind CSS.","fr":"Permet aux agents de générer une documentation de projet standardisée en utilisant Markdown, y compris des modèles de README.md avec des fonctionnalités comme les descriptions de projets, les piles techniques et les instructions de configuration, en exploitant des outils tels que Next.js, TypeScript et Tailwind CSS.","de":"Ermächtigt Agenten, standardisierte Projektunterlagen mit Markdown zu erstellen, einschließlich README.md-Vorlagen mit Funktionen wie Projektbeschreibungen, technischen Stacks und Einrichtungsanweisungen, unter Nutzung von Tools wie Next.js, TypeScript und Tailwind CSS.","pt":"Permite que os agentes gerem documentação de projeto padronizada usando Markdown, incluindo modelos de README.md com recursos como descrições de projeto, pilhas técnicas e instruções de configuração, aproveitando ferramentas como Next.js, TypeScript e Tailwind CSS.","ru":"Наделяет агентов возможностью генерировать стандартизированную документацию проекта с использованием Markdown, включая шаблоны README.md с функциями, такими как описания проекта, технологические стеки и инструкции по настройке, используя инструменты, такие как Next.js, TypeScript и Tailwind CSS.","ar":"تمكين الوكلاء من生成 توثيق مشروع معياري باستخدام Markdown، بما في ذلك قوالب README.md مع ميزات مثل وصف المشروع والكتل الفنية وتعليمات الإعداد، مستفيدة من أدوات مثل Next.js و TypeScript و Tailwind CSS."},"useCases":{"en":["Automating project setup with git clone and npm install","Generating technical documentation for projects using Node.js 18+ and npm or yarn","Streamlining environment setup with .env.example and .env.local files"],"zh":["使用 git clone 和 npm install 自动化项目设置","使用 Node.js 18+ 和 npm 或 yarn 为项目生成技术文档","使用 .env.example 和 .env.local 文件简化环境设置"],"ja":["git clone と npm install を使用してプロジェクトの設定を自動化する","Node.js 18+ と npm または yarn を使用してプロジェクトの技術文書を生成する",".env.example と .env.local ファイルを使用して環境設定をストリームライン化する"],"ko":["git clone과 npm install을 사용하여 프로젝트 설정을 자동화하는 것","Node.js 18+와 npm 또는 yarn을 사용하여 프로젝트 기술 문서를 생성하는 것",".env.example와 .env.local 파일을 사용하여 환경 설정을 간소화하는 것"],"es":["Automatización de la configuración del proyecto con git clone y npm install","Generación de documentación técnica para proyectos que utilizan Node.js 18+ y npm o yarn","Optimización de la configuración del entorno con archivos .env.example y .env.local"],"fr":["Automatisation de la configuration du projet avec git clone et npm install","Génération de documentation technique pour les projets utilisant Node.js 18+ et npm ou yarn","Rationalisation de la configuration de l''environnement avec des fichiers .env.example et .env.local"],"de":["Automatisierung der Projektkonfiguration mit git clone und npm install","Erstellung von technischer Dokumentation für Projekte, die Node.js 18+ und npm oder yarn verwenden","Optimierung der Umgebungskonfiguration mit .env.example- und .env.local-Dateien"],"pt":["Automatizar configuração do projeto com git clone e npm install","Gerar documentação técnica para projetos que usam Node.js 18+ e npm ou yarn","Otimizar configuração do ambiente com arquivos .env.example e .env.local"],"ru":["Автоматизировать настройку проекта с git clone и npm install","Генерировать техническую документацию для проектов, использующих Node.js 18+ и npm или yarn","Оптимизировать настройку окружения с помощью файлов .env.example и .env.local"],"ar":["توفير إعداد المشروع تلقائياً باستخدام git clone و npm install","генерировать توثيق فني للمشاريع التي تستخدم Node.js 18+ و npm أو yarn","تحسين إعداد البيئة باستخدام الملفات .env.example و .env.local"]},"limitations":{"en":["Requires Node.js 18+ and npm or yarn","Limited to projects using supported technologies like Next.js, TypeScript, and Tailwind CSS"],"zh":["需要 Node.js 18+ 和 npm 或 yarn","仅限于使用支持的技术，如 Next.js、TypeScript 和 Tailwind CSS 的项目"],"ja":["Node.js 18+ と npm または yarn が必要","サポートされているテクノロジー（Next.js、TypeScript、Tailwind CSS など）を使用するプロジェクトのみに制限される"],"ko":["Node.js 18+와 npm 또는 yarn이 필요함","지원되는 기술(Next.js, TypeScript, Tailwind CSS 등)을 사용하는 프로젝트에만 제한됨"],"es":["Requiere Node.js 18+ y npm o yarn","Limitado a proyectos que utilizan tecnologías compatibles como Next.js, TypeScript y Tailwind CSS"],"fr":["Nécessite Node.js 18+ et npm ou yarn","Limité aux projets utilisant des technologies prises en charge comme Next.js, TypeScript et Tailwind CSS"],"de":["Benötigt Node.js 18+ und npm oder yarn","Begrenzt auf Projekte, die unterstützte Technologien wie Next.js, TypeScript und Tailwind CSS verwenden"],"pt":["Requer Node.js 18+ e npm ou yarn","Limitado a projetos que usam tecnologias compatíveis, como Next.js, TypeScript e Tailwind CSS"],"ru":["Требует Node.js 18+ и npm или yarn","Ограничен проектами, использующими поддерживаемые технологии, такие как Next.js, TypeScript и Tailwind CSS"],"ar":["يتطلب Node.js 18+ و npm أو yarn","محدود للمشاريع التي تستخدم تقنيات مدعومة مثل Next.js و TypeScript و Tailwind CSS"]},"version":4},"contentHash":"6b3f56036c08589c39f74914bbf801b299b72da0a73c082fecc698981a04d856","qualityScore":48}');
